INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mag123c/linkhub/task', 'community', 'mag123c', 'linkhub', 'mag123c/linkhub', 'task', 0, 0, 30, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:38.498Z', '5fabb351e09caeea4d9f88210d31b1bd14db5d0216b2f52a97d167b1cb44a140', '{"id":"mag123c/linkhub/task","name":"task","description":{"en":"Task is a Chrome Extension designed for advanced bookmark management with tags and search, benefiting developers and power users. It integrates workflow orchestration from task analysis to Git commit.","zh":"Task AI工具提供了工作流程自动化的解决方案，涵盖分析、实现、审查等阶段","ja":"Task AIエージェントは、分析から実装、レビューまでのワークフローを自動化するツールです","ko":"Task Skill은 작업 분석부터 Git 커밋까지의 전체 사이클을 관리하는 통합 워크플로우 오케스트레이션 도구입니다","es":"Task es una extensión de Chrome para la gestión avanzada de marcadores con etiquetas y búsqueda, que integra el ciclo de vida de las tareas desde el análisis hasta el commit de Git","fr":"Task est une extension Chrome pour la gestion avancée des signets avec des étiquettes et une recherche, qui intègre le cycle de vie des tâches depuis l''analyse jusqu''au commit Git","de":"Task ist eine Chrome-Erweiterung für die erweiterte Lesezeichenverwaltung mit Tags und Suche, die den Lebenszyklus von Aufgaben von der Analyse bis zum Git-Commit integriert","pt":"O Task é uma extensão do Chrome para gerenciamento avançado de favoritos com tags e busca, melhorando a organização e produtividade","ru":"Задача - это расширение Chrome для расширенного управления закладками с тегами и поиском, повышающее организацию и производительность","ar":"المهام هي امتداد كروم لتنظيم العلامات المرجعية المتقدم مع タグ و البحث، مما يحسن التنظيم والإنتاجية"},"seo":{"title":{"en":"Task: Advanced Bookmark Management Setup Guide | AI Agent...","zh":"Task AI工具集成工作流程指南","ja":"Task AIエージェントのワークフロー統合ガイド","ko":"Task Skill 통합 워크플로우 오케스트레이션 가이드","es":"Guía de configuración de Task: gestión de tareas con Git","fr":"Guide de configuration de Task: gestion de tâches avec Git","de":"Task-Setup-Leitfaden: Erweiterte Aufgabenverwaltung mit Git","pt":"Guia de Configuração do Task: Gerenciamento Avançado de F...","ru":"Настройка задачи: Расширенное управление закладками с тег...","ar":"دليل إعداد المهام: إدارة متقدمة للعلامات المرجعية مع タグ و..."},"description":{"en":"Discover how to streamline your workflow with Task, a Chrome Extension for advanced bookmark management. Learn how to install and utilize its features today!","zh":"通过Task AI工具实现工作流程自动化，包括分析、实现、审查等阶段","ja":"Task AIエージェントを使用してワークフローを自動化する方法","ko":"Task Skill을 사용하여 작업 분석부터 Git 커밋까지의 전체 사이클을 관리하는 방법","es":"Aprende a configurar Task para gestionar tareas con etiquetas y búsqueda en Chrome, y optimiza tu flujo de trabajo con Git","fr":"Découvrez comment configurer Task pour gérer des tâches avec des étiquettes et une recherche dans Chrome, et optimisez votre workflow avec Git","de":"Erfahren Sie, wie Sie Task einrichten, um Aufgaben mit Tags und Suche in Chrome zu verwalten, und optimieren Sie Ihren Workflow mit Git","pt":"Aprenda a configurar o Task para gerenciar favoritos com tags e busca, otimizando sua produtividade","ru":"Узнайте, как настроить задачу для управления закладками с тегами и поиском, повышая производительность","ar":"تعرف على كيفية إعداد المهام لتنظيم العلامات المرجعية مع タグ و البحث، وزيادة الإنتاجية"},"definition":{"en":"Task is a Chrome Extension for managing bookmarks with tags and search functionality, enabling efficient workflow orchestration.","zh":"Task AI工具是一种工作流程自动化工具，用于管理和优化软件开发过程","ja":"Task AIエージェントは、ワークフローを自動化し、ソフトウェア開発プロセスを最適化するツールです","ko":"Task Skill은 작업 분석부터 Git 커밋까지의 전체 사이클을 관리하는 워크플로우 오케스트레이션 도구입니다","es":"Task es una herramienta de gestión de tareas que integra análisis, implementación y revisión en un solo flujo de trabajo","fr":"Task est un outil de gestion de tâches qui intègre l''analyse, la mise en œuvre et la révision dans un seul workflow","de":"Task ist ein Aufgabenmanagement-Tool, das Analyse, Implementierung und Überprüfung in einem einzigen Workflow integriert","pt":"O Task é uma ferramenta de gerenciamento de favoritos que utiliza tags e busca para organizar e otimizar a produtividade","ru":"Задача - это инструмент управления закладками, который использует теги и поиск для организации и повышения производительности","ar":"المهام هي أداة لإدارة العلامات المرجعية التي تستخدم タグ و البحث لتنظيم وزيادة الإنتاجية"},"features":{"en":["Utilizes workflow orchestration with Phase 1: analysis, Phase 2: implementation, and Phase 3: review","Supports Git commit management for feat, fix, and refactor types","Applies /developer and /frontend skills for logic and UI implementation","Enables functionality-based intermediate commits","Includes /reviewer skill application for issue resolution and feedback"],"zh":["支持工作流程的分析、实现、审查等阶段","自动创建分支和提交","支持多种开发语言和框架","提供代码审查和反馈功能","集成Git版本控制系统"],"ja":["ワークフローの分析、実装、レビューなどの段階をサポート","ブランチとコミットの自動作成","多くの開発言語とフレームワークをサポート","コードレビューとフィードバック機能を提供","Gitバージョン管理システムとの統合"],"ko":["작업 분석부터 구현, 리뷰까지의 전체 사이클을 관리","자동 브랜치 생성과 커밋","여러 개발 언어와 프레임워크를 지원","코드 리뷰와 피드백 기능을 제공","Git 버전 관리 시스템과 통합"],"es":["Gestión de tareas con etiquetas y búsqueda","Integración con Git para el ciclo de vida de las tareas","Análisis de requisitos y identificación de archivos afectados","Implementación de funcionalidades con commits intermedios","Revisión y retroalimentación con comentarios críticos, mayores y menores"],"fr":["Gestion de tâches avec des étiquettes et une recherche","Intégration avec Git pour le cycle de vie des tâches","Analyse des exigences et identification des fichiers affectés","Mise en œuvre de fonctionnalités avec des commits intermédiaires","Révision et feedback avec des commentaires critiques, majeurs et mineurs"],"de":["Aufgabenverwaltung mit Tags und Suche","Integration mit Git für den Lebenszyklus von Aufgaben","Anforderungsanalyse und Identifizierung von betroffenen Dateien","Implementierung von Funktionalitäten mit Zwischencommits","Überprüfung und Feedback mit kritischen, größeren und kleineren Kommentaren"],"pt":["Gerenciamento de favoritos com tags","Busca avançada de favoritos","Integração com o Git para gerenciamento de versões","Ciclo de vida de desenvolvimento completo, desde a análise até o commit","Suporte a múltiplas fases de desenvolvimento, incluindo análise, implementação e revisão"],"ru":["Управление закладками с тегами","Расширенный поиск закладок","Интеграция с Git для управления версиями","Полный цикл разработки, от анализа до коммита","Поддержка нескольких фаз разработки, включая анализ, реализацию и ревью"],"ar":["إدارة العلامات المرجعية مع タグ","بحث متقدم للعلامات المرجعية","التكامل مع Git لإدارة الإصدارات","دورة حياة التطوير الكاملة، من التحليل إلى الالتزام","دعم مراحل متعددة من التطوير، بما في ذلك التحليل والتنفيذ والمراجعة"]},"keywords":{"en":["how to use task chrome extension","task alternative to traditional bookmarking","task setup guide for developers","task vs bookmark manager","what is task chrome extension","task install and configuration"],"zh":["Task AI工具","工作流程自动化","软件开发过程","代码审查","Git版本控制","开发语言","框架","代码管理","项目管理"],"ja":["Task AIエージェント","ワークフロー自動化","ソフトウェア開発プロセス","コードレビュー","Gitバージョン管理","開発言語","フレームワーク","コード管理","プロジェクト管理"],"ko":["Task Skill","작업 분석","구현","리뷰","Git 커밋","코드 관리","프로젝트 관리","개발 언어","프레임워크","버전 관리"],"es":["gestión de tareas","etiquetas y búsqueda","Git","análisis de requisitos","implementación de funcionalidades","revisión y retroalimentación","herramientas de desarrollo","productividad","chrome extension"],"fr":["gestion de tâches","étiquettes et recherche","Git","analyse des exigences","mise en œuvre de fonctionnalités","révision et feedback","outils de développement","productivité","extension chrome"],"de":["Aufgabenverwaltung","Tags und Suche","Git","Anforderungsanalyse","Implementierung von Funktionalitäten","Überprüfung und Feedback","Entwicklungstools","Produktivität","Chrome-Erweiterung"],"pt":["task management","gerenciamento de favoritos","tags e busca","produtividade no desenvolvimento","ferramentas de desenvolvimento","extensão do Chrome","Git","ciclo de vida de desenvolvimento"],"ru":["задача","управление закладками","теги и поиск","производительность в разработке","инструменты разработки","расширение Chrome","Git","цикл разработки"],"ar":["مهمة","إدارة العلامات المرجعية","タグ و البحث","الإنتاجية في التطوير","أدوات التطوير","امتداد كروم","Git","دورة حياة التطوير"]}},"owner":"mag123c","repo":"linkhub","repoPath":"mag123c/linkhub","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.313Z","topics":[],"category":"community","skillMd":{"name":"task","description":"작업 오케스트레이션 스킬. 분석 → 구현 → 리뷰 → 커밋까지 전체 워크플로우 관리. 기능 개발, 버그 수정 등 모든 작업에 사용.","bodyPreview":"# Task Skill\n\n통합 워크플로우 오케스트레이션. 작업 분석부터 Git 커밋까지 전체 사이클 관리.\n\n## 워크플로우\n\n```\n/task \"작업 설명\"\n    │\n    ├─ Phase 1: 분석\n    │   ├─ 요구사항 파악\n    │   ├─ 영향받는 파일 식별\n    │   ├─ 작업 타입 결정 (feat/fix/refactor)\n    │   └─ 브랜치 생성\n    │\n    ├─ Phase 2: 구현\n    │   ├─ /developer 스킬 적용 (타입, 스토리지, 로직)\n    │   ├─ /frontend 스킬 적용 (UI, 컴포넌트)\n    │   └─ 기능 단위로 중간 커밋\n    │\n    ├─ Phase 3: 리뷰\n    │   ├─ /reviewer 스킬 적용\n    │   ├─ [Critical] 이슈 → Phase 2로 돌아가 수정\n    │   ├─ [Major] 이슈 → Phase 2로 돌아가 수정\n    │   └─ [Minor] 이슈","body":"# Task Skill\n\n통합 워크플로우 오케스트레이션. 작업 분석부터 Git 커밋까지 전체 사이클 관리.\n\n## 워크플로우\n\n```\n/task \"작업 설명\"\n    │\n    ├─ Phase 1: 분석\n    │   ├─ 요구사항 파악\n    │   ├─ 영향받는 파일 식별\n    │   ├─ 작업 타입 결정 (feat/fix/refactor)\n    │   └─ 브랜치 생성\n    │\n    ├─ Phase 2: 구현\n    │   ├─ /developer 스킬 적용 (타입, 스토리지, 로직)\n    │   ├─ /frontend 스킬 적용 (UI, 컴포넌트)\n    │   └─ 기능 단위로 중간 커밋\n    │\n    ├─ Phase 3: 리뷰\n    │   ├─ /reviewer 스킬 적용\n    │   ├─ [Critical] 이슈 → Phase 2로 돌아가 수정\n    │   ├─ [Major] 이슈 → Phase 2로 돌아가 수정\n    │   └─ [Minor] 이슈 → 선택적 수정\n    │\n    └─ Phase 4: 마무리\n        ├─ /verify 실행\n        ├─ 최종 커밋\n        └─ (선택) PR 생성 안내\n```\n\n## Phase 1: 분석\n\n### 작업 타입 판별\n\n| 타입 | 브랜치 접두사 | 설명 |\n|------|---------------|------|\n| 새 기능 | `feat/` | 새로운 기능 추가 |\n| 버그 수정 | `fix/` | 버그 수정 |\n| 리팩토링 | `refactor/` | 코드 개선 (기능 변경 없음) |\n| 문서 | `docs/` | 문서 작성/수정 |\n| 스타일 | `style/` | 코드 포맷팅 |\n| 테스트 | `test/` | 테스트 추가/수정 |\n\n### 브랜치 생성\n\n```bash\ngit checkout -b {타입}/{kebab-case-설명}\n# 예: feat/tag-filter, fix/search-bug\n```\n\n### 분석 체크리스트\n\n- [ ] 요구사항 명확히 이해\n- [ ] 영향받는 파일/모듈 식별\n- [ ] 필요한 스킬 결정 (developer, frontend, 둘 다)\n- [ ] 작업 단위 분할 (커밋 단위)\n\n## Phase 2: 구현\n\n### 스킬 호출 순서\n\n1. **데이터/로직 먼저**: `/developer` 스킬 적용\n   - 타입 정의, 인터페이스\n   - Storage 유틸리티\n   - 비즈니스 로직\n\n2. **UI/컴포넌트**: `/frontend` 스킬 적용\n   - React 컴포넌트\n   - 커스텀 훅\n   - 스타일링\n\n### 기능 단위 커밋\n\n구현 중 의미 있는 단위마다 커밋:\n\n```bash\ngit add <관련 파일들>\ngit commit -m \"{타입}: {설명}\"\n```\n\n**커밋 메시지 규칙** (Conventional Commits):\n```\nfeat: add tag filtering logic\nfeat: implement TagFilter component\nfix: search not matching partial text\nrefactor: extract storage utilities\n```\n\n**커밋 단위 기준**:\n- 하나의 논리적 변경 = 하나의 커밋\n- 롤백 시 독립적으로 되돌릴 수 있는 단위\n\n## Phase 3: 리뷰\n\n### /reviewer 스킬 적용\n\n구현 완료 후 자동으로 리뷰 수행:\n\n| 우선순위 | 조치 |\n|----------|------|\n| [Critical] | 반드시 수정 → Phase 2 |\n| [Major] | 수정 권장 → Phase 2 |\n| [Minor] | 선택적 수정 |\n\n### 수정 루프\n\n```\n리뷰 → 이슈 발견 → 수정 (developer/frontend) → 재리뷰\n```\n\n이슈가 없거나 Minor만 남으면 Phase 4로 진행.\n\n## Phase 4: 마무리\n\n### 최종 점검 (/verify 스킬 호출)\n\n```\n/verify 실행\n    ├─ pnpm build    # 빌드 확인\n    ├─ pnpm lint     # 린트 확인\n    └─ pnpm test:run # 테스트 확인\n```\n\n### 디렉토리별 CLAUDE.md 작성/갱신\n\n새 디렉토리 생성 또는 주요 변경 시 해당 디렉토리에 `CLAUDE.md` 작성.\n\n### 최종 커밋 (필요시)\n\n```bash\ngit add .\ngit commit -m \"{타입}: {전체 작업 요약}\"\n```\n\n## 예시\n\n### 입력\n```\n/task 태그 필터링 기능 추가\n```\n\n### 실행 흐름\n\n```\n1. 분석\n   - 타입: feat (새 기능)\n   - 브랜치: feat/tag-filter\n   - 영향: src/shared/types/, src/popup/components/\n   - 스킬: developer → frontend\n\n2. 구현\n   - /developer: 필터 로직, 타입 정의\n   - 커밋: \"feat: add tag filter logic\"\n   - /frontend: TagFilter.tsx 컴포넌트\n   - 커밋: \"feat: implement TagFilter component\"\n\n3. 리뷰\n   - /reviewer 실행\n   - [Minor] 변수명 개선 제안\n   - 선택적 수정\n\n4. 마무리\n   - /verify: 빌드/린트/테스트 통과\n   - 완료\n```\n\n## 주의사항\n\n- **커밋 마킹 금지**: Co-Author, Claude 마킹 절대 금지\n- **브랜치 보호**: main 직접 커밋 금지, 브랜치에서 작업\n- **빌드 확인**: 커밋 전 반드시 빌드 성공 확인\n- **작은 단위**: 큰 작업은 여러 브랜치로 분할 고려\n"},"lastSynced":"2026-03-08T02:02:38.498Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing integrated workflow orchestration from task analysis to Git commit.","zh":"适合需要从任务分析到 Git 提交的集成工作流编排的开发代理。","ja":"タスク分析からGitコミットまでの統合ワークフロー管理が必要な開発エージェントに適しています。","ko":"작업 분석에서 Git 커밋까지 통합 워크플ロー 오케스트레이션이 필요한 개발 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan orquestación de flujo de trabajo integrada desde el análisis de tareas hasta el compromiso de Git.","fr":"Parfait pour les agents de développement ayant besoin d''une orchestration de flux de travail intégrée de l''analyse de tâches à l''engagement Git.","de":"Perfekt für Entwicklungsmittel, die eine integrierte Workflow-Orchestrierung von der Aufgabenanalyse bis zum Git-Commit benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de orquestração de fluxo de trabalho integrada desde a análise de tarefas até o commit do Git.","ru":"Идеально подходит для агентов разработки, которым необходима интегрированная оркестрация рабочих процессов от анализа задач до фиксации в Git.","ar":"مثالي للوكلاء الذين يحتاجون إلى تنسيق تدفق عمل متكامل من تحليل المهام إلى الإلتزام بالجيت."},"recommendation":{"en":"Empowers agents to manage entire development cycles with tags, search, and workflow automation, utilizing Git commit integration and workflow phases like analysis, implementation, and review, all while applying skills like /developer and /frontend for tailored development experiences.","zh":"赋予代理管理整个开发周期的能力，使用标签、搜索和工作流自动化，利用 Git 提交集成和工作流阶段，如分析、实现和审查，同时应用像 /developer 和 /frontend 的技能以实现定制的开发体验。","ja":"エージェントがタグ、検索、ワークフロー自動化を使用して開発サイクル全体を管理できるようにし、Gitコミットの統合や分析、実装、レビューなどのワークフローフェーズを利用し、/developerや/frontendなどのスキルを適用してカスタマイズされた開発体験を提供します。","ko":"에이전트가 태그, 검색, 워크플ロー 자동화를 사용하여 전체 개발 주기를 관리할 수 있도록 하며, Git 커밋 통합 및 분석, 구현, 검토 등의 워크플ロー 단계를 활용하고, /developer 및 /frontend 등의 스킬을 적용하여 맞춤형 개발 환경을 제공합니다.","es":"Habilita a los agentes a administrar ciclos de desarrollo completos con etiquetas, búsqueda y automatización de flujo de trabajo, utilizando la integración de Git commit y fases de flujo de trabajo como análisis, implementación y revisión, todo mientras se aplican habilidades como /developer y /frontend para experiencias de desarrollo personalizadas.","fr":"Permet aux agents de gérer des cycles de développement complets avec des étiquettes, des recherches et une automatisation de flux de travail, en utilisant l''intégration de Git commit et des phases de flux de travail comme analyse, mise en œuvre et examen, tout en appliquant des compétences comme /developer et /frontend pour des expériences de développement personnalisées.","de":"Ermächtigt Agenten, gesamte Entwicklungszyklen mit Tags, Suche und Workflow-Automatisierung zu verwalten, indem sie die Git-Commit-Integration und Workflow-Phasen wie Analyse, Implementierung und Überprüfung nutzen und dabei Fähigkeiten wie /developer und /frontend für maßgeschneiderte Entwicklungserfahrungen anwenden.","pt":"Habilita os agentes a gerenciar ciclos de desenvolvimento inteiros com tags, busca e automação de fluxo de trabalho, utilizando a integração do commit do Git e fases de fluxo de trabalho como análise, implementação e revisão, aplicando habilidades como /developer e /frontend para experiências de desenvolvimento personalizadas.","ru":"Наделяет агентов возможностью управлять целыми циклами разработки с помощью тегов, поиска и автоматизации рабочих процессов, используя интеграцию с фиксацией в Git и фазы рабочих процессов, такие как анализ, реализация и обзор, применяя навыки, такие как /developer и /frontend, для адаптированных опытов разработки.","ar":"تمكين الوكلاء من إدارة دورات التطوير بأكملها باستخدام العلامات والبحث وأتمتة تدفق العمل، باستخدام دمج الالتزام في الجيت وأطوار تدفق العمل مثل التحليل والتنفيذ والمراجعة، مع تطبيق مهارات مثل /developer و /frontend لتجارب تطوير مخصصة."},"useCases":{"en":["Automating task management with workflow orchestration","Generating Git commits for feat/fix/refactor tasks","Orchestrating code reviews with /reviewer skill application"],"zh":["使用工作流编排自动化任务管理","为feat/fix/refactor任务生成Git提交","使用/reviewer技能应用编排代码审查"],"ja":["ワークフロー管理を使用したタスク管理の自動化","feat/fix/refactorタスクのGitコミットの生成","/reviewerスキルの適用によるコードレビューのオーケストレーション"],"ko":["워크플ロー 오케스트레이션을 사용한 작업 관리 자동화","feat/fix/refactor 작업의 Git 커밋 생성","/reviewer 스킬 적용을 통한 코드 리뷰 오케스트레이션"],"es":["Automatización de la gestión de tareas con orquestación de flujo de trabajo","Generación de compromisos de Git para tareas feat/fix/refactor","Orquestación de revisiones de código con la aplicación de habilidades /reviewer"],"fr":["Automatisation de la gestion des tâches avec orchestration de flux de travail","Génération d''engagements Git pour les tâches feat/fix/refactor","Orchestration des examens de code avec l''application de compétences /reviewer"],"de":["Automatisierung der Aufgabenverwaltung mit Workflow-Orchestrierung","Erzeugung von Git-Commits für Aufgaben feat/fix/refactor","Orchestrierung von Code-Reviews mit der Anwendung von Fähigkeiten /reviewer"],"pt":["Automatizar a gestão de tarefas com orquestração de fluxo de trabalho","Gerar commits do Git para tarefas feat/fix/refactor","Orquestrar revisões de código com aplicação da habilidade /reviewer"],"ru":["Автоматизировать управление задачами с помощью оркестрации рабочих процессов","Генерировать фиксации в Git для задач feat/fix/refactor","Оркестрировать обзоры кода с применением навыка /reviewer"],"ar":["أتمتة إدارة المهام مع تنسيق تدفق العمل","توليد التزامات الجيت للمهام feat/fix/refactor","تنسيق استعراضات الشفرة مع تطبيق مهارة /reviewer"]},"limitations":{"en":["Requires Git integration","Chrome Extension dependency","Limited to development workflows"],"zh":["需要Git集成","依赖Chrome扩展","仅限开发工作流"],"ja":["Gitの統合が必要","Chrome拡張機能への依存","開発ワークフローに限定"],"ko":["Git 통합이 필요","Chrome 확장 프로그램 의존","개발 워크플로에 한정"],"es":["Requiere integración de Git","Dependencia de la extensión de Chrome","Limitado a flujos de trabajo de desarrollo"],"fr":["Nécessite une intégration de Git","Dépendance de l''extension Chrome","Limité aux flux de travail de développement"],"de":["Erfordert Git-Integration","Abhängigkeit von der Chrome-Erweiterung","Begrenzt auf Entwicklung-Workflows"],"pt":["Requer integração com o Git","Dependência da Extensão do Chrome","Limitado a fluxos de trabalho de desenvolvimento"],"ru":["Требует интеграции с Git","Зависимость от расширения Chrome","Ограничен рабочими процессами разработки"],"ar":["يتطلب دمج الجيت","اعتماد على امتداد كروم","محدود بتدفقات عمل التطوير"]},"version":4},"contentHash":"5fabb351e09caeea4d9f88210d31b1bd14db5d0216b2f52a97d167b1cb44a140","qualityScore":30}');
