INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mag123c/linkhub/task', 'task', 'mag123c', 'linkhub', 'community', 'task mag123c linkhub community Task is a Chrome Extension designed for advanced bookmark management with tags and search, benefiting developers and power users. It integrates workflow orchestration from task analysis to Git commit. Task AI工具提供了工作流程自动化的解决方案，涵盖分析、实现、审查等阶段 Task AIエージェントは、分析から実装、レビューまでのワークフローを自動化するツールです Task Skill은 작업 분석부터 Git 커밋까지의 전체 사이클을 관리하는 통합 워크플로우 오케스트레이션 도구입니다 Task es una extensión de Chrome para la gestión avanzada de marcadores con etiquetas y búsqueda, que integra el ciclo de vida de las tareas desde el análisis hasta el commit de Git Task est une extension Chrome pour la gestion avancée des signets avec des étiquettes et une recherche, qui intègre le cycle de vie des tâches depuis l''analyse jusqu''au commit Git Task ist eine Chrome-Erweiterung für die erweiterte Lesezeichenverwaltung mit Tags und Suche, die den Lebenszyklus von Aufgaben von der Analyse bis zum Git-Commit integriert O Task é uma extensão do Chrome para gerenciamento avançado de favoritos com tags e busca, melhorando a organização e produtividade Задача - это расширение Chrome для расширенного управления закладками с тегами и поиском, повышающее организацию и производительность المهام هي امتداد كروم لتنظيم العلامات المرجعية المتقدم مع タグ و البحث، مما يحسن التنظيم والإنتاجية how to use task chrome extension task alternative to traditional bookmarking task setup guide for developers task vs bookmark manager what is task chrome extension task install and configuration Task AI工具 工作流程自动化 软件开发过程 代码审查 Git版本控制 开发语言 框架 代码管理 项目管理 Utilizes workflow orchestration with Phase 1: analysis, Phase 2: implementation, and Phase 3: review Supports Git commit management for feat, fix, and refactor types Applies /developer and /frontend skills for logic and UI implementation Enables functionality-based intermediate commits Includes /reviewer skill application for issue resolution and feedback Task is a Chrome Extension for managing bookmarks with tags and search functionality, enabling efficient workflow orchestration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yuch4/dx-selecta/steering', 'community', 'yuch4', 'dx-selecta', 'yuch4/dx-selecta', 'steering', 0, 0, 30, '2026-03-08T01:57:15.314Z', '2026-03-08T02:02:42.933Z', 'beeca4ab0cd30765b886148428e10ed7907c7bd65c21684c86da5e870308921c', '{"id":"yuch4/dx-selecta/steering","name":"steering","description":{"en":"The steering skill enables AI agents to manage workflows by planning, tracking, and reviewing tasks. It benefits developers by providing a structured approach to task management.","zh":"Steering Skill 是一种用于任务管理和追踪的工作流管理技能，帮助您高效地开发 AIエージェント","ja":"Steering Skill はタスク管理と追跡のためのワークフロー管理スキルで、AIエージェント開発の効率を向上させる","ko":"Steering 기능은 태스크 관리와 추적을 위한 워크플로우 관리 기능으로서 AI 에이전트 개발 효율을 높여줍니다","es":"Steering es una habilidad de gestión de flujo de trabajo que permite planificar, realizar un seguimiento y revisar el progreso de tus tareas de desarrollo","fr":"Steering est une compétence de gestion de flux de travail qui permet de planifier, de suivre et de revoir l''avancement de vos tâches de développement","de":"Steering ist eine Workflow-Management-Fähigkeit, die es ermöglicht, den Fortschritt Ihrer Entwicklungsarbeiten zu planen, zu verfolgen und zu überprüfen","pt":"O Steering é uma habilidade que ajuda a gerenciar workflows de forma eficaz, permitindo que os desenvolvedores planejem, rastreiem e revisem suas tarefas de forma centralizada.","ru":"ИИ Агент Steering - это навык, который помогает управлять workflow эффективно, позволяя разработчикам планировать, отслеживать и просматривать свои задачи в централизованном режиме.","ar":"Steering هو مهارة تساعد في إدارة سير العمل بفعالية، مما يسمح للمطورين بالتخطيط والتحديد والمتابعة لعملياتهم بطرق مركزية."},"seo":{"title":{"en":"Steering: Workflow Management Setup Guide | AI Agent Skill","zh":"AIエージェント Steering 技術指南","ja":"Steering Skill Setup Guide for AIエージェント","ko":"AI 에이전트 Steering 기능 구축 가이드","es":"Guía de configuración de Steering para el flujo de trabaj...","fr":"Configurer Steering pour une gestion de workflow efficace","de":"Steering-Setup-Leitfaden für die Workflow-Management","pt":"Guia de Configuração do Steering: Gerenciamento de Workflows","ru":"Настройка ИИ Агента Steering: Управление Workflow","ar":"دليل إعداد Steering: إدارة سير العمل"},"description":{"en":"Discover how to implement steering for efficient workflow management. Learn to create a single source of truth with tasklist.md and track progress effectively.","zh":"了解 Steering Skill 的技术细节，包括任务管理和追踪，提升您的 AIエージェント开发效率","ja":"Steering Skill を使用してタスク管理と追跡を実現し、AIエージェント開発の効率を向上させる","ko":"Steering 기능을 활용하여 태스크 관리와 추적을 구현하고 AI 에이전트 개발 효율을 높여보세요","es":"Aprende a configurar Steering para gestionar tu flujo de trabajo de desarrollo de manera efectiva y mejorar la productividad","fr":"Découvrez comment configurer Steering pour améliorer la gestion de votre flux de travail de développement","de":"Erfahren Sie, wie Sie Steering einrichten, um Ihre Workflow-Management-Produktivität zu steigern","pt":"Aprenda a configurar o Steering para gerenciar workflows de forma eficaz. Descubra como usar o Steering para melhorar a produtividade do seu time de desenvol...","ru":"Узнайте, как настроить ИИ Агента Steering для эффективного управления workflow. Откройте для себя, как использовать Steering для повышения производительности...","ar":"تعرف على كيفية إعداد Steering لإدارة سير العمل بفعالية. اكتشف كيفية استخدام Steering لتحسين إنتاجية فريقك التطويري."},"definition":{"en":"Steering is a workflow management skill that enables AI agents to plan, track, and review tasks using a structured approach.","zh":"Steering Skill 是一种 AIエージェント 技术，用于管理和追踪任务","ja":"Steering Skill は AIエージェント のワークフロー管理スキル","ko":"Steering 기능은 AI 에이전트의 워크플로우 관리 기능","es":"Steering es una habilidad que permite gestionar el flujo de trabajo de desarrollo mediante la creación de un registro de requerimientos, diseño y tareas","fr":"Steering est une compétence qui permet de gérer le flux de travail de développement en créant un enregistrement des exigences, de la conception et des tâches","de":"Steering ist eine Fähigkeit, die es ermöglicht, den Entwicklungs-Workflow durch die Erstellung eines Registers von Anforderungen, Design und Aufgaben zu managen","pt":"O que é Steering? É uma habilidade que gerencia workflows, permitindo que os desenvolvedores planejem e rastreiem suas tarefas de forma eficaz.","ru":"Что такое ИИ Агент Steering? Это навык, который управляет workflow, позволяя разработчикам планировать и отслеживать свои задачи эффективно.","ar":"ما هو Steering? هو مهارة لإدارة سير العمل، مما يسمح للمطورين بالتخطيط والتحديد بفعالية."},"features":{"en":["Creates a single source of truth with tasklist.md for progress tracking","Utilizes .steering/ directory for storing requirements, designs, and tasks","References guide.md for detailed rules and templates","Supports requirements, design, and tasklist templates for standardized workflow management","Generates output in .steering/<YYYYMMDD>-<slug>/requirement format"],"zh":["任务管理和追踪","工作流管理","支持 tasklist.md 文件","集成 references/guide.md 和 references/templates/","CLI 命令支持"],"ja":["タスク管理と追跡","ワークフロー管理","tasklist.md ファイルのサポート","references/guide.md と references/templates/ の統合","CLI コマンドのサポート"],"ko":["태스크 관리와 추적","워크플로우 관리","tasklist.md 파일 지원","references/guide.md와 references/templates/의 통합","CLI 명령어 지원"],"es":["Creación de un registro de requerimientos y diseño","Gestión de tareas mediante la creación de una lista de tareas","Uso de plantillas de requerimientos y diseño para agilizar el proceso","Creación de un registro de progreso en el directorio `.steering/`","Uso de `tasklist.md` como única fuente de verdad para el progreso"],"fr":["Création d''un enregistrement des exigences et de la conception","Gestion des tâches via la création d''une liste de tâches","Utilisation de modèles d''exigences et de conception pour accélérer le processus","Création d''un enregistrement de l''avancement dans le répertoire `.steering/`","Utilisation de `tasklist.md` comme seule source de vérité pour l''avancement"],"de":["Erstellung eines Registers von Anforderungen und Design","Aufgabenmanagement durch die Erstellung einer Aufgabenliste","Verwendung von Anforderungs- und Design-Vorlagen, um den Prozess zu beschleunigen","Erstellung eines Registers des Fortschritts im Verzeichnis `.steering/`","Verwendung von `tasklist.md` als einzige Quelle der Wahrheit für den Fortschritt"],"pt":["Gerenciamento de workflows centralizado","Criação de tarefas e acompanhamento de progresso","Uso de templates para requisitos e design","Integração com arquivos de referência para guias e modelos","Suporte à criação de listas de tarefas personalizadas"],"ru":["Централизованное управление workflow","Создание задач и отслеживание прогресса","Использование шаблонов для требований и дизайна","Интеграция с файлами справки для руководств и моделей","Поддержка создания индивидуальных списков задач"],"ar":["إدارة سير العمل المركزية","إنشاء المهام ومتابعة التقدم","استخدام القوالب للمتطلبات والتصميم","التكامل مع الملفات المرجعية لدليل والنموذج","دعم إنشاء قوائم المهام المخصصة"]},"keywords":{"en":["how to use steering","steering workflow management","steering alternative","steering vs workflow tools","steering install guide","steering setup tutorial","what is steering","steering for AI agents","workflow management with steering"],"zh":["AIエージェント","Steering Skill","任务管理","工作流管理","tasklist.md","CLI 命令","AI开发","效率提升"],"ja":["AIエージェント","Steering Skill","タスク管理","ワークフロー管理","tasklist.md","CLI コマンド","AI開発","効率向上"],"ko":["AI 에이전트","Steering 기능","태스크 관리","워크플로우 관리","tasklist.md","CLI 명령어","AI 개발","효율 향상"],"es":["Steering para desarrollo","gestión de flujo de trabajo","planificación de tareas","seguimiento de progreso","requerimientos de desarrollo","diseño de desarrollo","listas de tareas","Herramientas de desarrollo","AI Agent para desarrollo"],"fr":["Steering pour le développement","gestion de flux de travail","planification de tâches","suivi de l''avancement","exigences de développement","conception de développement","listes de tâches","Outils de développement","Agent IA pour le développement"],"de":["Steering für die Entwicklung","Workflow-Management","Aufgabenplanung","Fortschrittsverfolgung","Anforderungen an die Entwicklung","Entwicklungsdesign","Aufgabenlisten","Entwicklertools","KI-Agent für die Entwicklung"],"pt":["steering","gerenciamento de workflow","desenvolvimento de software","produtividade","ferramentas de desenvolvimento","guias de configuração","templates de requisitos","design de software"],"ru":["ИИ Агент Steering","управление workflow","разработка программного обеспечения","производительность","инструменты разработки","руководства по настройке","шаблоны требований","дизайн программного обеспечения"],"ar":["Steering","إدارة سير العمل","تطوير البرمجيات","الإنتاجية","أدوات التطوير","دلائل الإعداد","قوالب المتطلبات","تصميم البرمجيات"]}},"owner":"yuch4","repo":"dx-selecta","repoPath":"yuch4/dx-selecta","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.314Z","topics":[],"category":"community","skillMd":{"name":"steering","description":"作業指示ごとに .steering/ 配下へ requirements/design/tasklist を作成し、tasklist.md を唯一の進捗ソースとして実装を推進する。計画（作成）/実装（ループ）/振り返り（記録）の3モードで運用。「作業を計画して」「タスクリストを作成」「steering開始」「実装を進めて」などの依頼時に使用。","bodyPreview":"# Steering Skill\n\n作業を計画・追跡・振り返りするためのワークフロー管理スキル。\n\n## 目的\n\n- `.steering/` に「今回の作業の要求・設計・タスク」を必ず残す\n- `tasklist.md` を進捗の唯一の正（Single Source of Truth）にする\n\n## 参照ファイル\n\n| ファイル | 読むタイミング |\n|----------|----------------|\n| `references/guide.md` | 詳細ルール |\n| `references/templates/requirements.md` | 要求テンプレート |\n| `references/templates/design.md` | 設計テンプレート |\n| `references/templates/tasklist.md` | タスクリストテンプレート |\n\n## 入出力\n\n- 入力: ユーザーの指示（機能名/変更内容）、既存 docs（PRD/設計/アーキ等）\n- 出力:\n  - `.steering/<YYYYMMDD>-<slug>/requirem","body":"# Steering Skill\n\n作業を計画・追跡・振り返りするためのワークフロー管理スキル。\n\n## 目的\n\n- `.steering/` に「今回の作業の要求・設計・タスク」を必ず残す\n- `tasklist.md` を進捗の唯一の正（Single Source of Truth）にする\n\n## 参照ファイル\n\n| ファイル | 読むタイミング |\n|----------|----------------|\n| `references/guide.md` | 詳細ルール |\n| `references/templates/requirements.md` | 要求テンプレート |\n| `references/templates/design.md` | 設計テンプレート |\n| `references/templates/tasklist.md` | タスクリストテンプレート |\n\n## 入出力\n\n- 入力: ユーザーの指示（機能名/変更内容）、既存 docs（PRD/設計/アーキ等）\n- 出力:\n  - `.steering/<YYYYMMDD>-<slug>/requirements.md`\n  - `.steering/<YYYYMMDD>-<slug>/design.md`\n  - `.steering/<YYYYMMDD>-<slug>/tasklist.md`\n\n## モード\n\n### 1. plan モード\n3ファイル作成 + tasklist具体化\n\n### 2. implement モード\ntasklist を先頭から消化し、都度更新（未完了を残さない）\n\n### 3. reflect モード\ntasklist の振り返り欄を更新（全タスク完了後のみ）\n\n## 手順\n\n### plan モード\n1. 既存 docs を読んで方針を掴む\n2. ディレクトリを作成: `.steering/<YYYYMMDD>-<slug>/`\n3. テンプレから3ファイルを生成\n4. tasklist を具体的なタスクに分解\n\n### implement モード\n1. tasklist を読む\n2. 未完了タスクを1つ選ぶ\n3. 実装する\n4. tasklist を更新\n5. 1に戻る\n\n### reflect モード\n1. 全タスク完了を確認\n2. 振り返りを記録\n3. 学びや改善点をまとめる\n\n## tasklist.md 形式\n\n```markdown\n# タスクリスト\n\n## 概要\n- 作業名: [作業名]\n- 開始日: YYYY-MM-DD\n- 状態: planning / in_progress / done\n\n## タスク\n\n- [ ] タスク1\n- [ ] タスク2\n- [x] 完了したタスク\n\n## 振り返り\n\n（全タスク完了後に記入）\n```\n\n## 注意事項\n\n- implement中はtasklistを頻繁に更新する\n- 1タスク完了ごとにチェックを付ける\n- 新しいタスクが発生したら追加する\n- スコープ外のタスクは別のsteeringセッションにする\n"},"lastSynced":"2026-03-08T02:02:42.933Z","agentAnalysis":{"suitability":{"en":"Perfect for Workflow Management Agents needing structured task planning and tracking capabilities.","zh":"非常适合需要结构化任务规划和跟踪能力的工作流管理代理。","ja":"構造化されたタスク計画と追跡機能を必要とするワークフロー管理エージェントに最適です。","ko":"구조화된 작업 계획 및 추적 기능을 필요로 하는 워크플로우 관리 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Gestión de Flujo de Trabajo que requieren capacidades de planificación y seguimiento de tareas estructuradas.","fr":"Parfait pour les Agents de Gestion de Flux de Travail nécessitant une planification et un suivi de tâches structurés.","de":"Perfekt für Workflow-Management-Agents, die eine strukturierte Aufgabenplanung und -verfolgung benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Fluxo de Trabalho que precisam de planejamento e capacidades de rastreamento de tarefas estruturadas.","ru":"Идеально подходит для агентов управления рабочим процессом, которым требуются структурированные возможности планирования и отслеживания задач.","ar":"مثالي لعمليات إدارة تدفق العمل التي تحتاج إلى مهام مخططة ومهام قابلة للتتبع بنية"},"recommendation":{"en":"Empowers agents to manage workflows by planning, tracking, and reviewing tasks using Single Source of Truth tasklists and standardized templates for requirements and design, all stored in a `.steering/` directory.","zh":"使代理能够通过计划、跟踪和审查任务来管理工作流，使用单一事实来源任务列表和存储在 `.steering/` 目录中的标准化模板用于需求和设计。","ja":"エージェントがタスクを計画、追跡、レビューしてワークフローを管理できるようにし、シングルソースオブトゥルースのタスクリストと `.steering/` ディレクトリに格納された要件と設計の標準化されたテンプレートを使用します。","ko":"에이전트가 작업을 계획, 추적 및 검토하여 워크플로우를 관리할 수 있도록 하며, 단일 사실 원천의 작업 목록과 `.steering/` 디렉토리에 저장된 요구사항 및 설계를 위한 표준화된 템플릿을 사용합니다.","es":"Habilita a los agentes a gestionar flujos de trabajo planificando, seguimiento y revisando tareas utilizando listas de tareas de Una Fuente de Verdad y plantillas estandarizadas para requisitos y diseño, todas almacenadas en un directorio `.steering/`.","fr":"Permet aux agents de gérer les flux de travail en planifiant, suivant et révisant les tâches à l''aide de listes de tâches de Source Unique de Vérité et de modèles normalisés pour les exigences et la conception, le tout stocké dans un répertoire `.steering/`.","de":"Ermöglicht es Agenten, Workflows zu verwalten, indem sie Aufgaben planen, verfolgen und überprüfen, unter Verwendung von Single-Source-of-Truth-Aufgabenlisten und standardisierten Vorlagen für Anforderungen und Design, die alle in einem `.steering/`-Verzeichnis gespeichert sind.","pt":"Habilita os agentes a gerenciar fluxos de trabalho planejando, rastreando e revisando tarefas usando listas de tarefas de Única Fonte de Verdade e modelos padronizados para requisitos e design, todos armazenados em um diretório `.steering/`.","ru":"Наделяет агентов возможностью управлять рабочими процессами путем планирования, отслеживания и рассмотрения задач с помощью списков задач из Единого Источника Истины и стандартизированных шаблонов для требований и дизайна, все хранятся в директории `.steering/`.","ar":"تمكين الوكلاء من إدارة تدفقات العمل عن طريق تخطيط المهام وتتبعها ومراجعتها باستخدام قوائم المهام من مصدر وحيد للحقيقة وقوالب موحدة للمتطلبات والتصميم ،すべて يتم تخزينها في دليل `.steering/`."},"useCases":{"en":["Automating tasklist updates","Generating requirements and design documents using templates","Tracking progress through `tasklist.md`"],"zh":["自动更新任务列表","使用模板生成需求和设计文档","通过 `tasklist.md` 跟踪进度"],"ja":["タスクリストの自動更新","テンプレートを使用して要件と設計文書を生成","`tasklist.md` を介して進捗状況を追跡"],"ko":["작업 목록 자동 업데이트","템플릿을 사용하여 요구사항 및 설계 문서 생성","`tasklist.md`를 통해 진행 상황 추적"],"es":["Automatización de actualizaciones de listas de tareas","Generación de documentos de requisitos y diseño utilizando plantillas","Seguimiento del progreso a través de `tasklist.md`"],"fr":["Automatisation des mises à jour des listes de tâches","Génération de documents d''exigences et de conception à l''aide de modèles","Suivi de la progression via `tasklist.md`"],"de":["Automatisierung von Aufgabenlisten-Aktualisierungen","Erstellung von Anforderungs- und Design-Dokumenten unter Verwendung von Vorlagen","Verfolgung des Fortschritts über `tasklist.md`"],"pt":["Automatizar atualizações de listas de tarefas","Gerar documentos de requisitos e design usando modelos","Rastrear progresso por meio de `tasklist.md`"],"ru":["Автоматизировать обновления списков задач","Генерировать документы требований и дизайна с помощью шаблонов","Отслеживать прогресс через `tasklist.md`"],"ar":["توفير تحديثات قائمة المهام تلقائيا","إنتاج وثائق المتطلبات والتصميم باستخدام القوالب","تتبع التقدم من خلال `tasklist.md`"]},"limitations":{"en":["Requires filesystem access for `.steering/` directory","Dependent on user input for task planning and tracking"],"zh":["需要文件系统访问 `.steering/` 目录","依赖于用户输入进行任务规划和跟踪"],"ja":[" `.steering/` ディレクトリへのファイルシステムアクセスが必要","タスク計画と追跡にユーザー入力を依存"],"ko":["`.steering/` 디렉토리에 대한 파일 시스템 액세스가 필요","작업 계획 및 추적에 사용자 입력을 의존"],"es":["Requiere acceso al sistema de archivos para el directorio `.steering/`","Dependiente de la entrada del usuario para la planificación y seguimiento de tareas"],"fr":["Nécessite un accès au système de fichiers pour le répertoire `.steering/`","Dépend de la saisie de l''utilisateur pour la planification et le suivi des tâches"],"de":["Benötigt Zugriff auf das Dateisystem für das `.steering/`-Verzeichnis","Abhängig von der Benutzereingabe für die Aufgabenplanung und -verfolgung"],"pt":["Requer acesso ao sistema de arquivos para o diretório `.steering/`","Dependente da entrada do usuário para planejamento e rastreamento de tarefas"],"ru":["Требует доступа к файловой системе для директории `.steering/`","Зависит от ввода пользователя для планирования и отслеживания задач"],"ar":["يتطلب الوصول إلى نظام الملفات لدليل `.steering/`","يعتمد على إدخال المستخدم لتحديد مهام وتتبعها"]},"version":4},"contentHash":"beeca4ab0cd30765b886148428e10ed7907c7bd65c21684c86da5e870308921c","qualityScore":30}');
