INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yuch4/dx-selecta/steering', 'steering', 'yuch4', 'dx-selecta', 'community', 'steering yuch4 dx-selecta community The steering skill enables AI agents to manage workflows by planning, tracking, and reviewing tasks. It benefits developers by providing a structured approach to task management. Steering Skill 是一种用于任务管理和追踪的工作流管理技能，帮助您高效地开发 AIエージェント Steering Skill はタスク管理と追跡のためのワークフロー管理スキルで、AIエージェント開発の効率を向上させる Steering 기능은 태스크 관리와 추적을 위한 워크플로우 관리 기능으로서 AI 에이전트 개발 효율을 높여줍니다 Steering es una habilidad de gestión de flujo de trabajo que permite planificar, realizar un seguimiento y revisar el progreso de tus tareas de desarrollo Steering est une compétence de gestion de flux de travail qui permet de planifier, de suivre et de revoir l''avancement de vos tâches de développement Steering ist eine Workflow-Management-Fähigkeit, die es ermöglicht, den Fortschritt Ihrer Entwicklungsarbeiten zu planen, zu verfolgen und zu überprüfen O Steering é uma habilidade que ajuda a gerenciar workflows de forma eficaz, permitindo que os desenvolvedores planejem, rastreiem e revisem suas tarefas de forma centralizada. ИИ Агент Steering - это навык, который помогает управлять workflow эффективно, позволяя разработчикам планировать, отслеживать и просматривать свои задачи в централизованном режиме. Steering هو مهارة تساعد في إدارة سير العمل بفعالية، مما يسمح للمطورين بالتخطيط والتحديد والمتابعة لعملياتهم بطرق مركزية. how to use steering steering workflow management steering alternative steering vs workflow tools steering install guide steering setup tutorial what is steering steering for AI agents workflow management with steering AIエージェント Steering Skill 任务管理 工作流管理 tasklist.md CLI 命令 AI开发 效率提升 Creates a single source of truth with tasklist.md for progress tracking Utilizes .steering/ directory for storing requirements, designs, and tasks References guide.md for detailed rules and templates Supports requirements, design, and tasklist templates for standardized workflow management Generates output in .steering/<YYYYMMDD>-<slug>/requirement format Steering is a workflow management skill that enables AI agents to plan, track, and review tasks using a structured approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hmu332233/playground.playwright-cli/page-compare', 'community', 'hmu332233', 'playground.playwright-cli', 'hmu332233/playground.playwright-cli', 'page-compare', 0, 0, 30, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:45.699Z', '51adf7174374c7dae8403f1b01d123970e631ee3694fc3ff287d0a4693d60886', '{"id":"hmu332233/playground.playwright-cli/page-compare","name":"page-compare","description":{"en":"The page-compare skill captures screenshots of web pages and visually compares them to analyze differences, benefiting developers and testers. It utilizes playwright-cli for browser automation.","zh":"page-compare技能是用于比较网页截图的工具，使用Playwright CLI实现网页比较","ja":"page-compareスキルは、Webページのスクリーンショットを比較するツールで、Playwright CLIを使用","ko":"페이지 비교 기능은 웹 페이지의 스크린샷을 비교하는 도구로, Playwright CLI를 사용하여 구현합니다","es":"page-compare es una habilidad que captura pantallas de páginas web y las compara visualmente para analizar diferencias con playwright-cli","fr":"page-compare est une compétence qui capture des écrans de pages web et les compare visuellement pour analyser les différences avec playwright-cli","de":"page-compare ist eine Fähigkeit, die Screenshots von Webseiten erstellt und sie visuell vergleicht, um Unterschiede mit playwright-cli zu analysieren","pt":"O page-compare é uma habilidade que captura screenshots de páginas da web e compara visualmente as diferenças com o Playwright CLI.","ru":"ИИ Агент page-compare - это способность, которая захватывает скриншоты веб-страниц и сравнивает визуальные различия с помощью Playwright CLI.","ar":"page-compare هو مهارة تقوم بالتقاط لقطات شاشة من صفحات الويب ومقارنة الفروق البصرية باستخدام Playwright CLI."},"seo":{"title":{"en":"page-compare: Visual Page Comparison Setup Guide | AI Age...","zh":"页面比较工具设置指南 - 使用Playwright CLI","ja":"ページ比較ツールのベストプラクティス - Playwright CLIを使用","ko":"페이지 비교 기능 설정 가이드 - Playwright CLI 사용","es":"Guía de configuración de page-compare para análisis visual","fr":"Guide d''installation de page-compare pour comparaison vis...","de":"Einrichtungsleitfaden für page-compare zur visuellen Analyse","pt":"Guia de Configuração do page-compare: Comparação de Págin...","ru":"Настройка ИИ Агента page-compare: Сравнение Веб-страниц","ar":"دليل إعداد page-compare: مقارنة صفحات الويب"},"description":{"en":"Discover how to visually compare web pages with page-compare. Learn to capture screenshots and analyze differences with playwright-cli. Get started now!","zh":"使用page-compare技能，快速比较网页截图，发现差异。了解如何使用Playwright CLI实现网页比较","ja":"page-compareスキルを使用して、Webページのスクリーンショットを比較し、差異を検出。Playwright CLIの使用方法を学ぶ","ko":"page-compare 기능을 사용하여 웹 페이지의 스크린샷을 비교하고 차이점을 분석합니다. Playwright CLI 사용법을 알아보세요","es":"Aprende a configurar page-compare para comparar visualmente páginas web y analizar diferencias con playwright-cli","fr":"Découvrez comment installer page-compare pour comparer visuellement des pages web et analyser les différences avec playwright-cli","de":"Erfahren Sie, wie Sie page-compare einrichten, um Webseiten visuell zu vergleichen und Unterschiede mit playwright-cli zu analysieren","pt":"Aprenda a configurar o page-compare para comparar páginas da web e detectar diferenças visuais com o Playwright CLI","ru":"Узнайте, как настроить ИИ Агент page-compare для сравнения веб-страниц и обнаружения визуальных различий с помощью Playwright CLI","ar":"تعلم كيفية إعداد page-compare لمقارنة صفحات الويب واكتشاف الفروق البصرية باستخدام Playwright CLI"},"definition":{"en":"page-compare is a skill that captures and compares screenshots of web pages to identify visual differences using playwright-cli.","zh":"page-compare是AIエージェント中的一个技能，用于比较网页截图","ja":"page-compareは、AIエージェントのスキルの一つで、Webページのスクリーンショットを比較する","ko":"페이지 비교는 AI 도구의 기능 중 하나로, 웹 페이지의 스크린샷을 비교합니다","es":"page-compare es una herramienta de análisis visual que compara páginas web mediante screenshots","fr":"page-compare est un outil d''analyse visuelle qui compare des pages web à l''aide de captures d''écran","de":"page-compare ist ein Tool für visuelle Analyse, das Webseiten mithilfe von Screenshots vergleicht","pt":"O page-compare é uma ferramenta que compara páginas da web capturando screenshots e analisando diferenças visuais.","ru":"ИИ Агент page-compare - это инструмент, который сравнивает веб-страницы, захватывая скриншоты и анализируя визуальные различия.","ar":"page-compare هو أداة تقارن صفحات الويب عن طريق التقاط لقطات شاشة وتحليل الفروق البصرية."},"features":{"en":["Captures screenshots of web pages using playwright-cli","Visually compares screenshots to analyze differences","Supports multiple URL inputs for comparison","Utilizes playwright-cli open command for browser automation","Executes playwright-cli goto command for page navigation","Takes screenshots using playwright-cli screenshot command"],"zh":["使用Playwright CLI打开浏览器","支持多个URL的截图比较","可以使用/playwright-cli open命令打开浏览器","支持/playwright-cli goto命令跳转到指定URL","可以使用/playwright-cli screenshot命令捕获截图"],"ja":["Playwright CLIを使用してブラウザを開く","複数のURLのスクリーンショット比較をサポート","/playwright-cli openコマンドを使用してブラウザを開く","/playwright-cli gotoコマンドを使用して指定のURLに遷移","/playwright-cli screenshotコマンドを使用してスクリーンショットをキャプチャ"],"ko":["Playwright CLI를 사용하여 브라우저를 엽니다","여러 URL의 스크린샷 비교를 지원합니다","/playwright-cli open 명령으로 브라우저를 엽니다","/playwright-cli goto 명령으로 지정된 URL로 이동합니다","/playwright-cli screenshot 명령으로 스크린샷을 캡처합니다"],"es":["Captura de pantallas de páginas web con playwright-cli","Comparación visual de páginas web para analizar diferencias","Soporte para múltiples URLs en una sola ejecución","Uso de playwright-cli para abrir el navegador y capturar pantallas","Análisis de diferencias entre páginas web mediante screenshots"],"fr":["Capture d''écrans de pages web avec playwright-cli","Comparaison visuelle de pages web pour analyser les différences","Prise en charge de plusieurs URL en une seule exécution","Utilisation de playwright-cli pour ouvrir le navigateur et capturer des écrans","Analyse des différences entre les pages web à l''aide de captures d''écran"],"de":["Erstellung von Screenshots von Webseiten mit playwright-cli","Visueller Vergleich von Webseiten zur Analyse von Unterschieden","Unterstützung für mehrere URLs in einem einzigen Durchlauf","Verwendung von playwright-cli zum Öffnen des Browsers und Erstellen von Screenshots","Analyse von Unterschieden zwischen Webseiten mithilfe von Screenshots"],"pt":["Captura de screenshots de páginas da web com Playwright CLI","Comparação visual de diferenças entre páginas","Suporte a múltiplas URLs para comparação","Uso de comandos CLI para execução de tarefas","Análise de diferenças visuais entre páginas da web"],"ru":["Захват скриншотов веб-страниц с помощью Playwright CLI","Визуальное сравнение различий между страницами","Поддержка нескольких URL-адресов для сравнения","Использование команд CLI для выполнения задач","Анализ визуальных различий между веб-страницами"],"ar":["التقاط لقطات شاشة من صفحات الويب باستخدام Playwright CLI","مقارنة بصرية للفروق بين الصفحات","دعم العديد من عناوين URL للمقارنة","استخدام أوامر CLI لتنفيذ المهام","تحليل الفروق البصرية بين صفحات الويب"]},"keywords":{"en":["how to use page-compare","page-compare setup guide","visual page comparison tool","playwright-cli tutorial","page-compare alternative","page-compare vs selenium","page-compare install","web page comparison techniques"],"zh":["页面比较工具","Playwright CLI","网页截图比较","AIエージェント","页面比较设置","Playwright CLI使用","网页比较工具"],"ja":["ページ比較ツール","Playwright CLI","Webページのスクリーンショット比較","AIエージェント","ページ比較設定","Playwright CLIの使用","Webページ比較ツール"],"ko":["페이지 비교 기능","Playwright CLI","웹 페이지의 스크린샷 비교","AI 도구","페이지 비교 설정","Playwright CLI 사용","웹 페이지 비교 도구"],"es":["page-compare","análisis visual de páginas web","playwright-cli","captura de pantallas","comparación de páginas web","herramientas de análisis de página","desarrollo web","pruebas de página"],"fr":["page-compare","analyse visuelle de pages web","playwright-cli","capture d''écran","comparaison de pages web","outils d''analyse de page","développement web","tests de page"],"de":["page-compare","visuelle Analyse von Webseiten","playwright-cli","Screenshot","Vergleich von Webseiten","Tools für Seitenanalyse","Webentwicklung","Seitentests"],"pt":["page-compare","comparação de páginas da web","Playwright CLI","captura de screenshots","análise de diferenças visuais","desenvolvimento web","ferramentas de desenvolvimento"],"ru":["ИИ Агент page-compare","сравнение веб-страниц","Playwright CLI","захват скриншотов","анализ визуальных различий","веб-разработка","инструменты для разработки"],"ar":["page-compare","مقارنة صفحات الويب","Playwright CLI","التقاط لقطات شاشة","تحليل الفروق البصرية","تطوير الويب","أدوات التطوير"]}},"owner":"hmu332233","repo":"playground.playwright-cli","repoPath":"hmu332233/playground.playwright-cli","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.315Z","topics":[],"category":"community","skillMd":{"name":"page-compare","description":"여러 웹 페이지의 스크린샷을 찍어 시각적으로 동일한지 비교. 페이지 비교, 디자인 비교, 시각적 차이 확인 시 사용.","bodyPreview":"# page-compare Skill\n\n웹 페이지들의 스크린샷을 찍고 시각적으로 비교하여 차이점을 분석합니다.\n\n## 사용법\n\n```\n/page-compare <URL1> <URL2> [URL3] ...\n```\n\n**예시:**\n```\n/page-compare https://playground-playwright-cli.vercel.app/page-a.html https://playground-playwright-cli.vercel.app/page-b.html https://playground-playwright-cli.vercel.app/page-c.html\n```\n\n## 동작 방식\n\n1. **브라우저 실행**: `playwright-cli open` 명령으로 브라우저를 엽니다.\n\n2. **각 페이지 스크린샷 캡처**:\n   - 각 URL에 대해:\n     - `playwright-cli goto <URL>` 로 페이지 이동\n     - `playwright-cli screensho","body":"# page-compare Skill\n\n웹 페이지들의 스크린샷을 찍고 시각적으로 비교하여 차이점을 분석합니다.\n\n## 사용법\n\n```\n/page-compare <URL1> <URL2> [URL3] ...\n```\n\n**예시:**\n```\n/page-compare https://playground-playwright-cli.vercel.app/page-a.html https://playground-playwright-cli.vercel.app/page-b.html https://playground-playwright-cli.vercel.app/page-c.html\n```\n\n## 동작 방식\n\n1. **브라우저 실행**: `playwright-cli open` 명령으로 브라우저를 엽니다.\n\n2. **각 페이지 스크린샷 캡처**:\n   - 각 URL에 대해:\n     - `playwright-cli goto <URL>` 로 페이지 이동\n     - `playwright-cli screenshot --full-page --filename=page-N.png` 로 전체 페이지 스크린샷 저장\n     - N은 1부터 시작하는 순번\n\n3. **브라우저 종료**: `playwright-cli close` 로 브라우저를 닫습니다.\n\n4. **이미지 비교 분석**:\n   - `Read` 도구로 각 스크린샷 이미지 파일을 읽습니다.\n   - Claude의 멀티모달 능력을 활용하여 시각적 차이를 분석합니다.\n\n5. **결과 리포트 제공**:\n   - 페이지들이 시각적으로 동일한지 또는 다른지 판단\n   - 차이점이 있다면 구체적으로 설명 (레이아웃, 색상, 텍스트, 이미지 등)\n   - 각 페이지의 주요 특징 요약\n\n## 지시사항\n\n사용자가 이 skill을 호출하면:\n\n1. 제공된 URL 목록을 파싱합니다.\n2. playwright-cli로 브라우저를 열고 각 URL의 스크린샷을 캡처합니다.\n3. 모든 스크린샷 이미지를 읽어서 시각적으로 비교합니다.\n4. 다음 형식으로 결과를 보고합니다:\n\n```\n## 페이지 비교 결과\n\n### 캡처된 페이지\n- 페이지 1: <URL1>\n- 페이지 2: <URL2>\n- 페이지 3: <URL3> (있는 경우)\n\n### 시각적 비교 분석\n[각 페이지의 주요 시각적 특징 설명]\n\n### 동일성 판단\n- **결과**: 동일함 / 차이 있음\n- **차이점** (있는 경우):\n  - 레이아웃: [설명]\n  - 색상/스타일: [설명]\n  - 콘텐츠: [설명]\n  - 기타: [설명]\n\n### 요약\n[전체 비교 결과 요약]\n```\n\n## 참고사항\n\n- 스크린샷은 현재 작업 디렉토리에 저장됩니다.\n- `--full-page` 옵션을 사용하여 페이지 전체를 캡처합니다 (viewport만이 아닌).\n- 페이지 로딩 시간을 고려하여 스크린샷 전에 충분한 대기 시간을 둘 수 있습니다.\n- 동적 콘텐츠(애니메이션, 타임스탬프 등)로 인한 사소한 차이는 무시하고 주요 시각적 차이에 집중합니다.\n"},"lastSynced":"2026-03-08T02:02:45.699Z","agentAnalysis":{"suitability":{"en":"Perfect for Web Automation Agents needing visual comparison of web pages.","zh":"适合需要对网页进行视觉比较的 Web 自动化代理。","ja":"Web 自動化エージェントが Web ページの視覚的な比較を必要とする場合に最適です。","ko":"웹 자동화 에이전트가 웹 페이지의 시각적 비교를 필요로 하는 경우에 적합합니다.","es":"Ideal para Agentes de Automatización Web que necesitan comparación visual de páginas web.","fr":"Parfait pour les Agents d''Automatisation Web ayant besoin de comparaison visuelle de pages Web.","de":"Perfekt für Web-Automatisierungsagenten, die eine visuelle Vergleich von Webseiten benötigen.","pt":"Perfeito para Agentes de Automação da Web que necessitam de comparação visual de páginas da web.","ru":"Идеально подходит для веб-агентов автоматизации, которым требуется визуальное сравнение веб-страниц.","ar":"مثالي للوكلاء الآليين للويب الذين يحتاجون إلى مقارنة بصرية للصفحات الإلكترونية."},"recommendation":{"en":"Empowers agents to visually compare web pages using playwright-cli for browser automation, capturing screenshots and analyzing differences via visual inspection, enabling efficient debugging and testing of web applications using protocols like HTTP and HTML.","zh":"通过 playwright-cli 实现浏览器自动化，捕获屏幕截图并通过视觉检查分析差异，实现使用 HTTP 和 HTML 等协议的 Web 应用程序的高效调试和测试。","ja":"playwright-cli を使用してブラウザの自動化を実現し、スクリーンショットをキャプチャして視覚的な検査で差異を分析し、HTTP や HTML などのプロトコルを使用する Web アプリケーションの効率的なデバッグとテストを可能にします。","ko":"playwright-cli를 사용하여 브라우저 자동화를 구현하고, 스크린샷을 캡처하여 시각적 검사로 차이를 분석하여 HTTP 및 HTML等의 프로토콜을 사용하는 웹 애플리케이션의 효율적인 디버깅과 테스트를 가능하게 합니다.","es":"Habilita a los agentes a comparar visualmente páginas web utilizando playwright-cli para automatización de navegador, capturando capturas de pantalla y analizando diferencias a través de inspección visual, lo que permite una depuración y prueba eficientes de aplicaciones web utilizando protocolos como HTTP y HTML.","fr":"Permet aux agents de comparer visuellement des pages Web en utilisant playwright-cli pour l''automatisation du navigateur, en capturant des captures d''écran et en analysant les différences via l''inspection visuelle, ce qui permet un débogage et des tests efficaces d''applications Web utilisant des protocoles tels que HTTP et HTML.","de":"Ermöglicht es den Agenten, Webseiten visuell mithilfe von playwright-cli für Browserautomatisierung zu vergleichen, Screenshots zu erfassen und Unterschiede durch visuelle Inspektion zu analysieren, wodurch eine effiziente Fehlersuche und Tests von Webanwendungen unter Verwendung von Protokollen wie HTTP und HTML ermöglicht werden.","pt":"Habilita os agentes a comparar visualmente as páginas da web usando o playwright-cli para automação de navegador, capturando telas e analisando as diferenças por meio de inspeção visual, permitindo depuração e teste eficientes de aplicações da web usando protocolos como HTTP e HTML.","ru":"Предоставляет агентам возможность визуально сравнивать веб-страницы с помощью playwright-cli для автоматизации браузера, захвата экранов и анализа различий посредством визуального осмотра, обеспечивая эффективную отладку и тестирование веб-приложений с использованием протоколов HTTP и HTML.","ar":"تمكين الوكلاء من مقارنة الصفحات الإلكترونية بصرِيًّا باستخدام playwright-cli للتحكم التلقائي في المتصفح، وتصوير الشاشات وتحليل الفروق من خلال التفتيش البصري، مما يُمكّن من تصحيح الأخطاء واختبار التطبيقات الإلكترونية بفعالية باستخدام بروتوكولات مثل HTTP و HTML."},"useCases":{"en":["Automating visual regression testing","Debugging web page layout issues","Comparing web page updates across different environments"],"zh":["自动化视觉回归测试","调试网页布局问题","比较不同环境下的网页更新"],"ja":["視覚的回帰テストの自動化","Web ページのレイアウトの問題のデバッグ","異なる環境での Web ページの更新の比較"],"ko":["시각적 회귀 테스트의 자동화","웹 페이지 레이아웃 문제의 디버깅","다른 환경下的 웹 페이지 업데이트 비교"],"es":["Automatización de pruebas de regresión visual","Depuración de problemas de diseño de página web","Comparación de actualizaciones de páginas web en diferentes entornos"],"fr":["Automatisation des tests de régression visuelle","Débogage des problèmes de disposition de page Web","Comparaison des mises à jour de pages Web dans différents environnements"],"de":["Automatisierung von visuellen RegressionsTests","Fehlersuche bei Webseiten-Layoutproblemen","Vergleich von Webseiten-Updates in verschiedenen Umgebungen"],"pt":["Automatizar testes de regressão visual","Depurar problemas de layout de página da web","Comparar atualizações de página da web em diferentes ambientes"],"ru":["Автоматизировать визуальное регрессионное тестирование","Отладить проблемы макета веб-страницы","Сравнить обновления веб-страницы в различных средах"],"ar":["التحكم الآلي في اختبارات الانحدار البصري","تصحيح مشاكل تخطيط الصفحة الإلكترونية","مقارنة تحديثات الصفحة الإلكترونية في بيئات مختلفة"]},"limitations":{"en":["Requires playwright-cli installation","Limited to web pages accessible via HTTP/HTTPS"],"zh":["需要安装 playwright-cli","仅限于可以通过 HTTP/HTTPS 访问的网页"],"ja":["playwright-cli のインストールが必要","HTTP/HTTPS でアクセス可能な Web ページのみ"],"ko":["playwright-cli 설치가 필요","HTTP/HTTPS로 접근 가능한 웹 페이지만"],"es":["Requiere instalación de playwright-cli","Limitado a páginas web accesibles a través de HTTP/HTTPS"],"fr":["Nécessite l''installation de playwright-cli","Limité aux pages Web accessibles via HTTP/HTTPS"],"de":["Benötigt die Installation von playwright-cli","Begrenzt auf Webseiten, die über HTTP/HTTPS zugänglich sind"],"pt":["Requer instalação do playwright-cli","Limitado a páginas da web acessíveis via HTTP/HTTPS"],"ru":["Требуется установка playwright-cli","Ограничен для веб-страниц, доступных через HTTP/HTTPS"],"ar":["يتطلب تثبيت playwright-cli","محدود بالصفحات الإلكترونية القابلة للوصول عبر HTTP/HTTPS"]},"version":4},"contentHash":"51adf7174374c7dae8403f1b01d123970e631ee3694fc3ff287d0a4693d60886","qualityScore":30}');
