INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hmu332233/playground.playwright-cli/page-compare', 'page-compare', 'hmu332233', 'playground.playwright-cli', 'community', 'page-compare hmu332233 playground.playwright-cli community The page-compare skill captures screenshots of web pages and visually compares them to analyze differences, benefiting developers and testers. It utilizes playwright-cli for browser automation. page-compare技能是用于比较网页截图的工具，使用Playwright CLI实现网页比较 page-compareスキルは、Webページのスクリーンショットを比較するツールで、Playwright CLIを使用 페이지 비교 기능은 웹 페이지의 스크린샷을 비교하는 도구로, Playwright CLI를 사용하여 구현합니다 page-compare es una habilidad que captura pantallas de páginas web y las compara visualmente para analizar diferencias con playwright-cli page-compare est une compétence qui capture des écrans de pages web et les compare visuellement pour analyser les différences avec playwright-cli page-compare ist eine Fähigkeit, die Screenshots von Webseiten erstellt und sie visuell vergleicht, um Unterschiede mit playwright-cli zu analysieren O page-compare é uma habilidade que captura screenshots de páginas da web e compara visualmente as diferenças com o Playwright CLI. ИИ Агент page-compare - это способность, которая захватывает скриншоты веб-страниц и сравнивает визуальные различия с помощью Playwright CLI. page-compare هو مهارة تقوم بالتقاط لقطات شاشة من صفحات الويب ومقارنة الفروق البصرية باستخدام Playwright CLI. how to use page-compare page-compare setup guide visual page comparison tool playwright-cli tutorial page-compare alternative page-compare vs selenium page-compare install web page comparison techniques 页面比较工具 Playwright CLI 网页截图比较 AIエージェント 页面比较设置 Playwright CLI使用 网页比较工具 Captures screenshots of web pages using playwright-cli Visually compares screenshots to analyze differences Supports multiple URL inputs for comparison Utilizes playwright-cli open command for browser automation Executes playwright-cli goto command for page navigation Takes screenshots using playwright-cli screenshot command page-compare is a skill that captures and compares screenshots of web pages to identify visual differences using playwright-cli.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('izar/tm_skills/ctm', 'community', 'izar', 'tm_skills', 'izar/tm_skills', 'ctm', 0, 0, 30, '2026-03-08T01:57:15.319Z', '2026-03-08T02:02:57.129Z', '94019a9347fe853cf7354604afb17fe29aea84ecd8eefdbc19d88dfa2308bfc3', '{"id":"izar/tm_skills/ctm","name":"ctm","description":{"en":"The ctm skill helps developers examine business cases and user stories in the context of project baselines and existing threat models to identify security notable events. It benefits developers working with Continuous Threat Modeling.","zh":"CTM 技术是用于持续性威胁建模的 AI エージェント 技术。它可以帮助开发人员识别安全风险","ja":"CTM 技術は、継続的脅威モデルを作成するための AIエージェント 技術です。開発者がセキュリティリスクを識別するのに役立ちます","ko":"CTM 기술은 지속적인 위협 모델링을 위한 AI 에이전트 기술입니다. 개발자가 보안 위험을 식별하는 데 도움이 됩니다","es":"ctm es una habilidad de agente de inteligencia artificial que ayuda con el Modelado de Amenazas Continuo, examinando solicitudes de desarrollo y eventos de negocio para identificar posibles riesgos de seguridad","fr":"ctm est une compétence d''agent d''intelligence artificielle qui aide à la Modélisation de Menaces Continue, en examinant les demandes de développement et les événements commerciaux pour identifier les risques de sécurité potentiels","de":"ctm ist eine Fähigkeit von KI-Agents, die bei der Kontinuierlichen Bedrohungsmodellierung hilft, indem sie Entwicklungsanfragen und Geschäftereignisse auf potenzielle Sicherheitsrisiken hin untersucht","pt":"O CTM é uma habilidade de agente que ajuda na modelagem de ameaças contínua, examinando casos de negócios e histórias de usuário para identificar eventos de segurança notáveis","ru":"CTM - это навык агента, который помогает в постоянной моделировании угроз, анализируя бизнес-кейсы и пользовательские истории для выявления заметных событий безопасности ИИ Агентов","ar":"CTM هو مهارة وسيطة تساعد في نمذجة التهديدات المستمرة، حيث يتم فحص الحالات التجارية والقصص المستخدمة لتحديد أحداث الأمن المهمة للأدوات الذكية"},"seo":{"title":{"en":"ctm: Continuous Threat Modeling Setup Guide | AI Agent Skill","zh":"CTM Setup Guide: 持续性威胁建模","ja":"CTM セットアップガイド: Continuous Threat Modeling","ko":"CTM 설정 가이드: 지속적인 위협 모델링","es":"Guía de Configuración de ctm para Modelado de Amenazas Co...","fr":"Guide de Configuration de ctm pour Modélisation de Menace...","de":"Einrichtungsleitfaden für ctm zur Kontinuierlichen Bedroh...","pt":"Guia de Configuração do CTM: Modelagem de Ameaças Contínua","ru":"Руководство по настройке CTM: Постоянная модель угроз ИИ ...","ar":"دليل إعداد CTM: نمذجة التهديدات المستمرة للأدوات الذكية"},"description":{"en":"Unlock the power of Continuous Threat Modeling with ctm. Learn how to identify security notable events and get started with our expert guide today!","zh":"了解 CTM 技术，提高安全性和合规性。使用 AIエージェント 实现持续性威胁建模","ja":"CTM 技術を使用してセキュリティとコンプライアンスを強化する。AIエージェント を使用した継続的脅威モデルを作成します","ko":"CTM 기술을 사용하여 보안 및 규정 준수를 강화합니다. AI 에이전트를 사용하여 지속적인 위협 모델링을 구현합니다","es":"Aprende a utilizar ctm para identificar eventos de seguridad notables en tus proyectos con nuestra guía paso a paso","fr":"Découvrez comment utiliser ctm pour identifier les événements de sécurité notables dans vos projets avec notre guide étape par étape","de":"Erfahren Sie, wie Sie ctm verwenden, um sicherheitsrelevante Ereignisse in Ihren Projekten mit unserem Schritt-für-Schritt-Leitfaden zu identifizieren","pt":"Aprenda a implementar o CTM para melhorar a segurança do seu projeto com nossa guia passo a passo","ru":"Узнайте, как реализовать CTM для повышения безопасности вашего проекта с нашей пошаговой инструкцией ИИ Агентов","ar":"تعرف على كيفية تنفيذ CTM لتحسين أمن مشروعك مع دليلنا المفصل للأدوات الذكية"},"definition":{"en":"ctm is a skill that enables Continuous Threat Modeling by examining business cases and user stories to identify security notable events according to a baseline threat model.","zh":"CTM 是一种持续性威胁建模技术，用于识别安全风险","ja":"CTM は、セキュリティリスクを識別するための継続的脅威モデル技術です","ko":"CTM 은 보안 위험을 식별하기 위한 지속적인 위협 모델링 기술입니다","es":"ctm es una habilidad de agente que aplica el Modelado de Amenazas Continuo para identificar eventos de seguridad notables en proyectos","fr":"ctm est une compétence d''agent qui applique la Modélisation de Menaces Continue pour identifier les événements de sécurité notables dans les projets","de":"ctm ist eine Fähigkeit von KI-Agents, die die Kontinuierliche Bedrohungsmodellierung anwendet, um sicherheitsrelevante Ereignisse in Projekten zu identifizieren","pt":"O que é CTM? É uma habilidade de agente que examina casos de negócios e histórias de usuário para identificar eventos de segurança notáveis","ru":"Что такое CTM? Это навык агента, который анализирует бизнес-кейсы и пользовательские истории для выявления заметных событий безопасности ИИ Агентов","ar":"ما هو CTM؟ هو مهارة وسيطة تفحص الحالات التجارية والقصص المستخدمة لتحديد أحداث الأمن المهمة للأدوات الذكية"},"features":{"en":["Uses a security notable event checklist to track progress","Enriches development requests with relevant threat model data","Utilizes the CTM Developer Checklist for comprehensive analysis","Examines business cases in the context of project baselines","Identifies security notable events according to a baseline threat model","Supports copying and tracking of the security notable event checklist"],"zh":["使用安全显著事件检查表","找到基线威胁模型","丰富请求","使用 CTM 开发人员检查表"],"ja":["セキュリティ ノタブル イベント チェックリストを使用","基線脅威モデルを見つける","リクエストを豊富にする","CTM 開発者チェックリストを使用"],"ko":["보안显著 이벤트 체크리스트 사용","기반선 위협 모델찾기","요청丰富","CTM 개발자 체크리스트 사용"],"es":["Identificación de eventos de seguridad notables utilizando la lista de verificación de seguridad","Enriquecimiento de solicitudes de desarrollo con información de seguridad","Uso de la lista de verificación de CTM para evaluar riesgos de seguridad","Integración con modelos de amenazas existentes para una evaluación de seguridad completa","Análisis de eventos de negocio y solicitudes de desarrollo para identificar posibles riesgos de seguridad"],"fr":["Identification d''événements de sécurité notables à l''aide de la liste de vérification de sécurité","Enrichissement des demandes de développement avec des informations de sécurité","Utilisation de la liste de vérification de CTM pour évaluer les risques de sécurité","Intégration avec des modèles de menaces existants pour une évaluation de sécurité complète","Analyse d''événements commerciaux et de demandes de développement pour identifier les risques de sécurité potentiels"],"de":["Identifizierung sicherheitsrelevanter Ereignisse mit der Sicherheits-Checkliste","Anreicherung von Entwicklungsanfragen mit Sicherheitsinformationen","Verwendung der CTM-Checkliste zur Bewertung von Sicherheitsrisiken","Integration mit bestehenden Bedrohungsmodellen für eine umfassende Sicherheitsbewertung","Analyse von Geschäftereignissen und Entwicklungsanfragen zur Identifizierung potenzieller Sicherheitsrisiken"],"pt":["Análise de casos de negócios e histórias de usuário","Identificação de eventos de segurança notáveis","Utilização do CTM Developer Checklist","Enriquecimento de solicitações de desenvolvimento","Integração com modelos de ameaças base"],"ru":["Анализ бизнес-кейсов и пользовательских историй","Выявление заметных событий безопасности","Использование списка разработчика CTM","Обогащение запросов разработки","Интеграция с базовыми моделями угроз ИИ Агентов"],"ar":["تحليل الحالات التجارية والقصص المستخدمة","تحديد أحداث الأمن المهمة","استخدام قائمة مطور CTM","تحسين طلبات التطوير","دمج مع نماذج التهديدات الأساسية للأدوات الذكية"]},"keywords":{"en":["how to use ctm","what is ctm","ctm vs threat modeling","ctm install guide","ctm setup for developers","continuous threat modeling tutorial","ctm alternative solutions","ctm security notable events"],"zh":["CTM 技术","持续性威胁建模","AIエージェント","安全风险","开发人员","基线威胁模型","安全显著事件检查表"],"ja":["CTM 技術","継続的脅威モデル","AIエージェント","セキュリティリスク","開発者","基線脅威モデル","セキュリティ ノタブル イベント チェックリスト"],"ko":["CTM 기술","지속적인 위협 모델링","AI 에이전트","보안 위험","개발자","기반선 위협 모델","보안显著 이벤트 체크리스트"],"es":["ctm","Modelado de Amenazas Continuo","seguridad de la información","evaluación de riesgos","lista de verificación de seguridad","desarrollo de software seguro","seguridad en proyectos","identificación de eventos de seguridad","enriquecimiento de solicitudes de desarrollo"],"fr":["ctm","Modélisation de Menaces Continue","sécurité de l''information","évaluation des risques","liste de vérification de sécurité","développement de logiciels sécurisés","sécurité dans les projets","identification d''événements de sécurité","enrichissement des demandes de développement"],"de":["ctm","Kontinuierliche Bedrohungsmodellierung","Informationssicherheit","Risikobewertung","Sicherheits-Checkliste","sichere Software-Entwicklung","Sicherheit in Projekten","Identifizierung sicherheitsrelevanter Ereignisse","Anreicherung von Entwicklungsanfragen"],"pt":["CTM","Modelagem de Ameaças Contínua","Segurança de Projeto","Desenvolvimento de Software","Análise de Casos de Negócios","Identificação de Eventos de Segurança"],"ru":["CTM","Постоянная модель угроз","Безопасность проекта","Разработка программного обеспечения","Анализ бизнес-кейсов","Выявление заметных событий безопасности ИИ Агентов"],"ar":["CTM","نمذجة التهديدات المستمرة","أمن المشروع","تطوير البرمجيات","تحليل الحالات التجارية","تحديد أحداث الأمن المهمة للأدوات الذكية"]}},"owner":"izar","repo":"tm_skills","repoPath":"izar/tm_skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.319Z","topics":[],"category":"community","skillMd":{"name":"ctm","description":"examine a given development story and decide if it has security value that warrants inclusion in a threat model","bodyPreview":"## Overview\n\nGiven a business case, a user-story, a development request or similar, examine it in the context of the project and the existing baseline threat model and decide if it is a \"security notable event\" according to Continuous Threat Modeling.\n\n## Method\n Copy this checklist and track your progress:\n\n````\nSecurity notable event checklist\n\n- [ ] Find a baseline threat model\n- [ ] Enrich the request\n- [ ] Use the CTM Developer Checklist\n````\n\n**Step 1: Find a baseline threat model\n\nExamine","body":"## Overview\n\nGiven a business case, a user-story, a development request or similar, examine it in the context of the project and the existing baseline threat model and decide if it is a \"security notable event\" according to Continuous Threat Modeling.\n\n## Method\n Copy this checklist and track your progress:\n\n````\nSecurity notable event checklist\n\n- [ ] Find a baseline threat model\n- [ ] Enrich the request\n- [ ] Use the CTM Developer Checklist\n````\n\n**Step 1: Find a baseline threat model\n\nExamine the project''s directory for documentation that resembles a threat model. If one is found, use that as the baseline threat model. \nIf one is not found, ask the user if they would like to use the pytm skill to create one, or if they can provide a baseline threat model. Give the user the option to not have a baseline threat model but point out the quality of the analysis will be diminished.\n\n**Step 2: Enrich the request\n\nIf a baseline threat model is available, use it to enrich the corpus of the request. \nFeel free to ask the user as many elucidative questions about the request as you consider necessary. Use the answers to enrich the request.\n\n**Step 3: Use the CTM Developer Checklist\n\nUsing the content of ./Secure_Developer_Checklist.md try to identify in the user request instances that match the \"If you did THIS ...\" side of the reference table. If matches are found, use the \"... then do THAT\" respective field to suggest mitigations to the issue identified.\n\nThere can be many matches in any given request. Return all those matches.\n\nIf there are notable events, suggest to the user that a ticket be created reflecting this change so the threat model can be updated.\n\n\n"},"lastSynced":"2026-03-08T02:02:57.129Z","agentAnalysis":{"suitability":{"en":"Perfect for Security Analysis Agents needing advanced threat modeling capabilities for Continuous Threat Modeling (CTM)","zh":"非常适合需要高级威胁建模能力的安全分析代理进行持续威胁建模 (CTM)","ja":"セキュリティ分析エージェントが高度な脅威モデリング機能を必要とする継続的脅威モデリング (CTM) に最適","ko":"고급 위협 모델링 기능을 필요로 하는 보안 분석 에이전트에게 적합한 연속적인 위협 모델링 (CTM)","es":"Ideal para Agentes de Análisis de Seguridad que necesitan capacidades avanzadas de modelado de amenazas para Continuous Threat Modeling (CTM)","fr":"Idéal pour les Agents d''Analyse de Sécurité ayant besoin de capacités avancées de modélisation des menaces pour le Continuous Threat Modeling (CTM)","de":"Ideal für Security-Analyse-Agenten, die erweiterte Threat-Modelling-Fähigkeiten für Continuous Threat Modeling (CTM) benötigen","pt":"Perfeito para Agentes de Análise de Segurança que necessitam de capacidades avançadas de modelagem de ameaças para Modelagem de Ameaças Contínua (CTM)","ru":"Идеально подходит для агентов анализа безопасности, которым необходимы продвинутые возможности моделирования угроз для непрерывного моделирования угроз (CTM)","ar":"مثالي للوكلاء تحليل الأمن الذين يحتاجون إلى قدرات متقدمة لطراز التهديدات لطراز التهديدات المستمر (CTM)"},"recommendation":{"en":"Empowers agents to examine business cases and user stories in the context of project baselines and existing threat models, identifying security notable events using CTM Developer Checklists and baseline threat models","zh":"赋予代理检查业务用例和用户故事的能力，并在项目基线和现有威胁模型的背景下识别安全值得注意的事件，使用 CTM 开发人员检查清单和基线威胁模型","ja":"エージェントがプロジェクトベースラインや既存の脅威モデルとの文脈でビジネスケースやユーザーストーリーを調査し、CTM デベロッパーチェックリストやベースライン脅威モデルを使用してセキュリティの重要なイベントを識別することを可能にします","ko":"에이전트가 프로젝트 베이스라인과 기존의 위협 모델의 맥락에서 비즈니스 케이스와 사용자 스토리를 조사하고 CTM 개발자 체크리스트와 베이스라인 위협 모델을 사용하여 보안의 주목할만한 이벤트를 식별하는 것을 가능하게 함","es":"Permite a los agentes examinar casos de negocio y user stories en el contexto de los project baselines y los modelos de amenazas existentes, identificando security notable events mediante CTM Developer Checklists y baseline threat models","fr":"Permet aux agents d''examiner les business cases et les user stories dans le contexte des project baselines et des modèles de menaces existants, en identifiant les security notable events à l''aide des CTM Developer Checklists et des baseline threat models","de":"Ermöglicht es Agenten, business cases und user stories im Kontext von project baselines und bestehenden Threat-Models zu prüfen, indem sie security notable events mit CTM Developer Checklists und baseline threat models identifizieren","pt":"Habilita os agentes a examinarem casos de negócios e histórias de usuário no contexto das linhas de base do projeto e modelos de ameaça existentes, identificando eventos notáveis de segurança usando Listas de Verificação do Desenvolvedor CTM e modelos de ameaça de linha de base","ru":"Наделяет агентов возможностью изучать бизнес-кейсы и истории пользователей в контексте базовых проектов и существующих моделей угроз, выявляя заметные события безопасности с помощью контрольных списков разработчика CTM и базовых моделей угроз","ar":"يمنح الوكلاء القدرة على فحص الحالات التجارية وقصص المستخدمين في سياق خطوط قاعدة المشروع ونماذج التهديدات الحالية، وتحديد أحداث الأمان الملحوظة باستخدام قوائم التحقق من مطور CTM ونماذج التهديدات الأساسية"},"useCases":{"en":["Automating security notable event detection","Enriching development requests with threat model context","Validating user stories against project baselines"],"zh":["自动化安全值得注意的事件检测","用威胁模型上下文丰富开发请求","验证用户故事与项目基线"],"ja":["セキュリティの重要なイベントの検出を自動化する","脅威モデルのコンテキストを使用して開発リクエストを強化する","ユーザーストーリーをプロジェクトベースラインに対して検証する"],"ko":["보안의 주목할만한 이벤트 감지를 자동화하는 것","위협 모델의 맥락을 사용하여 개발 요청을 강화하는 것","사용자 스토리를 프로젝트 베이스라인에 대해 검증하는 것"],"es":["Automatización de la detección de security notable events","Enriquecimiento de solicitudes de desarrollo con contexto de threat model","Validación de user stories con respecto a project baselines"],"fr":["Automatisation de la détection des security notable events","Enrichissement des demandes de développement avec un contexte de threat model","Validation des user stories par rapport aux project baselines"],"de":["Automatisierung der Erkennung von security notable events","Anreicherung von Entwicklungsanfragen mit Threat-Model-Kontext","Validierung von user stories anhand von project baselines"],"pt":["Automatizar a detecção de eventos notáveis de segurança","Enriquecer solicitações de desenvolvimento com contexto de modelo de ameaça","Validar histórias de usuário contra linhas de base do projeto"],"ru":["Автоматизировать обнаружение заметных событий безопасности","Обогащать запросы разработки контекстом модели угроз","Проверять истории пользователей против базовых проектов"],"ar":["تأتمة الكشف عن أحداث الأمان الملحوظة","تعزيز طلبات التطوير بالسياق نموذج التهديد","التحقق من قصص المستخدمين ضد خطوط قاعدة المشروع"]},"limitations":{"en":["Requires existing baseline threat model","Limited to Continuous Threat Modeling (CTM) framework"],"zh":["需要现有的基线威胁模型","仅限于持续威胁建模 (CTM) 框架"],"ja":["既存のベースライン脅威モデルが必要","継続的脅威モデリング (CTM) フレームワークに限定される"],"ko":["기존의 베이스라인 위협 모델이 필요","연속적인 위협 모델링 (CTM) 프레임워크로 제한"],"es":["Requiere un baseline threat model existente","Limitado al framework Continuous Threat Modeling (CTM)"],"fr":["Nécessite un baseline threat model existant","Limité au framework Continuous Threat Modeling (CTM)"],"de":["Erfordert ein bestehendes baseline threat model","Beschränkt auf das Continuous Threat Modeling (CTM) Framework"],"pt":["Requer modelo de ameaça de linha de base existente","Limitado ao framework de Modelagem de Ameaças Contínua (CTM)"],"ru":["Требуется существующая базовая модель угроз","Ограничен до фреймворка непрерывного моделирования угроз (CTM)"],"ar":["يتطلب نموذج تهديد أساسي موجود","محدود إلى إطار عمل نمذجة التهديدات المستمر (CTM)"]},"version":4},"contentHash":"94019a9347fe853cf7354604afb17fe29aea84ecd8eefdbc19d88dfa2308bfc3","qualityScore":30}');
