INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('izar/tm_skills/ctm', 'ctm', 'izar', 'tm_skills', 'community', 'ctm izar tm_skills community The ctm skill helps developers examine business cases and user stories in the context of project baselines and existing threat models to identify security notable events. It benefits developers working with Continuous Threat Modeling. CTM 技术是用于持续性威胁建模的 AI エージェント 技术。它可以帮助开发人员识别安全风险 CTM 技術は、継続的脅威モデルを作成するための AIエージェント 技術です。開発者がセキュリティリスクを識別するのに役立ちます CTM 기술은 지속적인 위협 모델링을 위한 AI 에이전트 기술입니다. 개발자가 보안 위험을 식별하는 데 도움이 됩니다 ctm es una habilidad de agente de inteligencia artificial que ayuda con el Modelado de Amenazas Continuo, examinando solicitudes de desarrollo y eventos de negocio para identificar posibles riesgos de seguridad ctm est une compétence d''agent d''intelligence artificielle qui aide à la Modélisation de Menaces Continue, en examinant les demandes de développement et les événements commerciaux pour identifier les risques de sécurité potentiels ctm ist eine Fähigkeit von KI-Agents, die bei der Kontinuierlichen Bedrohungsmodellierung hilft, indem sie Entwicklungsanfragen und Geschäftereignisse auf potenzielle Sicherheitsrisiken hin untersucht O CTM é uma habilidade de agente que ajuda na modelagem de ameaças contínua, examinando casos de negócios e histórias de usuário para identificar eventos de segurança notáveis CTM - это навык агента, который помогает в постоянной моделировании угроз, анализируя бизнес-кейсы и пользовательские истории для выявления заметных событий безопасности ИИ Агентов CTM هو مهارة وسيطة تساعد في نمذجة التهديدات المستمرة، حيث يتم فحص الحالات التجارية والقصص المستخدمة لتحديد أحداث الأمن المهمة للأدوات الذكية how to use ctm what is ctm ctm vs threat modeling ctm install guide ctm setup for developers continuous threat modeling tutorial ctm alternative solutions ctm security notable events CTM 技术 持续性威胁建模 AIエージェント 安全风险 开发人员 基线威胁模型 安全显著事件检查表 Uses a security notable event checklist to track progress Enriches development requests with relevant threat model data Utilizes the CTM Developer Checklist for comprehensive analysis Examines business cases in the context of project baselines Identifies security notable events according to a baseline threat model Supports copying and tracking of the security notable event checklist ctm is a skill that enables Continuous Threat Modeling by examining business cases and user stories to identify security notable events according to a baseline threat model.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heddxh/NeoDB-You/compose-preview', 'community', 'heddxh', 'NeoDB-You', 'heddxh/NeoDB-You', 'compose-preview', 0, 0, 30, '2026-03-08T01:57:15.325Z', '2026-03-08T02:03:01.535Z', '1a2abd151c0721e7ccc83065e200e6ae2113d986d9247e626a4a0dd57c69091a', '{"id":"heddxh/NeoDB-You/compose-preview","name":"compose-preview","description":{"en":"compose-preview is a native Android app for NeoDB that creates previews for Jetpack Compose functions. It benefits Android developers using Jetpack Compose and Material 3.","zh":"Compose Preview 是一个 Jetpack Compose 函数的预览工具，帮助开发者优化 UI 设计","ja":"Compose Preview は Jetpack Compose 関数のプレビュー ツールであり、開発者が UI デザインを最適化するのに役立ちます","ko":"Compose Preview는 Jetpack Compose 함수의 미리 보기 도구로서 개발자가 UI 디자인을 최적화하는 데 도움이 됩니다","es":"Compose Preview es una herramienta para crear previews de funciones de Jetpack Compose, permitiendo una mayor personalización y flexibilidad en el desarrollo de aplicaciones Android","fr":"Compose Preview est un outil pour créer des aperçus de fonctions Jetpack Compose, offrant une personnalisation et une flexibilité accrues dans le développement d''applications Android","de":"Compose Preview ist ein Tool zum Erstellen von Vorschauen für Jetpack-Compose-Funktionen, das eine größere Anpassungsfähigkeit und Flexibilität bei der Entwicklung von Android-Anwendungen bietet","pt":"O Compose Preview é uma ferramenta para criar pré-visualizações de componentes Jetpack Compose. Ele oferece uma forma fácil de visualizar e testar componentes antes de implementá-los em um aplicativo","ru":"Compose Preview — это инструмент для создания предварительных просмотров компонентов Jetpack Compose. Он предоставляет простой способ просмотра и тестирования компонентов перед их реализацией в приложении с помощью ИИ Агентов","ar":"Compose Preview هو أداة لإنشاء معاينة لمكونات Jetpack Compose. يقدم وسيلة سهلة للعرض واختبار المكونات قبل تنفيذها في التطبيق"},"seo":{"title":{"en":"compose-preview: Jetpack Compose Setup Guide | AI Agent S...","zh":"Compose Preview 设置指南：Jetpack Compose 预览功能","ja":"Compose Preview セットアップガイド：Jetpack Compose プレビュー機能","ko":"Compose Preview 설정 가이드: Jetpack Compose预览 기능","es":"Guía de configuración de Compose Preview para Jetpack Com...","fr":"Guide de mise en place de Compose Preview pour Jetpack Co...","de":"Einrichtungsleitfaden für Compose Preview mit Jetpack Com...","pt":"Guia de Configuração do Compose Preview para Desenvolvedores","ru":"Настройка Compose Preview: Руководство для разработчиков ...","ar":"دليل إعداد Compose Preview لمنشئي التطبيقات الذكية"},"description":{"en":"Discover how to create previews for Jetpack Compose functions with compose-preview. Learn how to use @Preview annotations and more!","zh":"了解 Compose Preview 的基本用法和 @Preview 注解参数，优化您的 Jetpack Compose 开发体验","ja":"Compose Preview の基本的な使い方と @Preview アノテーションのパラメータを理解し、Jetpack Compose 開発体験を最適化する","ko":"Compose Preview의 기본 사용법과 @Preview 注解 매개변수를 알아보고 Jetpack Compose 개발 경험을 최적화하십시오","es":"Descubre cómo crear previews personalizados para tus funciones de Jetpack Compose con Compose Preview y mejora tu experiencia de desarrollo","fr":"Découvrez comment créer des aperçus personnalisés pour vos fonctions Jetpack Compose avec Compose Preview et améliorez votre expérience de développement","de":"Erfahren Sie, wie Sie benutzerdefinierte Vorschauen für Ihre Jetpack-Compose-Funktionen mit Compose Preview erstellen und Ihre Entwicklererfahrung verbessern","pt":"Aprenda a configurar o Compose Preview para criar pré-visualizações de componentes Jetpack Compose com facilidade e eficiência","ru":"Откройте для себя, как настроить Compose Preview для создания предварительных просмотров компонентов Jetpack Compose с помощью ИИ Агентов","ar":"اكتشف كيفية配置 Compose Preview لإنشاء معاينة مكونات Jetpack Compose بسهولة وفعالية"},"definition":{"en":"compose-preview is a tool for creating previews of Jetpack Compose functions, utilizing @Preview annotations and Material 3 design.","zh":"Compose Preview 是一个用于创建 Jetpack Compose 函数预览的工具","ja":"Compose Preview は Jetpack Compose 関数のプレビューを作成するためのツールです","ko":"Compose Preview는 Jetpack Compose 함수의 미리 보기를 생성하기 위한 도구입니다","es":"Compose Preview es una función de Jetpack Compose que permite crear vistas previas de componentes de interfaz de usuario","fr":"Compose Preview est une fonctionnalité de Jetpack Compose qui permet de créer des aperçus de composants d''interface utilisateur","de":"Compose Preview ist eine Funktion von Jetpack Compose, die das Erstellen von Vorschauen von Benutzeroberflächenkomponenten ermöglicht","pt":"O que é Compose Preview? É uma ferramenta de pré-visualização para componentes Jetpack Compose","ru":"Что такое Compose Preview? Это инструмент предварительного просмотра для компонентов Jetpack Compose, используемый в разработке с ИИ Агентами","ar":"ما هو Compose Preview؟ هو أداة معاينة لمكونات Jetpack Compose"},"features":{"en":["Creates previews for Jetpack Compose functions using @Preview annotations","Supports Material 3 design for Android apps","Utilizes Jetpack Compose for building native Android apps","Allows customization of preview names using the ''name'' parameter","Enables grouping of previews using the ''group'' parameter"],"zh":["支持 @Preview 注解参数","提供基本用法示例","优化 Jetpack Compose 开发体验","支持 Material 3/You 设计","支持 Jetpack Compose 函数预览"],"ja":["@Preview アノテーションのパラメータをサポート","基本的な使い方の例を提供","Jetpack Compose 開発体験を最適化","Material 3/You デザインをサポート","Jetpack Compose 関数のプレビューをサポート"],"ko":["@Preview 注解 매개변수를 지원","기본 사용법 예제 제공","Jetpack Compose 개발 경험을 최적화","Material 3/You 디자인 지원","Jetpack Compose 함수의 미리 보기를 지원"],"es":["Crea vistas previas personalizadas para tus funciones de Jetpack Compose","Utiliza la anotación @Preview para definir parámetros de vista previa","Establece el nombre y el grupo de la vista previa con los parámetros name y group","Compatibilidad con Material 3 y Jetpack Compose","Desarrollo de aplicaciones Android con una mayor flexibilidad y personalización"],"fr":["Créez des aperçus personnalisés pour vos fonctions Jetpack Compose","Utilisez l''annotation @Preview pour définir les paramètres de l''aperçu","Définissez le nom et le groupe de l''aperçu avec les paramètres name et group","Compatibilité avec Material 3 et Jetpack Compose","Développement d''applications Android avec une flexibilité et une personnalisation accrues"],"de":["Erstellen Sie benutzerdefinierte Vorschauen für Ihre Jetpack-Compose-Funktionen","Verwenden Sie die Annotation @Preview, um Vorschau-Parameter zu definieren","Legen Sie den Namen und die Gruppe der Vorschau mit den Parametern name und group fest","Kompatibilität mit Material 3 und Jetpack Compose","Entwicklung von Android-Anwendungen mit einer größeren Flexibilität und Anpassungsfähigkeit"],"pt":["Criação de pré-visualizações de componentes Jetpack Compose","Suporte à anotação @Preview","Parâmetros personalizáveis, como nome e grupo","Integração com Material 3/You","Desenvolvimento de aplicativos Android com Jetpack Compose"],"ru":["Создание предварительных просмотров компонентов Jetpack Compose","Поддержка аннотации @Preview","Параметры настройки, такие как имя и группа","Интеграция с Material 3/You","Разработка приложений Android с помощью Jetpack Compose и ИИ Агентов"],"ar":["إنشاء معاينة لمكونات Jetpack Compose","دعم التعليمة @Preview","معلمات قابلة للتخصيص، مثل الاسم والمجموعة","التكامل مع Material 3/You","تنمية التطبيقات Android باستخدام Jetpack Compose"]},"keywords":{"en":["how to use compose-preview","compose-preview setup guide","jetpack compose preview","material 3 android app","compose-preview alternative","compose-preview vs jetpack compose","compose-preview install","what is compose-preview"],"zh":["Compose Preview","Jetpack Compose","Material 3/You","AIエージェント","UI 设计","开发工具","Android 开发"],"ja":["Compose Preview","Jetpack Compose","Material 3/You","AIエージェント","UI デザイン","開発ツール","Android 開発"],"ko":["Compose Preview","Jetpack Compose","Material 3/You","AI 에이전트","UI 디자인","개발 도구","Android 개발"],"es":["Compose Preview","Jetpack Compose","Material 3","desarrollo de aplicaciones Android","vistas previas personalizadas","anotación @Preview","parámetros de vista previa","flexibilidad en el desarrollo"],"fr":["Compose Preview","Jetpack Compose","Material 3","développement d''applications Android","aperçus personnalisés","annotation @Preview","paramètres de l''aperçu","flexibilité dans le développement"],"de":["Compose Preview","Jetpack Compose","Material 3","Entwicklung von Android-Anwendungen","benutzerdefinierte Vorschauen","Annotation @Preview","Vorschau-Parameter","Flexibilität bei der Entwicklung"],"pt":["Compose Preview","Jetpack Compose","pré-visualização de componentes","desenvolvimento de aplicativos Android","Material 3/You","anotação @Preview","parâmetros personalizáveis"],"ru":["Compose Preview","Jetpack Compose","предварительный просмотр компонентов","разработка приложений Android","Material 3/You","аннотация @Preview","параметры настройки","ИИ Агенты"],"ar":["Compose Preview","Jetpack Compose","معاينة مكونات","تنمية التطبيقات Android","Material 3/You","التعليمة @Preview","معلمات قابلة للتخصيص","أدوات الذكاء الاصطناعي"]}},"owner":"heddxh","repo":"NeoDB-You","repoPath":"heddxh/NeoDB-You","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.325Z","topics":[],"category":"community","skillMd":{"name":"compose-preview","description":"Creates Compose Preview functions for composables. Use when asked to add preview, create preview, or generate @Preview for Compose UI.","bodyPreview":"# Compose Preview\n\n为 Jetpack Compose 函数创建预览。\n\n## 基本用法\n\n```kotlin\n@Preview\n@Composable\nprivate fun XxxPreview() {\n    AppTheme {\n        Xxx()\n    }\n}\n```\n\n## @Preview 注解参数\n\n| 参数                | 说明              | 示例                                                         |\n|-------------------|-----------------|------------------------------------------------------------|\n| `name`            | 预览名称            | `@Preview(name = \"Dark Mode\")`                             |\n| `group`           | 分组","body":"# Compose Preview\n\n为 Jetpack Compose 函数创建预览。\n\n## 基本用法\n\n```kotlin\n@Preview\n@Composable\nprivate fun XxxPreview() {\n    AppTheme {\n        Xxx()\n    }\n}\n```\n\n## @Preview 注解参数\n\n| 参数                | 说明              | 示例                                                         |\n|-------------------|-----------------|------------------------------------------------------------|\n| `name`            | 预览名称            | `@Preview(name = \"Dark Mode\")`                             |\n| `group`           | 分组名称            | `@Preview(group = \"Buttons\")`                              |\n| `widthDp`         | 宽度 (dp)         | `@Preview(widthDp = 320)`                                  |\n| `heightDp`        | 高度 (dp)         | `@Preview(heightDp = 640)`                                 |\n| `showBackground`  | 显示背景            | `@Preview(showBackground = true)`                          |\n| `backgroundColor` | 背景色 (ARGB Long) | `@Preview(backgroundColor = 0xFFFFFFFF)`                   |\n| `showSystemUi`    | 显示系统 UI         | `@Preview(showSystemUi = true)`                            |\n| `device`          | 设备规格            | `@Preview(device = \"id:pixel_5\")`                          |\n| `uiMode`          | UI 模式           | `@Preview(uiMode = Configuration.UI_MODE_NIGHT_YES)`       |\n| `locale`          | 语言              | `@Preview(locale = \"zh-rCN\")`                              |\n| `fontScale`       | 字体缩放            | `@Preview(fontScale = 1.5f)`                               |\n| `wallpaper`       | 壁纸              | `@Preview(wallpaper = Wallpapers.GREEN_DOMINATED_EXAMPLE)` |\n\n## Multipreview 注解\n\n创建自定义多预览注解以复用配置：\n\n```kotlin\n@Preview(name = \"Light\", uiMode = Configuration.UI_MODE_NIGHT_NO)\n@Preview(name = \"Dark\", uiMode = Configuration.UI_MODE_NIGHT_YES)\nannotation class ThemePreviews\n\n@Preview(name = \"Phone\", device = \"spec:width=411dp,height=891dp\")\n@Preview(name = \"Tablet\", device = \"spec:width=1280dp,height=800dp,dpi=240\")\nannotation class DevicePreviews\n```\n\n使用：\n\n```kotlin\n@ThemePreviews\n@DevicePreviews\n@Composable\nprivate fun MyComponentPreview() {\n    AppTheme {\n        MyComponent()\n    }\n}\n```\n\n## 设备规格\n\n### 预定义设备\n\n- `id:pixel_5`, `id:pixel_fold`, `id:pixel_tablet`\n- `id:wearos_small_round`, `id:wearos_large_round`\n\n### 自定义规格\n\n```kotlin\n@Preview(device = \"spec:width=411dp,height=891dp,dpi=420\")\n@Preview(device = \"spec:width=1280dp,height=800dp,orientation=landscape\")\n```\n\n## 项目约定\n\n1. **Preview 函数命名**: `XxxPreview` 或 `PreviewXxx`\n2. **使用 AppTheme**: 始终用 `AppTheme { }` 包裹预览内容\n3. **私有函数**: Preview 函数应为 `private`\n4. **Mock 数据**: 使用假数据填充预览，不依赖 ViewModel\n5. **放置位置**: 在同一文件中，放在被预览组件下方\n\n## 工作流程\n\n1. 找到需要预览的 Composable 函数\n2. 分析其参数，确定需要的 mock 数据\n3. 在函数下方创建 Preview 函数\n4. 用 `NeoDBYouTheme` 包裹\n5. 根据需要添加多个 `@Preview` 变体（亮/暗主题、不同尺寸等）,大多数情况下Preview不需要参数。\n\n## 示例\n\n### 简单组件预览\n\n```kotlin\n@Composable\nfun Greeting(name: String, modifier: Modifier = Modifier) {\n    Text(text = \"Hello $name!\", modifier = modifier)\n}\n\n@Preview(showBackground = true)\n@Composable\nprivate fun GreetingPreview() {\n    AppTheme {\n        Greeting(\"Android\")\n    }\n}\n```\n\n### 状态变体预览\n\n```kotlin\n@Preview(name = \"Empty\")\n@Preview(name = \"Loading\")\n@Preview(name = \"Content\")\n@Composable\nprivate fun MyScreenPreview() {\n    AppTheme {\n        // 根据需要展示不同状态\n    }\n}\n```\n\n### 亮暗主题预览\n\n```kotlin\n@PreviewLightDark\n@Composable\nprivate fun CardPreview() {\n    AppTheme {\n        MyCard(title = \"Sample\", content = \"Preview content\")\n    }\n}\n```\n"},"lastSynced":"2026-03-08T02:03:01.535Z","agentAnalysis":{"suitability":{"en":"Perfect for Android Development Agents utilizing Jetpack Compose and Material 3 for advanced UI previewing.","zh":"非常适合利用 Jetpack Compose 和 Material 3 进行高级 UI 预览的 Android 开发代理。","ja":"Jetpack Compose と Material 3 を使用した高度な UI プレビューに最適な Android 開発エージェントです。","ko":"Jetpack Compose와 Material 3를 사용한 고급 UI 미리 보기를 위한 안드로이드 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo de Android que utilizan Jetpack Compose y Material 3 para la visualización avanzada de la interfaz de usuario.","fr":"Parfait pour les agents de développement Android utilisant Jetpack Compose et Material 3 pour la prévisualisation avancée de l''interface utilisateur.","de":"Perfekt für Android-Entwicklungsagenten, die Jetpack Compose und Material 3 für die erweiterte Vorschau der Benutzeroberfläche verwenden.","pt":"Perfeito para Agentes de Desenvolvimento Android que utilizam Jetpack Compose e Material 3 para pré-visualização de UI avançada.","ru":"Идеально подходит для агентов разработки Android, использующих Jetpack Compose и Material 3 для расширенного просмотра интерфейса пользователя.","ar":"مثالي للوكلاء الذين يطورون تطبيقات أندرويد باستخدام Jetpack Compose و Material 3 لمعاينة واجهة المستخدم المتقدمة."},"recommendation":{"en":"Empowers agents to generate previews for Jetpack Compose functions, utilizing annotations like @Preview and integrating with Material 3 for enhanced UI design, all within the native Android app NeoDB.","zh":"赋予代理生成 Jetpack Compose 函数的预览，利用 @Preview 等注解，并与 Material 3 集成以增强 UI 设计，所有操作均在本地 Android 应用 NeoDB 中进行。","ja":"エージェントが Jetpack Compose 関数のプレビューを生成できるようにし、@Preview などのアノテーションを使用し、Material 3 と統合して UI デザインを強化し、すべてをネイティブ Android アプリの NeoDB 内で実行します。","ko":"에이전트가 Jetpack Compose 함수의 미리 보기를 생성할 수 있도록 하며, @Preview 등의 주석을 사용하고, Material 3와 통합하여 UI 디자인을 강화하며, 모든 것을 네이티브 안드로이드 앱인 NeoDB 내에서 실행합니다.","es":"Habilita a los agentes a generar vistas previas para las funciones de Jetpack Compose, utilizando anotaciones como @Preview e integrándose con Material 3 para un diseño de interfaz de usuario mejorado, todo dentro de la aplicación Android nativa NeoDB.","fr":"Permet aux agents de générer des aperçus pour les fonctions Jetpack Compose, en utilisant des annotations comme @Preview et en s''intégrant à Material 3 pour un design d''interface utilisateur amélioré, le tout dans l''application Android native NeoDB.","de":"Ermächtigt Agenten, Vorschauen für Jetpack-Compose-Funktionen zu generieren, indem sie Anmerkungen wie @Preview verwenden und sich in Material 3 für ein verbessertes Benutzeroberflächendesign integrieren, all dies innerhalb der nativen Android-App NeoDB.","pt":"Habilita os agentes a gerar pré-visualizações para funções do Jetpack Compose, utilizando anotações como @Preview e integrando com Material 3 para design de UI aprimorado, tudo dentro do aplicativo Android nativo NeoDB.","ru":"Наделяет агентов возможностью генерировать предварительные просмотры для функций Jetpack Compose, используя аннотации типа @Preview и интегрируя с Material 3 для улучшенного дизайна интерфейса пользователя, все внутри родного приложения Android NeoDB.","ar":"يمنح الوكلاء القدرة على إنشاء معاينة لموظّفي وظيفة Jetpack Compose، مع استخدام التعليقات مثل @Preview وتكامل مع Material 3 لتصميم واجهة المستخدم المحسّن، وكل ذلك داخل تطبيق Android الأصلي NeoDB."},"useCases":{"en":["Generating previews for custom composable functions","Debugging UI components with Material 3","Creating themed previews with AppTheme"],"zh":["为自定义可组合函数生成预览","使用 Material 3 调试 UI 组件","使用 AppTheme 创建主题预览"],"ja":["カスタムコンポーザブル関数のプレビューを生成する","Material 3 を使用して UI コンポーネントをデバッグする","AppTheme を使用してテーマのプレビューを作成する"],"ko":["커스텀 컴퍼지션 함수의 미리 보기를 생성하는 것","Material 3를 사용하여 UI 컴포넌트를 디버깅하는 것","AppTheme를 사용하여 테마 미리 보기를 생성하는 것"],"es":["Generación de vistas previas para funciones personalizadas componibles","Depuración de componentes de interfaz de usuario con Material 3","Creación de vistas previas temáticas con AppTheme"],"fr":["Génération d''aperçus pour des fonctions componibles personnalisées","Débogage des composants d''interface utilisateur avec Material 3","Création d''aperçus thématiques avec AppTheme"],"de":["Generierung von Vorschauen für benutzerdefinierte komponierbare Funktionen","Debuggen von Benutzeroberflächenkomponenten mit Material 3","Erstellung von thematischen Vorschauen mit AppTheme"],"pt":["Geração de pré-visualizações para funções compostas personalizadas","Depuração de componentes de UI com Material 3","Criação de pré-visualizações temáticas com AppTheme"],"ru":["Генерация предварительных просмотров для пользовательских составных функций","Отладка компонентов интерфейса пользователя с Material 3","Создание тематических предварительных просмотров с AppTheme"],"ar":["إنشاء معاينة لموظّفي وظيفة مخصصة","تصحيح أخطاء مكونات واجهة المستخدم مع Material 3","إنشاء معاينة مواضيعية مع AppTheme"]},"limitations":{"en":["Requires NeoDB and Android development environment","Specific to Jetpack Compose and Material 3"],"zh":["需要 NeoDB 和 Android 开发环境","仅限 Jetpack Compose 和 Material 3"],"ja":["NeoDB と Android 開発環境が必要","Jetpack Compose と Material 3 にのみ特化"],"ko":["NeoDB와 안드로이드 개발 환경이 필요함","Jetpack Compose와 Material 3에만 특화"],"es":["Requiere NeoDB y entorno de desarrollo de Android","Específico para Jetpack Compose y Material 3"],"fr":["Nécessite NeoDB et un environnement de développement Android","Spécifique à Jetpack Compose et Material 3"],"de":["Benötigt NeoDB und Android-Entwicklungsumgebung","Spezifisch für Jetpack Compose und Material 3"],"pt":["Exige NeoDB e ambiente de desenvolvimento Android","Específico para Jetpack Compose e Material 3"],"ru":["Требует NeoDB и среды разработки Android","Специфичен для Jetpack Compose и Material 3"],"ar":["يتطلب NeoDB وبيئة تطوير أندرويد","محدد ل Jetpack Compose و Material 3"]},"version":4},"contentHash":"1a2abd151c0721e7ccc83065e200e6ae2113d986d9247e626a4a0dd57c69091a","qualityScore":30}');
