INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('heddxh/NeoDB-You/compose-preview', 'compose-preview', 'heddxh', 'NeoDB-You', 'community', 'compose-preview heddxh NeoDB-You community compose-preview is a native Android app for NeoDB that creates previews for Jetpack Compose functions. It benefits Android developers using Jetpack Compose and Material 3. Compose Preview 是一个 Jetpack Compose 函数的预览工具，帮助开发者优化 UI 设计 Compose Preview は Jetpack Compose 関数のプレビュー ツールであり、開発者が UI デザインを最適化するのに役立ちます Compose Preview는 Jetpack Compose 함수의 미리 보기 도구로서 개발자가 UI 디자인을 최적화하는 데 도움이 됩니다 Compose Preview es una herramienta para crear previews de funciones de Jetpack Compose, permitiendo una mayor personalización y flexibilidad en el desarrollo de aplicaciones Android Compose Preview est un outil pour créer des aperçus de fonctions Jetpack Compose, offrant une personnalisation et une flexibilité accrues dans le développement d''applications Android Compose Preview ist ein Tool zum Erstellen von Vorschauen für Jetpack-Compose-Funktionen, das eine größere Anpassungsfähigkeit und Flexibilität bei der Entwicklung von Android-Anwendungen bietet O Compose Preview é uma ferramenta para criar pré-visualizações de componentes Jetpack Compose. Ele oferece uma forma fácil de visualizar e testar componentes antes de implementá-los em um aplicativo Compose Preview — это инструмент для создания предварительных просмотров компонентов Jetpack Compose. Он предоставляет простой способ просмотра и тестирования компонентов перед их реализацией в приложении с помощью ИИ Агентов Compose Preview هو أداة لإنشاء معاينة لمكونات Jetpack Compose. يقدم وسيلة سهلة للعرض واختبار المكونات قبل تنفيذها في التطبيق how to use compose-preview compose-preview setup guide jetpack compose preview material 3 android app compose-preview alternative compose-preview vs jetpack compose compose-preview install what is compose-preview Compose Preview Jetpack Compose Material 3/You AIエージェント UI 设计 开发工具 Android 开发 Creates previews for Jetpack Compose functions using @Preview annotations Supports Material 3 design for Android apps Utilizes Jetpack Compose for building native Android apps Allows customization of preview names using the ''name'' parameter Enables grouping of previews using the ''group'' parameter compose-preview is a tool for creating previews of Jetpack Compose functions, utilizing @Preview annotations and Material 3 design.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('moosingin3space/sun-api/lint-all', 'community', 'moosingin3space', 'sun-api', 'moosingin3space/sun-api', 'lint-all', 0, 0, 30, '2026-03-08T01:57:15.338Z', '2026-03-08T02:03:22.070Z', '52b97cb853cd79917cda4ff5a487f0f20b359e443b175974c28f7031382f8f1b', '{"id":"moosingin3space/sun-api/lint-all","name":"lint-all","description":{"en":"The lint-all skill provides a comprehensive linting solution for developers, utilizing Dagger functions to ensure project integrity. It benefits developers working on Cloudflare Worker projects.","zh":"lint-all是一种代码lint工具，用于检查代码错误和警告。通过使用Dagger函数`lint`，您可以轻松地检查整个项目的代码质量","ja":"lint-allは、コードのエラーと警告をチェックするためのツールです。Dagger関数`lint`を使用すると、プロジェクト全体のコード品質を簡単にチェックできます","ko":"lint-all은 코드 오류와 경고를 체크하는 도구입니다. Dagger 함수 `lint`를 사용하면 프로젝트 전체의 코드 품질을 쉽게 체크할 수 있습니다","es":"Lint-all es una herramienta que ayuda a asegurar la calidad del código mediante el análisis de errores y la aplicación de reglas de estilo. Se utiliza mediante la función Dagger ''lint''.","fr":"Lint-all est un outil qui aide à assurer la qualité du code en analysant les erreurs et en appliquant des règles de style. Il est utilisé via la fonction Dagger ''lint''.","de":"Lint-all ist ein Tool, das dazu beiträgt, die Qualität des Codes durch die Analyse von Fehlern und die Anwendung von Stilregeln sicherzustellen. Es wird über die Dagger-Funktion ''lint'' verwendet.","pt":"O lint-all é uma ferramenta para garantir a qualidade do código. Use o comando `dagger call lint --source=.` para lintar o projeto.","ru":"ИИ Агент lint-all - инструмент для обеспечения качества кода. Используйте команду `dagger call lint --source=.` для линтинга проекта.","ar":"أداة lint-all هي أداة للتحقق من جودة الكود. استخدم الأمر `dagger call lint --source=.` لتنفيذ لينت على المشروع."},"seo":{"title":{"en":"lint-all: Linting Setup Guide for AI Agents","zh":"lint-all Setup Guide: 代码lint工具","ja":"lint-all Setup Guide: AIエージェントのLintingベストプラクティス","ko":"lint-all 설정 가이드: 코드 품질 관리 도구","es":"Lint-all: Guía de configuración para desarrollo seguro","fr":"Lint-all : Guide de configuration pour un développement s...","de":"Lint-all: Konfigurationsleitfaden für sichere Entwicklung","pt":"Guia de Configuração do lint-all: Melhores Práticas para ...","ru":"ИИ Агенты: Настройка lint-all для Оптимальной Разработки","ar":"إعداد أداة lint-all: دليل أفضل الممارسات لل مطورين"},"description":{"en":"Discover how to use lint-all to streamline your development workflow. Learn how to lint your project with Dagger and get started today!","zh":"了解如何使用lint-all进行代码lint，提高代码质量和开发效率","ja":"AIエージェントのlint-allを使用してコードの品質を向上させる方法を学ぶ","ko":"코드 품질 관리를 위한 lint-all 설정 방법과 최적화 teknik에 대해 알아보세요","es":"Aprende a utilizar lint-all para asegurar la calidad de tu código. Descubre cómo configurar y utilizar esta herramienta para un desarrollo más eficiente.","fr":"Découvrez comment utiliser lint-all pour assurer la qualité de votre code. Apprenez à configurer et à utiliser cet outil pour un développement plus efficace.","de":"Erfahren Sie, wie Sie lint-all verwenden, um die Qualität Ihres Codes sicherzustellen. Entdecken Sie, wie Sie dieses Tool konfigurieren und verwenden können,...","pt":"Aprenda a configurar o lint-all para melhorar a qualidade do seu código. Descubra as melhores práticas e dicas para desenvolvedores.","ru":"Узнайте, как настроить lint-all для повышения качества вашего кода. Откройте для себя лучшие практики и советы для разработчиков.","ar":"تعلم كيفية設定 أداة lint-all لتحسين جودة كودك. اكتشف أفضل الممارسات والنصائح للمطورين."},"definition":{"en":"lint-all is a skill that enables project linting using the Dagger function, allowing for thorough code examination and validation.","zh":"lint-all是一种代码lint工具，用于检查代码错误和警告","ja":"lint-allは、コードのエラーと警告をチェックするためのAIエージェントのツールです","ko":"lint-all은 코드 오류와 경고를 체크하는 코드 품질 관리 도구입니다","es":"Lint-all es una función que se utiliza para analizar y corregir errores en el código, asegurando su calidad y seguridad.","fr":"Lint-all est une fonction qui permet d''analyser et de corriger les erreurs dans le code, en assurant ainsi sa qualité et sa sécurité.","de":"Lint-all ist eine Funktion, die zum Analysieren und Korrigieren von Fehlern im Code verwendet wird, um dessen Qualität und Sicherheit sicherzustellen.","pt":"O lint-all é uma ferramenta de linting que verifica a qualidade do código.","ru":"ИИ Агент lint-all - это инструмент линтинга, который проверяет качество кода.","ar":"أداة lint-all هي أداة لينت تعمل على التحقق من جودة الكود."},"features":{"en":["Utilizes the Dagger function `lint` to lint the entire project","Supports per-component linting with `cf-worker-lint` for Cloudflare Worker","Executes linting via command line with `dagger call lint --source=.`","Enables targeted linting with `dagger call cf-worker-lint --source=.`"],"zh":["使用Dagger函数`lint`进行代码lint","支持_per-component linting_","可以单独lint Cloudflare Worker","使用`dagger call cf-worker-lint`命令进行lint","支持多种代码检查功能"],"ja":["Dagger関数`lint`を使用したコードのlint","_Per-component linting_のサポート","Cloudflare Workerの個別lint","`dagger call cf-worker-lint`コマンドを使用したlint","多種のコードチェック機能のサポート"],"ko":["Dagger 함수 `lint`를 사용한 코드 lint","_per-component linting_ 지원","Cloudflare Worker의 개별 lint","`dagger call cf-worker-lint` 명령어를 사용한 lint","다양한 코드 체크 기능 지원"],"es":["Análisis de código mediante la función Dagger ''lint''","Detección de errores y aplicaciones de reglas de estilo","Compatibilidad con Cloudflare Worker","Posibilidad de análisis de componentes individuales","Uso de la línea de comandos para ejecutar comandos de lint","Integración con herramientas de desarrollo como Dagger"],"fr":["Analyse de code via la fonction Dagger ''lint''","Détection d''erreurs et application de règles de style","Compatibilité avec Cloudflare Worker","Possibilité d''analyse de composants individuels","Utilisation de la ligne de commande pour exécuter des commandes de lint","Intégration avec des outils de développement comme Dagger"],"de":["Code-Analyse über die Dagger-Funktion ''lint''","Fehlererkennung und Anwendung von Stilregeln","Kompatibilität mit Cloudflare Worker","Möglichkeit der Analyse einzelner Komponenten","Verwendung der Kommandozeile zur Ausführung von Lint-Befehlen","Integration mit Entwicklungstools wie Dagger"],"pt":["Suporte ao comando `dagger call lint --source=.`","Linting de componentes individuais com `dagger call cf-worker-lint --source=.`","Integração com o Dagger","Verificação da qualidade do código","Suporte à linting do Cloudflare Worker"],"ru":["Поддержка команды `dagger call lint --source=.`","Линтинг отдельных компонентов с `dagger call cf-worker-lint --source=.`","Интеграция с Dagger","Проверка качества кода","Поддержка линтинга Cloudflare Worker"],"ar":["دعم الأمر `dagger call lint --source=.`","تنفيذ لينت على المكونات الفردية مع `dagger call cf-worker-lint --source=.`","التكامل مع Dagger","التحقق من جودة الكود","دعم لينت Cloudflare Worker"]},"keywords":{"en":["how to use lint-all","lint-all setup guide","lint-all vs eslint","what is lint-all","lint-all install","lint-all alternative","dagger linting","cloudflare worker linting","project linting with lint-all"],"zh":["lint-all","代码lint","Dagger函数","代码检查","Cloudflare Worker","代码品质管理","AI工具","代码开发"],"ja":["lint-all","コードlint","Dagger関数","コードチェック","Cloudflare Worker","コード品質管理","AIエージェント","コード開発"],"ko":["lint-all","코드 lint","Dagger 함수","코드 체크","Cloudflare Worker","코드 품질 관리","AI 도구","코드 개발"],"es":["lint-all","herramientas de desarrollo","análisis de código","Dagger","Cloudflare Worker","seguridad del código","calidad del código","desarrollo seguro","configuración de lint"],"fr":["lint-all","outils de développement","analyse de code","Dagger","Cloudflare Worker","sécurité du code","qualité du code","développement sécurisé","configuration de lint"],"de":["lint-all","Entwicklungstools","Code-Analyse","Dagger","Cloudflare Worker","Sicherheit des Codes","Qualität des Codes","sichere Entwicklung","Lint-Konfiguration"],"pt":["lint-all","ferramenta de linting","qualidade do código","Dagger","Cloudflare Worker","desenvolvimento de software","melhores práticas de desenvolvimento"],"ru":["ИИ Агент","lint-all","инструмент линтинга","качество кода","Dagger","Cloudflare Worker","разработка программного обеспечения","лучшие практики разработки"],"ar":["أداة لينت","lint-all","أداة لينت","جودة الكود","Dagger","Cloudflare Worker","تطوير البرمجيات","أفضل الممارسات للتطوير"]}},"owner":"moosingin3space","repo":"sun-api","repoPath":"moosingin3space/sun-api","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.338Z","topics":[],"category":"community","skillMd":{"name":"lint-all","description":"Lint the entire project. Use whenever you finish editing to ensure your code is clean and follows best practices.","bodyPreview":"# Linting\n\nNote: this guide assumes you are in the root of the project.\n\nTo lint this project, you should use the Dagger function `lint`:\n\n```bash\ndagger call lint --source=.\n```\n\n## Per-component linting\n\nYou can also lint the Cloudflare Worker on its own:\n\n```bash\ndagger call cf-worker-lint --source=.\n```","body":"# Linting\n\nNote: this guide assumes you are in the root of the project.\n\nTo lint this project, you should use the Dagger function `lint`:\n\n```bash\ndagger call lint --source=.\n```\n\n## Per-component linting\n\nYou can also lint the Cloudflare Worker on its own:\n\n```bash\ndagger call cf-worker-lint --source=.\n```\n"},"lastSynced":"2026-03-08T02:03:22.070Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloudflare Worker Agents needing comprehensive linting and project integrity checks.","zh":"适合需要全面 linting 和项目完整性检查的 Cloudflare Worker Agents。","ja":"Cloudflare Worker エージェントが包括的な linting とプロジェクトの完全性の検証が必要な場合に最適です。","ko":"포괄적인 linting 및 프로젝트 무결성 점검을 필요로 하는 Cloudflare Worker 에이전트에 적합합니다.","es":"Ideal para Agentes de Cloudflare Worker que necesitan un linting y verificación de integridad del proyecto exhaustivos.","fr":"Parfait pour les agents Cloudflare Worker nécessitant un linting et des vérifications d''intégrité de projet complets.","de":"Perfekt für Cloudflare Worker-Agents, die umfassendes Linting und Projektintegritätsprüfungen benötigen.","pt":"Perfeito para Agentes de Trabalhador da Cloudflare que precisam de linting e verificação de integridade de projeto abrangentes.","ru":"Идеально подходит для агентов Cloudflare Worker, которым требуются комплексные проверки линтинга и проверки целостности проекта.","ar":"مثالي لعميل Cloudflare Worker الذي يحتاج إلى تحقق شاملة واختبارات صحة المشروع."},"recommendation":{"en":"Empowers agents to utilize Dagger functions for thorough project linting, ensuring integrity and adherence to standards, leveraging the `lint` and `cf-worker-lint` functions for comprehensive analysis.","zh":"赋予代理利用 Dagger 函数进行彻底的项目 linting，确保完整性和遵守标准，利用 `lint` 和 `cf-worker-lint` 函数进行全面分析。","ja":"エージェントが Dagger 関数を使用して包括的なプロジェクト linting を実行できるようにし、完全性と標準への準拠を保証し、`lint` と `cf-worker-lint` 関数を使用して詳細な分析を実行します。","ko":"에이전트가 Dagger 함수를 사용하여 철저한 프로젝트 linting을 수행할 수 있도록 하여 무결성과 표준 준수를 보장하며, `lint`와 `cf-worker-lint` 함수를 사용하여 포괄적인 분석을 수행합니다.","es":"Habilita a los agentes a utilizar funciones de Dagger para un linting de proyecto exhaustivo, garantizando la integridad y el cumplimiento de los estándares, aprovechando las funciones `lint` y `cf-worker-lint` para un análisis completo.","fr":"Permet aux agents d''utiliser les fonctions Dagger pour un linting de projet approfondi, garantissant l''intégrité et le respect des normes, en exploitant les fonctions `lint` et `cf-worker-lint` pour une analyse complète.","de":"Ermöglicht es den Agenten, Dagger-Funktionen für ein umfassendes Linting des Projekts zu nutzen, um Integrität und Einhaltung der Standards sicherzustellen, indem die Funktionen `lint` und `cf-worker-lint` für eine umfassende Analyse genutzt werden.","pt":"Habilita os agentes a utilizar funções do Dagger para linting de projeto abrangente, garantindo a integridade e a aderência aos padrões, aproveitando as funções `lint` e `cf-worker-lint` para análise abrangente.","ru":"Предоставляет агентам возможность использовать функции Dagger для тщательного линтинга проекта, обеспечивая целостность и соблюдение стандартов, используя функции `lint` и `cf-worker-lint` для всестороннего анализа.","ar":"يُمكّن العملاء من استخدام وظائف Dagger لتنفيذ اختبارات صحة شاملة للمشروع، وضمان السلامة والامتثال للمعايير، واستخدام الدوال `lint` و `cf-worker-lint` للتحليل الشامل."},"useCases":{"en":["Linting Cloudflare Worker projects for errors and inconsistencies","Performing per-component linting for targeted analysis","Ensuring project integrity through automated Dagger function calls"],"zh":["用于检测 Cloudflare Worker 项目中的错误和不一致性","针对特定组件进行 linting 以进行有针对性的分析","通过自动化的 Dagger 函数调用确保项目完整性"],"ja":["Cloudflare Worker プロジェクトのエラーと不一致性を検出するために使用","特定のコンポーネントに対して linting を実行してターゲットを絞った分析を行う","自動化された Dagger 関数の呼び出しによってプロジェクトの完全性を確保する"],"ko":["Cloudflare Worker 프로젝트에서 오류 및 불일치를 감지하기 위해 사용","특정 구성 요소에 대한 linting을 수행하여 대상 분석을 수행","자동화된 Dagger 함수 호출을 통해 프로젝트 무결성을 보장"],"es":["Linting de proyectos de Cloudflare Worker para errores e inconsistencias","Realización de linting por componente para un análisis dirigido","Garantía de integridad del proyecto a través de llamadas a funciones de Dagger automatizadas"],"fr":["Linting de projets Cloudflare Worker pour les erreurs et les incohérences","Exécution d''un linting par composant pour une analyse ciblée","Assurance de l''intégrité du projet via des appels de fonctions Dagger automatisés"],"de":["Linting von Cloudflare Worker-Projekten für Fehler und Inkonsistenzen","Durchführung von Linting pro Komponente für eine gezielte Analyse","Sicherstellung der Projektintegrität durch automatisierte Dagger-FunktionAufrufe"],"pt":["Análise de linting de projetos Cloudflare Worker para erros e inconsistências","Realização de linting por componente para análise direcionada","Garantia da integridade do projeto por meio de chamadas de funções do Dagger automatizadas"],"ru":["Проверка линтинга проектов Cloudflare Worker на ошибки и несоответствия","Проведение линтинга по компонентам для целевой аналитике","Обеспечение целостности проекта посредством автоматических вызовов функций Dagger"],"ar":["اختبار صحة مشاريع Cloudflare Worker للأخطاء والتناقضات","إجراء اختبارات صحة مُوجهة لكل مكون","ضمان سلامة المشروع من خلال呼الات وظائف Dagger الأتوماتيكية"]},"limitations":{"en":["Requires Dagger installation and configuration","Specific to Cloudflare Worker projects","Must be run from the project root directory"],"zh":["需要 Dagger 的安装和配置","仅适用于 Cloudflare Worker 项目","必须从项目根目录运行"],"ja":["Dagger のインストールと設定が必要","Cloudflare Worker プロジェクトにのみ適用","プロジェクトのルートディレクトリから実行する必要がある"],"ko":["Dagger 설치 및 구성이 필요","Cloudflare Worker 프로젝트에만 적용","프로젝트 루트 디렉토리에서 실행해야 함"],"es":["Requiere instalación y configuración de Dagger","Específico para proyectos de Cloudflare Worker","Debe ejecutarse desde el directorio raíz del proyecto"],"fr":["Nécessite l''installation et la configuration de Dagger","Spécifique aux projets Cloudflare Worker","Doit être exécuté depuis le répertoire racine du projet"],"de":["Benötigt Dagger-Installation und -Konfiguration","Spezifisch für Cloudflare Worker-Projekte","Muss vom Projekt-Stammmordner aus ausgeführt werden"],"pt":["Requer instalação e configuração do Dagger","Específico para projetos Cloudflare Worker","Deve ser executado a partir do diretório raiz do projeto"],"ru":["Требует установки и настройки Dagger","Конкретно для проектов Cloudflare Worker","Должно быть выполнено из корневого каталога проекта"],"ar":["يتطلب تثبيت وتكوين Dagger","محدد لمشاريع Cloudflare Worker","يجب تشغيله من دليل الجذر للمشروع"]},"version":4},"contentHash":"52b97cb853cd79917cda4ff5a487f0f20b359e443b175974c28f7031382f8f1b","qualityScore":30}');
