INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('moosingin3space/sun-api/lint-all', 'lint-all', 'moosingin3space', 'sun-api', 'community', 'lint-all moosingin3space sun-api community The lint-all skill provides a comprehensive linting solution for developers, utilizing Dagger functions to ensure project integrity. It benefits developers working on Cloudflare Worker projects. lint-all是一种代码lint工具，用于检查代码错误和警告。通过使用Dagger函数`lint`，您可以轻松地检查整个项目的代码质量 lint-allは、コードのエラーと警告をチェックするためのツールです。Dagger関数`lint`を使用すると、プロジェクト全体のコード品質を簡単にチェックできます lint-all은 코드 오류와 경고를 체크하는 도구입니다. Dagger 함수 `lint`를 사용하면 프로젝트 전체의 코드 품질을 쉽게 체크할 수 있습니다 Lint-all es una herramienta que ayuda a asegurar la calidad del código mediante el análisis de errores y la aplicación de reglas de estilo. Se utiliza mediante la función Dagger ''lint''. Lint-all est un outil qui aide à assurer la qualité du code en analysant les erreurs et en appliquant des règles de style. Il est utilisé via la fonction Dagger ''lint''. Lint-all ist ein Tool, das dazu beiträgt, die Qualität des Codes durch die Analyse von Fehlern und die Anwendung von Stilregeln sicherzustellen. Es wird über die Dagger-Funktion ''lint'' verwendet. O lint-all é uma ferramenta para garantir a qualidade do código. Use o comando `dagger call lint --source=.` para lintar o projeto. ИИ Агент lint-all - инструмент для обеспечения качества кода. Используйте команду `dagger call lint --source=.` для линтинга проекта. أداة lint-all هي أداة للتحقق من جودة الكود. استخدم الأمر `dagger call lint --source=.` لتنفيذ لينت على المشروع. how to use lint-all lint-all setup guide lint-all vs eslint what is lint-all lint-all install lint-all alternative dagger linting cloudflare worker linting project linting with lint-all lint-all 代码lint Dagger函数 代码检查 Cloudflare Worker 代码品质管理 AI工具 代码开发 Utilizes the Dagger function `lint` to lint the entire project Supports per-component linting with `cf-worker-lint` for Cloudflare Worker Executes linting via command line with `dagger call lint --source=.` Enables targeted linting with `dagger call cf-worker-lint --source=.` lint-all is a skill that enables project linting using the Dagger function, allowing for thorough code examination and validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('evorto-app/app/project-design', 'community', 'evorto-app', 'app', 'evorto-app/app', 'project-design', 0, 0, 30, '2026-03-08T01:57:15.339Z', '2026-03-08T02:03:24.137Z', 'd0d39b37dcae84a121288d4250a71dfcffdb31e77a7a8977ebbaa01647071038', '{"id":"evorto-app/app/project-design","name":"project-design","description":{"en":"The project-design skill helps developers create adaptive layouts using viewport queries and container queries. It benefits developers who need to build responsive components and page-level layouts.","zh":"项目设计涉及使用容器查询和视口断点创建响应式和适应性组件","ja":"プロジェクト設計では、コンテナクエリとビューポートブレークポイントを使用してレスポンシブでアダプティブなコンポーネントを作成する","ko":"프로젝트 디자인은 컨테이너 쿼리 및 뷰포트 브레이크포인트를 사용하여 반응형 및 적응형 컴포넌트를 생성","es":"El diseño de proyecto implica el uso de consultas de contenedor y viewport para una adaptación óptima","fr":"La conception de projet implique l''utilisation de requêtes de conteneur et de viewport pour une adaptation optimale","de":"Das Projekt-Design beinhaltet die Verwendung von Container- und Viewport-Abfragen für eine optimale Anpassung","pt":"O design de projeto envolve a utilização de viewport queries e container queries para criar layouts adaptáveis. Aprenda a aplicar essas técnicas para melhorar a estrutura da sua página.","ru":"Проектный дизайн включает в себя использование viewport queries и container queries для создания адаптивного макета. Узнайте, как применять эти техники для улучшения структуры вашей страницы.","ar":"يتضمن تصميم المشروع استخدام استفسارات العرض والاستفسارات الحاوية لإنشاء تخطيط قابل للتعديل. تعرف على كيفية تطبيق هذه التقنيات لتحسين هيكل صفحتك."},"seo":{"title":{"en":"project-design: Container Query Setup Guide | AI Agent Skill","zh":"项目设计最佳实践：容器查询和视口断点","ja":"プロジェクト設計ガイド：コンテナクエリとビューポートブレークポイント","ko":"프로젝트 디자인 가이드: 컨테이너 쿼리 및 뷰포트 브레이크포인트","es":"Guía de configuración de diseño de proyecto con consultas...","fr":"Guide de mise en place de la conception de projet avec de...","de":"Einrichtungsleitfaden für Projekt-Design mit Container-Ab...","pt":"Guia de Configuração de Projeto: Melhores Práticas de Design","ru":"ИИ Агенты: Настройка Проектного Дизайна","ar":"دليل تصميم المشروع: إعداد وتطبيق أفضل الممارسات"},"description":{"en":"Unlock adaptive layouts with project-design! Learn how to use viewport queries and container queries to create responsive components and page-level layouts. ...","zh":"了解项目设计的最佳实践，包括容器查询和视口断点的使用，以创建响应式和适应性组件","ja":"プロジェクト設計のベストプラクティスを学び、コンテナクエリとビューポートブレークポイントを使用してレスポンシブでアダプティブなコンポーネントを作成する","ko":"프로젝트 디자인의最佳实践을 배우고 컨테이너 쿼리 및 뷰포트 브레이크포인트를 사용하여 반응형 및 적응형 컴포넌트를 생성","es":"Aprende a diseñar proyectos con consultas de contenedor y viewport para una adaptación óptima","fr":"Découvrez comment concevoir des projets avec des requêtes de conteneur et de viewport pour une adaptation optimale","de":"Erfahren Sie, wie Sie Projekte mit Container- und Viewport-Abfragen für eine optimale Anpassung entwerfen","pt":"Aprenda a aplicar as melhores práticas de design de projeto com viewport queries e container queries para layout de componentes adaptáveis.","ru":"Узнайте, как настраивать проектный дизайн с помощью viewport queries и container queries для адаптивного компонентного макета.","ar":"تعرف على كيفية تطبيق أفضل الممارسات لتصميم المشروع باستخدام استفسارات العرض والاستفسارات الحاوية لتنسيق مكونات قابل للتعديل."},"definition":{"en":"project-design is a technique for creating adaptive layouts using viewport queries for page-level changes and container queries for component-level adaptation.","zh":"项目设计是指使用容器查询和视口断点创建响应式和适应性组件的过程","ja":"プロジェクト設計とは、コンテナクエリとビューポートブレークポイントを使用してレスポンシブでアダプティブなコンポーネントを作成するプロセス","ko":"프로젝트 디자인은 컨테이너 쿼리 및 뷰포트 브레이크포인트를 사용하여 반응형 및 적응형 컴포넌트를 생성하는 프로세스","es":"El diseño de proyecto es una técnica que utiliza consultas de contenedor y viewport para adaptar componentes","fr":"La conception de projet est une technique qui utilise des requêtes de conteneur et de viewport pour adapter des composants","de":"Das Projekt-Design ist eine Technik, die Container- und Viewport-Abfragen verwendet, um Komponenten anzupassen","pt":"O design de projeto é uma técnica que utiliza viewport queries e container queries para criar layouts adaptáveis e melhorar a estrutura da página.","ru":"Проектный дизайн - это техника, которая использует viewport queries и container queries для создания адаптивного макета и улучшения структуры страницы.","ar":"تصميم المشروع هو تقنية تستخدم استفسارات العرض والاستفسارات الحاوية لإنشاء تخطيط قابل للتعديل وتحسين هيكل الصفحة."},"features":{"en":["Uses viewport breakpoints (sm:, md:, lg:) for global structure","Utilizes container queries (@container and @sm:, @md:, @lg:) for reusable components","Supports marking intentional component boundaries with @container","Enables adaptation to parent width for reusable components","Follows rules for using viewport queries and container queries"],"zh":["使用视口断点（sm:、md:、lg:）创建全局结构","使用容器查询（@container和@sm:、@md:、@lg:）创建可重用组件","标记有意的组件边界以@container","避免深度或不必要的容器查询","使用容器查询创建适应性组件"],"ja":["ビューポートブレークポイント（sm:、md:、lg:）を使用してグローバル構造を作成","コンテナクエリ（@containerと@sm:、@md:、@lg:）を使用して再利用可能なコンポーネントを作成","意図的なコンポーネント境界を@containerでマーク","深度または不要なコンテナクエリを避ける","コンテナクエリを使用してアダプティブなコンポーネントを作成"],"ko":["뷰포트 브레이크포인트（sm:、md:、lg:）를 사용하여 전역 구조 생성","컨테이너 쿼리（@container와 @sm:、@md:、@lg:）를 사용하여 재사용 가능한 컴포넌트 생성","의도적인 컴포넌트 경계를 @container로 표시","깊은 또는 불필요한 컨테이너 쿼리를 피함","컨테이너 쿼리를 사용하여 적응형 컴포넌트 생성"],"es":["Uso de consultas de contenedor (@container) para componentes reutilizables","Uso de consultas de viewport (sm:, md:, lg:) para estructuras globales","Adaptación de componentes a la anchura del padre","Uso de puntos de interrupción (breakpoints) para cambios en la estructura de la página","Aplicación de reglas para un diseño de proyecto óptimo"],"fr":["Utilisation de requêtes de conteneur (@container) pour des composants réutilisables","Utilisation de requêtes de viewport (sm:, md:, lg:) pour des structures globales","Adaptation de composants à la largeur du parent","Utilisation de points d''interruption (breakpoints) pour des changements dans la structure de la page","Application de règles pour une conception de projet optimale"],"de":["Verwendung von Container-Abfragen (@container) für wiederverwendbare Komponenten","Verwendung von Viewport-Abfragen (sm:, md:, lg:) für globale Strukturen","Anpassung von Komponenten an die Breite des Elternteils","Verwendung von Unterbrechungspunkten (breakpoints) für Änderungen in der Seitenstruktur","Anwendung von Regeln für ein optimales Projekt-Design"],"pt":["Utilização de viewport queries para mudanças de layout de nível de página","Utilização de container queries para adaptação de componentes","Definição de breakpoints para layout de componentes","Uso de @container para marcar limites de componentes","Aplicação de regras de design para layouts adaptáveis"],"ru":["Использование viewport queries для изменений макета уровня страницы","Использование container queries для адаптации компонентов","Определение точек разрыва для макета компонентов","Использование @container для маркировки границ компонентов","Применение правил дизайна для адаптивного макета"],"ar":["استخدام استفسارات العرض لتغييرات تخطيط مستوى الصفحة","استخدام الاستفسارات الحاوية لتكيف المكونات","تحديد نقاط الكسر لتخطيط المكونات","استخدام @container لتحديد حدود المكونات","تطبيق قواعد التصميم لتخطيط قابل للتعديل"]},"keywords":{"en":["how to use project-design","what is project-design","project-design alternative","project-design vs CSS media queries","project-design install","project-design setup guide","container query tutorial","viewport query best practices"],"zh":["项目设计","容器查询","视口断点","响应式设计","适应性组件","AIエージェント","前端开发"],"ja":["プロジェクト設計","コンテナクエリ","ビューポートブレークポイント","レスポンシブデザイン","アダプティブなコンポーネント","AIエージェント","フロントエンド開発"],"ko":["프로젝트 디자인","컨테이너 쿼리","뷰포트 브레이크포인트","반응형 디자인","적응형 컴포넌트","AI에이전트","프론트엔드 개발"],"es":["diseño de proyecto","consultas de contenedor","viewport","breakpoints","adaptación de componentes","estructura de página","Herramientas de AI para diseño de proyecto","Agentes de IA para diseño de proyecto"],"fr":["conception de projet","requêtes de conteneur","viewport","points d''interruption","adaptation de composants","structure de page","Outils d''IA pour conception de projet","Agents d''IA pour conception de projet"],"de":["Projekt-Design","Container-Abfragen","Viewport","Unterbrechungspunkte","Anpassung von Komponenten","Seitenstruktur","AI-Tools für Projekt-Design","KI-Agents für Projekt-Design"],"pt":["design de projeto","viewport queries","container queries","layout adaptável","breakpoints","componentes reutilizáveis","melhores práticas de design"],"ru":["ИИ Агенты","проектный дизайн","viewport queries","container queries","адаптивный макет","точки разрыва","переиспользуемые компоненты","лучшие практики дизайна"],"ar":["تصميم المشروع","استفسارات العرض","الاستفسارات الحاوية","تخطيط قابل للتعديل","نقاط الكسر","مكونات قابلة لإعادة الاستخدام","أفضل الممارسات لتصميم المشروع"]}},"owner":"evorto-app","repo":"app","repoPath":"evorto-app/app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.339Z","topics":[],"category":"community","skillMd":{"name":"project-design","description":"Project-specific UI and styling guidance for Evorto, including when to use viewport queries versus Tailwind v4 container queries.","bodyPreview":"# Project Design\n\n## Container Queries\n\nUse viewport queries for page-level layout changes and container queries for component-level adaptation.\n\n### Rules\n\n1. Use viewport breakpoints (`sm:`, `md:`, `lg:`) for global structure (page grids, shell layout, top-level navigation behavior).\n2. Use container queries (`@container` and `@sm:`, `@md:`, `@lg:`) for reusable components that should adapt to their parent width.\n3. Mark only intentional component boundaries with `@container`; avoid deep or un","body":"# Project Design\n\n## Container Queries\n\nUse viewport queries for page-level layout changes and container queries for component-level adaptation.\n\n### Rules\n\n1. Use viewport breakpoints (`sm:`, `md:`, `lg:`) for global structure (page grids, shell layout, top-level navigation behavior).\n2. Use container queries (`@container` and `@sm:`, `@md:`, `@lg:`) for reusable components that should adapt to their parent width.\n3. Mark only intentional component boundaries with `@container`; avoid deep or unnecessary nested containers.\n4. Keep a predictable model: layout responds to viewport, components respond to container.\n5. Build for modern browsers and keep components readable if container query variants do not apply.\n\n### Tailwind v4 Pattern\n\n```html\n<section class=\"@container\">\n  <div class=\"grid gap-4 @lg:grid-cols-2\">\n    <article class=\"rounded-2xl p-4\">\n      <h3 class=\"text-base @md:text-lg\">Card title</h3>\n      <p class=\"@sm:line-clamp-3\">Component content adapts to container width.</p>\n    </article>\n  </div>\n</section>\n```\n\n### Project Notes\n\n- Prefer simple, explicit breakpoints over many tiny threshold tweaks.\n- Document non-obvious container-query behavior in the feature README when it affects UX.\n\n## Material Theming (Tailwind-First)\n\nIn this project, Material theming is consumed primarily through Tailwind tokens defined in `/Users/hedde/code/evorto/src/tailwind.css`, not through Angular Material utility classes.\n\n### Rules\n\n1. Treat `src/tailwind.css` as the theming bridge from Material system tokens (`--mat-sys-*`) to Tailwind tokens (`--color-*`, `--radius-*`, font tokens).\n2. In templates, prefer Tailwind semantic classes such as `bg-surface`, `text-on-surface`, `bg-primary-container`, and `rounded-2xl`.\n3. In component CSS, use `var(--mat-sys-*)` directly only when a style cannot be expressed cleanly with existing Tailwind utilities.\n4. If a needed token is missing, extend the mapping in `src/tailwind.css` instead of introducing hardcoded hex values.\n5. Keep dark/light behavior token-driven via Material system variables; avoid component-level theme branching unless required.\n\n### Practical Workflow\n\n1. Pick the Material role/token (for example surface, on-surface, primary-container).\n2. Use the mapped Tailwind utility first (`bg-*`, `text-*`, `rounded-*`).\n3. Add or adjust token mappings in `src/tailwind.css` when coverage is missing.\n\nReference: [Angular Material - Theming your components](https://material.angular.dev/guide/theming-your-components) (focus on CSS variables/system tokens).\n"},"lastSynced":"2026-03-08T02:03:24.137Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing adaptive layout generation using viewport and container queries.","zh":"适用于需要使用视口和容器查询生成自适应布局的前端代理。","ja":"フロントエンドエージェントがビューポートとコンテナクエリを使用して適応性レイアウトを生成する必要がある場合に適しています。","ko":"뷰포트와 컨테이너 쿼리를 사용하여 적응형 레이아웃을 생성해야 하는 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan generación de diseños adaptables utilizando consultas de viewport y contenedor.","fr":"Parfait pour les agents Frontend ayant besoin de génération de mise en page adaptative à l''aide de requêtes de viewport et de conteneur.","de":"Perfekt für Frontend-Agents, die adaptive Layout-Generierung unter Verwendung von Viewport- und Container-Abfragen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de geração de layout adaptativa usando viewport e consultas de contêiner.","ru":"Идеально для Фронтенд-агентов, которым необходима адаптивная генерация макета с использованием viewport и запросов контейнера.","ar":"مثالي لعميل واجهة المستخدم التي تحتاج إلى توليد تخطيط قابل للتكيف باستخدام نقطة العرض واستفسارات الحاوية."},"recommendation":{"en":"Empowers agents to create responsive components and page-level layouts using viewport breakpoints and container queries, enabling adaptive designs with @container and @sm:, @md:, @lg: syntax.","zh":"赋予代理创建响应式组件和页面级别布局的能力，使用视口断点和容器查询，实现自适应设计，使用@container和@sm:, @md:, @lg:语法。","ja":"エージェントがビューポートのブレークポイントとコンテナクエリを使用してレスポンシブなコンポーネントとページレベルのレイアウトを作成できるようにし、@containerと@sm:, @md:, @lg:構文を使用して適応性デザインを実現します。","ko":"에이전트가 뷰포트 브레이크포인트와 컨테이너 쿼리를 사용하여 반응형 컴포넌트와 페이지 수준 레이아웃을 생성할 수 있도록 하여, @container와 @sm:, @md:, @lg: 구문을 사용하여 적응형 디자인을 가능하게 합니다.","es":"Habilita a los agentes a crear componentes y diseños de nivel de página responsivos utilizando puntos de interrupción de viewport y consultas de contenedor, lo que permite diseños adaptables con la sintaxis @container y @sm:, @md:, @lg:.","fr":"Permet aux agents de créer des composants et des mises en page de niveau de page responsives à l''aide de points de rupture de viewport et de requêtes de conteneur, permettant ainsi des conceptions adaptables avec la syntaxe @container et @sm:, @md:, @lg:.","de":"Ermächtigt Agenten, responsive Komponenten und Seitenebenen-Layouts unter Verwendung von Viewport-Breakpoints und Container-Abfragen zu erstellen, wodurch adaptive Designs mit der Syntax @container und @sm:, @md:, @lg: ermöglicht werden.","pt":"Habilita os agentes a criar componentes responsivos e layouts de nível de página usando pontos de quebra de viewport e consultas de contêiner, permitindo designs adaptativos com sintaxe @container e @sm:, @md:, @lg:.","ru":"Наделяет агентов возможностью создавать отзывчивые компоненты и макеты уровня страницы с использованием точек разрыва viewport и запросов контейнера, позволяя создавать адаптивные дизайны с синтаксисом @container и @sm:, @md:, @lg:.","ar":"تمكين العميل من إنشاء مكونات استجابة وتصميمات صفحة باستخدام نقاط انكسار نقطة العرض والاستفسارات الحاوية، وتمكين التصاميم القابلة للتكيف مع بناء الجملة @container و @sm: و @md: و @lg:."},"useCases":{"en":["Generating responsive page grids using viewport queries","Creating adaptive reusable components with container queries","Debugging layout issues using @container and @sm:, @md:, @lg: rules"],"zh":["使用视口查询生成响应式页面网格","使用容器查询创建可重用的适应性组件","使用@container和@sm:, @md:, @lg:规则调试布局问题"],"ja":["ビューポートクエリを使用してレスポンシブなページグリッドを生成する","コンテナクエリを使用して再利用可能な適応性コンポーネントを作成する","@containerと@sm:, @md:, @lg:ルールを使用してレイアウトの問題をデバッグする"],"ko":["뷰포트 쿼리를 사용하여 반응형 페이지 그리드를 생성하는こと","컨테이너 쿼리를 사용하여 재사용 가능한 적응형 컴포넌트를 생성하는 것","@container와 @sm:, @md:, @lg: 규칙을 사용하여 레이아웃 문제를 디버깅하는 것"],"es":["Generación de cuadrículas de página responsivas utilizando consultas de viewport","Creación de componentes reutilizables adaptables con consultas de contenedor","Depuración de problemas de diseño utilizando reglas @container y @sm:, @md:, @lg:"],"fr":["Génération de grilles de page responsives à l''aide de requêtes de viewport","Création de composants réutilisables adaptables avec des requêtes de conteneur","Débogage des problèmes de mise en page à l''aide de règles @container et @sm:, @md:, @lg:"],"de":["Generierung responsiver Seitengitter unter Verwendung von Viewport-Abfragen","Erstellung adaptiver, wiederverwendbarer Komponenten mit Container-Abfragen","Fehlerbehebung bei Layout-Problemen unter Verwendung von @container- und @sm:, @md:, @lg-Regeln"],"pt":["Geração de grades de página responsivas usando consultas de viewport","Criação de componentes reutilizáveis adaptativos com consultas de contêiner","Depuração de problemas de layout usando regras @container e @sm:, @md:, @lg:"],"ru":["Генерация отзывчивых сеток страниц с использованием запросов viewport","Создание адаптивных многоразовых компонентов с использованием запросов контейнера","Отладка проблем макета с использованием правил @container и @sm:, @md:, @lg:"],"ar":["توليد شبكات صفحة استجابة باستخدام استفسارات نقطة العرض","إنشاء مكونات قابلة لإعادة الاستخدام قابلة للتكيف باستخدام استفسارات الحاوية","تصحيح أخطاء تصميم التخطيط باستخدام قواعد @container و @sm: و @md: و @lg:"]},"limitations":{"en":["Requires understanding of viewport and container query syntax","Intended for component-level and page-level layout adaptations only"],"zh":["需要了解视口和容器查询的语法","仅适用于组件级别和页面级别的布局适应"],"ja":["ビューポートとコンテナクエリの構文を理解する必要がある","コンポーネントレベルとページレベルのレイアウト適応のみに使用する"],"ko":["뷰포트와 컨테이너 쿼리의 구문을 이해해야 함","컴포넌트 수준과 페이지 수준의 레이아웃 적응에만 사용"],"es":["Requiere comprensión de la sintaxis de consultas de viewport y contenedor","Diseñado solo para adaptaciones de diseño a nivel de componente y página"],"fr":["Nécessite une compréhension de la syntaxe des requêtes de viewport et de conteneur","Conçu uniquement pour les adaptations de conception au niveau du composant et de la page"],"de":["Erfordert Verständnis der Syntax von Viewport- und Container-Abfragen","Nur für Layout-Anpassungen auf Komponenten- und Seitenebene vorgesehen"],"pt":["Requer entendimento da sintaxe de consultas de viewport e contêiner","Destinado apenas a adaptações de layout de nível de componente e página"],"ru":["Требует понимания синтаксиса запросов viewport и контейнера","Предназначен только для адаптаций макета уровня компонента и страницы"],"ar":["يتطلب فهم بناء الجملة لاستفسارات نقطة العرض والحاوية","مصمم فقط لتعديلات تخطيط مستوى المكون والصفحة"]},"version":4},"contentHash":"d0d39b37dcae84a121288d4250a71dfcffdb31e77a7a8977ebbaa01647071038","qualityScore":30}');
