INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('evorto-app/app/project-design', 'project-design', 'evorto-app', 'app', 'community', 'project-design evorto-app app community The project-design skill helps developers create adaptive layouts using viewport queries and container queries. It benefits developers who need to build responsive components and page-level layouts. 项目设计涉及使用容器查询和视口断点创建响应式和适应性组件 プロジェクト設計では、コンテナクエリとビューポートブレークポイントを使用してレスポンシブでアダプティブなコンポーネントを作成する 프로젝트 디자인은 컨테이너 쿼리 및 뷰포트 브레이크포인트를 사용하여 반응형 및 적응형 컴포넌트를 생성 El diseño de proyecto implica el uso de consultas de contenedor y viewport para una adaptación óptima La conception de projet implique l''utilisation de requêtes de conteneur et de viewport pour une adaptation optimale Das Projekt-Design beinhaltet die Verwendung von Container- und Viewport-Abfragen für eine optimale Anpassung O design de projeto envolve a utilização de viewport queries e container queries para criar layouts adaptáveis. Aprenda a aplicar essas técnicas para melhorar a estrutura da sua página. Проектный дизайн включает в себя использование viewport queries и container queries для создания адаптивного макета. Узнайте, как применять эти техники для улучшения структуры вашей страницы. يتضمن تصميم المشروع استخدام استفسارات العرض والاستفسارات الحاوية لإنشاء تخطيط قابل للتعديل. تعرف على كيفية تطبيق هذه التقنيات لتحسين هيكل صفحتك. how to use project-design what is project-design project-design alternative project-design vs CSS media queries project-design install project-design setup guide container query tutorial viewport query best practices 项目设计 容器查询 视口断点 响应式设计 适应性组件 AIエージェント 前端开发 Uses viewport breakpoints (sm:, md:, lg:) for global structure Utilizes container queries (@container and @sm:, @md:, @lg:) for reusable components Supports marking intentional component boundaries with @container Enables adaptation to parent width for reusable components Follows rules for using viewport queries and container queries project-design is a technique for creating adaptive layouts using viewport queries for page-level changes and container queries for component-level adaptation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ShouxinZhang/agent-multiSubAgents/local-dev-workflow', 'community', 'ShouxinZhang', 'agent-multiSubAgents', 'ShouxinZhang/agent-multiSubAgents', 'local-dev-workflow', 0, 0, 30, '2026-03-08T01:57:15.342Z', '2026-03-08T02:03:28.551Z', 'c09392b058e0c234ca4938da6279691ed51616f9526c58fdcbce7b9e36e316a7', '{"id":"ShouxinZhang/agent-multiSubAgents/local-dev-workflow","name":"local-dev-workflow","description":{"en":"The local-dev-workflow skill enables developers to manage their development process efficiently, from understanding requirements to Git management. It benefits developers by streamlining their workflow.","zh":"本地开发全链路工作流是一种提高开发效率和质量的方法，包括需求理解、方案对齐、编码实现等步骤","ja":"ローカル開発ワークフローは開発効率と品質を向上させるための方法で、要件理解、計画の整合、コード実装などを含む","ko":"로컬 개발 워크플ロー는 개발 효율성과 품질을 향상시키는 방법으로 요구사항 이해, 계획 조정, 코드 구현 등을 포함한다","es":"El flujo de trabajo de desarrollo local es un proceso que implica la recepción de requisitos, la comprensión del estado actual, la alineación de esquemas y la implementación de código","fr":"Le flux de travail de développement local est un processus qui implique la réception de exigences, la compréhension de l''état actuel, l''alignement de schémas et la mise en œuvre de code","de":"Der lokale Entwicklungswerkfluss ist ein Prozess, der die Aufnahme von Anforderungen, das Verständnis des aktuellen Zustands, die Ausrichtung von Schemata und die Implementierung von Code umfasst","pt":"O fluxo de desenvolvimento local é uma sequência de etapas que visam garantir a qualidade e a eficiência do código, incluindo validação, controle de qualidade e sincronização de documentos","ru":"Местный поток разработки - это последовательность шагов, направленных на обеспечение качества и эффективности кода, включая проверку, контроль качества и синхронизацию документов","ar":"تدفق العمل التطويري المحلي هو تسلسل من الخطوات التي تهدف