INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ShouxinZhang/agent-multiSubAgents/local-dev-workflow', 'local-dev-workflow', 'ShouxinZhang', 'agent-multiSubAgents', 'community', 'local-dev-workflow ShouxinZhang agent-multiSubAgents community The local-dev-workflow skill enables developers to manage their development process efficiently, from understanding requirements to Git management. It benefits developers by streamlining their workflow. 本地开发全链路工作流是一种提高开发效率和质量的方法，包括需求理解、方案对齐、编码实现等步骤 ローカル開発ワークフローは開発効率と品質を向上させるための方法で、要件理解、計画の整合、コード実装などを含む 로컬 개발 워크플ロー는 개발 효율성과 품질을 향상시키는 방법으로 요구사항 이해, 계획 조정, 코드 구현 등을 포함한다 El flujo de trabajo de desarrollo local es un proceso que implica la recepción de requisitos, la comprensión del estado actual, la alineación de esquemas y la implementación de código Le flux de travail de développement local est un processus qui implique la réception de exigences, la compréhension de l''état actuel, l''alignement de schémas et la mise en œuvre de code Der lokale Entwicklungswerkfluss ist ein Prozess, der die Aufnahme von Anforderungen, das Verständnis des aktuellen Zustands, die Ausrichtung von Schemata und die Implementierung von Code umfasst O fluxo de desenvolvimento local é uma sequência de etapas que visam garantir a qualidade e a eficiência do código, incluindo validação, controle de qualidade e sincronização de documentos Местный поток разработки - это последовательность шагов, направленных на обеспечение качества и эффективности кода, включая проверку, контроль качества и синхронизацию документов تدفق العمل التطويري المحلي هو تسلسل من الخطوات التي تهدف إلى ضمان جودة وكفاءة الكود، بما في ذلك التحقق والتحكم النوعي وتزامن الوثائق how to use local-dev-workflow local-dev-workflow setup guide local-dev-workflow vs Jenkins what is local-dev-workflow local-dev-workflow install local-dev-workflow alternative local-dev-workflow tutorial local-dev-workflow Git management local-dev-workflow build checks 本地开发 全链路工作流 需求理解 方案对齐 编码实现 质量门禁 Git管理 开发日志 结构文档同步 Implements a 7-step development workflow using AGENTS.md and dev logs Executes build checks using the build-check command Syncs repository structure using the repo-structure-sync command Manages Git workflow with automated commit and push Validates UI and service behavior with minimal runnable validation Maintains development logs using the dev-logs command local-dev-workflow is a development process management skill that automates tasks such as build checks, repo structure sync, and Git management to improve developer productivity');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sakamotchi/sql-query-build/check-nuxt-ui-v4', 'community', 'sakamotchi', 'sql-query-build', 'sakamotchi/sql-query-build', 'check-nuxt-ui-v4', 0, 0, 30, '2026-03-08T01:57:15.343Z', '2026-03-08T02:03:30.909Z', '8d22e34b33cf23a0b5e170c3e86950f566dcef3dd996b6db1a4b617d2c31fdab', '{"id":"sakamotchi/sql-query-build/check-nuxt-ui-v4","name":"check-nuxt-ui-v4","description":{"en":"The check-nuxt-ui-v4 skill scans Markdown documents for Nuxt UI v3 syntax and suggests corrections to v4 syntax, benefiting developers in maintaining consistent and up-to-date documentation.","zh":"check-nuxt-ui-v4技能用于检测Nuxt UI v3的旧语法，并自动更正为v4语法，支持Markdown文档扫描","ja":"check-nuxt-ui-v4スキルは、Nuxt UI v3の古い記法を検出し、v4記法に自動修正するために使用され、Markdownドキュメントのスキャンをサポートする","ko":"check-nuxt-ui-v4 스킬은 Nuxt UI v3의 구문법을检测하고 v4 문법으로 자동 수정하기 위해 사용되며 Markdown 문서의 스캔을 지원합니다","es":"check-nuxt-ui-v4 es una herramienta que ayuda a migrar a Nuxt UI v4, detectando y corrigiendo el código antiguo en documentos Markdown","fr":"check-nuxt-ui-v4 est un outil qui aide à migrer vers Nuxt UI v4, en détectant et en corrigeant le code ancien dans les documents Markdown","de":"check-nuxt-ui-v4 ist ein Tool, das bei der Migration auf Nuxt UI v4 hilft, indem es alten Code in Markdown-Dokumenten erkennt und korrigiert","pt":"O check-nuxt-ui-v4 é uma ferramenta que ajuda a atualizar a UI para a versão 4 do Nuxt UI, detectando e corrigindo problemas de compatibilidade.","ru":"ИИ Агент check-nuxt-ui-v4 - это инструмент, который помогает обновить UI до версии 4 Nuxt UI, обнаруживая и исправляя проблемы совместимости.","ar":"العامل الذكي check-nuxt-ui-v4 هو أداة تساعد في تحديث الواجهة إلى الإصدار 4 من Nuxt UI، حيث يكتشف ويصلح مشاكل التوافق."},"seo":{"title":{"en":"check-nuxt-ui-v4: Nuxt UI v4 Compatibility Setup Guide | ...","zh":"Nuxt UI v4 语法检查工具设置指南","ja":"Nuxt UI v4 記法チェックスキル設定ガイド","ko":"Nuxt UI v4 문법 검사 도구 설정 가이드","es":"Guía de configuración de check-nuxt-ui-v4 para la migraci...","fr":"Guide de mise en place de check-nuxt-ui-v4 pour la migrat...","de":"Einrichtungsleitfaden für check-nuxt-ui-v4 zur Migration ...","pt":"Guia de Configuração do check-nuxt-ui-v4 para Atualização...","ru":"Настройка ИИ Агента check-nuxt-ui-v4 для Обновления UI","ar":"دليل إعداد العامل الذكي check-nuxt-ui-v4 لتحديث الواجهة"},"description":{"en":"Discover how to seamlessly migrate from Nuxt UI v3 to v4 with the check-nuxt-ui-v4 skill, ensuring compatibility and streamlining your development process - ...","zh":"使用check-nuxt-ui-v4技能检测Nuxt UI v3的旧语法，并自动更正为v4语法，提高开发效率","ja":"check-nuxt-ui-v4スキルを使用してNuxt UI v3の古い記法を検出し、v4記法に自動修正して開発効率を向上させる","ko":"check-nuxt-ui-v4 스킬을 사용하여 Nuxt UI v3의 구문법을检测하고 v4 문법으로 자동 수정하여 개발 효율성을提高합니다","es":"Descubre cómo check-nuxt-ui-v4 ayuda a migrar a Nuxt UI v4, detectando y corrigiendo el código antiguo en tus documentos Markdown","fr":"Découvrez comment check-nuxt-ui-v4 aide à migrer vers Nuxt UI v4, en détectant et en corrigeant le code ancien dans vos documents Markdown","de":"Erfahren Sie, wie check-nuxt-ui-v4 bei der Migration auf Nuxt UI v4 hilft, indem es alten Code in Ihren Markdown-Dokumenten erkennt und korrigiert","pt":"Descubra como usar o check-nuxt-ui-v4 para atualizar sua UI para a versão 4 do Nuxt UI e melhorar a qualidade dos documentos","ru":"Узнайте, как использовать ИИ Агент check-nuxt-ui-v4 для обновления вашего UI до версии 4 Nuxt UI и улучшения качества документов","ar":"تعرف على كيفية استخدام العامل الذكي check-nuxt-ui-v4 لتحديث واجهة المستخدم إلى الإصدار 4 من Nuxt UI وتحسين جودة الوثائق"},"definition":{"en":"check-nuxt-ui-v4 is a skill that checks Nuxt UI v3 syntax in Markdown documents and assists in migrating to Nuxt UI v4 syntax.","zh":"check-nuxt-ui-v4是用于检测和修正Nuxt UI v3到v4语法的AI工具","ja":"check-nuxt-ui-v4は、Nuxt UI v3からv4記法への検出と修正を支援するAIエージェントです","ko":"check-nuxt-ui-v4는 Nuxt UI v3에서 v4 문법으로의 검출과 수정을支援하는 AI 도구입니다","es":"check-nuxt-ui-v4 es una herramienta de AI que verifica y corrige el código de Nuxt UI v3 en documentos Markdown para su migración a v4","fr":"check-nuxt-ui-v4 est un outil d''IA qui vérifie et corrige le code de Nuxt UI v3 dans les documents Markdown pour sa migration vers v4","de":"check-nuxt-ui-v4 ist ein AI-Tool, das den Code von Nuxt UI v3 in Markdown-Dokumenten überprüft und korrigiert, um ihn auf v4 zu migrieren","pt":"O check-nuxt-ui-v4 é uma ferramenta de verificação de UI que ajuda a detectar e corrigir problemas de compatibilidade com a versão 4 do Nuxt UI","ru":"ИИ Агент check-nuxt-ui-v4 - это инструмент проверки UI, который помогает обнаружить и исправить проблемы совместимости с версией 4 Nuxt UI","ar":"العامل الذكي check-nuxt-ui-v4 هو أداة فحص الواجهة التي تساعد في الكشف عن مشاكل التوافق مع الإصدار 4 من Nuxt UI وتصلحها"},"features":{"en":["Scans Markdown documents in `docs/working/` directory for Nuxt UI v3 syntax","Detects and suggests corrections for `UFormGroup`, `:options=`, `options=`, and `v-bind:options=` patterns","Replaces deprecated `UButtonGroup` with `UFieldGroup` in Nuxt UI v4","Supports quality checks for new and existing documentation","Ensures project-wide consistency and reviews manually written documents"],"zh":["检测Nuxt UI v3的旧语法","自动更正为v4语法","支持Markdown文档扫描","检查UFormGroup、UButtonGroup等组件的使用","检测：options=、v-bind:options=等属性的使用"],"ja":["Nuxt UI v3の古い記法を検出","v4記法への自動修正","Markdownドキュメントのスキャンをサポート","UFormGroup、UButtonGroup等コンポーネントの使用をチェック","：options=、v-bind:options=等属性の使用を検出"],"ko":["Nuxt UI v3의 구문법을检测","v4 문법으로의 자동 수정","Markdown 문서의 스캔을 지원","UFormGroup、UButtonGroup等 컴포넌트의 사용을 확인","：options=、v-bind:options=等 속성의 사용을检测"],"es":["Detección de código antiguo de Nuxt UI v3 en documentos Markdown","Corrección automática del código para su migración a Nuxt UI v4","Reemplazo de componentes como UFormGroup por UFormField","Reemplazo de atributos como :options= por :items=","Detección de componentes no recomendados en Nuxt UI v4 como UButtonGroup"],"fr":["Détection du code ancien de Nuxt UI v3 dans les documents Markdown","Correction automatique du code pour sa migration vers Nuxt UI v4","Remplacement de composants comme UFormGroup par UFormField","Remplacement d''attributs comme :options= par :items=","Détection de composants non recommandés dans Nuxt UI v4 comme UButtonGroup"],"de":["Erkennung von altem Code von Nuxt UI v3 in Markdown-Dokumenten","Automatische Korrektur des Codes für die Migration auf Nuxt UI v4","Ersetzung von Komponenten wie UFormGroup durch UFormField","Ersetzung von Attributen wie :options= durch :items=","Erkennung von nicht empfohlenen Komponenten in Nuxt UI v4 wie UButtonGroup"],"pt":["Detecção de componentes obsoletos do Nuxt UI v3","Correção automática de atributos de compatibilidade","Suporte à atualização de documentos Markdown","Verificação de padrões de compatibilidade","Substituição de componentes obsoletos por novos"],"ru":["Обнаружение устаревших компонентов Nuxt UI v3","Автоматическая коррекция атрибутов совместимости","Поддержка обновления документов Markdown","Проверка шаблонов совместимости","Замена устаревших компонентов на новые"],"ar":["اكتشاف مكونات قديمة من Nuxt UI v3","تصحيح تلقائي لسمات التوافق","دعم تحديث مستندات Markdown","فحص أنماط التوافق","استبدال المكونات القديمة بالمكونات الجديدة"]},"keywords":{"en":["check-nuxt-ui-v4 setup guide","Nuxt UI v4 migration","Markdown documentation scanner","check-nuxt-ui-v4 vs Nuxt UI v3","how to use check-nuxt-ui-v4","Nuxt UI v4 compatibility checker","check-nuxt-ui-v4 install","Nuxt UI v4 syntax converter"],"zh":["Nuxt UI v4","语法检查","AI工具","Markdown文档扫描","UFormGroup","UButtonGroup","：options=","v-bind:options="],"ja":["Nuxt UI v4","記法チェック","AIエージェント","Markdownドキュメントスキャン","UFormGroup","UButtonGroup","：options=","v-bind:options="],"ko":["Nuxt UI v4","문법 검사","AI 도구","Markdown 문서 스캔","UFormGroup","UButtonGroup","：options=","v-bind:options="],"es":["check-nuxt-ui-v4","Nuxt UI v4","migración de código","corrección de código","Markdown","Nuxt UI v3","UFormGroup","UFormField","AI herramientas de desarrollo"],"fr":["check-nuxt-ui-v4","Nuxt UI v4","migration de code","correction de code","Markdown","Nuxt UI v3","UFormGroup","UFormField","outils de développement IA"],"de":["check-nuxt-ui-v4","Nuxt UI v4","Code-Migration","Code-Korrektur","Markdown","Nuxt UI v3","UFormGroup","UFormField","AI-Entwicklungstools"],"pt":["check-nuxt-ui-v4","Nuxt UI v4","atualização de UI","compatibilidade de UI","ferramenta de verificação de UI","documentos Markdown","componentes obsoletos","atributos de compatibilidade"],"ru":["check-nuxt-ui-v4","Nuxt UI v4","обновление UI","совместимость UI","инструмент проверки UI","документы Markdown","устаревшие компоненты","атрибуты совместимости"],"ar":["check-nuxt-ui-v4","Nuxt UI v4","تحديث الواجهة","توافق الواجهة","أداة فحص الواجهة","وثائق Markdown","مكونات قديمة","سمات التوافق"]}},"owner":"sakamotchi","repo":"sql-query-build","repoPath":"sakamotchi/sql-query-build","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.343Z","topics":[],"category":"community","skillMd":{"name":"check-nuxt-ui-v4","description":"ドキュメント内のNuxt UI v3記法を検出し、v4記法への修正を支援します。「ドキュメントをチェックして」「Nuxt UI v4の記法を確認」などで呼び出されます。","bodyPreview":"# Nuxt UI v4 記法チェックスキル\n\n## 概要\n\nこのスキルは、プロジェクト内のMarkdownドキュメント（特に `docs/working/` 配下）をスキャンし、Nuxt UI v3 の古い記法を検出して、v4 記法への修正を支援します。\n\n## 使用シーン\n\n- 新しいドキュメントを作成した後の品質チェック\n- 既存ドキュメントのメンテナンス\n- プロジェクト全体の一貫性確認\n- 人間が手動で書いたドキュメントのレビュー\n\n## チェック対象\n\n### 検出パターン\n\n| パターン | 問題 | 修正方法 |\n|---------|------|---------|\n| `UFormGroup` | v3 のコンポーネント名 | `UFormField` に置換 |\n| `:options=` または `options=` | v3 の属性名 | `:items=` に置換 |\n| `v-bind:options=` | v3 の属性名 | `:items=` に置換 |\n| `UButtonGroup` | v4 では非推奨 | `UFieldGroup` に置換","body":"# Nuxt UI v4 記法チェックスキル\n\n## 概要\n\nこのスキルは、プロジェクト内のMarkdownドキュメント（特に `docs/working/` 配下）をスキャンし、Nuxt UI v3 の古い記法を検出して、v4 記法への修正を支援します。\n\n## 使用シーン\n\n- 新しいドキュメントを作成した後の品質チェック\n- 既存ドキュメントのメンテナンス\n- プロジェクト全体の一貫性確認\n- 人間が手動で書いたドキュメントのレビュー\n\n## チェック対象\n\n### 検出パターン\n\n| パターン | 問題 | 修正方法 |\n|---------|------|---------|\n| `UFormGroup` | v3 のコンポーネント名 | `UFormField` に置換 |\n| `:options=` または `options=` | v3 の属性名 | `:items=` に置換 |\n| `v-bind:options=` | v3 の属性名 | `:items=` に置換 |\n| `UButtonGroup` | v4 では非推奨 | `UFieldGroup` に置換 |\n\n### チェック対象ファイル\n\n- `docs/working/**/*.md` - 開発作業ドキュメント\n- `docs/**/*.md` - 永続化ドキュメント（オプション）\n- `.claude/skills/**/SKILL.md` - スキルドキュメント（オプション）\n\n## 実行手順\n\nこのスキルが呼び出されたら、以下の手順で実行してください：\n\n### 1. スコープの確認\n\nユーザーに確認します：\n\n- **特定のディレクトリのみ** をチェックするか\n- **プロジェクト全体** をチェックするか\n\n指定がない場合は `docs/working/` をデフォルトとします。\n\n### 2. ファイルスキャン\n\n対象ディレクトリ内の `.md` ファイルを検索します：\n\n```bash\nfind docs/working -name \"*.md\" -type f\n```\n\n### 3. パターン検出\n\n各ファイルに対して、以下のパターンを検索します：\n\n- `UFormGroup` の使用箇所\n- `options=` または `:options=` の使用箇所\n- `v-bind:options=` の使用箇所\n- `UButtonGroup` の使用箇所\n\n検出には `grep` コマンドまたは Grep ツールを使用します。\n\n### 4. 結果レポート\n\n検出結果を以下の形式でユーザーに報告します：\n\n```markdown\n## チェック結果\n\n### 検出された問題\n\n#### ファイル: docs/working/20251230_example/design.md\n\n**問題1: UFormGroup の使用（行123）**\n```vue\n<!-- 現在 -->\n<UFormGroup label=\"データベース\">\n  <USelect v-model=\"selected\" :options=\"databases\" />\n</UFormGroup>\n\n<!-- 修正案 -->\n<UFormField label=\"データベース\" name=\"database\">\n  <USelect v-model=\"selected\" :items=\"databases\" />\n</UFormField>\n```\n\n**問題2: options 属性の使用（行156）**\n```vue\n<!-- 現在 -->\n<USelectMenu v-model=\"selected\" :options=\"items\" />\n\n<!-- 修正案 -->\n<USelectMenu v-model=\"selected\" :items=\"items\" />\n```\n\n### サマリー\n\n- チェック対象ファイル: 10件\n- 問題検出ファイル: 3件\n- 検出された問題: 5件\n  - UFormGroup: 2件\n  - options 属性: 3件\n```\n\n### 5. 修正オプションの提示\n\nユーザーに以下のオプションを提示します：\n\n1. **自動修正** - 検出された問題を自動で修正する\n2. **手動修正** - ファイルパスと行番号を提示し、ユーザーが手動で修正\n3. **スキップ** - チェックのみ実行し、修正は行わない\n\n### 6. 自動修正（選択された場合）\n\nユーザーが自動修正を選択した場合：\n\n1. 各ファイルに対して Edit ツールを使用\n2. `UFormGroup` → `UFormField` に置換\n3. `:options=` → `:items=` に置換\n4. `options=` → `items=` に置換\n5. `UButtonGroup` → `UFieldGroup` に置換\n6. 修正完了をユーザーに報告\n\n**注意**:\n- コードブロック内のみを対象とし、説明文は変更しない\n- 文脈を確認し、誤検出を避ける\n- バックアップを推奨する\n\n## チェックロジック\n\n### 検出時の考慮事項\n\n1. **コードブロック内のみ対象**\n   - ` ```vue ` ブロック内のコードを優先的にチェック\n   - Markdown のコードブロック外の説明文は慎重に扱う\n\n2. **誤検出の回避**\n   - `UFormGroup` が「v3の例」として意図的に記載されている場合は除外\n   - コメントで `<!-- v3 の例 -->` などと明記されている場合は除外\n\n3. **文脈の確認**\n   - `options` が Nuxt UI コンポーネントの属性として使用されているか確認\n   - 他の用途（変数名、プロパティ名など）との区別\n\n## 使用例\n\n詳細は [examples.md](examples.md) を参照してください。\n\n## 関連ドキュメント\n\n- `.claude/skills/generate-working-docs/SKILL.md` - ドキュメント生成スキル\n- `CLAUDE.md` - プロジェクトガイドライン\n\n## Nuxt UI v4 記法リファレンス\n\n### v3 → v4 移行対応表\n\n| v3（検出対象） | v4（修正後） | 説明 |\n|---------------|-------------|------|\n| `UFormGroup` | `UFormField` | フォームフィールドラッパー |\n| `options` 属性 | `items` 属性 | USelect, USelectMenu等の選択肢 |\n| `UButtonGroup` | `UFieldGroup` | ボタングループラッパー（v4では非推奨） |\n\n### 正しい記法（v4）\n\n```vue\n<template>\n  <!-- ✅ 正しい: UFormField を使用 -->\n  <UFormField label=\"データベース\" name=\"database\">\n    <USelect v-model=\"selected\" :items=\"databases\" />\n  </UFormField>\n\n  <!-- ✅ 正しい: items 属性を使用 -->\n  <USelectMenu v-model=\"selected\" :items=\"options\" />\n\n  <!-- ✅ 正しい: UFieldGroup を使用してボタンをグループ化 -->\n  <UFieldGroup>\n    <UButton color=\"primary\">INSERT</UButton>\n    <UButton color=\"gray\">UPDATE</UButton>\n    <UButton color=\"gray\">DELETE</UButton>\n  </UFieldGroup>\n</template>\n```\n\n### 誤った記法（v3）\n\n```vue\n<template>\n  <!-- ❌ 検出される: UFormGroup（v3） -->\n  <UFormGroup label=\"データベース\">\n    <USelect v-model=\"selected\" :options=\"databases\" />\n  </UFormGroup>\n\n  <!-- ❌ 検出される: options 属性（v3） -->\n  <USelectMenu v-model=\"selected\" :options=\"options\" />\n\n  <!-- ❌ 検出される: UButtonGroup（v4では非推奨） -->\n  <UButtonGroup>\n    <UButton color=\"primary\">INSERT</UButton>\n    <UButton color=\"gray\">UPDATE</UButton>\n    <UButton color=\"gray\">DELETE</UButton>\n  </UButtonGroup>\n</template>\n```\n"},"lastSynced":"2026-03-08T02:03:30.909Z","agentAnalysis":{"suitability":{"en":"Perfect for Documentation Analysis Agents specializing in Nuxt.js ecosystem modernization.","zh":"适用于专门从事Nuxt.js生态系统现代化的文档分析代理","ja":"Nuxt.jsエコシステムのモダERN化を専門とするドキュメント分析エージェントに適しています","ko":"Nuxt.js 생태계 현대화를 전문으로 하는 문서 분석 에이전트에게 적합합니다","es":"Perfecto para agentes de análisis de documentación especializados en la modernización del ecosistema Nuxt.js.","fr":"Parfait pour les agents d''analyse de documentation spécialisés dans la modernisation de l''écosystème Nuxt.js.","de":"Perfekt für Dokumentationsanalyse-Agents, die auf die Modernisierung des Nuxt.js-Ökosystems spezialisiert sind.","pt":"Perfeito para Agentes de Análise de Documentação especializados em modernização do ecossistema Nuxt.js.","ru":"Идеально для Агентов Анализа Документации, специализирующихся на модернизации экосистемы Nuxt.js.","ar":"مثالي لعميل تحليل الوثائق المتخصص في تحديث نظام بيئة Nuxt.js."},"recommendation":{"en":"Empowers agents to scan Markdown documentation for deprecated Nuxt UI v3 syntax patterns and automatically suggest v4-compliant replacements, including component migrations like UFormGroup to UFormField and attribute updates from :options= to :items=, ensuring documentation consistency across projects.","zh":"赋予代理扫描Markdown文档以检测过时的Nuxt UI v3语法模式，并自动建议v4兼容的替换，包括从UFormGroup到UFormField的组件迁移和从:options=到:items=的属性更新，确保项目间文档的一致性","ja":"エージェントにMarkdownドキュメントをスキャンして非推奨のNuxt UI v3構文パターンを検出し、v4に準拠した置き換えを自動的に提案する機能を提供する。これには、UFormGroupからUFormFieldへのコンポーネントの移行や、:options=から:items=への属性の更新が含まれ、プロジェクト間のドキュメントの一貫性を確保する","ko":"에이전트가 Markdown 문서를 스캔하여 구식 Nuxt UI v3 구문 패턴을 감지하고 v4 호환替换을 자동으로 제안하도록 하는데, UFormGroup에서 UFormField로의 컴포넌트 마이그레이션 및 :options=에서 :items=로의 속성 업데이트가 포함되어 프로젝트 간 문서 일관성을 보장합니다","es":"Permite a los agentes escanear la documentación de Markdown para detectar patrones de sintaxis obsoletos de Nuxt UI v3 y sugerir automáticamente reemplazos compatibles con v4, incluyendo migraciones de componentes como UFormGroup a UFormField y actualizaciones de atributos de :options= a :items=, garantizando la consistencia de la documentación en todos los proyectos.","fr":"Permet aux agents d''analyser la documentation Markdown pour détecter les modèles de syntaxe obsolètes de Nuxt UI v3 et suggérer automatiquement des remplacements compatibles v4, y compris les migrations de composants comme UFormGroup vers UFormField et les mises à jour d''attributs de :options= à :items=, garantissant la cohérence de la documentation à travers les projets.","de":"Ermöglicht es Agents, Markdown-Dokumentationen auf veraltete Nuxt UI v3-Syntaxmuster zu scannen und automatisch v4-kompatible Ersetzungen vorzuschlagen, einschließlich Komponentenmigrationen wie UFormGroup zu UFormField und Attributaktualisierungen von :options= auf :items=, um die Konsistenz der Dokumentation über alle Projekte hinweg sicherzustellen.","pt":"Habilita os agentes a digitalizar a documentação Markdown para detectar padrões de sintaxe obsoletos do Nuxt UI v3 e sugerir automaticamente substituições compatíveis com o v4, incluindo migrações de componentes como UFormGroup para UFormField e atualizações de atributos de :options= para :items=, garantindo a consistência da documentação em projetos.","ru":"Позволяет агентам сканировать документацию Markdown для обнаружения устаревших шаблонов синтаксиса Nuxt UI v3 и автоматически предлагать замену, совместимую с v4, включая миграцию компонентов, таких как UFormGroup в UFormField, и обновление атрибутов с :options= на :items=, обеспечивая согласованность документации в проектах.","ar":"يُمكّن الوكيل من فحص الوثائق Markdown للكشف عن أنماط البناء القديمة من Nuxt UI v3 واقتراح بديلات تلقائيًا متوافقة مع الإصدار v4، بما في ذلك هجرة المكونات مثل UFormGroup إلى UFormField وتحديث السمة من :options= إلى :items=، مما يضمن συνέimité الوثائق عبر المشاريع."},"useCases":{"en":["Automating legacy syntax detection in docs/ directories","Generating v4 migration reports for developer review","Validating Markdown consistency in version-controlled projects","Enforcing documentation standards in CI/CD pipelines"],"zh":["自动化遗留语法检测在docs/目录中","为开发人员生成v4迁移报告","在版本控制项目中验证Markdown一致性","在CI/CD流水线中强制执行文档标准"],"ja":["docs/ディレクトリ内のレガシーシンタックスの自動検出","開発者レビュー用のv4移行レポートの生成","バージョン管理プロジェクトでのMarkdownの一貫性の検証","CI/CDパイプラインでのドキュメント基準の強制"],"ko":["docs/ 디렉토리 내에서 레거시 구문 자동 감지","개발자 리뷰용 v4 마이그레이션 보고서 생성","버전 관리 프로젝트에서 Markdown 일관성 검증","CI/CD 파이프라인에서 문서 표준 강제"],"es":["Automatización de la detección de sintaxis heredada en directorios docs/","Generación de informes de migración v4 para revisión de desarrolladores","Validación de la coherencia de Markdown en proyectos controlados por versiones","Aplicación de estándares de documentación en tuberías de CI/CD"],"fr":["Automatisation de la détection de syntaxe héritée dans les répertoires docs/","Génération de rapports de migration v4 pour examen des développeurs","Validation de la cohérence de Markdown dans les projets contrôlés par version","Application des normes de documentation dans les pipelines de CI/CD"],"de":["Automatisierung der Erkennung von veralteter Syntax in docs/-Verzeichnissen","Generierung von v4-Migrationsberichten für die Überprüfung durch Entwickler","Validierung der Konsistenz von Markdown in versionskontrollierten Projekten","Durchsetzung von Dokumentationsstandards in CI/CD-Pipelines"],"pt":["Automatizar a detecção de sintaxe legada em diretórios docs/","Gerar relatórios de migração v4 para revisão do desenvolvedor","Validar a consistência do Markdown em projetos controlados por versão","Impor padrões de documentação em pipelines de CI/CD"],"ru":["Автоматизировать обнаружение устаревшего синтаксиса в директориях docs/","Генерировать отчеты о миграции v4 для обзора разработчиком","Проверять согласованность Markdown в проектах, контролируемых по версиям","Внедрять стандарты документации в конвейерах CI/CD"],"ar":["تأتمتة الكشف عن البناء القديم في المجلدات docs/","توليد تقارير هجرة الإصدار v4 للمراجعة النمطية","التحقق من الاتساق في Markdown في المشاريع المسيطر عليها بإصدار","تنفيذ معايير الوثائق في خطوط أنابيب CI/CD"]},"limitations":{"en":["Limited to Markdown file analysis","Requires filesystem access to scan docs/working/","Nuxt UI-specific syntax patterns only"],"zh":["仅限Markdown文件分析","需要文件系统访问权限来扫描docs/working/","仅支持Nuxt UI特定语法模式"],"ja":["Markdownファイル分析のみ","docs/working/のスキャンにファイルシステムへのアクセスが必要","Nuxt UI特有の構文パターンのみ"],"ko":["Markdown 파일 분석만 가능","docs/working/ 스캔을 위해 파일 시스템 접근 권한 필요","Nuxt UI 특정 구문 패턴만 지원"],"es":["Limitado al análisis de archivos Markdown","Requiere acceso al sistema de archivos para escanear docs/trabajando/","Patrones de sintaxis específicos de Nuxt UI solamente"],"fr":["Limité à l''analyse de fichiers Markdown","Nécessite un accès au système de fichiers pour analyser docs/travail/","Modèles de syntaxe spécifiques à Nuxt UI uniquement"],"de":["Begrenzt auf die Analyse von Markdown-Dateien","Benötigt Zugriff auf das Dateisystem, um docs/Arbeitsverzeichnisse zu scannen","Nuxt UI-spezifische Syntaxmuster nur"],"pt":["Limitado à análise de arquivos Markdown","Exige acesso ao sistema de arquivos para digitalizar docs/working/","Padrões de sintaxe específicos do Nuxt UI apenas"],"ru":["Ограничен анализом файлов Markdown","Требует доступа к файловой системе для сканирования docs/working/","Только шаблоны синтаксиса, специфичные для Nuxt UI"],"ar":["محدود بتحليل ملفات Markdown","يتطلب الوصول إلى نظام الملفات لفحص docs/working/","أنماط البناء الخاصة بنuxt UI فقط"]},"version":4},"contentHash":"8d22e34b33cf23a0b5e170c3e86950f566dcef3dd996b6db1a4b617d2c31fdab","qualityScore":30}');
