INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sakamotchi/sql-query-build/check-nuxt-ui-v4', 'check-nuxt-ui-v4', 'sakamotchi', 'sql-query-build', 'community', 'check-nuxt-ui-v4 sakamotchi sql-query-build community The check-nuxt-ui-v4 skill scans Markdown documents for Nuxt UI v3 syntax and suggests corrections to v4 syntax, benefiting developers in maintaining consistent and up-to-date documentation. check-nuxt-ui-v4技能用于检测Nuxt UI v3的旧语法，并自动更正为v4语法，支持Markdown文档扫描 check-nuxt-ui-v4スキルは、Nuxt UI v3の古い記法を検出し、v4記法に自動修正するために使用され、Markdownドキュメントのスキャンをサポートする check-nuxt-ui-v4 스킬은 Nuxt UI v3의 구문법을检测하고 v4 문법으로 자동 수정하기 위해 사용되며 Markdown 문서의 스캔을 지원합니다 check-nuxt-ui-v4 es una herramienta que ayuda a migrar a Nuxt UI v4, detectando y corrigiendo el código antiguo en documentos Markdown check-nuxt-ui-v4 est un outil qui aide à migrer vers Nuxt UI v4, en détectant et en corrigeant le code ancien dans les documents Markdown check-nuxt-ui-v4 ist ein Tool, das bei der Migration auf Nuxt UI v4 hilft, indem es alten Code in Markdown-Dokumenten erkennt und korrigiert O check-nuxt-ui-v4 é uma ferramenta que ajuda a atualizar a UI para a versão 4 do Nuxt UI, detectando e corrigindo problemas de compatibilidade. ИИ Агент check-nuxt-ui-v4 - это инструмент, который помогает обновить UI до версии 4 Nuxt UI, обнаруживая и исправляя проблемы совместимости. العامل الذكي check-nuxt-ui-v4 هو أداة تساعد في تحديث الواجهة إلى الإصدار 4 من Nuxt UI، حيث يكتشف ويصلح مشاكل التوافق. check-nuxt-ui-v4 setup guide Nuxt UI v4 migration Markdown documentation scanner check-nuxt-ui-v4 vs Nuxt UI v3 how to use check-nuxt-ui-v4 Nuxt UI v4 compatibility checker check-nuxt-ui-v4 install Nuxt UI v4 syntax converter Nuxt UI v4 语法检查 AI工具 Markdown文档扫描 UFormGroup UButtonGroup ：options= v-bind:options= Scans Markdown documents in `docs/working/` directory for Nuxt UI v3 syntax Detects and suggests corrections for `UFormGroup`, `:options=`, `options=`, and `v-bind:options=` patterns Replaces deprecated `UButtonGroup` with `UFieldGroup` in Nuxt UI v4 Supports quality checks for new and existing documentation Ensures project-wide consistency and reviews manually written documents check-nuxt-ui-v4 is a skill that checks Nuxt UI v3 syntax in Markdown documents and assists in migrating to Nuxt UI v4 syntax.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('spences10/devhub-crm/error-handling-patterns', 'community', 'spences10', 'devhub-crm', 'spences10/devhub-crm', 'error-handling-patterns', 0, 0, 30, '2026-03-08T01:57:15.345Z', '2026-03-08T02:03:33.516Z', 'edece175dbd1e75c9898dc15b690052e8923b6ed39f1c3beda89a4dde2a4590f', '{"id":"spences10/devhub-crm/error-handling-patterns","name":"error-handling-patterns","description":{"en":"Error-handling-patterns is a skill that enables AI agents to handle errors effectively using Svelte boundaries and snippets. It benefits developers by providing a robust error handling mechanism.","zh":"错误处理模式是使用 Svelte 实现错误边界和重试机制的方法，用于提升应用稳定性","ja":"エラーハンドリングパターンは、Svelte を使用してエラーボーダーとリトライメカニズムを実装する方法であり、アプリの安定性を向上させるために使用されます","ko":"오류 처리 패턴은 Svelte를 사용하여 오류 경계와 재시도 메커니즘을 구현하는 방법으로 애플리케이션의 안정성을 향상시키는 데 사용됩니다","es":"Los patrones de manejo de errores permiten a los desarrolladores gestionar errores de manera efectiva en aplicaciones Svelte","fr":"Les modèles de gestion d''erreurs permettent aux développeurs de gérer les erreurs de manière efficace dans les applications Svelte","de":"Fehlerbehandlungsmuster ermöglichen es Entwicklern, Fehler in Svelte-Anwendungen effektiv zu handhaben","pt":"O padrão de tratamento de erros é uma técnica para lidar com erros em aplicações Svelte, utilizando o componente svelte:boundary.","ru":"Шаблоны обработки ошибок - это техника для обработки ошибок в приложениях Svelte, используя компонент svelte:boundary.","ar":"نمط معالجة الأخطاء هو تقنية للتعامل مع الأخطاء في التطبيقات Svelte، باستخدام مكون svelte:boundary."},"seo":{"title":{"en":"Error-Handling-Patterns: Best Practices for AI Agents | A...","zh":"错误处理模式 Setup Guide - AIエージェント","ja":"エラーハンドリングパターン Best Practices - AIエージェント","ko":"오류 처리 패턴 Setup Guide - AI 도구","es":"Patrones de manejo de errores: Guía de configuración","fr":"Modèles de gestion d''erreurs: Meilleures pratiques","de":"Fehlerbehandlungsmuster: Einrichtungsleitfaden","pt":"Padrões de Tratamento de Erros: Guia de Configuração","ru":"ИИ Агенты: Шаблоны Обработки Ошибок - Настройка","ar":"نماذج معالجة الأخطاء: دليل الإعداد"},"description":{"en":"Discover how to implement error-handling-patterns in your AI agent projects. Learn how to use Svelte boundaries and snippets to catch component errors and im...","zh":"学习错误处理模式，使用 Svelte 实现错误边界和重试机制，提升应用稳定性","ja":"エラーハンドリングパターンを学び、Svelte を使用してエラーボーダーとリトライメカニズムを実装して、アプリの安定性を向上させる","ko":"오류 처리 패턴을 학습하고 Svelte를 사용하여 오류 경계와 재시도 메커니즘을 구현하여 애플리케이션의 안정성을 향상시키는 방법","es":"Aprende a implementar patrones de manejo de errores con Svelte y mejora la experiencia del usuario con nuestra guía de configuración","fr":"Découvrez comment mettre en œuvre des modèles de gestion d''erreurs avec Svelte et améliorez l''expérience utilisateur avec notre guide de configuration","de":"Erfahren Sie, wie Sie Fehlerbehandlungsmuster mit Svelte implementieren und die Benutzererfahrung mit unserem Einrichtungsleitfaden verbessern","pt":"Aprenda a implementar padrões de tratamento de erros em sua aplicação com o componente svelte:boundary","ru":"Изучите шаблоны обработки ошибок с помощью компонента svelte:boundary для ИИ Агентов","ar":"تعلم كيفية تنفيذ نماذج معالجة الأخطاء في تطبيقك باستخدام مكون svelte:boundary"},"definition":{"en":"Error-handling-patterns is a technique used to catch and handle component errors in Svelte applications, ensuring a better user experience.","zh":"错误处理模式是指使用 Svelte 的错误边界和重试机制来处理应用错误","ja":"エラーハンドリングパターンとは、Svelte のエラーボーダーとリトライメカニズムを使用してアプリのエラーを処理する方法","ko":"오류 처리 패턴은 Svelte의 오류 경계와 재시도 메커니즘을 사용하여 애플리케이션의 오류를 처리하는 방법","es":"Un patrón de manejo de errores es una técnica para capturar y manejar errores en aplicaciones Svelte","fr":"Un modèle de gestion d''erreurs est une technique pour capturer et gérer les erreurs dans les applications Svelte","de":"Ein Fehlerbehandlungsmuster ist eine Technik zum Erfassen und H