INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('spences10/devhub-crm/error-handling-patterns', 'error-handling-patterns', 'spences10', 'devhub-crm', 'community', 'error-handling-patterns spences10 devhub-crm community Error-handling-patterns is a skill that enables AI agents to handle errors effectively using Svelte boundaries and snippets. It benefits developers by providing a robust error handling mechanism. 错误处理模式是使用 Svelte 实现错误边界和重试机制的方法，用于提升应用稳定性 エラーハンドリングパターンは、Svelte を使用してエラーボーダーとリトライメカニズムを実装する方法であり、アプリの安定性を向上させるために使用されます 오류 처리 패턴은 Svelte를 사용하여 오류 경계와 재시도 메커니즘을 구현하는 방법으로 애플리케이션의 안정성을 향상시키는 데 사용됩니다 Los patrones de manejo de errores permiten a los desarrolladores gestionar errores de manera efectiva en aplicaciones Svelte Les modèles de gestion d''erreurs permettent aux développeurs de gérer les erreurs de manière efficace dans les applications Svelte Fehlerbehandlungsmuster ermöglichen es Entwicklern, Fehler in Svelte-Anwendungen effektiv zu handhaben O padrão de tratamento de erros é uma técnica para lidar com erros em aplicações Svelte, utilizando o componente svelte:boundary. Шаблоны обработки ошибок - это техника для обработки ошибок в приложениях Svelte, используя компонент svelte:boundary. نمط معالجة الأخطاء هو تقنية للتعامل مع الأخطاء في التطبيقات Svelte، باستخدام مكون svelte:boundary. error-handling-patterns setup guide how to use error-handling-patterns in Svelte error-handling-patterns vs try-catch blocks error-handling-patterns install for AI agents what is error-handling-patterns in Svelte error-handling-patterns best practices for developers error-handling-patterns alternative approaches error-handling-patterns tutorial for AI agent developers 错误处理模式 Svelte 错误边界 重试机制 错误处理最佳实践 AIエージェント 错误处理 setup Svelte 应用错误处理 Uses Svelte boundaries to catch component errors Utilizes snippets to display loading and error messages Supports retry functionality with the reset button Implements error handling using the failed(error, reset) snippet Leverages the get_contacts() function to fetch contact data Employs the svelte:boundary directive to wrap error-prone components Error-handling-patterns is a technique used to catch and handle component errors in Svelte applications, ensuring a better user experience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('WHITS-ISLAND/inspirehub-mobile/retro', 'community', 'WHITS-ISLAND', 'inspirehub-mobile', 'WHITS-ISLAND/inspirehub-mobile', 'retro', 0, 0, 30, '2026-03-08T01:57:15.345Z', '2026-03-08T02:03:34.017Z', '8319a10e00954c03febe742344a78c0fb8df3ccec17130ec12463f5888e80985', '{"id":"WHITS-ISLAND/inspirehub-mobile/retro","name":"retro","description":{"en":"Retro analyzes agent memory and proposes efficiency improvements, benefiting developers by automating repetitive tasks and enhancing AI agent performance.","zh":"Retro AI Agent 是一种分析エージェントメモリ、检测重复模式、优化性能的工具","ja":"Retro AIエージェントはエージェントメモリを分析し、繰り返しパターンを検出して効率化を提案するツールです","ko":"Retro AI 에이전트는 에이전트 메모리를 분석하고 반복 패턴을 검출하여 최적화를 제안하는 툴입니다","es":"Retro es una plataforma de compartición de ideas que analiza la memoria de los agentes de inteligencia artificial y proporciona propuestas de optimización","fr":"Retro est une plateforme de partage d''idées qui analyse la mémoire des agents d''intelligence artificielle et propose des optimisations","de":"Retro ist eine Plattform für Ideenverteilung, die die Speicherung von KI-Agents analysiert und Optimierungsvorschläge bereitstellt","pt":"O Retro é um skill que analisa a memória dos agentes de IA para detectar padrões repetitivos e sugerir melhorias","ru":"Retro - это навык, который анализирует память ИИ Агентов для обнаружения повторяющихся закономерностей и предложения улучшений","ar":"Retro هو مهارة تحليل ذاكرة وكلاء الذكاء الاصطناعي لاكتشاف الأنماط المكررة واقتراح التحسينات"},"seo":{"title":{"en":"Retro: Efficiency Optimization for AI Agents | AI Agent S...","zh":"Retro AI Agent 效率化设置指南","ja":"Retro AIエージェントの効率化セットアップガイド","ko":"Retro AI 에이전트 최적화 설정 가이드","es":"Guía de Configuración de Retro: Optimización de Agentes d...","fr":"Guide de Configuration de Retro : Optimisation des Agents...","de":"Retro-Konfigurationsleitfaden: Optimierung von KI-Agents","pt":"Retro: Guia de Configuração para Análise de Memória de Ag...","ru":"Retro: Настройка анализа памяти ИИ Агентов","ar":"Retro: دليل إعداد تحليل ذاكرة وكلاء الذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of your AI agents with Retro, the ultimate efficiency optimization skill - discover how to automate repetitive tasks and improve pe...","zh":"Retro AI Agent 功能介绍：分析エージェントメモリ，检测重复模式，优化性能","ja":"Retro AIエージェントの機能紹介：エージェントメモリ分析、繰り返しパターンの検出、効率化提案","ko":"Retro AI 에이전트 기능 소개: 에이전트 메모리 분석, 반복 패턴検출, 최적화 제안","es":"Aprende a configurar y optimizar los agentes de inteligencia artificial con Retro, mejora la eficiencia y reduce la complejidad","fr":"Découvrez comment configurer et optimiser les agents d''intelligence artificielle avec Retro, améliorez l''efficacité et réduisez la complexité","de":"Erfahren Sie, wie Sie KI-Agents mit Retro konfigurieren und optimieren, verbessern Sie die Effizienz und reduzieren die Komplexität","pt":"Descubra como o Retro ajuda a otimizar a memória dos agentes de IA, detectando padrões repetitivos e sugerindo melhorias","ru":"Узнайте, как Retro помогает оптимизировать память ИИ Агентов, обнаруживая повторяющиеся закономерности и предлагая улучшения","ar":"تعرف على كيفية مساعدة Retro في تحسين ذاكرة وكلاء الذكاء الاصطناعي، من خلال كشف النمط المكرر وتقديم اقتراحات التحسين"},"definition":{"en":"Retro is a skill that analyzes agent memory, detects repeated patterns, and proposes automation opportunities to optimize AI agent efficiency.","zh":"Retro AI Agent 是一种用于分析和优化 AI エージェント性能的工具","ja":"Retro AIエージェントはAIエージェントの性能を分析・最適化するためのツールです","ko":"Retro AI 에이전트는 AI 에이전트의 성능을 분석하고 최적화하는 툴입니다","es":"Retro es un skill que analiza la memoria de los agentes de inteligencia artificial para optimizar su rendimiento","fr":"Retro est un skill qui analyse la mémoire des agents d''intelligence artificielle pour optimiser leur performance","de":"Retro ist ein Skill, der die Speicherung von KI-Agents analysiert, um deren Leistung zu optimieren","pt":"Retro é uma ferramenta de análise de memória de agentes de IA que ajuda a identificar áreas de melhoria","ru":"Retro - это инструмент анализа памяти ИИ Агентов, помогающий выявить области для улучшения","ar":"Retro هو أداة تحليل ذاكرة وكلاء الذكاء الاصطناعي التي تساعد في تحديد مجالات التحسين"},"features":{"en":["Analyzes `.claude/agent-memory/*/MEMORY.md` files to detect repeated patterns","Proposes automation opportunities based on repeated patterns","Checks for context bloating in MEMORY.md files with over 200 lines","Suggests sub-agent creation for uncovered areas","Recommends shared rule creation for duplicated knowledge"],"zh":["分析エージェントメモリ","检测重复模式","优化性能","自动化スキル化","コンテキスト肥大化チェック"],"ja":["エージェントメモリ分析","繰り返しパターンの検出","効率化提案","スキル化自動化","コンテキスト肥大化チェック"],"ko":["에이전트 메모리 분석","반복 패턴 검출","최적화 제안","스킬 자동화","콘텍스트 비대화 체크"],"es":["Análisis de la memoria de los agentes de inteligencia artificial","Detección de patrones repetitivos para la automatización","Propuestas de optimización para mejorar la eficiencia","Comprobación de la complejidad de la memoria y recomendaciones de reorganización","Detección de áreas no cubiertas por los agentes existentes y propuestas de nuevos agentes"],"fr":["Analyse de la mémoire des agents d''intelligence artificielle","Détection de modèles répétitifs pour l''automatisation","Propositions d''optimisation pour améliorer l''efficacité","Vérification de la complexité de la mémoire et recommandations de réorganisation","Détection de domaines non couverts par les agents existants et propositions de nouveaux agents"],"de":["Analyse der Speicherung von KI-Agents","Erkennung von wiederkehrenden Mustern für die Automatisierung","Optimierungsvorschläge zur Verbesserung der Effizienz","Überprüfung der Komplexität der Speicherung und Empfehlungen zur Reorganisation","Erkennung von nicht abgedeckten Bereichen durch bestehende Agents und Vorschläge für neue Agents"],"pt":["Análise de memória de agentes de IA para detectar padrões repetitivos","Sugestão de melhorias baseada em padrões detectados","Verificação de duplicação de conhecimento entre agentes","Proposta de criação de novos agentes para cobrir lacunas","Checagem de integridade de MEMORY.md para evitar problemas de desempenho"],"ru":["Анализ памяти ИИ Агентов для обнаружения повторяющихся закономерностей","Предложение улучшений на основе обнаруженных закономерностей","Проверка дублирования знаний между агентами","Предложение создания новых агентов для покрытия пробелов","Проверка целостности MEMORY.md для предотвращения проблем с производительностью"],"ar":["تحليل ذاكرة وكلاء الذكاء الاصطناعي لاكتشاف الأنماط المكررة","اقتراح تحسينات بناءً على الأنماط المكتشفة","التحقق من تكرار المعرفة بين الوكلاء","اقتراح إنشاء وكلاء جدد لتغطية الفجوات","التحقق من سلامة MEMORY.md لتجنب مشاكل الأداء"]},"keywords":{"en":["how to use retro","retro ai agent skill","retro vs other optimization tools","retro install guide","what is retro","retro alternative","retro setup tutorial","retro efficiency optimization","retro for ai developers"],"zh":["Retro AI Agent","AIエージェント","エージェントメモリ分析","繰り返しパターン検出","効率化提案","スキル化自動化","コンテキスト肥大化チェック"],"ja":["Retro AIエージェント","AIエージェント","エージェントメモリ分析","繰り返しパターンの検出","効率化提案","スキル化自動化","コンテキスト肥大化チェック"],"ko":["Retro AI 에이전트","AI 에이전트","에이전트 메모리 분석","반복 패턴 검출","최적화 제안","스킬 자동화","콘텍스트 비대화 체크"],"es":["agentes de inteligencia artificial","optimización de agentes","automatización de tareas","análisis de memoria","compartición de ideas","platormas de inteligencia artificial","desarrollo de agentes","IA","inteligencia artificial"],"fr":["agents d''intelligence artificielle","optimisation des agents","automatisation des tâches","analyse de la mémoire","partage d''idées","plateformes d''intelligence artificielle","développement d''agents","IA","intelligence artificielle"],"de":["KI-Agents","Optimierung von KI-Agents","Automatisierung von Aufgaben","Analyse der Speicherung","Ideenverteilung","Plattformen für Künstliche Intelligenz","Entwicklung von KI-Agents","KI","Künstliche Intelligenz"],"pt":["Retro","Análise de memória de agentes de IA","Otimização de desempenho","Detecção de padrões repetitivos","Melhoria de agentes de IA","Desenvolvimento de agentes de IA","Ferramentas de análise de memória"],"ru":["Retro","Анализ памяти ИИ Агентов","Оптимизация производительности","Обнаружение повторяющихся закономерностей","Улучшение ИИ Агентов","Разработка ИИ Агентов","Инструменты анализа памяти"],"ar":["Retro","تحليل ذاكرة وكلاء الذكاء الاصطناعي","تحسين الأداء","اكتشاف الأنماط المكررة","تحسين وكلاء الذكاء الاصطناعي","تطوير وكلاء الذكاء الاصطناعي","أدوات تحليل الذاكرة"]}},"owner":"WHITS-ISLAND","repo":"inspirehub-mobile","repoPath":"WHITS-ISLAND/inspirehub-mobile","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.345Z","topics":[],"category":"community","skillMd":{"name":"retro","description":"エージェントの振り返りを実行し、スキル化候補・サブエージェント増設提案・コンテキスト肥大化チェックをレポートする","bodyPreview":"# 振り返り・効率化スキル\r\n\r\nエージェントのメモリを分析し、効率化のための提案を行う。\r\n\r\n## 処理フロー\r\n\r\n### 1. エージェントメモリ分析\r\n\r\n- `.claude/agent-memory/*/MEMORY.md` を全て読み込み\r\n- 各ファイルの行数をチェック（200行超 → コンテキスト肥大化警告）\r\n- 「Repeated Patterns」セクションから繰り返しパターンを集約\r\n\r\n### 2. スキル化候補の検出\r\n\r\n- 繰り返しパターンを分析し、スキル化で自動化できるものを提案\r\n- 既存スキル（`.claude/skills/*/SKILL.md`）と重複しないか確認\r\n\r\n### 3. サブエージェント増設の判断\r\n\r\n- 「Pain Points」セクションから、既存エージェントではカバーできない領域を検出\r\n- 新エージェント作成の提案（役割・ツール・スコープ）\r\n\r\n### 4. コンテキスト肥大化チェック\r\n\r\n- MEMORY.mdの行数 > 200行: 整理推奨\r\n- 同じ知見が複数エージェントに重複: 共有ルール化を提案","body":"# 振り返り・効率化スキル\r\n\r\nエージェントのメモリを分析し、効率化のための提案を行う。\r\n\r\n## 処理フロー\r\n\r\n### 1. エージェントメモリ分析\r\n\r\n- `.claude/agent-memory/*/MEMORY.md` を全て読み込み\r\n- 各ファイルの行数をチェック（200行超 → コンテキスト肥大化警告）\r\n- 「Repeated Patterns」セクションから繰り返しパターンを集約\r\n\r\n### 2. スキル化候補の検出\r\n\r\n- 繰り返しパターンを分析し、スキル化で自動化できるものを提案\r\n- 既存スキル（`.claude/skills/*/SKILL.md`）と重複しないか確認\r\n\r\n### 3. サブエージェント増設の判断\r\n\r\n- 「Pain Points」セクションから、既存エージェントではカバーできない領域を検出\r\n- 新エージェント作成の提案（役割・ツール・スコープ）\r\n\r\n### 4. コンテキスト肥大化チェック\r\n\r\n- MEMORY.mdの行数 > 200行: 整理推奨\r\n- 同じ知見が複数エージェントに重複: 共有ルール化を提案\r\n\r\n### 5. レポート出力\r\n\r\n## 出力フォーマット\r\n\r\n```markdown\r\n## 振り返りレポート\r\n\r\n### コンテキスト状況\r\n| エージェント | MEMORY.md行数 | ステータス |\r\n|-------------|--------------|-----------|\r\n| kotlin-dev  | 45行         | 正常      |\r\n| ios-dev     | 210行        | 要整理    |\r\n\r\n### スキル化候補\r\n- [ ] (パターン名)（(エージェント名)で(N)回以上実施）\r\n\r\n### サブエージェント増設提案\r\n- (提案またはなし)\r\n\r\n### ルール追加提案\r\n- [ ] (提案)\r\n```\r\n\r\n## エージェントメモリ規約\r\n\r\n各エージェントのMEMORY.mdに以下のセクションを維持する:\r\n\r\n- **Repeated Patterns**: 繰り返し行った作業パターン\r\n- **Pain Points**: 既存の仕組みでは解決しにくかった課題\r\n- **Lessons Learned**: 学んだ知見・ベストプラクティス\r\n"},"lastSynced":"2026-03-08T02:03:34.017Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude, AutoGPT, or LangChain requiring efficiency improvements through automated task analysis and optimization.","zh":"适用于 Claude、AutoGPT 或 LangChain 等需要通过自动任务分析和优化来提高效率的 AI Agents。","ja":"Claude、AutoGPT、LangChain などの効率性の向上を必要とする AI エージェントに適しています。","ko":"효율성을 향상하기 위해 자동화된 작업 분석 및 최적화를 필요로 하는 Claude, AutoGPT 또는 LangChain과 같은 AI 에이전트에 적합합니다.","es":"Ideal para Agentes de IA como Claude, AutoGPT o LangChain que requieren mejoras en la eficiencia a través del análisis y optimización de tareas automatizadas.","fr":"Idéal pour les agents IA comme Claude, AutoGPT ou LangChain nécessitant des améliorations d''efficacité grâce à l''analyse et à l''optimisation de tâches automatisées.","de":"Ideal für KI-Agents wie Claude, AutoGPT oder LangChain, die Effizienzverbesserungen durch automatisierte Aufgabenanalyse und -optimierung benötigen.","pt":"Ideal para Agentes de IA como Claude, AutoGPT ou LangChain que requerem melhorias de eficiência por meio de análise e otimização de tarefas automatizadas.","ru":"Идеально для агентов ИИ, таких как Claude, AutoGPT или LangChain, требующих улучшения эффективности за счет автоматизированного анализа и оптимизации задач.","ar":"مثالي لعمليات الوكلاء الذكية مثل Claude و AutoGPT و LangChain التي تتطلب تحسينات في الكفاءة من خلال تحليل المهام والتحسين التلقائي."},"recommendation":{"en":"Empowers agents to analyze their memory and propose efficiency enhancements, automating repetitive tasks and improving performance by identifying repeated patterns in `.claude/agent-memory/*/MEMORY.md` files and suggesting skill automation and sub-agent deployment.","zh":"赋予代理分析其内存并提议效率增强的能力，自动化重复任务并通过在 `.claude/agent-memoryMEMORY.md` ファイル内の繰り返しのパターンを識別することでパフォーマンスを向上させ、繰り返しのタスクの自動化とサブエージェントの展開を提案します。","ja":"Empowers agents to analyze their memory and propose efficiency enhancements, automating repetitive tasks and improving performance by identifying repeated patterns in `.claude/agent-memory/*/MEMORY.md` files and suggesting skill automation and sub-agent deployment.","ko":"에이전트가 메모리를 분석하고 효율성 향상을 제안하는 기능을 제공하여 반복되는 작업을 자동화하고 `.claude/agent-memory/*/MEMORY.md` 파일에서 반복되는 패턴을 식별하여 성능을 향상시키고, 스킬 자동화 및 서브 에이전트 배치를 제안합니다.","es":"Habilita a los agentes a analizar su memoria y proponer mejoras de eficiencia, automatizando tareas repetitivas y mejorando el rendimiento al identificar patrones repetidos en los archivos `.claude/agent-memoryMEMORY.md` et en suggérant l''automatisation des compétences et le déploiement de sous-agents.","fr":"Empowers agents to analyze their memory and propose efficiency enhancements, automating repetitive tasks and improving performance by identifying repeated patterns in `.claude/agent-memory/*/MEMORY.md` files and suggesting skill automation and sub-agent deployment.","de":"Ermöglicht es den Agents, ihr Gedächtnis zu analysieren und Effizienzverbesserungen vorzuschlagen, indem repetitive Aufgaben automatisiert und die Leistung durch die Identifizierung wiederholter Muster in `.claude/agent-memory/*/MEMORY.md`-Dateien verbessert wird und die Automatisierung von Fähigkeiten und die Bereitstellung von Subagenten vorgeschlagen wird.","pt":"Habilita os agentes a analisar a memória e propor melhorias de eficiência, automatizando tarefas repetitivas e melhorando o desempenho, identificando padrões repetidos nos arquivos `.claude/agent-memoryMEMORY.md` и предлагая автоматизацию навыков и развертывание субагентов.","ru":"Empowers agents to analyze their memory and propose efficiency enhancements, automating repetitive tasks and improving performance by identifying repeated patterns in `.claude/agent-memory/*/MEMORY.md` files and suggesting skill automation and sub-agent deployment.","ar":"تمكّن الوكلاء من تحليل الذاكرة واقتراح تحسينات في الكفاءة، وتأتمة المهام المتكررة وتحسين الأداء، من خلال تحديد الأنماط المتكررة في ملفات `.claude/agent-memory/*/MEMORY.md` واقتراح أتمتة المهارات ونشر الوكلاء الفرعيين."},"useCases":{"en":["Automating repetitive task identification","Analyzing agent memory for efficiency improvements","Proposing sub-agent deployment for enhanced performance","Detecting context bloat in MEMORY.md files"],"zh":["自动化重复任务识别","分析代理内存以提高效率","提议子代理部署以增强性能","检测 MEMORY.md 文件中的上下文膨胀"],"ja":["繰り返しのタスク識別の自動化","エージェントのメモリ分析による効率性の向上","パフォーマンスの向上のためのサブエージェントの展開の提案","MEMORY.md ファイル内のコンテキストの膨張の検出"],"ko":["반복되는 작업 식별 자동화","에이전트 메모리 분석을 통한 효율성 향상","성능 향상을 위한 서브 에이전트 배치 제안","MEMORY.md 파일 내의 컨텍스트 부풀림 감지"],"es":["Automatización de la identificación de tareas repetitivas","Análisis de la memoria del agente para mejoras de eficiencia","Propuesta de implementación de subagentes para un mejor rendimiento","Detección de inflado de contexto en archivos MEMORY.md"],"fr":["Automatisation de l''identification de tâches répétitives","Analyse de la mémoire de l''agent pour améliorer l''efficacité","Proposition de déploiement de sous-agents pour améliorer les performances","Détection de l''inflation de contexte dans les fichiers MEMORY.md"],"de":["Automatisierung der Identifizierung wiederholter Aufgaben","Analyse des Agenten-Gedächtnisses für Effizienzverbesserungen","Vorschlag zur Bereitstellung von Subagenten für verbesserte Leistung","Erkennung von Kontextaufblähung in MEMORY.md-Dateien"],"pt":["Automação da identificação de tarefas repetitivas","Análise da memória do agente para melhorias de eficiência","Proposta de implantação de sub-agentes para desempenho melhorado","Detecção de inflação de contexto em arquivos MEMORY.md"],"ru":["Автоматизация выявления повторяющихся задач","Анализ памяти агента для улучшения эффективности","Предложение развертывания субагентов для улучшения производительности","Обнаружение вздутия контекста в файлах MEMORY.md"],"ar":["أتمتة تحديد المهام المتكررة","تحليل ذاكرة الوكيل لتحسين الكفاءة","اقتراح نشر وكلاء فرعيين لتحسين الأداء","كشف انفجار السياق في ملفات MEMORY.md"]},"limitations":{"en":["Requires access to `.claude/agent-memory` and `.claude/skills` directories","Limited to agents with MEMORY.md files","Context bloat detection limited to 200-line threshold in MEMORY.md files"],"zh":["需要访问 `.claude/agent-memory` 和 `.claude/skills` 目录","仅限于具有 MEMORY.md 文件的代理","MEMORY.md 文件中的上下文膨胀检测仅限于 200 行阈值"],"ja":["`.claude/agent-memory` と `.claude/skills` ディレクトリへのアクセスが必要","MEMORY.md ファイルを持つエージェントのみに限定","MEMORY.md ファイル内のコンテキストの膨張の検出は 200 行のしきい値に限定"],"ko":["`.claude/agent-memory` 및 `.claude/skills` 디렉토리에 대한 액세스가 필요","MEMORY.md 파일을 갖는 에이전트에만 제한","MEMORY.md 파일 내의 컨텍스트 부풀림 감지는 200줄 임계값으로 제한"],"es":["Requiere acceso a los directorios `.claude/agent-memory` y `.claude/skills`","Limitado a agentes con archivos MEMORY.md","La detección de inflado de contexto está limitada a un umbral de 200 líneas en archivos MEMORY.md"],"fr":["Nécessite l''accès aux répertoires `.claude/agent-memory` et `.claude/skills`","Limité aux agents avec des fichiers MEMORY.md","La détection de l''inflation de contexte est limitée à un seuil de 200 lignes dans les fichiers MEMORY.md"],"de":["Erfordert den Zugriff auf die Verzeichnisse `.claude/agent-memory` und `.claude/skills`","Begrenzt auf Agents mit MEMORY.md-Dateien","Die Erkennung von Kontextaufblähung ist auf eine Schwelle von 200 Zeilen in MEMORY.md-Dateien begrenzt"],"pt":["Requer acesso aos diretórios `.claude/agent-memory` e `.claude/skills`","Limitado a agentes com arquivos MEMORY.md","Detecção de inflação de contexto limitada a um limiar de 200 linhas em arquivos MEMORY.md"],"ru":["Требует доступа к директориям `.claude/agent-memory` и `.claude/skills`","Ограничен агентами с файлами MEMORY.md","Обнаружение вздутия контекста ограничено порогом в 200 строк в файлах MEMORY.md"],"ar":["يتطلب الوصول إلى الدلائل `.claude/agent-memory` و `.claude/skills`","محدود بالوكلاء الذين لديهم ملفات MEMORY.md","يكشف انفجار السياق مقيد بمعايير 200 سطر في ملفات MEMORY.md"]},"version":4},"contentHash":"8319a10e00954c03febe742344a78c0fb8df3ccec17130ec12463f5888e80985","qualityScore":30}');
