INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shiroinock/Darts-Score-Trainer/dartboard-rendering', 'dartboard-rendering', 'shiroinock', 'Darts-Score-Trainer', 'community', 'dartboard-rendering shiroinock Darts-Score-Trainer community The dartboard-rendering skill generates accurate dartboard layouts, benefiting developers and designers who need to create realistic graphics Dartboard Rendering是一种实现ダーツボード的描画顺序和层次结构的技术，通过遵循特定的原则和最佳实践来优化AIエージェント的开发 ダーツボード描画は、ダーツボードのレイヤリングと描画順序を正しく実現する技術です 다트보드 렌더링은 다트보드의 렌더링 순서와 계층 구조를 구현하는 기술로, 개발을 최적화하기 위한 원리와 최적화 방법을 제공합니다 El renderizado de dianas de dardos implica seguir un orden específico para lograr una capa correcta, desde la limpieza de fondo hasta la visualización de segmentos numéricos Le rendering de cibles de fléchettes implique de suivre un ordre spécifique pour atteindre une couche correcte, de la purge de l''arrière-plan à la visualisation des numéros de segments Das Rendering von Dartboards beinhaltet die Befolgung einer bestimmten Reihenfolge, um eine korrekte Schicht zu erreichen, von der Hintergrundlöschung bis zur Anzeige von Segmentnummern Renderização de dartboard com precisão, seguindo os padrões de camada certos Рендеринг дартсборда с точностью, следуя правильному порядку слоев تصيير لوحة الدارت بالدقة، باتباع قواعد الطبقات الصحيحة how to use dartboard-rendering dartboard-rendering setup guide dartboard rendering best practices what is dartboard-rendering dartboard-rendering implementation pattern dartboard rendering for AI agents Dartboard Rendering AIエージェント ダーツボード描画 描画順序 レイヤリング スパイダー セグメント番号 Implements drawing order principles for accurate layering Supports rendering of double ring, outer single, triple ring, and inner single sections Generates spider wire boundaries using two-step rendering process Includes rendering of outer and inner bullseye targets Defines segment numbering for precise dartboard layout Dartboard-rendering is a technical implementation pattern that defines the drawing order and best practices for rendering dartboards');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stpcoder/kakao-terminal/kakao-down', 'community', 'stpcoder', 'kakao-terminal', 'stpcoder/kakao-terminal', 'kakao-down', 0, 0, 30, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:44.724Z', '67db497cb993367091acf522e206cb4a30d50378dccbad13c72a3df3e87dc918', '{"id":"stpcoder/kakao-terminal/kakao-down","name":"kakao-down","description":{"en":"The kakao-down skill retrieves the latest KakaoTalk messages, allowing developers to access recent conversations. It benefits developers who need to integrate KakaoTalk messaging into their applications.","zh":"Kakao-Down AI工具允许开发者使用Python CLI命令查看最新的KakaoTalk消息","ja":"Kakao-Down AIエージェントは、Python CLIコマンドを使用して最新のKakaoTalkメッセージを閲覧することができます","ko":"카카오톡 최신 메시지 보기 kakao-down은 Python CLI 명령어를 통해 최신의 카카오톡 메시지를 볼 수 있는 기술입니다","es":"kakao-down es una herramienta que permite ver los mensajes más recientes de KakaoTalk mediante Python y CLI","fr":"kakao-down est un outil qui permet d''afficher les messages les plus récents de KakaoTalk à l''aide de Python et de CLI","de":"kakao-down ist ein Tool, das die Anzeige der neuesten KakaoTalk-Nachrichten mithilfe von Python und CLI ermöglicht","pt":"O kakao-down é uma ferramenta que permite visualizar as mensagens mais recentes do KakaoTalk com facilidade, utilizando o CLI do Python.","ru":"ИИ Агент kakao-down - это инструмент, который позволяет просматривать последние сообщения в KakaoTalk, используя Python CLI.","ar":"kakao-down هو أداة تمكنك من عرض الرسائل الحديثة في KakaoTalk بسهولة، باستخدام واجهة سطر الأوامر Python."},"seo":{"title":{"en":"kakao-down: Latest Message Retrieval Setup Guide | AI Age...","zh":"Kakao-Down AI工具设置指南","ja":"Kakao-Down AIエージェントのベストプラクティス","ko":"카카오톡 최신 메시지 보기 kakao-down Setup Guide","es":"Guía de configuración de kakao-down para desarrolladores","fr":"Guide de mise en place de kakao-down pour les développeurs","de":"Einrichtungsleitfaden für kakao-down-Entwickler","pt":"Guia de Configuração do kakao-down: Visualize Mensagens R...","ru":"Настройка ИИ Агента kakao-down: Руководство по просмотру ...","ar":"دليل إعداد kakao-down: عرض الرسائل الحديثة"},"description":{"en":"Discover how to fetch the latest KakaoTalk messages with kakao-down. Learn to use the `/kakao-down` command and optimize your workflow today!","zh":"了解Kakao-Down AI工具的技术细节，包括Python CLI命令和最新消息查看功能","ja":"Kakao-Down AIエージェントの機能と設定方法を紹介します。最新メッセージの閲覧やPython CLIコマンドについても解説","ko":"카카오톡 최신 메시지 보기 kakao-down의 기술 내용과 설정 방법을 알아보세요. Python CLI 명령어와 최신 메시지 보기 기능 등","es":"Aprende a utilizar kakao-down para ver los mensajes más recientes de KakaoTalk con Python y CLI","fr":"Découvrez comment utiliser kakao-down pour afficher les messages les plus récents de KakaoTalk avec Python et CLI","de":"Erfahren Sie, wie Sie kakao-down verwenden, um die neuesten KakaoTalk-Nachrichten mit Python und CLI anzuzeigen","pt":"Aprenda a configurar o kakao-down para visualizar as 10 mensagens mais recentes do KakaoTalk com facilidade","ru":"Узнайте, как настроить ИИ Агент kakao-down, чтобы просматривать последние 10 сообщений в KakaoTalk","ar":"تعرف على كيفية إعداد kakao-down لعرض 10 رسائل حديثة في KakaoTalk بسهولة"},"definition":{"en":"kakao-down is a command-line tool that fetches the latest KakaoTalk messages, using the `/kakao-down` command with optional offset parameters.","zh":"Kakao-Down AI工具是一种使用Python CLI命令查看KakaoTalk最新消息的技术","ja":"Kakao-Down AIエージェントは、KakaoTalkの最新メッセージを閲覧するためのPython CLIコマンドを使用する技術です","ko":"카카오톡 최신 메시지 보기 kakao-down은 카카오톡의 최신 메시지를 보기 위한 Python CLI 명령어를 사용하는 기술입니다","es":"kakao-down es una herramienta de línea de comandos que muestra los mensajes más recientes de KakaoTalk","fr":"kakao-down est un outil de ligne de commande qui affiche les messages les plus récents de KakaoTalk","de":"kakao-down ist ein Kommandozeilen-Tool, das die neuesten KakaoTalk-Nachrichten anzeigt","pt":"O kakao-down é uma ferramenta de linha de comando que permite visualizar as mensagens mais recentes do KakaoTalk","ru":"ИИ Агент kakao-down - это инструмент командной строки, который позволяет просматривать последние сообщения в KakaoTalk","ar":"kakao-down هو أداة سطر الأوامر التي تمكنك من عرض الرسائل الحديثة في KakaoTalk"},"features":{"en":["Executes the `kakao_cli.py down` command to retrieve latest messages","Supports offset parameters, e.g., `/kakao-down 20`, to fetch a specified number of messages","Automatically decreases offset on each call to retrieve newer messages","Resets to the latest messages with the `/kakao-refresh` command","Navigates to previous messages with the `/kakao-up` command"],"zh":["使用Python CLI命令查看最新的KakaoTalk消息","支持设置消息数量，例如/kakao-down 20","具有调用时offset减少的功能","支持/kakao-up和/kakao-refresh命令"],"ja":["Python CLIコマンドを使用して最新のKakaoTalkメッセージを閲覧","メッセージ数の設定が可能，例：/kakao-down 20","呼出時にoffsetが減少する機能","／kakao-upおよび／kakao-refreshコマンドのサポート"],"ko":["Python CLI 명령어를 통해 최신의 카카오톡 메시지를 볼 수 있음","메시지 수 설정이 가능함, 예: /kakao-down 20","호출할 때마다 offset이 감소하는 기능","/kakao-up 및 /kakao-refresh 명령어 지원"],"es":["Ver los 10 mensajes más recientes de KakaoTalk de forma predeterminada","Opción para ver un número personalizado de mensajes más recientes","Utiliza Python y CLI para interactuar con KakaoTalk","Offset de decremento automático para cargar mensajes más antiguos","Compatibilidad con comandos como /kakao-up y /kakao-refresh"],"fr":["Afficher les 10 messages les plus récents de KakaoTalk par défaut","Option pour afficher un nombre personnalisé de messages les plus récents","Utilise Python et CLI pour interagir avec KakaoTalk","Décrément automatique de l''offset pour charger des messages plus anciens","Compatibilité avec des commandes comme /kakao-up et /kakao-refresh"],"de":["Anzeige der 10 neuesten KakaoTalk-Nachrichten standardmäßig","Option, um eine benutzerdefinierte Anzahl von Nachrichten anzuzeigen","Verwendung von Python und CLI zur Interaktion mit KakaoTalk","Automatischer Offset-Abzug zum Laden älterer Nachrichten","Unterstützung für Befehle wie /kakao-up und /kakao-refresh"],"pt":["Visualize as 10 mensagens mais recentes do KakaoTalk","Utiliza o CLI do Python para executar comandos","Permite ajustar o número de mensagens exibidas","Utiliza offset para controlar a ordem das mensagens","Permite resetar para as mensagens mais recentes"],"ru":["Просматривает последние 10 сообщений в KakaoTalk","Использует Python CLI для выполнения команд","Позволяет регулировать количество отображаемых сообщений","Использует смещение для контроля порядка сообщений","Позволяет сбросить до последних сообщений"],"ar":["يعرض 10 رسائل حديثة في KakaoTalk","يستخدم واجهة سطر الأوامر Python للتشغيل","يسمح بالتحكم في عدد الرسائل المعروضة","يستخدم الإزاحة للتحكم في ترتيب الرسائل","يسمح بإعادة ضبط إلى الرسائل الحديثة"]},"keywords":{"en":["how to use kakao-down","kakao-down setup guide","kakao-down alternative","kakao-down vs other messaging tools","kakao-down install","latest KakaoTalk message retrieval","KakaoTalk messaging integration","command-line messaging tools"],"zh":["Kakao-Down AI工具","Python CLI命令","KakaoTalk最新消息","AI工具设置","Kakao-Down设置指南","Python开发","CLI命令"],"ja":["Kakao-Down AIエージェント","Python CLIコマンド","KakaoTalk最新メッセージ","AIエージェントの設定","Kakao-Downのベストプラクティス","Python開発","CLIコマンド"],"ko":["카카오톡 최신 메시지 보기","kakao-down","Python CLI 명령어","카카오톡 메시지","AI 에이전트 설정","카카오톡 최신 메시지 보기 설정 방법","Python 개발","CLI 명령어"],"es":["kakao-down","KakaoTalk","Python","CLI","herramientas de desarrollo","mensaje más reciente","offset de decremento","comandos personalizados"],"fr":["kakao-down","KakaoTalk","Python","CLI","outils de développement","message le plus récent","décrément d''offset","commandes personnalisées"],"de":["kakao-down","KakaoTalk","Python","CLI","Entwicklungstools","neueste Nachricht","Offset-Abzug","benutzerdefinierte Befehle"],"pt":["kakao-down","KakaoTalk","CLI do Python","visualizar mensagens recentes","ferramenta de linha de comando","configuração do kakao-down"],"ru":["kakao-down","KakaoTalk","Python CLI","просмотр последних сообщений","инструмент командной строки","настройка ИИ Агента kakao-down"],"ar":["kakao-down","KakaoTalk","واجهة سطر الأوامر Python","عرض الرسائل الحديثة","أداة سطر الأوامر","إعداد أداة kakao-down"]}},"owner":"stpcoder","repo":"kakao-terminal","repoPath":"stpcoder/kakao-terminal","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.349Z","topics":[],"category":"community","skillMd":{"name":"kakao-down","description":"카카오톡 최신 메시지 보기. 카톡 아래로, 최신 메시지, kakao down, KakaoTalk scroll down 시 사용.","bodyPreview":"# 카카오톡 최신 메시지 보기\n\n아래로 스크롤하여 최신 메시지를 봅니다.\n\n## 실행\n\n```bash\ncd /Users/taehoje/space/kakao-terminal && python kakao_cli.py down $ARGUMENTS\n```\n\n## 옵션\n\n- `/kakao-down` - 10개 최신으로 (기본)\n- `/kakao-down 20` - 20개 최신으로\n\n## 동작 방식\n\n- 호출할 때마다 offset 감소\n- 최소 offset은 0 (가장 최신)\n- 현재에 가까운 메시지를 읽음\n\n## 다음 단계\n\n- `/kakao-up` - 이전 메시지로\n- `/kakao-refresh` - 가장 최신으로 리셋","body":"# 카카오톡 최신 메시지 보기\n\n아래로 스크롤하여 최신 메시지를 봅니다.\n\n## 실행\n\n```bash\ncd /Users/taehoje/space/kakao-terminal && python kakao_cli.py down $ARGUMENTS\n```\n\n## 옵션\n\n- `/kakao-down` - 10개 최신으로 (기본)\n- `/kakao-down 20` - 20개 최신으로\n\n## 동작 방식\n\n- 호출할 때마다 offset 감소\n- 최소 offset은 0 (가장 최신)\n- 현재에 가까운 메시지를 읽음\n\n## 다음 단계\n\n- `/kakao-up` - 이전 메시지로\n- `/kakao-refresh` - 가장 최신으로 리셋\n"},"lastSynced":"2026-03-08T02:03:44.724Z","agentAnalysis":{"suitability":{"en":"Perfect for Messaging Agents needing integrated KakaoTalk conversation retrieval.","zh":"非常适合需要集成KakaoTalk对话检索的消息代理。","ja":"KakaoTalk会話の取得を統合する必要があるメッセージエージェントに最適です。","ko":"카카오톡 대화 조회를 통합해야 하는 메시지 에이전트에 적합합니다.","es":"Perfecto para agentes de mensajería que necesitan recuperación de conversaciones de KakaoTalk integrada.","fr":"Parfait pour les agents de messagerie nécessitant une récupération de conversations KakaoTalk intégrée.","de":"Perfekt für Messaging-Agents, die eine integrierte KakaoTalk-Konversationsrückgewinnung benötigen.","pt":"Perfeito para Agentes de Mensagens que precisam de recuperação de conversas do KakaoTalk integrada.","ru":"Идеально подходит для Messaging Agents, которым необходима интегрированная функция извлечения разговоров KakaoTalk.","ar":"مثالي لعميل Messaging الذي يحتاج إلى استرجاع محادثات KakaoTalk المتكاملة."},"recommendation":{"en":"Empowers agents to fetch the latest KakaoTalk messages using Python, enabling seamless integration of recent conversations into applications via the kakao-cli.py script and supporting protocols like offset adjustments for message retrieval.","zh":"使代理能够使用Python获取最新的KakaoTalk消息，实现最近对话通过kakao-cli.py脚本和支持的协议（如偏移量调整）无缝集成到应用程序中。","ja":"エージェントがPythonを使用して最新のKakaoTalkメッセージを取得し、kakao-cli.pyスクリプトとサポートされるプロトコル（オフセット調整など）を介して最近の会話をアプリケーションにシームレスに統合できるようにします。","ko":"에이전트가 Python을 사용하여 최신 카카오톡 메시지를 가져올 수 있도록 하여 kakao-cli.py 스크립트와 지원되는 프로토콜(예: 오프셋 조정)을 통해 최근 대화를 애플리케이션에無縫로 통합할 수 있습니다.","es":"Habilita a los agentes a recuperar los mensajes de KakaoTalk más recientes utilizando Python, lo que permite una integración sin problemas de conversaciones recientes en aplicaciones a través del script kakao-cli.py y protocolos de apoyo como ajustes de desplazamiento para la recuperación de mensajes.","fr":"Permet aux agents de récupérer les messages KakaoTalk les plus récents à l''aide de Python, ce qui permet une intégration transparente de conversations récentes dans des applications via le script kakao-cli.py et des protocoles de support tels que les ajustements d''offset pour la récupération de messages.","de":"Ermächtigt Agenten, die neuesten KakaoTalk-Nachrichten mithilfe von Python abzurufen, wodurch eine nahtlose Integration von aktuellen Konversationen in Anwendungen über das Skript kakao-cli.py und unterstützende Protokolle wie Offset-Anpassungen für die Nachrichtenrückgewinnung ermöglicht wird.","pt":"Habilita os agentes a buscar as mensagens mais recentes do KakaoTalk usando Python, permitindo uma integração sem problemas das conversas recentes em aplicações via script kakao-cli.py e suportando protocolos como ajustes de offset para recuperação de mensagens.","ru":"Предоставляет агентам возможность извлекать последние сообщения KakaoTalk с помощью Python, что позволяет осуществлять бесперебойную интеграцию недавних разговоров в приложения через скрипт kakao-cli.py и поддерживает протоколы, такие как корректировка смещения для извлечения сообщений.","ar":"تمكن الوكلاء من استرجاع أحدث رسائل KakaoTalk باستخدام Python، وتمكين التكامل السلس لآخر المحادثات في التطبيقات عبر سكريبت kakao-cli.py ودعم البروتوكولات مثل تعديلات_OFFSET لاسترجاع الرسائل."},"useCases":{"en":["Retrieving recent KakaoTalk conversations for analysis","Integrating KakaoTalk messaging into custom applications","Automating KakaoTalk message updates with offset controls"],"zh":["检索最近的KakaoTalk对话以进行分析","将KakaoTalk消息集成到自定义应用程序","使用偏移量控制自动更新KakaoTalk消息"],"ja":["最近のKakaoTalk会話を分析するために取得","KakaoTalkメッセージをカスタムアプリケーションに統合","オフセット制御を使用してKakaoTalkメッセージを自動更新"],"ko":["최근 카카오톡 대화를 분석하기 위해 조회","카카오톡 메시지를 사용자 지정 애플리케이션에 통합","오프셋 제어를 사용하여 카카오톡 메시지를 자동으로 업데이트"],"es":["Recuperación de conversaciones de KakaoTalk recientes para análisis","Integración de mensajería de KakaoTalk en aplicaciones personalizadas","Automatización de actualizaciones de mensajes de KakaoTalk con controles de desplazamiento"],"fr":["Récupération de conversations KakaoTalk récentes pour analyse","Intégration de la messagerie KakaoTalk dans des applications personnalisées","Automatisation des mises à jour de messages KakaoTalk avec des contrôles d''offset"],"de":["Abruf von aktuellen KakaoTalk-Konversationen für die Analyse","Integration von KakaoTalk-Messaging in benutzerdefinierte Anwendungen","Automatisierung von KakaoTalk-Nachrichtenaktualisierungen mit Offset-Steuerungen"],"pt":["Recuperar conversas recentes do KakaoTalk para análise","Integrar mensagens do KakaoTalk em aplicações personalizadas","Automatizar atualizações de mensagens do KakaoTalk com controles de offset"],"ru":["Извлечение недавних разговоров KakaoTalk для анализа","Интеграция сообщений KakaoTalk в пользовательские приложения","Автоматизация обновлений сообщений KakaoTalk с управлением смещением"],"ar":["استرجاع محادثات KakaoTalk الأخيرة للتحليل","دمج رسائل KakaoTalk في التطبيقات المخصصة","تحديث رسائل KakaoTalk تلقائيًا مع التحكم في الإزاحة"]},"limitations":{"en":["Requires Python environment","KakaoTalk account and credentials needed","Offset limited to a minimum of 0 (most recent messages)"],"zh":["需要Python环境","需要KakaoTalk帐户和凭据","偏移量最小值为0（最_recent消息）"],"ja":["Python環境が必要","KakaoTalkアカウントと資格情報が必要","オフセットは最小0（最も新しいメッセージ）"],"ko":["Python 환경이 필요","카카오톡 계정 및 자격 증명이 필요","오프셋의 최소값은 0(최근 메시지)"],"es":["Requiere entorno de Python","Cuenta y credenciales de KakaoTalk necesarias","Offset limitado a un mínimo de 0 (mensajes más recientes)"],"fr":["Nécessite un environnement Python","Compte et informations d''identification KakaoTalk nécessaires","Offset limité à un minimum de 0 (messages les plus récents)"],"de":["Benötigt Python-Umgebung","KakaoTalk-Konto und Anmeldeinformationen erforderlich","Offset auf ein Minimum von 0 (aktuellste Nachrichten) beschränkt"],"pt":["Requer ambiente Python","Conta e credenciais do KakaoTalk necessárias","Offset limitado a um mínimo de 0 (mensagens mais recentes)"],"ru":["Требуется среда Python","Требуется аккаунт и учетные данные KakaoTalk","Ограничение смещения минимально 0 (самые недавние сообщения)"],"ar":["يتطلب بيئة Python","مطلوب حساب وبيانات اعتماد KakaoTalk","الحد الأدنى للمسافة البعدية هو 0 (الأحدث رسائل)"]},"version":4},"contentHash":"67db497cb993367091acf522e206cb4a30d50378dccbad13c72a3df3e87dc918","qualityScore":30}');
