INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stpcoder/kakao-terminal/kakao-down', 'kakao-down', 'stpcoder', 'kakao-terminal', 'community', 'kakao-down stpcoder kakao-terminal community The kakao-down skill retrieves the latest KakaoTalk messages, allowing developers to access recent conversations. It benefits developers who need to integrate KakaoTalk messaging into their applications. Kakao-Down AI工具允许开发者使用Python CLI命令查看最新的KakaoTalk消息 Kakao-Down AIエージェントは、Python CLIコマンドを使用して最新のKakaoTalkメッセージを閲覧することができます 카카오톡 최신 메시지 보기 kakao-down은 Python CLI 명령어를 통해 최신의 카카오톡 메시지를 볼 수 있는 기술입니다 kakao-down es una herramienta que permite ver los mensajes más recientes de KakaoTalk mediante Python y CLI kakao-down est un outil qui permet d''afficher les messages les plus récents de KakaoTalk à l''aide de Python et de CLI kakao-down ist ein Tool, das die Anzeige der neuesten KakaoTalk-Nachrichten mithilfe von Python und CLI ermöglicht O kakao-down é uma ferramenta que permite visualizar as mensagens mais recentes do KakaoTalk com facilidade, utilizando o CLI do Python. ИИ Агент kakao-down - это инструмент, который позволяет просматривать последние сообщения в KakaoTalk, используя Python CLI. kakao-down هو أداة تمكنك من عرض الرسائل الحديثة في KakaoTalk بسهولة، باستخدام واجهة سطر الأوامر Python. how to use kakao-down kakao-down setup guide kakao-down alternative kakao-down vs other messaging tools kakao-down install latest KakaoTalk message retrieval KakaoTalk messaging integration command-line messaging tools Kakao-Down AI工具 Python CLI命令 KakaoTalk最新消息 AI工具设置 Kakao-Down设置指南 Python开发 CLI命令 Executes the `kakao_cli.py down` command to retrieve latest messages Supports offset parameters, e.g., `/kakao-down 20`, to fetch a specified number of messages Automatically decreases offset on each call to retrieve newer messages Resets to the latest messages with the `/kakao-refresh` command Navigates to previous messages with the `/kakao-up` command kakao-down is a command-line tool that fetches the latest KakaoTalk messages, using the `/kakao-down` command with optional offset parameters.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('z3z1ma/vibe-pipe/loom-workspace', 'community', 'z3z1ma', 'vibe-pipe', 'z3z1ma/vibe-pipe', 'loom-workspace', 0, 0, 30, '2026-03-08T01:57:15.350Z', '2026-03-08T02:03:46.961Z', '559b475f8a9bb98c8b4ae3a9530ad6609289250a78e681c77652aceedeffb09f', '{"id":"z3z1ma/vibe-pipe/loom-workspace","name":"loom-workspace","description":{"en":"loom-workspace is a tool for managing a horde of favorite TUIs, enabling developers to efficiently manage worktrees and branches. It benefits developers working with multiple terminal interfaces.","zh":"Loom Workspace 是一个用于管理 TUI 工具的测试平台，提供 worktree 基础功能和分支命名推荐","ja":"Loom Workspace は TUI ツールを管理するためのテストベッドであり、worktree 基礎機能とブランチ命名の推奨を提供します","ko":"Loom Workspace는 TUI 툴을 관리하기 위한 테스트베드이며 worktree 기본 기능과 브랜치 이름 지정 권장 사항을 제공합니다","es":"loom-workspace es una herramienta para gestionar múltiples interfaces de usuario en línea de comandos. Ofrece funcionalidades como la creación y administración de worktrees y la gestión de ramas","fr":"loom-workspace est un outil pour gérer plusieurs interfaces utilisateur en ligne de commande. Il propose des fonctionnalités telles que la création et l''administration de worktrees et la gestion de branches","de":"loom-workspace ist ein Tool zur Verwaltung mehrerer Kommandozeilen-Tools. Es bietet Funktionen wie die Erstellung und Verwaltung von Worktrees und die Verwaltung von Branches","pt":"O Loom Workspace é uma ferramenta para gerenciar múltiplas interfaces de usuário de texto. Aprenda a configurá-lo","ru":"Loom Workspace - это инструмент для управления множеством текстовых интерфейсов пользователя. Узнайте, как его настроить","ar":"مساحة عمل Loom هي أداة لادارة واجهات المستخدم النصية المتعددة. تعرف على كيفية ضبطها"},"seo":{"title":{"en":"loom-workspace: Worktree Management Setup Guide | AI Agen...","zh":"Loom Workspace 集成指南：TUI 工具管理最佳实践","ja":"Loom Workspace セットアップガイド：TUI ツール管理のベストプラクティス","ko":"Loom Workspace 설정 가이드: TUI 툴 관리 모범 사례","es":"Guía de Configuración de loom-workspace para Desarrolladores","fr":"Guide de Mise en Place de loom-workspace pour les Dévelop...","de":"Einrichtungsleitfaden für loom-workspace-Entwickler","pt":"Loom Workspace: Guia de Configuração para Gerenciamento d...","ru":"Loom Workspace: Настройка и управление инструментами TUI","ar":"loom workspace: دليل الإعداد لادارة واجهات المستخدم النصية"},"description":{"en":"Discover how to manage multiple TUIs with loom-workspace. Learn to add, list, and remove worktrees with ease. Get started now!","zh":"了解 Loom Workspace 的功能和技术细节，掌握 TUI 工具管理的最佳实践","ja":"Loom Workspace の機能と技術的な詳細を学び、TUI ツール管理のベストプラクティスをマスターする","ko":"Loom Workspace의 기능과 기술적 세부 정보를 알아보고 TUI 툴 관리의 모범 사례를 익히십시오","es":"Aprende a configurar y utilizar loom-workspace para gestionar tus herramientas de interfaz de usuario en línea de comandos favoritas","fr":"Découvrez comment configurer et utiliser loom-workspace pour gérer vos outils d''interface utilisateur en ligne de commande préférés","de":"Erfahren Sie, wie Sie loom-workspace konfigurieren und verwenden, um Ihre bevorzugten Kommandozeilen-Tools zu verwalten","pt":"Aprenda a configurar o Loom Workspace para gerenciar suas ferramentas TUI favoritas de forma eficiente","ru":"Узнайте, как настроить Loom Workspace для эффективного управления вашими любимыми инструментами TUI","ar":"تعرف على كيفية ضبط مساحة عمل Loom لادارة أدوات واجهة المستخدم النصية المفضلة لديك بفعالية"},"definition":{"en":"loom-workspace is a management tool for terminal interfaces, providing worktree basics and branch naming recommendations for efficient development workflows.","zh":"Loom Workspace 是一个用于管理 TUI 工具的测试平台","ja":"Loom Workspace は TUI ツールを管理するためのテストベッドです","ko":"Loom Workspace는 TUI 툴을 관리하기 위한 테스트베드입니다","es":"loom-workspace es un agente de AI que gestiona herramientas de interfaz de usuario en línea de comandos","fr":"loom-workspace est un agent IA qui gère des outils d''interface utilisateur en ligne de commande","de":"loom-workspace ist ein KI-Agent, der Kommandozeilen-Tools verwaltet","pt":"O Loom Workspace é uma ferramenta de gerenciamento de interfaces de usuário de texto","ru":"Loom Workspace - это инструмент управления текстовыми интерфейсами пользователя","ar":"مساحة عمل Loom هي أداة لادارة واجهات المستخدم النصية"},"features":{"en":["Manages worktrees using `compound_workspace` commands","Adds worktrees with `compound_workspace(argv=[\"repo\", \"worktree\", \"add\", \"<branch>\"])`","Lists worktrees with `compound_workspace(argv=[\"repo\", \"worktree\", \"ls\"])`","Removes worktrees with `compound_workspace(argv=[\"repo\", \"worktree\", \"rm\", \"<branch>\"])`","Provides repo status with `compound_workspace(argv=[\"repo\", \"status\"])`"],"zh":["worktree 基础功能","分支命名推荐","CLI 命令支持","工作树添加和删除","仓库状态查询"],"ja":["worktree 基礎機能","ブランチ命名の推奨","CLI コマンド対応","ワークツリーの追加と削除","リポジトリ状態の照会"],"ko":["worktree 기본 기능","브랜치 이름 지정 권장 사항","CLI 명령어 지원","작업 트리 추가 및 제거","리포지토리 상태 조회"],"es":["Creación y administración de worktrees","Gestión de ramas con nombres personalizados","Ejecución de comandos de repositorio como ''status'' y ''ls''","Eliminación de worktrees","Compatibilidad con la línea de comandos para una integración fluida"],"fr":["Création et administration de worktrees","Gestion de branches avec des noms personnalisés","Exécution de commandes de référentiel comme ''status'' et ''ls''","Suppression de worktrees","Compatibilité avec la ligne de commande pour une intégration fluide"],"de":["Erstellung und Verwaltung von Worktrees","Verwaltung von Branches mit benutzerdefinierten Namen","Ausführung von Repository-Befehlen wie ''status'' und ''ls''","Entfernen von Worktrees","Kompatibilität mit der Kommandozeile für eine nahtlose Integration"],"pt":["Gerenciamento de worktrees para branches","Listagem de worktrees","Remoção de worktrees","Verificação de status do repositório","Suporte a naming de branches personalizadas"],"ru":["Управление worktrees для веток","Список worktrees","Удаление worktrees","Проверка статуса репозитория","Поддержка настраиваемого именования веток"],"ar":["ادارة worktrees لفرع","قائمة worktrees","حذف worktrees","تحقق من حالة المستودع","دعم تسمية فرع مخصص"]},"keywords":{"en":["how to use loom-workspace","loom-workspace alternative","loom-workspace setup guide","what is loom-workspace","loom-workspace vs git","loom-workspace install","loom-workspace worktree management","terminal interface management","TUI management tool"],"zh":["Loom Workspace","TUI 工具管理","worktree","CLI 命令","仓库状态","AI エージェント","TUI 工具集成"],"ja":["Loom Workspace","TUI ツール管理","worktree","CLI コマンド","リポジトリ状態","AIエージェント","TUI ツール統合"],"ko":["Loom Workspace","TUI 툴 관리","worktree","CLI 명령어","리포지토리 상태","AI 에이전트","TUI 툴 통합"],"es":["loom-workspace","herramientas de interfaz de usuario en línea de comandos","gestión de worktrees","gestión de ramas","agente de AI para desarrolladores","integración con la línea de comandos","desarrollo de software","herramientas de desarrollo"],"fr":["loom-workspace","outils d''interface utilisateur en ligne de commande","gestion de worktrees","gestion de branches","agent IA pour les développeurs","intégration avec la ligne de commande","développement de logiciels","outils de développement"],"de":["loom-workspace","Kommandozeilen-Tools","Verwaltung von Worktrees","Verwaltung von Branches","KI-Agent für Entwickler","Integration mit der Kommandozeile","Software-Entwicklung","Entwicklungstools"],"pt":["Loom Workspace","gerenciamento de TUIs","ferramentas de linha de comando","worktrees","branches","repositório","CLI","ferramentas de desenvolvimento"],"ru":["Loom Workspace","управление TUI","инструменты командной строки","worktrees","ветки","репозиторий","CLI","инструменты разработки","ИИ Агенты"],"ar":["مساحة عمل Loom","ادارة واجهات المستخدم النصية","أدوات سطر الأوامر","worktrees","فرع","مستودع","CLI","أدوات التطوير","الوكلاء الذكية"]}},"owner":"z3z1ma","repo":"vibe-pipe","repoPath":"z3z1ma/vibe-pipe","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.350Z","topics":[],"category":"community","skillMd":{"name":"loom-workspace","description":"Use loom workspace to create/manage worktrees for isolated execution of tickets.","version":"1","tags":"git,workflow","bodyPreview":"<!-- BEGIN:compound:skill-managed -->\n## Worktree basics (repo model)\n\nEnsure a worktree exists for a branch:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"add\", \"<branch>\"])`\n\nList worktrees:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"ls\"])`\n\nRemove a worktree:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"rm\", \"<branch>\"])`\n\nRepo status:\n\n- `compound_workspace(argv=[\"repo\", \"status\"])`\n\n## Branch naming\n\nRecommended:\n\n- `ticket-<ticket-id>-<short-slug>`\n\nExample:\n\n- `ticket-42-s","body":"<!-- BEGIN:compound:skill-managed -->\n## Worktree basics (repo model)\n\nEnsure a worktree exists for a branch:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"add\", \"<branch>\"])`\n\nList worktrees:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"ls\"])`\n\nRemove a worktree:\n\n- `compound_workspace(argv=[\"repo\", \"worktree\", \"rm\", \"<branch>\"])`\n\nRepo status:\n\n- `compound_workspace(argv=[\"repo\", \"status\"])`\n\n## Branch naming\n\nRecommended:\n\n- `ticket-<ticket-id>-<short-slug>`\n\nExample:\n\n- `ticket-42-streaming-chunking`\n\n## Practical note\n\nOpenCode runs inside *one* working directory. Typically, this is the main branch worktree.\n`loom workspace` creates the worktree path (usually under `.loom-repo/worktrees/<branch>`).\nDo the code changes in that worktree.\n<!-- END:compound:skill-managed -->\n\n## Manual notes\n\n_This section is preserved when the skill is updated. Put human notes, caveats, and exceptions here._\n"},"lastSynced":"2026-03-08T02:03:46.961Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing efficient worktree and branch management in TUI environments.","zh":"非常适合需要在 TUI 环境中高效管理工作树和分支的开发者代理。","ja":"TUI 環境で効率的なワークツリーとブランチの管理が必要なデベロッパーエージェントに最適です。","ko":"TUI 환경에서 효율적인 작업 트리 및 분기 관리가 필요한 개발자 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan una gestión eficiente de worktree y ramas en entornos TUI.","fr":"Parfait pour les Agents de Développeur ayant besoin d''une gestion efficace de worktree et de branches dans les environnements TUI.","de":"Perfekt für Entwickleragenten, die eine effiziente Verwaltung von Worktrees und Branches in TUI-Umgebungen benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de gerenciamento eficiente de worktree e branch em ambientes TUI.","ru":"Идеально подходит для агентов-разработчиков, которым необходим эффективный менеджмент worktree и branch в средах TUI.","ar":"مثالي لعميل المطور الذي يحتاج إلى إدارة شجرة العمل وفروعها بكفاءة في بيئات واجهة المستخدم النصية."},"recommendation":{"en":"Empowers agents to manage multiple terminal interfaces, worktrees, and branches using commands like ''worktree add'' and ''worktree ls'', streamlining development workflows with repo status checks and custom branch naming conventions like ''ticket-<ticket-id>-<short-slug>''.","zh":"使代理能够使用诸如 ''worktree add'' 和 ''worktree ls'' 之类的命令管理多个终端接口、工作树和分支，通过仓库状态检查和自定义分支命名约定（如 ''ticket-<ticket-id>-<short-slug>''）来简化开发工作流程。","ja":"エージェントが ''worktree add'' や ''worktree ls'' などのコマンドを使用して複数のターミナルインターフェイス、ワークツリー、ブランチを管理し、リポジトリのステータスを確認し、カスタムブランチ命名規則（例： ''ticket-<ticket-id>-<short-slug>''）で開発ワークフローを合理化することを可能にします。","ko":"에이전트가 ''worktree add'' 및 ''worktree ls''와 같은 명령을 사용하여 여러 터미널 인터페이스, 작업 트리 및 분기를 관리하고, 저장소 상태를 확인하고, 사용자 정의 분기 이름 규칙(예: ''ticket-<ticket-id>-<short-slug>'')을 통해 개발 워크플ロー를 최적화합니다.","es":"Habilita a los agentes a gestionar múltiples interfaces de terminal, worktrees y ramas utilizando comandos como ''worktree add'' y ''worktree ls'', optimizando los flujos de trabajo de desarrollo con comprobaciones de estado de repositorio y convenciones de nomenclatura de ramas personalizadas como ''ticket-<ticket-id>-<short-slug>''.","fr":"Permet aux agents de gérer plusieurs interfaces de terminal, worktrees et branches en utilisant des commandes comme ''worktree add'' et ''worktree ls'', rationalisant les flux de travail de développement avec des vérifications de statut de référentiel et des conventions de dénomination de branche personnalisées comme ''ticket-<ticket-id>-<short-slug>''.","de":"Ermöglicht es Agenten, mehrere Terminal-Oberflächen, Worktrees und Branches mit Befehlen wie ''worktree add'' und ''worktree ls'' zu verwalten, wodurch Entwicklungsworkflows mit Repository-Statusprüfungen und benutzerdefinierten Branch-Namenskonventionen wie ''ticket-<ticket-id>-<short-slug>'' optimiert werden.","pt":"Habilita os agentes a gerenciar várias interfaces de terminal, worktrees e branches usando comandos como ''worktree add'' e ''worktree ls'', racionalizando fluxos de trabalho de desenvolvimento com verificação de status do repositório e convenções de nomenclatura de branch personalizadas como ''ticket-<ticket-id>-<short-slug>''.","ru":"Наделяет агентов возможностью управлять несколькими терминальными интерфейсами, worktree и ветками с помощью команд типа ''worktree add'' и ''worktree ls'', оптимизируя рабочие процессы разработки с помощью проверки статуса репозитория и настраиваемых соглашений об именовании веток, таких как ''ticket-<ticket-id>-<short-slug>''.","ar":"تمكّن الوكيل من إدارة واجهات الطرفية المتعددة وشجرة العمل وفروعها باستخدام أوامر مثل ''worktree add'' و ''worktree ls''، وترشيد تدفقات العمل التطويرية مع فحص حالة المستودع والاتفاقيات المخصصة لتسمية الفروع مثل ''ticket-<ticket-id>-<short-slug>''."},"useCases":{"en":["Automating worktree creation for new branches","Listing and managing existing worktrees","Removing unused worktrees to maintain a clean repository"],"zh":["为新分支自动创建工作树","列出和管理现有的工作树","删除未使用的工作树以保持干净的仓库"],"ja":["新しいブランチのためのワークツリーの自動作成","既存のワークツリーのリストと管理","未使用のワークツリーの削除によるクリーンなリポジトリの維持"],"ko":["新的 브랜치에 대한 작업 트리 자동 생성","기존 작업 트리 목록 및 관리","클린 저장소를 유지하기 위한 사용되지 않은 작업 트리 제거"],"es":["Automatización de la creación de worktree para nuevas ramas","Listado y gestión de worktrees existentes","Eliminación de worktrees no utilizados para mantener un repositorio limpio"],"fr":["Automatisation de la création de worktree pour de nouvelles branches","Liste et gestion des worktrees existants","Suppression des worktrees inutilisés pour maintenir un référentiel propre"],"de":["Automatisierung der Erstellung von Worktrees für neue Branches","Auflistung und Verwaltung von vorhandenen Worktrees","Entfernen nicht verwendeter Worktrees, um ein sauberes Repository zu erhalten"],"pt":["Automatizar a criação de worktree para novas branches","Listar e gerenciar worktrees existentes","Remover worktrees não utilizados para manter um repositório limpo"],"ru":["Автоматизировать создание worktree для новых веток","Перечислять и управлять существующими worktree","Удалять неиспользуемые worktree для поддержания чистого репозитория"],"ar":["توفير автоматизации لإنشاء شجرة العمل للفروع الجديدة","إدراج وإدارة شجرات العمل الحالية","إزالة شجرات العمل غير المستخدمة للحفاظ على مستودع نظيف"]},"limitations":{"en":["Requires command-line interface access","Limited to Git repository management"],"zh":["需要命令行接口访问","仅限 Git 仓库管理"],"ja":["コマンドラインインターフェイスへのアクセスが必要","Git リポジトリの管理のみ"],"ko":["명령줄 인터페이스 액세스가 필요","Git 저장소 관리만"],"es":["Requiere acceso a la interfaz de línea de comandos","Limitado a la gestión de repositorios Git"],"fr":["Nécessite un accès à l''interface de ligne de commande","Limité à la gestion de référentiels Git"],"de":["Benötigt Zugriff auf die Kommandozeilenoberfläche","Befehlt sich auf die Verwaltung von Git-Repositorys"],"pt":["Requer acesso à interface de linha de comando","Limitado ao gerenciamento de repositório Git"],"ru":["Требует доступа к командной строке","Ограничен менеджментом репозитория Git"],"ar":["يتطلب وصولاً إلى واجهة سطر الأوامر","محدود بإدارة مستودع جيت"]},"version":4},"contentHash":"559b475f8a9bb98c8b4ae3a9530ad6609289250a78e681c77652aceedeffb09f","qualityScore":30}');
