INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('z3z1ma/vibe-pipe/loom-workspace', 'loom-workspace', 'z3z1ma', 'vibe-pipe', 'community', 'loom-workspace z3z1ma vibe-pipe community loom-workspace is a tool for managing a horde of favorite TUIs, enabling developers to efficiently manage worktrees and branches. It benefits developers working with multiple terminal interfaces. Loom Workspace 是一个用于管理 TUI 工具的测试平台，提供 worktree 基础功能和分支命名推荐 Loom Workspace は TUI ツールを管理するためのテストベッドであり、worktree 基礎機能とブランチ命名の推奨を提供します Loom Workspace는 TUI 툴을 관리하기 위한 테스트베드이며 worktree 기본 기능과 브랜치 이름 지정 권장 사항을 제공합니다 loom-workspace es una herramienta para gestionar múltiples interfaces de usuario en línea de comandos. Ofrece funcionalidades como la creación y administración de worktrees y la gestión de ramas loom-workspace est un outil pour gérer plusieurs interfaces utilisateur en ligne de commande. Il propose des fonctionnalités telles que la création et l''administration de worktrees et la gestion de branches loom-workspace ist ein Tool zur Verwaltung mehrerer Kommandozeilen-Tools. Es bietet Funktionen wie die Erstellung und Verwaltung von Worktrees und die Verwaltung von Branches O Loom Workspace é uma ferramenta para gerenciar múltiplas interfaces de usuário de texto. Aprenda a configurá-lo Loom Workspace - это инструмент для управления множеством текстовых интерфейсов пользователя. Узнайте, как его настроить مساحة عمل Loom هي أداة لادارة واجهات المستخدم النصية المتعددة. تعرف على كيفية ضبطها how to use loom-workspace loom-workspace alternative loom-workspace setup guide what is loom-workspace loom-workspace vs git loom-workspace install loom-workspace worktree management terminal interface management TUI management tool Loom Workspace TUI 工具管理 worktree CLI 命令 仓库状态 AI エージェント TUI 工具集成 Manages worktrees using `compound_workspace` commands Adds worktrees with `compound_workspace(argv=["repo", "worktree", "add", "<branch>"])` Lists worktrees with `compound_workspace(argv=["repo", "worktree", "ls"])` Removes worktrees with `compound_workspace(argv=["repo", "worktree", "rm", "<branch>"])` Provides repo status with `compound_workspace(argv=["repo", "status"])` loom-workspace is a management tool for terminal interfaces, providing worktree basics and branch naming recommendations for efficient development workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bearcove/pikru/idiomatic-rust', 'community', 'bearcove', 'pikru', 'bearcove/pikru', 'idiomatic-rust', 0, 0, 30, '2026-03-08T01:57:15.351Z', '2026-03-08T02:03:49.863Z', '82a5bef99f6d72bd4d25232d5229d2f255c4de15bd4ab70c96282c51aa659d29', '{"id":"bearcove/pikru/idiomatic-rust","name":"idiomatic-rust","description":{"en":"Idiomatic-rust is a Rust port of C code that prioritizes correct behavior over line-by-line translation. It benefits developers who want to write idiomatic Rust code.","zh":"idiomatic-rust 是 Rust 的一种编程风格，强调正确的行为而非简单的代码转换","ja":"idiomatic-rust は、Rust のコーディングスタイルで、正しい動作を重視します","ko":"idiomatic-rust는 Rust의 코딩 스타일로, 올바른 동작을 강조합니다","es":"Idiomatic Rust es una implementación de pikchr en Rust, que promueve el uso de patrones y prácticas idiomáticas de Rust","fr":"Idiomatic Rust est une implémentation de pikchr en Rust, qui encourage l''utilisation de modèles et de pratiques idiomatiques de Rust","de":"Idiomatic Rust ist eine Implementierung von pikchr in Rust, die die Verwendung von Mustern und idiomatischen Praktiken von Rust fördert","pt":"O idiomatic-rust é uma porta do pikchr para Rust, focada em comportamento correto, não tradução linha-a-linha. Aprenda a escrever código Rust idiomático","ru":"Идиоматический Rust - это порт pikchr для Rust, ориентированный на правильное поведение, а не на перевод строка за строкой. Узнайте, как писать идиоматический код на Rust","ar":"إيدوماتيك رست هو منفذ لبيكشر على رست، يركز على السلوك الصحيح، وليس على الترجمة سطر بسطر. تعلم كيفية كتابة код رست إيدوماتيكي"},"seo":{"title":{"en":"Idiomatic-Rust: Rust Port Best Practices | AI Agent Skill","zh":"Rust 编程最佳实践：idiomatic-rust Setup Guide","ja":"Rust をマスターする：idiomatic-rust ベストプラクティス","ko":"Rust 개발 가이드：idiomatic-rust_AI 에이전트","es":"Guía de configuración de Idiomatic Rust: Mejores práctica...","fr":"Guide de mise en place d''Idiomatic Rust: Bonnes pratiques...","de":"Einrichtungsleitfaden für Idiomatic Rust: Best Practices ...","pt":"Guia de Configuração do Idiomatic Rust: Melhores Práticas...","ru":"ИИ Агенты: Руководство по Настройке Idiomatic Rust для Ра...","ar":"دليل إعداد إيدوماتيك رست:أفضل الممارسات لمنصة الفير"},"description":{"en":"Discover how to port C code to Rust effectively with idiomatic-rust. Learn to avoid C patterns and implement correct behavior with this expert guide.","zh":"了解 idiomatic-rust 的技术细节，掌握 Rust 编程最佳实践，提高代码质量","ja":"Rust のベストプラクティスを学び、AI エージェントと一緒に開発効率を向上させる","ko":"Rust 개발을 위한 idiomatic-rust_AI 에이전트를 사용하여 코드의 품질과 효율성을 높이세요","es":"Aprende a utilizar Idiomatic Rust de manera efectiva, evitando patrones de C y aprovechando al máximo las características de Rust","fr":"Découvrez comment utiliser Idiomatic Rust de manière efficace, en évitant les modèles C et en exploitant pleinement les fonctionnalités de Rust","de":"Erfahren Sie, wie Sie Idiomatic Rust effektiv nutzen können, indem Sie C-Muster vermeiden und die Funktionen von Rust voll ausschöpfen","pt":"Aprenda a utilizar o idiomatic-rust de forma eficaz, com dicas e truques para melhorar seu código Rust","ru":"Узнайте, как эффективно использовать idiomatic-rust, с советами и хитростями для улучшения вашего кода на Rust","ar":"تعلم كيفية استخدام إيدوماتيك رست بطريقة فعالة، مع نصائح وأفكار لتحسين кодك على رست"},"definition":{"en":"Idiomatic-rust is a Rust port that emphasizes writing Rust code, not C code in Rust, to achieve correct behavior.","zh":"idiomatic-rust 是一种 Rust 编程风格，注重正确行为和代码的 idiomatic 表达","ja":"idiomatic-rust は、Rust のコーディングスタイルで、正しい動作とアイディオマティックなコードを重視します","ko":"idiomatic-rust는 Rust의 코딩 스타일로, 올바른 동작과 아이디오매틱한 코드를 강조합니다","es":"Idiomatic Rust es un enfoque de programación que se centra en escribir código Rust de manera natural y efectiva","fr":"Idiomatic Rust est une approche de programmation qui se concentre sur l''écriture de code Rust de manière naturelle et efficace","de":"Idiomatic Rust ist ein Programmieransatz, der sich auf die natürliche und effektive Implementierung von Rust-Code konzentriert","pt":"Idiomatic-rust é uma técnica de programação que visa escrever código Rust de forma natural e eficaz","ru":"Идиоматический Rust - это техника программирования, направленная на написание кода на Rust в естественной и эффективной форме","ar":"إيدوماتيك رست هي تقنية برمجة تهدف إلى كتابة код رست بطريقة طبيعية وفعالة"},"features":{"en":["Implements methods on structs to compute values where data lives","Avoids C-style functions with boolean flag parameters","Prioritizes correct behavior over line-by-line translation from C","Supports Rust-specific programming patterns and best practices","Provides a pikchr port to Rust for improved functionality"],"zh":["实现结构体方法封装","避免 C 风格的函数调用","使用 Rust 的类型系统","优化代码的可读性和可维护性","支持 pikchr 图形库"],"ja":["構造体メソッドのエンカプスュレーション","C スタイルの関数呼び出しの回避","Rust の型システムの使用","コードの可読性と保守性の最適化","pikchr グラフィックライブラリのサポート"],"ko":["구조체 메서드封装","C 스타일의 함수 호출 회피","Rust의 타입 시스템 사용","코드의 가독성과 유지보수성 최적화","pikchr 그래픽 라이브러리 지원"],"es":["Implementación de pikchr en Rust","Uso de patrones y prácticas idiomáticas de Rust","Evitación de patrones de C en el código Rust","Uso de métodos en structs para encapsular lógica","Aplicación de la filosofía de ''poner la lógica donde vive los datos''"],"fr":["Implémentation de pikchr en Rust","Utilisation de modèles et de pratiques idiomatiques de Rust","Évitement de modèles C dans le code Rust","Utilisation de méthodes dans les structs pour encapsuler la logique","Application de la philosophie de ''mettre la logique où vivent les données''"],"de":["Implementierung von pikchr in Rust","Verwendung von Mustern und idiomatischen Praktiken von Rust","Vermeidung von C-Mustern im Rust-Code","Verwendung von Methoden in Structs zur Kapselung von Logik","Anwendung der Philosophie von ''die Logik dort zu platzieren, wo die Daten leben''"],"pt":["Porta do pikchr para Rust","Foco em comportamento correto, não tradução linha-a-linha","Escreva código Rust idiomático com métodos e structs","Separe a lógica onde os dados vivem","Melhore a legibilidade e manutenção do código"],"ru":["Порт pikchr для Rust","Фокус на правильном поведении, а не на переводе строка за строкой","Пишите идиоматический код на Rust с методами и структурами","Разделите логику там, где живут данные","Улучшите читаемость и поддержку кода"],"ar":["منفذ لبيكشر على رست","التركيز على السلوك الصحيح، وليس على الترجمة سطر بسطر","اكتب код رست إيدوماتيكي مع طرق و structs","افصل المنطق حيث تعيش البيانات","تحسين قراءة و صيانة الكود"]},"keywords":{"en":["how to use idiomatic-rust","idiomatic-rust vs rust-c","idiomatic-rust setup guide","what is idiomatic-rust","idiomatic-rust alternative to c","idiomatic-rust install rust","rust port best practices","avoiding c patterns in rust","idiomatic-rust documentation"],"zh":["Rust 编程","idiomatic-rust","Rust 最佳实践","代码优化","结构体方法","pikchr 图形库"],"ja":["Rust プログラミング","idiomatic-rust","Rust ベストプラクティス","コード最適化","構造体メソッド","pikchr グラフィックライブラリ"],"ko":["Rust 프로그래밍","idiomatic-rust","Rust 개발 가이드","코드 최적화","구조체 메서드","pikchr 그래픽 라이브러리"],"es":["Idiomatic Rust","pikchr en Rust","patrones de Rust","prácticas idiomáticas de Rust","evitar patrones de C en Rust","desarrollo de software en Rust","programación en Rust","Herramientas de AI para desarrolladores","Agentes de IA para programación"],"fr":["Idiomatic Rust","pikchr en Rust","modèles de Rust","pratiques idiomatiques de Rust","éviter les modèles C dans Rust","développement de logiciels en Rust","programmation en Rust","Outils d''IA pour les développeurs","Agents d''IA pour la programmation"],"de":["Idiomatic Rust","pikchr in Rust","Muster von Rust","idiomatische Praktiken von Rust","Vermeidung von C-Mustern in Rust","Softwareentwicklung in Rust","Programmierung in Rust","KI-Tools für Entwickler","KI-Agents für die Programmierung"],"pt":["idiomatic-rust","pikchr","Rust","programação funcional","desenvolvimento de software","melhores práticas","código eficaz","legibilidade de código"],"ru":["ИИ Агенты","Идиоматический Rust","pikchr","Rust","функциональное программирование","разработка программного обеспечения","лучшие практики","эффективный код","читаемость кода"],"ar":["إيدوماتيك رست","منصة الفير","بيكشر","رست","برمجة وظيفية","تطوير البرمجيات","أفضل الممارسات","كود فعال","قراءة الكود"]}},"owner":"bearcove","repo":"pikru","repoPath":"bearcove/pikru","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.351Z","topics":[],"category":"community","skillMd":{"name":"idiomatic-rust","description":"Idiomatic Rust patterns for pikru C port. Use when writing or reviewing Rust code ported from C. Dont write C in Rust - the goal is correct behavior, not line-by-line translation.","bodyPreview":"# Idiomatic Rust: Don''t port C patterns\n\nThis is a Rust port of C code, but **do not write C in Rust**. The goal is correct behavior, not line-by-line translation.\n\n## Put logic where the data lives\n\nIf a struct has all the information needed to compute something, make it a method:\n\n```rust\n// BAD: C-style function with boolean flag soup\nfn text_width(text: &str, charwid: f64, is_mono: bool, font_scale: f64, is_bold: bool) -> f64\n\n// GOOD: The type already knows its properties\nimpl PositionedTex","body":"# Idiomatic Rust: Don''t port C patterns\n\nThis is a Rust port of C code, but **do not write C in Rust**. The goal is correct behavior, not line-by-line translation.\n\n## Put logic where the data lives\n\nIf a struct has all the information needed to compute something, make it a method:\n\n```rust\n// BAD: C-style function with boolean flag soup\nfn text_width(text: &str, charwid: f64, is_mono: bool, font_scale: f64, is_bold: bool) -> f64\n\n// GOOD: The type already knows its properties\nimpl PositionedText {\n    fn width_inches(&self, charwid: f64) -> f64 {\n        // self.mono, self.bold, self.big are all right here\n    }\n}\n```\n\n**Rationale:** Boolean flags are:\n- Easy to pass in wrong order (`width(s, w, true, 1.0, false)` - which bool is which?)\n- Require the caller to extract properties just to pass them back in\n- Duplicate knowledge that the type already has\n\n## Use newtypes for domain concepts\n\n```rust\n// BAD: Bare f64 everywhere, easy to mix up inches and pixels\nfn convert(value: f64, scale: f64) -> f64\n\n// GOOD: The type system catches mistakes\nstruct Inches(f64);\nstruct Pixels(f64);\nfn convert(value: Inches, scale: &Scaler) -> Pixels\n```\n\n## Prefer methods over standalone functions\n\nWhen you find yourself writing `foo_bar(bar, ...)`, consider `bar.foo(...)` instead. This:\n- Groups related functionality\n- Enables IDE autocomplete on the type\n- Makes the relationship between data and operations explicit\n\n## Enums over boolean flags\n\n```rust\n// BAD: What does `true` mean here?\nrender_text(text, true, false)\n\n// GOOD: Self-documenting\nenum TextAnchor { Start, Middle, End }\nrender_text(text, TextAnchor::Start)\n```\n\n## The C code is a spec, not a template\n\nWhen porting C:\n1. Understand what the C code **does** (behavior)\n2. Understand **why** it does it (intent)\n3. Implement that behavior idiomatically in Rust\n\nThe `// cref:` comments link to C for reference, but the Rust should stand on its own.\n"},"lastSynced":"2026-03-08T02:03:49.863Z","agentAnalysis":{"suitability":{"en":"Perfect for Rust-based AI Agents needing to write idiomatic and efficient Rust code.","zh":"非常适合需要编写惯用且高效Rust代码的Rust-based AI Agents。","ja":"RustベースのAIエージェントがイディオマティックで効率的なRustコードを書く必要がある場合に最適です。","ko":"惯用적이고 효율적인 Rust 코드를 작성해야 하는 Rust 기반 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de Inteligencia Artificial basados en Rust que necesitan escribir código Rust idiomático y eficiente.","fr":"Parfait pour les Agents d''Intelligence Artificielle basés sur Rust nécessitant d''écrire du code Rust idiomatique et efficace.","de":"Perfekt für auf Rust basierende KI-Agents, die idiatischen und effizienten Rust-Code schreiben müssen.","pt":"Perfeito para Agentes de IA baseados em Rust que precisam escrever código Rust idiomático e eficiente.","ru":"Идеально подходит для агентов ИИ на основе Rust, которым необходимо писать идиоматический и эффективный код на Rust.","ar":"مثالي لعميل الذكاء الاصطناعي المستند إلى روست الذي يحتاج إلى كتابة رمز روست اصطلاحي وفعال."},"recommendation":{"en":"Empowers agents to prioritize correct behavior over line-by-line translation, utilizing Rust''s native features and best practices, such as implementing logic as methods on structs and avoiding C-style function patterns with boolean flags.","zh":"赋予代理人将正确的行为置于逐行翻译之上，利用Rust的原生功能和最佳实践，例如将逻辑作为结构体的方法实现，并避免使用带有布尔标志的C风格函数模式。","ja":"エージェントに、逐行翻訳よりも正しい動作を優先する権限を与え、Rustのネイティブ機能やベストプラクティスを利用できるようにし、例えばロジックを構造体のメソッドとして実装し、ブールフラグを使用したCスタイルの関数パターンを避けることができる。","ko":"에이전트가 일일이 번역하기보다 올바른 동작을 우선시하도록 하고, Rust의 네이티브 기능과最佳實踐을 활용할 수 있도록 하며, 예를 들어 로직을 구조체의 메서드로 구현하고, 불린旗를 사용한 C 스타일 함수 패턴을 피하는 등이다.","es":"Habilita a los agentes a priorizar el comportamiento correcto sobre la traducción línea por línea, utilizando las características nativas de Rust y las mejores prácticas, como implementar la lógica como métodos en estructuras y evitar patrones de funciones de estilo C con banderas booleanas.","fr":"Permet aux agents de donner la priorité au comportement correct au-dessus de la traduction ligne par ligne, en utilisant les fonctionnalités natives de Rust et les meilleures pratiques, telles que la mise en œuvre de la logique en tant que méthodes sur des structures et l''évitement des modèles de fonctions de style C avec des indicateurs booléens.","de":"Ermöglicht es den Agenten, das korrekte Verhalten über die zeilenweise Übersetzung zu priorisieren, indem sie die nativen Funktionen von Rust und die bewährten Verfahren nutzen, wie z.B. die Implementierung der Logik als Methoden auf Structs und das Vermeiden von C-Style-Funktionsmustern mit booleschen Flags.","pt":"Habilita os agentes a priorizar o comportamento correto sobre a tradução linha por linha, utilizando os recursos nativos do Rust e as melhores práticas, como implementar a lógica como métodos em structs e evitar padrões de função em estilo C com flags booleanas.","ru":"Наделяет агентов возможностью отдавать предпочтение правильному поведению над переводом построчно, используя встроенные функции Rust и лучшие практики, такие как реализация логики в виде методов struct и избегание функций в стиле C с булевыми флагами.","ar":"يمنح الوكيل القدرة على إعطاء الأولوية للسلوك الصحيح على الترجمة السطرية ، باستخدام الميزات الأصلية لـ Rust وأفضل الممارسات ، مثل تنفيذ المنطق كأسلوب على الهياكل وتجنب أنماط الوظائف بالنمط سي مع أعلام منطقية."},"useCases":{"en":["Refactoring C-style code to idiomatic Rust","Implementing methods on structs for encapsulated logic","Avoiding boolean flag soup in function parameters"],"zh":["将C风格代码重构为惯用Rust代码","在结构体上实现方法以封装逻辑","避免在函数参数中使用布尔旗标志"],"ja":["CスタイルのコードをイディオマティックなRustコードにリファクタリングする","構造体上でメソッドを実装してロジックをカプセル化する","関数パラメータでブールフラグを使用するのを避ける"],"ko":["C 스타일 코드를惯用적인 Rust 코드로 리팩토링하기","구조체에서 메서드를 구현하여 로직을 캡슐화하기","함수 매개변수에서 불린 旗를 사용하지 않기"],"es":["Reestructuración de código de estilo C a Rust idiomático","Implementación de métodos en estructuras para lógica encapsulada","Evitación de la sopa de banderas booleanas en parámetros de función"],"fr":["Réorganisation de code de style C en Rust idiomatique","Mise en œuvre de méthodes sur des structures pour une logique encapsulée","Évitement de la soupe de drapeaux booléens dans les paramètres de fonction"],"de":["Umstrukturierung von C-Style-Code in idiatischen Rust-Code","Implementierung von Methoden auf Structs für einkapselte Logik","Vermeidung von boolescher Flag-Suppe in Funktionsparametern"],"pt":["Reestruturação de código em estilo C para Rust idiomático","Implementação de métodos em structs para lógica encapsulada","Evitar sopa de bandeiras booleanas em parâmetros de função"],"ru":["Рефакторинг кода в стиле C в идиоматический Rust","Реализация методов в struct для инкапсулированной логики","Избегание супа из булевых флагов в параметрах функций"],"ar":["إعادة هيكلة رمز بالنمط سي إلى روست اصطلاحي","تنفيذ الأساليب على الهياكل من أجل منطق محكم","تجنب حساء من أعلام منطقية في معاملات الوظائف"]},"limitations":{"en":["Requires Rust programming knowledge","Not a direct line-by-line translation from C code"],"zh":["需要Rust编程知识","不能直接从C代码逐行翻译"],"ja":["Rustプログラミングの知識が必要","Cコードから直接逐行翻訳できない"],"ko":["Rust 프로그래밍 지식이 필요하다","C 코드에서 직접 일일이 번역할 수 없다"],"es":["Requiere conocimientos de programación en Rust","No es una traducción directa línea por línea desde el código C"],"fr":["Nécessite des connaissances en programmation Rust","N''est pas une traduction directe ligne par ligne depuis le code C"],"de":["Benötigt Rust-Programmierkenntnisse","Ist keine direkte zeilenweise Übersetzung aus C-Code"],"pt":["Requer conhecimento de programação em Rust","Não é uma tradução direta linha por linha do código C"],"ru":["Требует знаний программирования на Rust","Не является прямым переводом построчно кода на C"],"ar":["يتطلب معرفة بالبرمجة بلغة روست","ليس ترجمة مباشرة سطر بسطر من رمز سي"]},"version":4},"contentHash":"82a5bef99f6d72bd4d25232d5229d2f255c4de15bd4ab70c96282c51aa659d29","qualityScore":30}');
