INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bearcove/pikru/idiomatic-rust', 'idiomatic-rust', 'bearcove', 'pikru', 'community', 'idiomatic-rust bearcove pikru community Idiomatic-rust is a Rust port of C code that prioritizes correct behavior over line-by-line translation. It benefits developers who want to write idiomatic Rust code. idiomatic-rust 是 Rust 的一种编程风格，强调正确的行为而非简单的代码转换 idiomatic-rust は、Rust のコーディングスタイルで、正しい動作を重視します idiomatic-rust는 Rust의 코딩 스타일로, 올바른 동작을 강조합니다 Idiomatic Rust es una implementación de pikchr en Rust, que promueve el uso de patrones y prácticas idiomáticas de Rust Idiomatic Rust est une implémentation de pikchr en Rust, qui encourage l''utilisation de modèles et de pratiques idiomatiques de Rust Idiomatic Rust ist eine Implementierung von pikchr in Rust, die die Verwendung von Mustern und idiomatischen Praktiken von Rust fördert O idiomatic-rust é uma porta do pikchr para Rust, focada em comportamento correto, não tradução linha-a-linha. Aprenda a escrever código Rust idiomático Идиоматический Rust - это порт pikchr для Rust, ориентированный на правильное поведение, а не на перевод строка за строкой. Узнайте, как писать идиоматический код на Rust إيدوماتيك رست هو منفذ لبيكشر على رست، يركز على السلوك الصحيح، وليس على الترجمة سطر بسطر. تعلم كيفية كتابة код رست إيدوماتيكي how to use idiomatic-rust idiomatic-rust vs rust-c idiomatic-rust setup guide what is idiomatic-rust idiomatic-rust alternative to c idiomatic-rust install rust rust port best practices avoiding c patterns in rust idiomatic-rust documentation Rust 编程 idiomatic-rust Rust 最佳实践 代码优化 结构体方法 pikchr 图形库 Implements methods on structs to compute values where data lives Avoids C-style functions with boolean flag parameters Prioritizes correct behavior over line-by-line translation from C Supports Rust-specific programming patterns and best practices Provides a pikchr port to Rust for improved functionality Idiomatic-rust is a Rust port that emphasizes writing Rust code, not C code in Rust, to achieve correct behavior.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fyuuki0jp/SourceDoc/plan-adr-flow', 'community', 'fyuuki0jp', 'SourceDoc', 'fyuuki0jp/SourceDoc', 'plan-adr-flow', 0, 0, 30, '2026-03-08T01:57:15.352Z', '2026-03-08T02:03:53.343Z', '7337d5bb3586b1b85f05e8c8c6f8d42d679f7f42c63dd61318e363f027c55823', '{"id":"fyuuki0jp/SourceDoc/plan-adr-flow","name":"plan-adr-flow","description":{"en":"The plan-adr-flow skill analyzes source code to generate documentation, benefiting developers by keeping task planning and technical decisions organized in PLAN.md and docs/ADR/ files.","zh":"Plan-ADR-Flow 是一种自动化任务规划和技术决策文档化的技术，通过创建 PLAN.md 和 docs/ADR/ 文件实现开发过程的透明度","ja":"Plan-ADR-Flow はタスクプランニングと技術的意思決定を自動化ドキュメント化する技術で、PLAN.md と docs/ADR/ ファイルを作成して開発プロセスの透明性を実現する","ko":"Plan-ADR-Flow는 태스크 계획 및 기술적 의사결정을 자동화 문서화하는 기술로, PLAN.md 및 docs/ADR/ 파일을 생성하여 개발 프로세스의 투명성을 실현합니다","es":"plan-adr-flow es un flujo de trabajo que analiza el código fuente y crea documentación técnica. Ayuda a mantener la planificación de tareas y decisiones técnicas documentadas.","fr":"plan-adr-flow est un flux de travail qui analyse le code source et crée une documentation technique. Il aide à maintenir la planification des tâches et les décisions techniques documentées.","de":"plan-adr-flow ist ein Arbeitsablauf, der den Quellcode analysiert und technische Dokumentation erstellt. Er hilft dabei, die Aufgabenplanung und technische Entscheidungen zu dokumentieren.","pt":"O plan-adr-flow é uma ferramenta que analisa o código-fonte e cria documentação técnica de alta qualidade, melhorando a colaboração e a tomada de decisões","ru":"plan-adr-flow - это инструмент, который анализирует исходный код и создает техническую документацию высокого качества, улучшая сотрудничество и принятие решений","ar":"تدفق plan-adr هو أداة تحليل الشفرة المصدرية وإنشاء توثيق تقني عالي الجودة، مما يحسن التعاون وعمليات اتخاذ القرارات"},"seo":{"title":{"en":"plan-adr-flow: Technical Planning Setup Guide | AI Agent ...","zh":"Plan-ADR-Flow 设置指南：任务规划和技术决策文档化","ja":"Plan-ADR-Flow セットアップガイド：タスクプランニングと技術的意思決定のドキュメント化","ko":"Plan-ADR-Flow 설정 가이드: 태스크 계획 및 기술적 의사결정 문서화","es":"Guía de Configuración de plan-adr-flow para Documentación...","fr":"Configurer plan-adr-flow pour une Meilleure Documentation...","de":"Einrichtungsleitfaden für plan-adr-flow zur Technischen D...","pt":"Guia de Configuração do plan-adr-flow para Documentação T...","ru":"Настройка plan-adr-flow: ИИ Агенты для Технической Докуме...","ar":"إعداد تدفق plan-adr لتوثيق تقني متقدم باستخدام أدوات الذك..."},"description":{"en":"Discover how plan-adr-flow streamlines task planning and technical decision documentation. Learn how to implement PLAN.md and ADR workflows today!","zh":"了解 Plan-ADR-Flow 技术，实现任务规划和技术决策的自动化文档化，提高开发效率","ja":"Plan-ADR-Flow 技術を利用してタスクプランニングと技術的意思決定を自動化ドキュメント化し、開発効率を向上させる","ko":"Plan-ADR-Flow 기술을 사용하여 태스크 계획 및 기술적 의사결정을 자동화 문서화하고 개발 효율성을 높입니다","es":"Aprende a configurar plan-adr-flow para mantener la planificación de tareas y decisiones técnicas documentadas con Herramientas de Inteligencia Artificial","fr":"Découvrez comment configurer plan-adr-flow pour maintenir la planification des tâches et les décisions techniques documentées avec des Outils d''Intelligence ...","de":"Erfahren Sie, wie Sie plan-adr-flow einrichten, um die Aufgabenplanung und technische Entscheidungen mit KI-Tools zu dokumentieren","pt":"Aprenda a configurar o plan-adr-flow para melhorar a documentação técnica e a tomada de decisões com AI Agents","ru":"Узнайте, как настроить plan-adr-flow для улучшения технической документации и принятия решений с помощью ИИ Агентов","ar":"اكتشف كيفية إعداد تدفق plan-adr لتحسين توثيق تقني وعمليات اتخاذ القرارات باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"plan-adr-flow is a technical planning skill that automates documentation creation for tasks and technical decisions using PLAN.md and ADR files.","zh":"Plan-ADR-Flow 是一种自动化任务规划和技术决策文档化的技术","ja":"Plan-ADR-Flow はタスクプランニングと技術的意思決定を自動化ドキュメント化する技術","ko":"Plan-ADR-Flow는 태스크 계획 및 기술적 의사결정을 자동화 문서화하는 기술","es":"plan-adr-flow es un flujo de trabajo que combina la planificación de tareas y la documentación de decisiones técnicas","fr":"plan-adr-flow est un flux de travail qui combine la planification des tâches et la documentation des décisions techniques","de":"plan-adr-flow ist ein Arbeitsablauf, der die Aufgabenplanung und die Dokumentation von technischen Entscheidungen kombiniert","pt":"plan-adr-flow é uma ferramenta de documentação técnica que analisa o código-fonte e cria planos e registros de decisões","ru":"plan-adr-flow - это инструмент технической документации, который анализирует исходный код и создает планы и записи решений","ar":"تدفق plan-adr هو أداة توثيق تقني تحليل الشفرة المصدرية وإنشاء خطط وسجلات قرارات"},"features":{"en":["Creates or replaces PLAN.md at repo root with implementation plans","Drafts plans and confirms with users before implementation for decomposable tasks","Tries task size to determine if PLAN.md or ADR creation is necessary","Documents technical decisions in docs/ADR/ files before, during, and after implementation","Supports workflow automation for task planning and technical decision documentation"],"zh":["自动创建 PLAN.md 文件","创建 docs/ADR/ 文件","任务规划和技术决策文档化","支持任务大小的评估","实现开发过程的透明度"],"ja":["PLAN.md ファイルの自動作成","docs/ADR/ ファイルの作成","タスクプランニングと技術的意思決定のドキュメント化","タスクサイズの評価のサポート","開発プロセスの透明性の実現"],"ko":["PLAN.md 파일 자동 생성","docs/ADR/ 파일 생성","태스크 계획 및 기술적 의사결정 문서화","태스크 크기 평가 지원","개발 프로세스의 투명성 실현"],"es":["Análisis de código fuente para crear documentación técnica","Creación de PLAN.md y docs/ADR para documentar decisiones técnicas","Flujo de trabajo para mantener la planificación de tareas y decisiones técnicas documentadas","Compatibilidad con herramientas de Inteligencia Artificial para mejorar la documentación","Triage de tareas para determinar si se requiere un plan y documentación"],"fr":["Analyse du code source pour créer une documentation technique","Création de PLAN.md et docs/ADR pour documenter les décisions techniques","Flux de travail pour maintenir la planification des tâches et les décisions techniques documentées","Compatibilité avec des Outils d''Intelligence Artificielle pour améliorer la documentation","Triage des tâches pour déterminer si un plan et une documentation sont nécessaires"],"de":["Quellcode-Analyse zur Erstellung von technischer Dokumentation","Erstellung von PLAN.md und docs/ADR zur Dokumentation von technischen Entscheidungen","Arbeitsablauf zur Aufrechterhaltung der Aufgabenplanung und technischen Entscheidungen","Kompatibilität mit KI-Tools zur Verbesserung der Dokumentation","Triage von Aufgaben zur Bestimmung, ob ein Plan und eine Dokumentation erforderlich sind"],"pt":["Análise de código-fonte para criação de documentação técnica","Criação de planos e registros de decisões em PLAN.md e docs/ADR","Integração com fluxos de trabalho de desenvolvimento de software","Suporte à colaboração e tomada de decisões em equipe","Automatização de tarefas de documentação técnica"],"ru":["Анализ исходного кода для создания технической документации","Создание планов и записей решений в PLAN.md и docs/ADR","Интеграция с рабочими процессами разработки программного обеспечения","Поддержка сотрудничества и принятия решений в команде","Автоматизация задач технической документации"],"ar":["تحليل الشفرة المصدرية لإنشاء توثيق تقني","إنشاء خطط وسجلات قرارات في PLAN.md و docs/ADR","التكامل مع سير عمل تطوير البرمجيات","دعم التعاون وعمليات اتخاذ القرارات في الفريق","آلية أتمتة مهام التوثيق التقني"]},"keywords":{"en":["how to use plan-adr-flow","plan-adr-flow setup guide","plan-adr-flow alternative","plan-adr-flow vs traditional planning methods","what is plan-adr-flow","plan-adr-flow install","plan-adr-flow workflow automation","technical planning with plan-adr-flow","ADR file management with plan-adr-flow"],"zh":["Plan-ADR-Flow","AIエージェント","任务规划","技术决策","文档化","自动化","开发效率","PLAN.md","docs/ADR/"],"ja":["Plan-ADR-Flow","AIエージェント","タスクプランニング","技術的意思決定","ドキュメント化","自動化","開発効率","PLAN.md","docs/ADR/"],"ko":["Plan-ADR-Flow","AI 에이전트","태스크 계획","기술적 의사결정","문서화","자동화","개발 효율성","PLAN.md","docs/ADR/"],"es":["plan-adr-flow","documentación técnica","Herramientas de Inteligencia Artificial","planificación de tareas","decisiones técnicas","flujo de trabajo","análisis de código fuente","creación de documentación","triage de tareas"],"fr":["plan-adr-flow","documentation technique","Outils d''Intelligence Artificielle","planification des tâches","décisions techniques","flux de travail","analyse du code source","création de documentation","triage des tâches"],"de":["plan-adr-flow","technische Dokumentation","KI-Tools","Aufgabenplanung","technische Entscheidungen","Arbeitsablauf","Quellcode-Analyse","Erstellung von Dokumentation","Triage von Aufgaben"],"pt":["plan-adr-flow","documentação técnica","AI Agents","ferramentas de desenvolvimento de software","colaboração em equipe","tomada de decisões","análise de código-fonte","criação de planos","registros de decisões"],"ru":["plan-adr-flow","техническая документация","ИИ Агенты","инструменты разработки программного обеспечения","сотрудничество в команде","принятие решений","анализ исходного кода","создание планов","записи решений"],"ar":["تدفق plan-adr","توثيق تقني","أدوات الذكاء الاصطناعي","أدوات تطوير البرمجيات","تعاون الفريق","اتخاذ القرارات","تحليل الشفرة المصدرية","إنشاء خطط","سجلات قرارات"]}},"owner":"fyuuki0jp","repo":"SourceDoc","repoPath":"fyuuki0jp/SourceDoc","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.352Z","topics":[],"category":"community","skillMd":{"name":"plan-adr-flow","description":"Plan and document coding tasks with PLAN.md and ADRs in docs/ADR. Use when a task can be decomposed, when asked to create or update PLAN.md, or when capturing technical decisions.","bodyPreview":"# Plan + ADR Flow\n\n## Goal\n\nKeep task planning and technical decisions documented in `PLAN.md` and `docs/ADR/...` before, during, and after implementation.\n\n## Workflow\n\n1. **Triage task size**\n   - If the task is not meaningfully decomposable, proceed without creating `PLAN.md` or ADR unless requested.\n   - If the task is decomposable, draft a plan and confirm with the user before implementation.\n\n2. **Create plan and ADR when planning**\n   - Create or replace `PLAN.md` at repo root with the im","body":"# Plan + ADR Flow\n\n## Goal\n\nKeep task planning and technical decisions documented in `PLAN.md` and `docs/ADR/...` before, during, and after implementation.\n\n## Workflow\n\n1. **Triage task size**\n   - If the task is not meaningfully decomposable, proceed without creating `PLAN.md` or ADR unless requested.\n   - If the task is decomposable, draft a plan and confirm with the user before implementation.\n\n2. **Create plan and ADR when planning**\n   - Create or replace `PLAN.md` at repo root with the implementation plan.\n   - Create `docs/ADR/YYYYMMDD-title.md` for the technical decision record before coding.\n   - Create `docs/ADR/` if missing.\n   - Use a short, lowercase, hyphenated slug for `title`.\n\n3. **Update during implementation**\n   - Treat `PLAN.md` as a living memo; update it frequently to reflect reality.\n   - Append ADR updates when technical issues or new decisions appear; keep prior entries.\n\n4. **Finalize after implementation**\n   - Update ADR with outcomes, changes, and follow-ups.\n   - Mark `PLAN.md` as complete or reflect the final state.\n\n## ADR template (minimum)\n\n```markdown\n# <Title>\n\nDate: YYYY-MM-DD\nStatus: Proposed | Accepted | Superseded\n\n## Context\n- <Why this decision is needed>\n\n## Decision\n- <What is decided>\n\n## Consequences\n- <Impact, tradeoffs, follow-ups>\n\n## Change log\n- YYYY-MM-DD: <What changed and why>\n```\n\n## Notes\n\n- Keep ADR updates additive; never delete past entries.\n- Keep `PLAN.md` specific to the current task; do not modify `PLANS.md` unless explicitly asked.\n"},"lastSynced":"2026-03-08T02:03:53.343Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring structured task planning and technical decision documentation in Markdown files like PLAN.md and docs/ADR/","zh":"适合需要结构化任务规划和技术决策文档的开发代理，特别是使用Markdown文件，如PLAN.md和docs/ADR/。","ja":"開発エージェントが構造化されたタスクプランと技術的な意思決定のドキュメントを必要とする場合に最適です。特に、Markdownファイル（例：PLAN.md、docs/ADR/）を使用する場合に適しています。","ko":"구조화된 태스크 계획 및 기술적인 의사 결정 문서가 필요한 개발 에이전트에게 적합합니다. 예를 들어, Markdown 파일(PAN.md, docs/ADR/)을 사용하는 경우에 적합합니다.","es":"Ideal para Agentes de Desarrollo que requieren una planificación de tareas estructurada y documentación de decisiones técnicas en archivos Markdown como PLAN.md y docs/ADR/","fr":"Idéal pour les agents de développement nécessitant une planification de tâches structurée et une documentation de décisions techniques dans des fichiers Markdown comme PLAN.md et docs/ADR/","de":"Ideal für Entwicklungsmittel, die eine strukturierte Aufgabenplanung und technische Entscheidungsdokumentation in Markdown-Dateien wie PLAN.md und docs/ADR/ erfordern","pt":"Ideal para Agentes de Desenvolvimento que requerem planejamento de tarefas estruturado e documentação de decisões técnicas em arquivos Markdown como PLAN.md e docs/ADR/","ru":"Идеально подходит для агентов разработки, требующих структурированного планирования задач и документации технических решений в файлах Markdown, таких как PLAN.md и docs/ADR/","ar":"مثالي لعميل التطوير الذين يحتاجون إلى تخطيط مهام منظم وتوثيق القرارات الفنية في ملفات Markdown مثل PLAN.md و docs/ADR/"},"recommendation":{"en":"Empowers agents to generate and manage technical decision records in ADR format and task plans in Markdown, streamlining development workflows through organized documentation in `PLAN.md` and `docs/ADR/` files, leveraging Markdown parsing and generation capabilities","zh":"赋予代理生成和管理技术决策记录（ADR格式）和任务计划（Markdown格式），从而通过有组织的文档来简化开发工作流程，利用Markdown解析和生成功能，实现`PLAN.md`和`docs/ADR/`文件的高效管理。","ja":"エージェントに技術的な意思決定レコード（ADR形式）とタスクプラン（Markdown形式）の生成と管理を可能にし、開発ワークフローを効率化します。Markdownの解析と生成機能を利用し、`PLAN.md`と`docs/ADR/`ファイルの管理を簡素化します。","ko":"에이전트가 기술적인 의사 결정 기록(ADR 형식)과 태스크 계획(Markdown 형식)을 생성하고 관리하여 개발 워크플ロー를 효율화합니다. Markdown의 파싱과 생성 기능을 활용하여 `PLAN.md`와 `docs/ADR/` 파일의 관리를 간소화합니다.","es":"Habilita a los agentes a generar y gestionar registros de decisiones técnicas en formato ADR y planes de tareas en Markdown, racionalizando los flujos de trabajo de desarrollo a través de la documentación organizada en archivos `PLAN.md` y `docs/ADR/`, aprovechando las capacidades de análisis y generación de Markdown","fr":"Permet aux agents de générer et de gérer des enregistrements de décisions techniques au format ADR et des plans de tâches en Markdown, rationalisant les flux de travail de développement grâce à une documentation organisée dans les fichiers `PLAN.md` et `docs/ADR/`, en exploitant les capacités d''analyse et de génération de Markdown","de":"Ermächtigt die Agenten, technische Entscheidungssatzungen im ADR-Format und Aufgabenpläne in Markdown zu generieren und zu verwalten, und rationalisiert so die Entwicklungsworkflows durch eine organisierte Dokumentation in `PLAN.md`- und `docs/ADR/`-Dateien, indem es die Markdown-Analyse- und -Generierungsfähigkeiten nutzt","pt":"Habilita os agentes a gerar e gerenciar registros de decisões técnicas no formato ADR e planos de tarefas em Markdown, otimizando os fluxos de trabalho de desenvolvimento por meio de documentação organizada em arquivos `PLAN.md` e `docs/ADR/`, utilizando capacidades de análise e geração de Markdown","ru":"Наделяет агентов возможностью генерировать и управлять записями технических решений в формате ADR и планами задач в Markdown, оптимизируя рабочие процессы разработки за счет организованной документации в файлах `PLAN.md` и `docs/ADR/`, используя возможности парсинга и генерации Markdown","ar":"يمكن للوكلاء توليد وسرد سجلات القرارات الفنية بالصيغة ADR ومخططات المهام بالصيغة Markdown، ويسهم في تسهيل سير عمل التطوير من خلال توثيق منظم في ملفات `PLAN.md` و `docs/ADR/`، واستخدام khảيات تحليل وإنشاء Markdown"},"useCases":{"en":["Automating documentation updates in `PLAN.md`","Generating ADR records for technical decisions","Organizing task planning and implementation details in Markdown files"],"zh":["自动更新`PLAN.md`的文档","为技术决策生成ADR记录","在Markdown文件中组织任务规划和实施细节"],"ja":["`PLAN.md`のドキュメントを自動更新する","技術的な意思決定のためにADRレコードを生成する","Markdownファイルでタスクプランと実装の詳細を整理する"],"ko":["`PLAN.md`의 문서를 자동으로 업데이트 하는 것","기술적인 의사 결정에 대한 ADR 기록을 생성하는 것","Markdown 파일에서 태스크 계획과 구현 세부 정보를 조직하는 것"],"es":["Automatizar las actualizaciones de la documentación en `PLAN.md`","Generar registros ADR para decisiones técnicas","Organizar la planificación de tareas y los detalles de implementación en archivos Markdown"],"fr":["Automatiser les mises à jour de la documentation dans `PLAN.md`","Générer des enregistrements ADR pour les décisions techniques","Organiser la planification des tâches et les détails de mise en œuvre dans des fichiers Markdown"],"de":["Automatisieren der Dokumentenaktualisierungen in `PLAN.md`","Erzeugen von ADR-Satzungen für technische Entscheidungen","Organisieren der Aufgabenplanung und der Implementierungsdetails in Markdown-Dateien"],"pt":["Automatizar atualizações de documentação em `PLAN.md`","Gerar registros ADR para decisões técnicas","Organizar planejamento de tarefas e detalhes de implementação em arquivos Markdown"],"ru":["Автоматизировать обновления документации в `PLAN.md`","Генерировать записи ADR для технических решений","Организовывать планирование задач и детали реализации в файлах Markdown"],"ar":["تأتمتة تحديثات الوثائق في `PLAN.md`","إنتاج سجلات ADR للقرارات الفنية","تنظيم تخطيط المهام وتفاصيل التنفيذ في ملفات Markdown"]},"limitations":{"en":["Requires access to repository filesystem for reading and writing `PLAN.md` and `docs/ADR/` files","Limited to tasks that are meaningfully decomposable"],"zh":["需要访问仓库文件系统以读写`PLAN.md`和`docs/ADR/`文件","仅适用于可以有意义地分解的任务"],"ja":["`PLAN.md`と`docs/ADR/`ファイルを読み書きするためにリポジトリファイルシステムへのアクセスが必要","意味のあるタスクにのみ適用可能"],"ko":["`PLAN.md`와 `docs/ADR/` 파일을 읽고 쓰기 위해 저장소 파일 시스템에 액세스해야 함","의미 있는 태스크에만 적용 가능"],"es":["Requiere acceso al sistema de archivos del repositorio para leer y escribir archivos `PLAN.md` y `docs/ADR/`","Limitado a tareas que se pueden descomponer de manera significativa"],"fr":["Nécessite un accès au système de fichiers du référentiel pour lire et écrire les fichiers `PLAN.md` et `docs/ADR/`","Limité aux tâches qui peuvent être décomposées de manière significative"],"de":["Benötigt Zugriff auf das Dateisystem des Repositories zum Lesen und Schreiben von `PLAN.md`- und `docs/ADR/`-Dateien","Begrenzt auf Aufgaben, die sinnvoll zerlegbar sind"],"pt":["Requer acesso ao sistema de arquivos do repositório para leitura e gravação de arquivos `PLAN.md` e `docs/ADR/`","Limitado a tarefas que podem ser devidamente decompostas"],"ru":["Требует доступа к файловой системе репозитория для чтения и записи файлов `PLAN.md` и `docs/ADR/`","Ограничен задачами, которые можно осмысленно разложить на составные части"],"ar":["يتطلب الوصول إلى نظام ملفات المستودع للقراءة والكتابة من ملفات `PLAN.md` و `docs/ADR/`","محدود بالمهام التي يمكن تفكيكها بشكل ذي معنى"]},"version":4},"contentHash":"7337d5bb3586b1b85f05e8c8c6f8d42d679f7f42c63dd61318e363f027c55823","qualityScore":30}');
