INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shellRaining/rainMcp/rainMcp-release', 'rainMcp-release', 'shellRaining', 'rainMcp', 'community', 'rainMcp-release shellRaining rainMcp community The rainMcp-release skill automates version upgrades for developers, utilizing bash commands and Cargo package management. It benefits developers working with Tauri and JSON configurations. rainMcp-release 是一个用于版本升级的工具，支持查找版本号、批量修改和更新 Cargo.lock rainMcp-release はバージョンアップグレードツールです - AIエージェント rainMcp-release는 버전 업그레이드 도구로 버전 번호 찾기, 일괄 수정 및 Cargo.lock 업데이트를 지원합니다 rainMcp-release es una herramienta para gestionar versiones y actualizaciones de software. Utiliza comandos como grep, sed y cargo para automatizar el proceso. rainMcp-release est un outil pour gérer les versions et les mises à jour de logiciels. Il utilise des commandes comme grep, sed et cargo pour automatiser le processus. rainMcp-release ist ein Tool zur Verwaltung von Versionen und Software-Updates. Es verwendet Befehle wie grep, sed und cargo, um den Prozess zu automatisieren. O rainMcp-release é uma ferramenta de atualização de versão que utiliza comandos Bash para modificar arquivos de configuração. Aprenda a usá-la com nossas dicas RainMcp-release - это инструмент обновления версии, который использует команды Bash для изменения файлов конфигурации ИИ Агентов. Узнайте, как им пользоваться rainMcp-release هو أداة تحديث الإصدار التي تستخدم أوامر Bash لتعديل ملفات التكوين لأدوات الذكاء الاصطناعي. تعرف على كيفية استخدامها how to use rainMcp-release rainMcp-release setup guide automated version upgrade Tauri configuration management Cargo package management bash script automation git workflow optimization rainMcp-release install rainMcp-release alternative rainMcp-release 版本升级 Cargo.lock 包管理 版本管理 AI工具 自动化版本升级 Executes grep commands to find current version numbers in package.json and Cargo.toml files Utilizes sed for batch modification of version numbers across multiple files Updates Cargo.lock files using cargo check Runs lint and format checks using bun run Manages git status, diff, and commit operations for version control rainMcp-release is a skill that automates the version upgrade process using bash scripts and Cargo package management for Tauri configurations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stravinest/house-hold-account/app-modify-workflow', 'community', 'stravinest', 'house-hold-account', 'stravinest/house-hold-account', 'app-modify-workflow', 0, 0, 30, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:57.121Z', '9525b02d6fee9f7f60e947e4cad2cc486737d3eaef09e651894081a62799ae54', '{"id":"stravinest/house-hold-account/app-modify-workflow","name":"app-modify-workflow","description":{"en":"The app-modify-workflow skill enables developers to systematically modify and improve existing app features. It provides a structured approach to changing, debugging, and refining UI/UX elements","zh":"app-modify-workflow是一种用于修改和改进现有应用程序功能的6个阶段的工作流程，支持修改目标代码分析和UI/UX改进","ja":"app-modify-workflowは、既存のアプリケーション機能を変更または改善するための6段階のワークフローです。修改対象コードの分析やUI/UXの改善をサポートしています","ko":"app-modify-workflow는 기존 앱 기능을 수정 및 개선하기 위한 6단계 워크플로우입니다. 수정 대상 코드 분석 및 UI/UX 개선 기능을 제공합니다","es":"El flujo de trabajo de app-modify-workflow es un proceso de 6 pasos para mejorar aplicaciones existentes, enfocado en la modificación de funcionalidades y la mejora de la UI/UX","fr":"L''agent app-modify-workflow est un flux de travail de 6 étapes pour améliorer les applications existantes, axé sur la modification des fonctionnalités et l''amélioration de l''UI/UX","de":"Der app-modify-workflow ist ein 6-Schritte-Workflows zur Verbesserung bestehender Anwendungen, fokussiert auf die Modifizierung von Funktionalitäten und die Verbesserung der Benutzeroberfläche","pt":"O App Modify Workflow é um processo sistemático de 6 etapas para modificar e melhorar funcionalidades existentes em aplicativos","ru":"ИИ Агент App Modify Workflow - это системный 6-этапный процесс для модификации и улучшения существующих функций в приложениях","ar":"وكيل التطبيق MODIFY WORKFLOW هو عملية 系统ية من 6 مراحل لتعديل وتحسين الميزات الحالية في التطبيقات"},"seo":{"title":{"en":"app-modify-workflow: Streamlined App Modification Workflo...","zh":"AI工具：app-modify-workflow设置指南","ja":"AIエージェント：app-modify-workflowのベストプラクティス","ko":"app-modify-workflow 설정 가이드","es":"Guía de configuración de app-modify-workflow para desarro...","fr":"Guide d''intégration de l''agent app-modify-workflow pour l...","de":"Einrichtungsleitfaden für app-modify-workflow: Werkzeug f...","pt":"Guia de Configuração do App Modify Workflow","ru":"Настройка ИИ Агента App Modify Workflow","ar":"دليل إعداد وكيل التطبيق MODIFY WORKFLOW"},"description":{"en":"Discover how to optimize your app modification process with app-modify-workflow. Learn how to activate and utilize this 6-stage workflow for improved app fun...","zh":"了解app-modify-workflow的技术细节和设置方法，优化您的开发流程","ja":"app-modify-workflowの機能と設定方法をマスターし、開発効率を向上させる","ko":"app-modify-workflow의 기술 세부 사항과 설정 방법을 알아보세요","es":"Aprende a utilizar el flujo de trabajo de app-modify-workflow para mejorar tus aplicaciones existentes con 6 pasos sistemáticos","fr":"Découvrez comment utiliser l''agent app-modify-workflow pour améliorer vos applications existantes avec un flux de travail de 6 étapes","de":"Erfahren Sie, wie Sie den app-modify-workflow verwenden, um Ihre bestehenden Anwendungen mit einem 6-Schritte-Workflows zu verbessern","pt":"Aprenda a usar o App Modify Workflow para melhorar a experiência do usuário e corrigir bugs em seu aplicativo","ru":"Узнайте, как настроить ИИ Агент App Modify Workflow для улучшения пользовательского опыта и исправления ошибок в вашем приложении","ar":"تعلم كيفية إعداد وكيل التطبيق MODIFY WORKFLOW لتحسين تجربة المستخدم وتصحيح الأخطاء في تطبيقك"},"definition":{"en":"app-modify-workflow is a systematic 6-stage workflow for modifying and improving existing app features, focusing on changing, debugging, and refining UI/UX elements","zh":"app-modify-workflow是一种AI工具，用于优化和修改现有应用程序功能","ja":"app-modify-workflowは、AIエージェントの一種で、既存のアプリケーション機能を最適化および変更するために使用されます","ko":"app-modify-workflow는 기존 앱 기능을 최적화하고 수정하기 위한 AI 에이전트입니다","es":"El app-modify-workflow es un proceso sistemático para mejorar aplicaciones existentes","fr":"L''agent app-modify-workflow est un flux de travail système pour améliorer les applications existantes","de":"Der app-modify-workflow ist ein systematischer Prozess zur Verbesserung bestehender Anwendungen","pt":"O que é App Modify Workflow? É um processo para modificar e melhorar funcionalidades existentes em aplicativos","ru":"Что такое ИИ Агент App Modify Workflow? Это процесс для модификации и улучшения существующих функций в приложениях","ar":"ما هو وكيل التطبيق MODIFY WORKFLOW؟ هو عملية لتعديل وتحسين الميزات الحالية في التطبيقات"},"features":{"en":["Activates via commands such as ''앱 수정 워크플로우'' or ''/app-modify-workflow''","Supports phase-based analysis, including 현황 분석 and UI/UX review","Enables modification of existing app features, including 버그 수정 and UI/UX 개선","Allows for specific requests, such as ''앱 수정 워크플로우로 결제수단 관리 화면을 개선해줘''","Includes a structured approach to app modification, with clear phases and analysis steps","Utilizes a simple and intuitive command structure for easy workflow activation"],"zh":["6个阶段的工作流程","修改目标代码分析","UI/UX改进","支持命令行激活","优化现有应用程序功能"],"ja":["6段階のワークフロー","変更対象コードの分析","UI/UXの改善","コマンドラインによるアクティベーション","既存のアプリケーション機能の最適化"],"ko":["6단계 워크플로우","수정 대상 코드 분석","UI/UX 개선","CLI 명령어 활성화","기존 앱 기능 최적화"],"es":["Análisis de código de la aplicación existente","Modificación de funcionalidades y mejora de la UI/UX","Implementación de un flujo de trabajo de 6 pasos","Soporte para la mejora de la experiencia del usuario","Integración con herramientas de desarrollo de aplicaciones","Compatibilidad con diferentes tecnologías y plataformas"],"fr":["Analyse du code de l''application existante","Modification des fonctionnalités et amélioration de l''UI/UX","Mise en œuvre d''un flux de travail de 6 étapes","Prise en charge de l''amélioration de l''expérience utilisateur","Intégration avec des outils de développement d''applications","Compatibilité avec différentes technologies et plateformes"],"de":["Analyse des Codes der bestehenden Anwendung","Modifizierung von Funktionalitäten und Verbesserung der Benutzeroberfläche","Implementierung eines 6-Schritte-Workflows","Unterstützung für die Verbesserung der Benutzererfahrung","Integration mit Entwicklungstools für Anwendungen","Kompatibilität mit verschiedenen Technologien und Plattformen"],"pt":["Análise de código existente","Melhoria da UI/UX","Correção de bugs","Otimização da experiência do usuário","Integração com comando de voz","Suporte a desenvolvedores"],"ru":["Анализ существующего кода","Улучшение пользовательского интерфейса","Исправление ошибок","Оптимизация пользовательского опыта","Интеграция с голосовой командой","Поддержка разработчиков"],"ar":["تحليل الكود الحالي","تحسين واجهة المستخدم","تصحيح الأخطاء","تحسين تجربة المستخدم","التكامل مع أوامر الصوت","دعم المطورين"]},"keywords":{"en":["how to use app-modify-workflow","app-modify-workflow alternative","app-modify-workflow setup guide","what is app-modify-workflow","app-modify-workflow vs other workflows","app-modify-workflow install","app-modify-workflow tutorial","app-modify-workflow best practices","app-modify-workflow activation commands"],"zh":["AI工具","app-modify-workflow","应用程序修改","工作流程优化","命令行激活","UI/UX改进"],"ja":["AIエージェント","app-modify-workflow","アプリケーション変更","ワークフロー最適化","コマンドラインアクティベーション","UI/UX改善"],"ko":["AI 에이전트","app-modify-workflow","앱 기능 수정","워크플로우 최적화","CLI 명령어","UI/UX 개선"],"es":["app-modify-workflow","desarrollo de aplicaciones","mejora de aplicaciones existentes","flujo de trabajo de 6 pasos","modificación de funcionalidades","mejora de la UI/UX","herramientas de desarrollo de aplicaciones","tecnologías de desarrollo de aplicaciones"],"fr":["app-modify-workflow","développement d''applications","amélioration d''applications existantes","flux de travail de 6 étapes","modification de fonctionnalités","amélioration de l''UI/UX","outils de développement d''applications","technologies de développement d''applications"],"de":["app-modify-workflow","Anwendungsentwicklung","Verbesserung bestehender Anwendungen","6-Schritte-Workflows","Modifizierung von Funktionalitäten","Verbesserung der Benutzeroberfläche","Entwicklungstools für Anwendungen","Technologien für Anwendungsentwicklung"],"pt":["app modify workflow","desenvolvimento de aplicativos","melhoria da ui/ux","correção de bugs","otimização da experiência do usuário","comando de voz","ai agent","ferramentas de desenvolvimento"],"ru":["ии агент app modify workflow","разработка приложений","улучшение пользовательского интерфейса","исправление ошибок","оптимизация пользовательского опыта","голосовая команда","инструменты разработки","ии агенты"],"ar":["وكيل التطبيق modify workflow","تطوير التطبيقات","تحسين واجهة المستخدم","تصحيح الأخطاء","تحسين تجربة المستخدم","أوامر الصوت","أدوات التطوير","وكلاء الذكاء الاصطناعي"]}},"owner":"stravinest","repo":"house-hold-account","repoPath":"stravinest/house-hold-account","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.353Z","topics":[],"category":"community","skillMd":{"name":"app-modify-workflow","description":"앱 수정 워크플로우를 시작합니다. 현황 분석 -> UI/UX 검토 -> 엣지 케이스 확인 -> 사용자 질문 -> 계획 수립 -> 구현 -> 코드 리뷰 반복 순서로 체계적인 앱 수정을 진행합니다. /app-modify-workflow, 앱 수정 워크플로우, 수정 워크플로우로 등의 명령으로 활성화됩니다.","bodyPreview":"# 앱 수정 워크플로우 (App Modify Workflow)\n\n기존 앱 기능을 수정/개선할 때 사용하는 체계적인 6단계 워크플로우입니다.\n새 기능 개발이 아닌 **기존 기능의 변경, 버그 수정, UI/UX 개선**에 특화되어 있습니다.\n\n## 활성화 방법\n\n다음 명령어로 워크플로우를 시작합니다:\n\n- `앱 수정 워크플로우` 또는 `수정 워크플로우로 진행해줘`\n- `/app-modify-workflow`\n- `앱 수정으로 [요청 내용]`\n\n### 예시\n\n```\n사용자: 앱 수정 워크플로우로 결제수단 관리 화면을 개선해줘\n사용자: /app-modify-workflow 카테고리 선택 UI 수정\n사용자: 수정 워크플로우로 거래 입력 폼의 UX 개선해줘\n```\n\n---\n\n## 워크플로우 개요\n\n```\n[요청 접수]\n    |\n    v\n[Phase 1: 현황 분석] ─────────────────────────────────\n    |  - 수정 대상 코드 분석\n    |  - UI/UX","body":"# 앱 수정 워크플로우 (App Modify Workflow)\n\n기존 앱 기능을 수정/개선할 때 사용하는 체계적인 6단계 워크플로우입니다.\n새 기능 개발이 아닌 **기존 기능의 변경, 버그 수정, UI/UX 개선**에 특화되어 있습니다.\n\n## 활성화 방법\n\n다음 명령어로 워크플로우를 시작합니다:\n\n- `앱 수정 워크플로우` 또는 `수정 워크플로우로 진행해줘`\n- `/app-modify-workflow`\n- `앱 수정으로 [요청 내용]`\n\n### 예시\n\n```\n사용자: 앱 수정 워크플로우로 결제수단 관리 화면을 개선해줘\n사용자: /app-modify-workflow 카테고리 선택 UI 수정\n사용자: 수정 워크플로우로 거래 입력 폼의 UX 개선해줘\n```\n\n---\n\n## 워크플로우 개요\n\n```\n[요청 접수]\n    |\n    v\n[Phase 1: 현황 분석] ─────────────────────────────────\n    |  - 수정 대상 코드 분석\n    |  - UI/UX 현황 파악\n    |  - 엣지 케이스 식별\n    v\n[Phase 2: 요구사항 명확화] ───────────────────────────\n    |  - AskUserQuestion으로 질문\n    |  - 답변 기반 요구사항 정리\n    v\n[Phase 3: 계획 수립] ─────────────────────────────────\n    |  - plan 모드로 상세 계획 작성\n    |  - 사용자 승인\n    v\n[Phase 4: 구현] ──────────────────────────────────────\n    |  - modify-todo.md 생성 및 실행\n    |  - Agent 분담 작업\n    v\n[Phase 5: 코드 리뷰 및 반복] ─────────────────────────\n    |  - code-reviewer 실행\n    +──[결함 발견]──> [modify-todo.md 업데이트] ──> [Phase 4]\n    |\n    v\n[Phase 6: 완료] ──────────────────────────────────────\n    - 테스트 검증\n    - 결과 보고\n    - 아카이브\n```\n\n---\n\n## Phase 1: 현황 분석\n\n### 1.1 수정 대상 코드 분석\n\n수정 대상 기능과 관련된 코드를 심층 분석합니다.\n\n```\nTask(\n  subagent_type: \"feature-dev:code-explorer\",\n  prompt: \"[수정 대상 기능]의 현재 구현을 분석해주세요.\n  - 관련 파일 목록\n  - 실행 경로 추적\n  - 의존성 맵핑\n  - 현재 아키텍처 패턴\"\n)\n```\n\n### 1.2 UI/UX 현황 파악\n\n현재 UI/UX 상태를 분석하고 개선점을 식별합니다.\n\n#### 분석 항목\n\n| 항목 | 확인 사항 |\n|------|----------|\n| 레이아웃 | 요소 배치, 간격, 정렬 |\n| 색상 | 일관성, 접근성, 다크모드 지원 |\n| 폰트 | 크기, 가독성, 계층 구조 |\n| 인터랙션 | 터치 영역, 피드백, 애니메이션 |\n| 상태 표시 | 로딩, 에러, 빈 상태 처리 |\n| 반응성 | 다양한 화면 크기 대응 |\n\n#### 스크린샷 분석 (선택사항)\n\n```\n# 현재 화면 캡처\nmcp__mobile-mcp__mobile_take_screenshot\n\n# UI 요소 분석\nmcp__mobile-mcp__mobile_list_elements_on_screen\n```\n\n### 1.3 엣지 케이스 식별\n\n수정 시 고려해야 할 엣지 케이스를 식별합니다.\n\n#### 공통 엣지 케이스 체크리스트\n\n| 카테고리 | 엣지 케이스 |\n|----------|-----------|\n| 데이터 | 빈 데이터, 대량 데이터, 특수 문자, 긴 텍스트 |\n| 네트워크 | 오프라인, 느린 연결, 타임아웃 |\n| 사용자 입력 | 유효하지 않은 입력, 빠른 연속 클릭, 동시 요청 |\n| 권한 | 권한 없음, 읽기 전용, 만료된 세션 |\n| 디바이스 | 작은 화면, 큰 화면, 접근성 설정 |\n| 상태 | 초기 상태, 중간 상태, 에러 복구 |\n\n### 1.4 분석 결과 저장\n\n분석 결과를 파일로 저장합니다.\n\n```markdown\n# 현황 분석 결과\n\n## 수정 대상: [기능명]\n\n### 관련 파일\n- lib/features/[feature]/presentation/pages/xxx_page.dart\n- lib/features/[feature]/presentation/widgets/xxx_widget.dart\n- ...\n\n### 현재 UI/UX 상태\n- 강점: ...\n- 개선점: ...\n\n### 식별된 엣지 케이스\n1. [엣지 케이스 1]\n2. [엣지 케이스 2]\n3. ...\n\n### 의존성\n- Provider: ...\n- Repository: ...\n```\n\n저장 위치: `.workflow/context/analysis-result.md`\n\n---\n\n## Phase 2: 요구사항 명확화\n\n### 2.1 사용자 질문\n\n분석 결과를 바탕으로 사용자에게 구체적인 질문을 합니다.\n\n```\nAskUserQuestion(\n  questions: [\n    {\n      \"question\": \"UI 개선 방향을 선택해주세요\",\n      \"header\": \"UI 방향\",\n      \"options\": [\n        {\"label\": \"레이아웃 재구성\", \"description\": \"요소 배치와 구조를 변경\"},\n        {\"label\": \"스타일 개선\", \"description\": \"색상, 폰트, 간격 조정\"},\n        {\"label\": \"인터랙션 개선\", \"description\": \"애니메이션, 피드백 추가\"},\n        {\"label\": \"전면 리디자인\", \"description\": \"전체적으로 새롭게 설계\"}\n      ],\n      \"multiSelect\": false\n    },\n    {\n      \"question\": \"우선 처리할 엣지 케이스를 선택해주세요\",\n      \"header\": \"엣지 케이스\",\n      \"options\": [\n        {\"label\": \"데이터 관련\", \"description\": \"빈 데이터, 대량 데이터 처리\"},\n        {\"label\": \"에러 처리\", \"description\": \"네트워크 오류, 타임아웃\"},\n        {\"label\": \"입력 검증\", \"description\": \"유효하지 않은 입력 처리\"},\n        {\"label\": \"모든 케이스\", \"description\": \"전부 처리\"}\n      ],\n      \"multiSelect\": true\n    }\n  ]\n)\n```\n\n### 2.2 질문 카테고리\n\n| 카테고리 | 질문 예시 |\n|----------|----------|\n| 범위 | 어떤 부분까지 수정할까요? (특정 컴포넌트 / 전체 화면) |\n| 우선순위 | 가장 중요한 개선 사항은 무엇인가요? |\n| 제약사항 | 유지해야 할 기존 동작이 있나요? |\n| 호환성 | 이전 버전과의 호환성이 필요한가요? |\n| 테스트 | 어떤 시나리오를 반드시 테스트해야 하나요? |\n\n### 2.3 요구사항 정리\n\n사용자 답변을 바탕으로 요구사항을 정리합니다.\n\n```markdown\n# 수정 요구사항\n\n## 기능: [기능명]\n\n### 사용자 요청 요약\n- [핵심 요청 내용]\n\n### UI/UX 요구사항\n- [ ] [UI 요구사항 1]\n- [ ] [UI 요구사항 2]\n\n### 기능 요구사항\n- [ ] [기능 요구사항 1]\n- [ ] [기능 요구사항 2]\n\n### 엣지 케이스 처리\n- [ ] [엣지 케이스 1]\n- [ ] [엣지 케이스 2]\n\n### 제약사항\n- [유지해야 할 동작]\n- [호환성 요구사항]\n```\n\n저장 위치: `.workflow/modify-requirements.md`\n\n---\n\n## Phase 3: 계획 수립\n\n### 3.1 Plan 모드 진입\n\n요구사항을 바탕으로 상세 구현 계획을 수립합니다.\n\n```\nEnterPlanMode()\n```\n\n### 3.2 계획 작성 가이드\n\nPlan 모드에서 다음 내용을 포함하여 계획을 작성합니다:\n\n```markdown\n# 수정 계획: [기능명]\n\n## 변경 범위\n\n### 수정할 파일\n| 파일 | 변경 유형 | 변경 내용 |\n|------|----------|----------|\n| xxx_page.dart | 수정 | 레이아웃 구조 변경 |\n| xxx_widget.dart | 신규 | 새 위젯 추가 |\n| xxx_provider.dart | 수정 | 상태 로직 개선 |\n\n### 영향받는 영역\n- 직접 영향: [영향받는 기능 1], [영향받는 기능 2]\n- 간접 영향: [관련 기능]\n\n## 구현 단계\n\n### 1단계: [제목]\n- 작업 내용\n- 예상 변경 사항\n\n### 2단계: [제목]\n- 작업 내용\n- 예상 변경 사항\n\n## 테스트 계획\n\n### 단위 테스트\n- [ ] [테스트 케이스 1]\n- [ ] [테스트 케이스 2]\n\n### 통합 테스트\n- [ ] [시나리오 1]\n- [ ] [시나리오 2]\n\n### 엣지 케이스 테스트\n- [ ] [엣지 케이스 1]\n- [ ] [엣지 케이스 2]\n\n## 리스크 및 대응\n\n| 리스크 | 대응 방안 |\n|--------|----------|\n| [리스크 1] | [대응 1] |\n| [리스크 2] | [대응 2] |\n```\n\n### 3.3 사용자 승인\n\n계획 완료 후 승인을 요청합니다.\n\n```\nExitPlanMode()\n```\n\n---\n\n## Phase 4: 구현\n\n### 4.1 modify-todo.md 생성\n\n```markdown\n# Modify Todo: [작업명]\n\n## 메타 정보\n- 생성일: YYYY-MM-DD HH:MM\n- 현재 Phase: 4 (구현)\n- 상태: 진행중\n- 리뷰 반복 횟수: 0\n\n## 관련 문서\n- 분석 결과: .workflow/context/analysis-result.md\n- 요구사항: .workflow/modify-requirements.md\n\n---\n\n## 작업 목록\n\n### 1. 준비 단계\n| 번호 | 작업 | 담당 Agent | 상태 | 결과 |\n|------|------|-----------|------|------|\n| 1.1 | 기존 코드 백업 확인 | - | 대기 | - |\n| 1.2 | 의존성 확인 | Explore | 대기 | - |\n\n### 2. 구현 단계\n| 번호 | 작업 | 담당 Agent | 상태 | 결과 |\n|------|------|-----------|------|------|\n| 2.1 | [수정 작업 1] | tdd-developer | 대기 | - |\n| 2.2 | [수정 작업 2] | general-purpose | 대기 | - |\n| 2.3 | [UI 수정] | general-purpose | 대기 | - |\n\n### 3. 엣지 케이스 처리\n| 번호 | 작업 | 담당 Agent | 상태 | 결과 |\n|------|------|-----------|------|------|\n| 3.1 | [엣지 케이스 1] | tdd-developer | 대기 | - |\n| 3.2 | [엣지 케이스 2] | tdd-developer | 대기 | - |\n\n### 4. 검증 단계\n| 번호 | 작업 | 담당 Agent | 상태 | 결과 |\n|------|------|-----------|------|------|\n| 4.1 | 코드 리뷰 | code-reviewer | 대기 | - |\n| 4.2 | 테스트 작성 | test-writer | 대기 | - |\n\n---\n\n## 리뷰 피드백 히스토리\n\n---\n\n## 변경 로그\n- YYYY-MM-DD HH:MM: 초기 생성\n```\n\n저장 위치: `.workflow/modify-todo.md`\n\n### 4.2 Agent 할당 테이블\n\n| 작업 유형 | 담당 Agent | 설명 |\n|----------|-----------|------|\n| 코드 분석 | `Explore` | 기존 코드 구조 파악 |\n| 로직 수정 | `tdd-developer` | 테스트 우선 개발로 안전한 수정 |\n| UI 수정 | `general-purpose` | 위젯, 레이아웃 변경 |\n| 테스트 | `test-writer` | 테스트 코드 작성 |\n| 리뷰 | `feature-dev:code-reviewer` | 코드 품질 검토 |\n\n### 4.3 실행 규칙\n\n1. **순차 실행**: 의존성 있는 작업은 순차 실행\n2. **병렬 실행**: 독립적인 UI 작업은 병렬 가능\n3. **상태 업데이트**: 작업 완료 시 즉시 modify-todo.md 업데이트\n4. **결과 기록**: 변경된 파일과 주요 내용 기록\n\n---\n\n## Phase 5: 코드 리뷰 및 반복\n\n### 5.1 리뷰 실행\n\n```\nTask(\n  subagent_type: \"feature-dev:code-reviewer\",\n  prompt: \"수정된 코드를 리뷰해주세요.\n\n  확인 항목:\n  1. 버그: 로직 오류, 예외 처리 누락\n  2. 보안: 취약점, 데이터 노출\n  3. 성능: 불필요한 렌더링, 메모리 누수\n  4. 품질: 코드 스타일, 가독성\n  5. 호환성: 기존 기능 영향\n\n  변경된 파일: [파일 목록]\"\n)\n```\n\n### 5.2 리뷰 결과 처리\n\n#### 결함 발견 시\n\n1. modify-todo.md의 \"리뷰 피드백 히스토리\" 섹션에 피드백 추가\n2. 해당 작업의 상태를 `재작업`으로 변경\n3. \"리뷰 반복 횟수\" 증가\n4. 담당 Agent에게 재할당하여 Phase 4 재실행\n\n```markdown\n## 리뷰 피드백 히스토리\n\n### 1차 리뷰 (YYYY-MM-DD)\n- [x] xxx_page.dart: dispose에서 리소스 해제 누락 -> 재작업 완료\n- [x] xxx_widget.dart: 에러 상태 UI 미구현 -> 재작업 완료\n```\n\n#### 결함 없음\n\n1. 모든 작업 상태를 `완료`로 변경\n2. Phase 6으로 진행\n\n### 5.3 반복 제한\n\n- **최대 3회**까지 리뷰 반복\n- 초과 시 사용자에게 확인 요청\n\n```\n3회 이상 리뷰가 반복되었습니다.\n현재 남은 이슈:\n- [이슈 1]\n- [이슈 2]\n\n계속 진행하시겠습니까? (Y/n)\n```\n\n---\n\n## Phase 6: 완료\n\n### 6.1 테스트 검증\n\n```bash\n# 단위 테스트\nflutter test test/features/[feature]/\n\n# 전체 분석\nflutter analyze\n\n# 빌드 검증\nflutter build apk --debug\n```\n\n### 6.2 앱 테스트 (선택사항)\n\n```\n# 앱 실행 및 수정 사항 확인\nmcp__mobile-mcp__mobile_launch_app\nmcp__mobile-mcp__mobile_take_screenshot\n```\n\n### 6.3 결과 보고\n\n```markdown\n## 앱 수정 워크플로우 완료\n\n### 작업 요약\n- 수정 대상: [기능명]\n- 총 작업 수: [N]개\n- 리뷰 반복: [N]회\n\n### 변경된 파일\n| 파일 | 변경 유형 | 주요 변경 내용 |\n|------|----------|--------------|\n| xxx_page.dart | 수정 | 레이아웃 개선 |\n| xxx_widget.dart | 신규 | 에러 상태 위젯 추가 |\n\n### 해결된 엣지 케이스\n- [x] [엣지 케이스 1]\n- [x] [엣지 케이스 2]\n\n### 테스트 결과\n- 단위 테스트: 통과 (N/N tests)\n- 분석: 통과 (0 issues)\n- 빌드: 성공\n\n### 다음 단계\n- [ ] 실제 디바이스 테스트\n- [ ] PR 생성\n- [ ] QA 검토\n```\n\n### 6.4 아카이브\n\n```bash\nmkdir -p .workflow/archived\nmv .workflow/modify-todo.md .workflow/archived/YYYY-MM-DD_[작업명]_modify.md\n```\n\n---\n\n## 체크포인트 시스템\n\n### 파일 구조\n\n```\n.workflow/\n├── modify-todo.md           # 작업 목록 + 상태 추적\n├── modify-requirements.md   # 요구사항 정의\n├── checkpoint.md            # 현재 체크포인트\n├── context/\n│   ├── analysis-result.md   # Phase 1 분석 결과\n│   ├── questions-result.md  # Phase 2 질문 결과\n│   └── plan-result.md       # Phase 3 계획\n├── results/\n│   └── task-X.X.md          # Agent 작업 결과\n└── archived/\n```\n\n### checkpoint.md 형식\n\n```markdown\n# Modify Workflow Checkpoint\n\n## 현재 상태\n- 작업명: [작업명]\n- 현재 Phase: [1-6]\n- 현재 작업: [작업 번호]\n- 마지막 업데이트: YYYY-MM-DD HH:MM\n\n## 다음 단계\n- 다음 Phase: [Phase 번호]\n- 다음 작업: [작업 설명]\n- 담당 Agent: [Agent 타입]\n\n## 재개 명령어\n앱 수정 워크플로우 재개\n\n## 컨텍스트 파일 참조\n- modify-todo.md: .workflow/modify-todo.md\n- 분석 결과: .workflow/context/analysis-result.md\n```\n\n### 워크플로우 재개\n\n```\n앱 수정 워크플로우 재개\n/app-modify-workflow resume\n```\n\n---\n\n## 주의사항\n\n1. **기존 기능 보존**: 수정 시 기존 동작이 깨지지 않도록 주의\n2. **테스트 필수**: 수정 전후 테스트로 회귀 방지\n3. **에러 처리 원칙 준수**: CLAUDE.md의 에러 처리 원칙 (rethrow 등)\n4. **단일 modify-todo.md**: 동시에 하나의 수정 작업만 진행\n5. **리뷰 반복 제한**: 최대 3회 (초과 시 사용자 확인)\n6. **사용자 확인**: Phase 2, 3에서 반드시 사용자 승인 필요\n7. **엣지 케이스 처리**: 식별된 엣지 케이스는 반드시 처리\n\n---\n\n## 전체 흐름 예시\n\n### 사용자 요청\n\n```\n사용자: 앱 수정 워크플로우로 결제수단 관리 화면의 UX를 개선해줘\n```\n\n### 실행 과정\n\n```\n[Phase 1] 현황 분석\n   -> 코드 분석: PaymentMethodManagementPage, 관련 위젯 분석\n   -> UI/UX 파악: 현재 레이아웃, 인터랙션 분석\n   -> 엣지 케이스: 빈 목록, 긴 이름, 삭제 확인 등 식별\n\n[Phase 2] 요구사항 명확화\n   -> 질문: \"UI 개선 방향은?\", \"우선 엣지 케이스는?\"\n   -> 사용자 답변: \"레이아웃 재구성\", \"에러 처리 우선\"\n   -> 요구사항 정리: modify-requirements.md 생성\n\n[Phase 3] 계획 수립\n   -> EnterPlanMode 진입\n   -> 상세 계획 작성 (파일별 변경 사항, 단계별 작업)\n   -> ExitPlanMode로 사용자 승인\n\n[Phase 4] 구현\n   -> modify-todo.md 생성: 8개 작업 정의\n   -> 1.1 Explore -> 완료: \"의존성 확인\"\n   -> 2.1 tdd-developer -> 완료: \"리스트 구조 변경\"\n   -> 2.2 general-purpose -> 완료: \"UI 개선\"\n   -> 3.1 tdd-developer -> 완료: \"빈 상태 처리\"\n\n[Phase 5] 코드 리뷰 반복\n   -> 1차 리뷰: \"에러 메시지 개선 필요\"\n   -> 재작업: 에러 UI 수정\n   -> 2차 리뷰: 통과\n\n[Phase 6] 완료\n   -> flutter test: 통과\n   -> flutter analyze: 통과\n   -> 결과 보고\n   -> modify-todo.md 아카이브\n```\n"},"lastSynced":"2026-03-08T02:03:57.121Z","agentAnalysis":{"suitability":{"en":"Perfect for UI/UX-focused Agents needing structured app modification workflows.","zh":"适合需要结构化应用程序修改工作流的 UI/UX 集中型 Agent。","ja":"UI/UX に焦点を当てたエージェントが構造化されたアプリケーション修正ワークフローを必要とする場合に適しています。","ko":"UI/UX 중심의 에이전트가 구조화된 애플리케이션 수정 워크플ロー가 필요한 경우 적합합니다.","es":"Perfecto para Agentes centrados en UI/UX que necesitan flujos de trabajo de modificación de aplicaciones estructurados.","fr":"Parfait pour les agents axés sur l''UI/UX nécessitant des flux de travail de modification d''applications structurés.","de":"Perfekt für UI/UX-fokussierte Agenten, die strukturierte App-Modifizierungs-Workflows benötigen.","pt":"Perfeito para Agentes focados em UI/UX que necessitam de fluxos de trabalho de modificação de aplicativos estruturados.","ru":"Идеально подходит для агентов, ориентированных на UI/UX, которым необходимы структурированные рабочие процессы модификации приложений.","ar":"مثالي للعميل الذي يركز على واجهة المستخدم وتجربة المستخدم ويتطلب سير عمل تعديل تطبيقات منظم."},"recommendation":{"en":"Empowers agents to systematically modify and improve existing app features using a 6-step workflow, providing a structured approach to changing, debugging, and refining UI/UX elements with commands like `/app-modify-workflow`.","zh":"赋予代理人使用 6 步工作流程系统地修改和改进现有应用程序功能的能力，提供一种结构化的方法来更改、调试和改进 UI/UX 元素，使用诸如 `/app-modify-workflow` 的命令。","ja":"エージェントに 6 ステップのワークフローを使用して、既存のアプリケーション機能を体系的に修正および改善する能力を付与し、`/app-modify-workflow` などのコマンドを使用して UI/UX 要素を変更、デバッグ、および改良するための構造化されたアプローチを提供します。","ko":"에이전트가 6단계 워크플로를 사용하여 기존 애플리케이션 기능을 체계적으로 수정하고 개선할 수 있는 능력을 부여하여 `/app-modify-workflow`와 같은 명령을 사용하여 UI/UX 요소를 변경, 디버깅 및 개선하는 구조화된 접근 방식을 제공합니다.","es":"Habilita a los agentes a modificar y mejorar sistemáticamente las características de la aplicación existente utilizando un flujo de trabajo de 6 pasos, proporcionando un enfoque estructurado para cambiar, depurar y perfeccionar elementos UI/UX con comandos como `/app-modify-workflow`.","fr":"Permet aux agents de modifier et d''améliorer systématiquement les fonctionnalités de l''application existante en utilisant un flux de travail de 6 étapes, fournissant une approche structurée pour modifier, déboguer et affiner les éléments UI/UX avec des commandes comme `/app-modify-workflow`.","de":"Ermächtigt die Agenten, bestehende App-Funktionen systematisch zu modifizieren und zu verbessern, indem sie einen 6-Schritt-Workflow verwenden, der einen strukturierten Ansatz zur Änderung, Fehlersuche und Verfeinerung von UI/UX-Elementen mit Befehlen wie `/app-modify-workflow` bietet.","pt":"Permite que os agentes modifiquem e melhorem systematicamente os recursos existentes do aplicativo usando um fluxo de trabalho de 6 etapas, fornecendo uma abordagem estruturada para alterar, depurar e refinar elementos de UI/UX com comandos como `/app-modify-workflow`.","ru":"Позволяет агентам систематически изменять и улучшать существующие функции приложения, используя рабочий процесс из 6 шагов, обеспечивая структурированный подход к изменению, отладке и совершенствованию элементов UI/UX с помощью команд, таких как `/app-modify-workflow`.","ar":"تمكن العميل من تعديل وتحسين الميزات الحالية للتطبيق بشكل منهجي باستخدام سير عمل من 6 خطوات، ويقدم نهجًا منظمًا لتغيير وتحديد الأخطاء وتصفية عناصر واجهة المستخدم وتجربة المستخدم باستخدام أوامر مثل `/app-modify-workflow`."},"useCases":{"en":["Debugging UI issues in existing app features","Refining UX elements for better user engagement","Modifying app workflows to improve overall user experience"],"zh":["调试现有应用程序功能中的 UI 问题","改进 UX 元素以提高用户参与度","修改应用程序工作流程以提高整体用户体验"],"ja":["既存のアプリケーション機能における UI の問題をデバッグする","UX 要素を改善してユーザー エンゲージメントを高める","アプリケーションのワークフローを修正して全体的なユーザー エクスペリエンスを向上させる"],"ko":["기존 애플리케이션 기능에서 UI 문제를 디버깅하는 것","UX 요소를 개선하여 사용자 참여를 높이는 것","애플리케이션 워크플ロー 수정하여 전체 사용자 경험을 개선하는 것"],"es":["Depuración de problemas de UI en características de aplicaciones existentes","Perfeccionamiento de elementos UX para una mejor participación del usuario","Modificación de flujos de trabajo de aplicaciones para mejorar la experiencia del usuario en general"],"fr":["Débogage des problèmes d''UI dans les fonctionnalités d''applications existantes","Affinement des éléments UX pour une meilleure implication de l''utilisateur","Modification des flux de travail d''applications pour améliorer l''expérience utilisateur globale"],"de":["Fehlersuche bei UI-Problemen in bestehenden App-Funktionen","Verfeinerung von UX-Elementen für eine bessere Benutzerbeteiligung","Modifizierung von App-Workflows, um die gesamte Benutzererfahrung zu verbessern"],"pt":["Depuração de problemas de UI em recursos de aplicativos existentes","Refinamento de elementos de UX para melhor engajamento do usuário","Modificação de fluxos de trabalho de aplicativos para melhorar a experiência geral do usuário"],"ru":["Отладка проблем UI в существующих функциях приложения","Уточнение элементов UX для лучшего взаимодействия с пользователем","Модификация рабочих процессов приложения для улучшения общего опыта пользователя"],"ar":["تصحيح الأخطاء في مشاكل واجهة المستخدم في الميزات الحالية للتطبيق","تحسين عناصر تجربة المستخدم لتحقيق تفاعل أفضل مع المستخدم","تعديل سير عمل التطبيقات لتحسين تجربة المستخدم بشكل عام"]},"limitations":{"en":["Limited to modifying existing app features, not developing new ones","Requires specific commands like `앱 수정 워크플로우` or `/app-modify-workflow` to activate"],"zh":["仅限修改现有应用程序功能，而不是开发新的功能","需要特定的命令，如 `/app-modify-workflow` 来激活"],"ja":["既存のアプリケーション機能の修正のみが可能であり、新しい機能の開発は不可","特定のコマンド (例: `/app-modify-workflow`) が必要である"],"ko":["기존 애플리케이션 기능을 수정하는 것만 가능하며, 새로운 기능을 개발하는 것은 불가능합니다.","특정 명령 (예: `/app-modify-workflow`)이 필요합니다."],"es":["Limitado a la modificación de características de aplicaciones existentes, no al desarrollo de nuevas","Requiere comandos específicos como `/app-modify-workflow` para activar"],"fr":["Limité à la modification de fonctionnalités d''applications existantes, et non au développement de nouvelles","Nécessite des commandes spécifiques comme `/app-modify-workflow` pour activer"],"de":["Begrenzt auf die Modifizierung bestehender App-Funktionen, nicht auf die Entwicklung neuer","Erfordert spezifische Befehle wie `/app-modify-workflow`, um zu aktivieren"],"pt":["Limitado à modificação de recursos de aplicativos existentes, não ao desenvolvimento de novos","Requer comandos específicos como `/app-modify-workflow` para ativar"],"ru":["Ограничен изменением существующих функций приложения, а не разработкой новых","Требует специальных команд, таких как `/app-modify-workflow`, для активации"],"ar":["محدود بتعديل الميزات الحالية للتطبيق، وليس تطوير ميزات جديدة","يتطلب أوامر محددة مثل `/app-modify-workflow` لتنشيط"]},"version":4},"contentHash":"9525b02d6fee9f7f60e947e4cad2cc486737d3eaef09e651894081a62799ae54","qualityScore":30}');
