INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stravinest/house-hold-account/app-modify-workflow', 'app-modify-workflow', 'stravinest', 'house-hold-account', 'community', 'app-modify-workflow stravinest house-hold-account community The app-modify-workflow skill enables developers to systematically modify and improve existing app features. It provides a structured approach to changing, debugging, and refining UI/UX elements app-modify-workflow是一种用于修改和改进现有应用程序功能的6个阶段的工作流程，支持修改目标代码分析和UI/UX改进 app-modify-workflowは、既存のアプリケーション機能を変更または改善するための6段階のワークフローです。修改対象コードの分析やUI/UXの改善をサポートしています app-modify-workflow는 기존 앱 기능을 수정 및 개선하기 위한 6단계 워크플로우입니다. 수정 대상 코드 분석 및 UI/UX 개선 기능을 제공합니다 El flujo de trabajo de app-modify-workflow es un proceso de 6 pasos para mejorar aplicaciones existentes, enfocado en la modificación de funcionalidades y la mejora de la UI/UX L''agent app-modify-workflow est un flux de travail de 6 étapes pour améliorer les applications existantes, axé sur la modification des fonctionnalités et l''amélioration de l''UI/UX Der app-modify-workflow ist ein 6-Schritte-Workflows zur Verbesserung bestehender Anwendungen, fokussiert auf die Modifizierung von Funktionalitäten und die Verbesserung der Benutzeroberfläche O App Modify Workflow é um processo sistemático de 6 etapas para modificar e melhorar funcionalidades existentes em aplicativos ИИ Агент App Modify Workflow - это системный 6-этапный процесс для модификации и улучшения существующих функций в приложениях وكيل التطبيق MODIFY WORKFLOW هو عملية 系统ية من 6 مراحل لتعديل وتحسين الميزات الحالية في التطبيقات how to use app-modify-workflow app-modify-workflow alternative app-modify-workflow setup guide what is app-modify-workflow app-modify-workflow vs other workflows app-modify-workflow install app-modify-workflow tutorial app-modify-workflow best practices app-modify-workflow activation commands AI工具 app-modify-workflow 应用程序修改 工作流程优化 命令行激活 UI/UX改进 Activates via commands such as ''앱 수정 워크플로우'' or ''/app-modify-workflow'' Supports phase-based analysis, including 현황 분석 and UI/UX review Enables modification of existing app features, including 버그 수정 and UI/UX 개선 Allows for specific requests, such as ''앱 수정 워크플로우로 결제수단 관리 화면을 개선해줘'' Includes a structured approach to app modification, with clear phases and analysis steps Utilizes a simple and intuitive command structure for easy workflow activation app-modify-workflow is a systematic 6-stage workflow for modifying and improving existing app features, focusing on changing, debugging, and refining UI/UX elements');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('USW-Circle-Link/USW-Circle-Link-APP/component-usage', 'community', 'USW-Circle-Link', 'USW-Circle-Link-APP', 'USW-Circle-Link/USW-Circle-Link-APP', 'component-usage', 0, 0, 30, '2026-03-08T01:57:15.356Z', '2026-03-08T02:04:02.312Z', 'df61e5848058238efbec4a6aa1b2d2853319f94aa0642751945180a5ba0a9e0d', '{"id":"USW-Circle-Link/USW-Circle-Link-APP/component-usage","name":"component-usage","description":{"en":"The component-usage skill provides a reusable UI component library for Dart, enabling developers to efficiently build and style applications. It benefits developers working with the Donggurami app.","zh":"本文介绍了Dart组件库的使用方法，包括组件架构、样式模式和组件列表","ja":"コンポーネント使用の概要と、AIエージェントとの統合方法を説明します","ko":"동구라미 앱 컴포넌트 라이브러리의 개요와 컴포넌트 사용 방법을 설명합니다","es":"La biblioteca de componentes de Dongurami proporciona componentes de interfaz de usuario reutilizables para aplicaciones. Los componentes están organizados en carpetas y siguen un patrón de estilo separado.","fr":"La bibliothèque de composants de Dongurami fournit des composants d''interface utilisateur réutilisables pour les applications. Les composants sont organisés dans des dossiers et suivent un modèle de style séparé.","de":"Die Komponentenbibliothek von Dongurami bietet wiederverwendbare Benutzeroberflächenkomponenten für Anwendungen. Die Komponenten sind in Ordnern organisiert und folgen einem separaten Stil-Muster.","pt":"O componente-usage é uma biblioteca de componentes UI reutilizáveis para o app. Veja como utilizar e personalizar.","ru":"Компонент-usage - это библиотека повторно используемых UI-компонентов для приложения. См. как использовать и настраивать.","ar":"مكون-إستخدام هو مكتبة من المكونات القابلة لإعادة الاستخدام لتقديم واجهة المستخدم. انظر كيفية الإستخدام والتخصيص."},"seo":{"title":{"en":"component-usage: Dart Component Library Setup Guide | AI ...","zh":"组件使用指南：Dart 组件库设置","ja":"コンポーネント使用のベストプラクティス：AIエージェントとの統合","ko":"컴포넌트 사용 가이드: 동구라미 앱 컴포넌트 라이브러리","es":"Guía de Uso de Componentes: Mejores Prácticas para Desarr...","fr":"Guide d''Utilisation des Composants: Bonnes Pratiques pour...","de":"Komponenten-Verwendung: Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração de Component-Usage para Desenvolvedores","ru":"ИИ Агенты: Руководство по Использованию Компонентов","ar":"دليل إعداد إستخدام المكونات للبرمجة"},"description":{"en":"Discover how to leverage the component-usage skill to streamline your UI development with reusable components and styles. Get started now!","zh":"了解如何使用Dart组件库，实现UI组件的重用和自定义，提升开发效率","ja":"AIエージェントと統合するコンポーネント使用の方法を学び、開発効率を向上させます","ko":"동구라미 앱 컴포넌트 라이브러리를 사용하여 UI 컴포넌트를 재사용하고 커스텀하게 사용하는 방법을 알아보세요","es":"Aprende a utilizar componentes reutilizables en tu aplicación con nuestra guía de uso de componentes. Descubre las mejores prácticas para desarrolladores.","fr":"Découvrez comment utiliser des composants réutilisables dans votre application avec notre guide d''utilisation des composants. Apprenez les meilleures pratiqu...","de":"Erfahren Sie, wie Sie wiederverwendbare Komponenten in Ihrer Anwendung verwenden können. Unsere Komponenten-Verwendung-Anleitung bietet die besten Praktiken ...","pt":"Aprenda a utilizar componentes reutilizáveis em seu projeto com o componente-usage. Veja como configurar e personalizar.","ru":"Узнайте, как использовать повторно используемые компоненты в вашем проекте с помощью компонента-usage. См. как настроить и настроить.","ar":"تعرف على كيفية استخدام المكونات القابلة لإعادة الاستخدام في مشروعك مع مكون-إستخدام. انظر كيفية الإعداد والتخصيص."},"definition":{"en":"component-usage is a reusable UI component library for the Donggurami app, providing a structured approach to building and styling applications with Dart.","zh":"组件使用是指在Dart组件库中重用和自定义UI组件的过程","ja":"コンポーネント使用とは、AIエージェントと統合するUIコンポーネントの再利用とカスタマイズのプロセスです","ko":"컴포넌트 사용이란 동구라미 앱 컴포넌트 라이브러리에서 UI 컴포넌트를 재사용하고 커스텀하는 과정입니다","es":"Un componente es un elemento reutilizable de la interfaz de usuario que se puede utilizar en diferentes partes de una aplicación.","fr":"Un composant est un élément réutilisable de l''interface utilisateur qui peut être utilisé dans différentes parties d''une application.","de":"Ein Komponente ist ein wiederverwendbares Element der Benutzeroberfläche, das in verschiedenen Teilen einer Anwendung verwendet werden kann.","pt":"Component-usage é uma biblioteca de componentes UI reutilizáveis para aplicações","ru":"Компонент-usage - это библиотека повторно используемых UI-компонентов для приложений","ar":"مكون-إستخدام هو مكتبة من المكونات القابلة لإعادة الاستخدام لتقديم واجهة المستخدم"},"features":{"en":["Provides a structured folder structure for components in `lib/widgets/{component_name}/`","Supports style separation pattern through `{component_name}_styles.dart` files","Allows for custom styling using `MyComponentStyle.defaultStyle.copyWith` method","Includes a navigation and layout component library","Enables efficient reuse of UI components across the application"],"zh":["支持Dart语言","提供lib/widgets/{component_name}/文件夹结构","实现样式分离模式","支持基本样式和自定义样式","提供组件列表和导航功能"],"ja":["Dart言語対応","lib/widgets/{component_name}/フォルダ構造を提供","スタイル分離パターンを実現","基本スタイルとカスタムスタイルをサポート","コンポーネントリストとナビゲーション機能を提供"],"ko":["Dart 언어 지원","lib/widgets/{component_name}/ 폴더 구조 제공","스타일 분리 패턴 구현","기본 스타일과 커스텀 스타일 지원","컴포넌트 목록과 네비게이션 기능 제공"],"es":["Componentes reutilizables de interfaz de usuario","Organización de componentes en carpetas","Patrón de estilo separado para cada componente","Compatibilidad con estilos personalizados","Estructura de componentes flexible y escalable"],"fr":["Composants d''interface utilisateur réutilisables","Organisation des composants dans des dossiers","Modèle de style séparé pour chaque composant","Compatibilité avec des styles personnalisés","Structure de composants flexible et évolutive"],"de":["Wiederverwendbare Benutzeroberflächenkomponenten","Organisation von Komponenten in Ordnern","Separates Stil-Muster für jeden Komponenten","Unterstützung für benutzerdefinierte Styles","Flexibles und skalierbares Komponenten-Design"],"pt":["Arquitetura de componentes com separação de estilos","Utilização de pastas para organização de componentes","Personalização de estilos com padrão de copia","Suporte a navegação e layout","Integração com Dart"],"ru":["Архитектура компонентов с разделением стилей","Использование папок для организации компонентов","Настройка стилей с помощью шаблона копирования","Поддержка навигации и макета","Интеграция с Dart"],"ar":["هندسة المكونات مع فصل الأنماط","استخدام الملفات لتنظيم المكونات","تخصيص الأنماط باستخدام نمط النسخ","دعم الملاحة والتركيب","التكامل مع Dart"]},"keywords":{"en":["how to use component-usage","component-usage Dart library","component-usage vs Flutter","component-usage setup guide","install component-usage","what is component-usage","component-usage alternative","component-usage navigation component","component-usage style pattern"],"zh":["Dart组件库","UI组件重用","自定义样式","组件架构","样式分离模式","AI工具","Dart开发"],"ja":["Dartコンポーネントライブラリ","UIコンポーネントの再利用","カスタムスタイル","コンポーネントアーキテクチャ","スタイル分離パターン","AIエージェント","Dart開発"],"ko":["Dart 컴포넌트 라이브러리","UI 컴포넌트 재사용","커스텀 스타일","컴포넌트 아키텍처","스타일 분리 패턴","AI 툴","Dart 개발"],"es":["componentes reutilizables","interfaz de usuario","patrón de estilo","estilos personalizados","desarrollo de aplicaciones","Herramientas de AI para desarrolladores","Guía de uso de componentes"],"fr":["composants réutilisables","interface utilisateur","modèle de style","styles personnalisés","développement d''applications","Outils d''IA pour les développeurs","Guide d''utilisation des composants"],"de":["wiederverwendbare Komponenten","Benutzeroberfläche","Stil-Muster","benutzerdefinierte Styles","Anwendungsentwicklung","KI-Tools für Entwickler","Komponenten-Verwendung-Anleitung"],"pt":["component-usage","biblioteca de componentes","reutilização de componentes","desenvolvimento de aplicações","Dart","navegação","layout","estilos personalizados"],"ru":["компонент-usage","библиотека компонентов","повторное использование компонентов","разработка приложений","Dart","навигация","макет","настраиваемые стили"],"ar":["مكون-إستخدام","مكتبة المكونات","إعادة استخدام المكونات","برمجة التطبيقات","Dart","الملاحة","التركيب","الأنماط المخصصة"]}},"owner":"USW-Circle-Link","repo":"USW-Circle-Link-APP","repoPath":"USW-Circle-Link/USW-Circle-Link-APP","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.356Z","topics":[],"category":"community","skillMd":{"name":"component-usage","description":"동구라미 앱 컴포넌트 라이브러리 사용 가이드. UI 컴포넌트 구현, 스타일 커스터마이징, 위젯 활용법 안내. Keywords: component, widget, ui, style, button, dialog, text field, chip, app bar, drawer","bodyPreview":"# 동구라미 컴포넌트 라이브러리\n\n## 개요\n\n동구라미 앱의 재사용 가능한 UI 컴포넌트 라이브러리입니다.\n모든 컴포넌트는 `lib/widgets/{component_name}/` 폴더에 위치하며, 스타일 분리 패턴을 따릅니다.\n\n## 컴포넌트 아키텍처\n\n### 폴더 구조\n```\nlib/widgets/\n├── {component_name}/\n│   ├── {component_name}.dart        # 컴포넌트 구현\n│   └── {component_name}_styles.dart # 스타일 클래스\n```\n\n### 스타일 패턴\n```dart\n// 1. 기본 스타일 사용\nMyComponent()\n\n// 2. 커스텀 스타일 사용\nMyComponent(\n  style: MyComponentStyle.defaultStyle.copyWith(\n    backgroundColor: Colors.blue,\n  ),\n)\n```\n\n---\n\n## 컴포넌트 목록\n\n### 네비게이션 & 레이아웃","body":"# 동구라미 컴포넌트 라이브러리\n\n## 개요\n\n동구라미 앱의 재사용 가능한 UI 컴포넌트 라이브러리입니다.\n모든 컴포넌트는 `lib/widgets/{component_name}/` 폴더에 위치하며, 스타일 분리 패턴을 따릅니다.\n\n## 컴포넌트 아키텍처\n\n### 폴더 구조\n```\nlib/widgets/\n├── {component_name}/\n│   ├── {component_name}.dart        # 컴포넌트 구현\n│   └── {component_name}_styles.dart # 스타일 클래스\n```\n\n### 스타일 패턴\n```dart\n// 1. 기본 스타일 사용\nMyComponent()\n\n// 2. 커스텀 스타일 사용\nMyComponent(\n  style: MyComponentStyle.defaultStyle.copyWith(\n    backgroundColor: Colors.blue,\n  ),\n)\n```\n\n---\n\n## 컴포넌트 목록\n\n### 네비게이션 & 레이아웃\n\n| 컴포넌트 | 설명 | 문서 |\n|----------|------|------|\n| AppBar | 메인 화면용 커스텀 앱바 | [app-bar.md](app-bar.md) |\n| DetailAppBar | 상세 화면용 앱바 (뒤로가기 + 제목) | [detail-app-bar.md](detail-app-bar.md) |\n| DrawerMenu | 드로어 메뉴 (로그인/비로그인 통합) | [drawer-menu.md](drawer-menu.md) |\n| DrawerItem | 드로어 메뉴 아이템 | [drawer-item.md](drawer-item.md) |\n| DrawerEventItem | 드로어 이벤트 아이템 | [drawer-event-item.md](drawer-event-item.md) |\n\n### 필터 & 선택\n\n| 컴포넌트 | 설명 | 문서 |\n|----------|------|------|\n| FilterTabBar | 전체/모집중 필터 탭 | [filter-tab-bar.md](filter-tab-bar.md) |\n| CategoryFilterButton | 카테고리 필터 버튼 | [category-filter-button.md](category-filter-button.md) |\n| CategoryPicker | 카테고리 선택 다이얼로그 | [category-picker.md](category-picker.md) |\n| RemovableChip | 삭제 가능한 칩 | [removable-chip.md](removable-chip.md) |\n| SelectedCategoryChipList | 선택된 카테고리 칩 목록 | [selected-category-chip-list.md](selected-category-chip-list.md) |\n\n### 입력 필드\n\n| 컴포넌트 | 설명 | 문서 |\n|----------|------|------|\n| RoundedTextField | 둥근 텍스트 필드 | [rounded-text-field.md](rounded-text-field.md) |\n| RoundedEmailField | 둥근 이메일 필드 | [rounded-email-field.md](rounded-email-field.md) |\n| EmailTextField | 이메일 텍스트 필드 | [email-text-field.md](email-text-field.md) |\n| EmailTextFieldWithButton | 버튼 포함 이메일 필드 | [email-text-field-with-button.md](email-text-field-with-button.md) |\n| RoundedDropdown | 둥근 드롭다운 | [rounded-dropdown.md](rounded-dropdown.md) |\n\n### 다이얼로그 & 오버레이\n\n| 컴포넌트 | 설명 | 문서 |\n|----------|------|------|\n| AlertTextDialog | 알림 다이얼로그 | [alert-text-dialog.md](alert-text-dialog.md) |\n| CircleCertificateDialog | 인증 코드 다이얼로그 | [circle-certificate-dialog.md](circle-certificate-dialog.md) |\n| MajorPickerDialog | 학과 선택 다이얼로그 | [major-picker-dialog.md](major-picker-dialog.md) |\n| PolicyDialog | 약관 다이얼로그 | [policy-dialog.md](policy-dialog.md) |\n| NotificationOverlay | 알림 오버레이 | [notification-overlay.md](notification-overlay.md) |\n| CircleDetailOverlay | 동아리 상세 오버레이 | [circle-detail-overlay.md](circle-detail-overlay.md) |\n\n### 동아리 관련\n\n| 컴포넌트 | 설명 | 문서 |\n|----------|------|------|\n| CircleList | 동아리 목록 | [circle-list.md](circle-list.md) |\n| CircleItem | 동아리 아이템 | [circle-item.md](circle-item.md) |\n| CircleGroup | 동아리 그룹 | [circle-group.md](circle-group.md) |\n| CircleDetailItem | 동아리 상세 아이템 | [circle-detail-item.md](circle-detail-item.md) |\n\n### 기타\n\n| 컴포넌트 | 설명 | 문서 |\n|----------|------|------|\n| TextFontWidget | 텍스트 폰트 헬퍼 | [text-font-widget.md](text-font-widget.md) |\n| NoticeList | 공지사항 목록 | [notice-list.md](notice-list.md) |\n| CloudMessaging | FCM 메시징 위젯 | [cloud-messaging.md](cloud-messaging.md) |\n\n---\n\n## 테마 색상\n\n| 용도 | 색상 코드 | 설명 |\n|------|-----------|------|\n| Primary | `#FFB052` | 브랜드 주 색상 (오렌지) |\n| Primary Dark | `#FF9A21` | 브랜드 진한 색상 |\n| Background | `#F0F2F5` | 배경 회색 |\n| Text Primary | `#000000` | 주 텍스트 색상 |\n| Text Secondary | `#767676` | 보조 텍스트 색상 |\n| Text Tertiary | `#A8A8A8` | 연한 텍스트 색상 |\n| Border | `#DBDBDB` | 기본 테두리 색상 |\n| Divider | `#CECECE` | 구분선 색상 |\n\n---\n\n## 새 컴포넌트 추가 가이드\n\n### 1. 폴더 생성\n```bash\nmkdir lib/widgets/{new_component}\n```\n\n### 2. 스타일 파일 생성\n```dart\n// lib/widgets/{new_component}/{new_component}_styles.dart\nimport ''package:flutter/material.dart'';\n\nclass NewComponentStyle {\n  final Color backgroundColor;\n\n  const NewComponentStyle({\n    this.backgroundColor = Colors.white,\n  });\n\n  static const NewComponentStyle defaultStyle = NewComponentStyle();\n\n  NewComponentStyle copyWith({Color? backgroundColor}) {\n    return NewComponentStyle(\n      backgroundColor: backgroundColor ?? this.backgroundColor,\n    );\n  }\n}\n```\n\n### 3. 컴포넌트 파일 생성\n```dart\n// lib/widgets/{new_component}/{new_component}.dart\nimport ''package:flutter/material.dart'';\nimport ''{new_component}_styles.dart'';\n\nclass NewComponent extends StatelessWidget {\n  final NewComponentStyle style;\n\n  const NewComponent({\n    super.key,\n    this.style = NewComponentStyle.defaultStyle,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Container(color: style.backgroundColor);\n  }\n}\n```\n"},"lastSynced":"2026-03-08T02:04:02.312Z","agentAnalysis":{"suitability":{"en":"Perfect for Dart-based Agents needing reusable UI component libraries for efficient application development.","zh":"非常适合需要可重用UI组件库的Dart-based Agents，用于高效的应用程序开发。","ja":"Dartベースのエージェントが再利用可能なUIコンポーネントライブラリを必要とする場合に最適です。","ko":"다트 기반 에이전트가 효율적인 애플리케이션 개발을 위해 재사용 가능한 UI 컴포넌트 라이브러리를 필요로 하는 경우에 적합합니다.","es":"Perfecto para agentes basados en Dart que necesitan bibliotecas de componentes de interfaz de usuario reutilizables para un desarrollo de aplicaciones eficiente.","fr":"Parfait pour les agents basés sur Dart ayant besoin de bibliothèques de composants d''interface utilisateur réutilisables pour un développement d''applications efficace.","de":"Perfekt für Dart-basierte Agenten, die wiederverwendbare Benutzeroberflächenkomponentenbibliotheken für eine effiziente Anwendungsentwicklung benötigen.","pt":"Perfeito para Agentes baseados em Dart que precisam de bibliotecas de componentes de interface do usuário reutilizáveis para desenvolvimento de aplicativos eficiente.","ru":"Идеально подходит для агентов на основе Dart, которым требуются повторно используемые библиотеки компонентов пользовательского интерфейса для эффективного развития приложений.","ar":"مثالي للوكلاء الذين يستندون إلى Dart الذين يحتاجون إلى مكتبات مكونات واجهة المستخدم قابلة لإعادة الاستخدام لتطوير التطبيقات بكفاءة."},"recommendation":{"en":"Empowers agents to build and style applications with a comprehensive UI component library, utilizing Dart and following a style separation pattern, and provides customizable components with a standardized folder structure, enabling efficient development and maintenance of the Donggurami app.","zh":"赋予代理构建和样式化应用程序的能力，使用全面性的UI组件库，利用Dart，并遵循样式分离模式，并提供可定制的组件和标准化的文件夹结构，实现Donggurami应用程序的高效开发和维护。","ja":"エージェントがDartを使用して、アプリケーションを構築およびスタイル化できるようにし、包括的なUIコンポーネントライブラリを提供し、スタイル分離パターンに従い、カスタマイズ可能なコンポーネントと標準化されたフォルダ構造を提供して、Dongguramiアプリの効率的な開発とメンテナンスを可能にします。","ko":"다트를 사용하여 에이전트가 애플리케이션을 구축하고 스타일을 지정할 수 있도록 하며, 포괄적인 UI 컴포넌트 라이브러리를 제공하고, 스타일 분리 패턴을 따르며, 사용자 지정 가능한 컴포넌트와 표준화된 폴더 구조를 제공하여 Donggurami 애플리케이션의 효율적인 개발 및 유지 보수를 가능하게 합니다.","es":"Habilita a los agentes a construir y dar estilo a aplicaciones con una biblioteca de componentes de interfaz de usuario integral, utilizando Dart y siguiendo un patrón de separación de estilo, y proporciona componentes personalizables con una estructura de carpetas estandarizada, lo que permite un desarrollo y mantenimiento eficientes de la aplicación Donggurami.","fr":"Permet aux agents de construire et de personnaliser des applications avec une bibliothèque complète de composants d''interface utilisateur, en utilisant Dart et en suivant un modèle de séparation de style, et fournit des composants personnalisables avec une structure de dossiers standardisée, permettant ainsi un développement et une maintenance efficaces de l''application Donggurami.","de":"Ermächtigt Agenten, Anwendungen mit einer umfassenden Benutzeroberflächenkomponentenbibliothek zu erstellen und zu gestalten, indem Dart verwendet und ein Stil-Trennmuster befolgt wird, und bietet anpassbare Komponenten mit einer standardisierten Ordnerstruktur, wodurch eine effiziente Entwicklung und Wartung der Donggurami-App ermöglicht wird.","pt":"Habilita os agentes a construir e personalizar aplicativos com uma biblioteca abrangente de componentes de interface do usuário, utilizando Dart e seguindo um padrão de separação de estilos, e fornece componentes personalizáveis com uma estrutura de pasta padronizada, permitindo o desenvolvimento e manutenção eficientes do aplicativo Donggurami.","ru":"Наделяет агентов возможностью создавать и настраивать приложения с помощью всесторонней библиотеки компонентов пользовательского интерфейса, используя Dart и следуя шаблону разделения стилей, и предоставляет настраиваемые компоненты со стандартизированной структурой папок, что позволяет эффективно разрабатывать и поддерживать приложение Donggurami.","ar":"يمنح الوكلاء القدرة على بناء وتخصيص التطبيقات باستخدام مكتبة شاملة من مكونات واجهة المستخدم، باستخدام Dart ومتابعة نمط فصل الأنماط، وتوفر مكونات قابلة للتعديل مع هيكل مجلدات معياري، مما يسمح بالتطوير والصيانة الفعالة لتطبيق Donggurami."},"useCases":{"en":["Building reusable UI components for the Donggurami app","Customizing component styles with Dart","Organizing code with a standardized folder structure"],"zh":["为Donggurami应用程序构建可重用UI组件","使用Dart自定义组件样式","使用标准化的文件夹结构组织代码"],"ja":["Dongguramiアプリケーションの再利用可能なUIコンポーネントを構築する","Dartを使用してコンポーネントのスタイルをカスタマイズする","標準化されたフォルダ構造を使用してコードを整理する"],"ko":["Donggurami 애플리케이션을 위한 재사용 가능한 UI 컴포넌트를 구축하는 것","다트를 사용하여 컴포넌트 스타일을 사용자 지정하는 것","표준화된 폴더 구조를 사용하여 코드를 조직하는 것"],"es":["Creación de componentes de interfaz de usuario reutilizables para la aplicación Donggurami","Personalización de estilos de componentes con Dart","Organización de código con una estructura de carpetas estandarizada"],"fr":["Création de composants d''interface utilisateur réutilisables pour l''application Donggurami","Personnalisation des styles de composants avec Dart","Organisation du code avec une structure de dossiers standardisée"],"de":["Erstellung wiederverwendbarer Benutzeroberflächenkomponenten für die Donggurami-App","Anpassung von Komponentenstilen mit Dart","Organisation von Code mit einer standardisierten Ordnerstruktur"],"pt":["Construção de componentes de interface do usuário reutilizáveis para o aplicativo Donggurami","Personalização de estilos de componentes com Dart","Organização de código com uma estrutura de pasta padronizada"],"ru":["Создание повторно используемых компонентов пользовательского интерфейса для приложения Donggurami","Настройка стилей компонентов с помощью Dart","Организация кода со стандартизированной структурой папок"],"ar":["بناء مكونات واجهة المستخدم قابلة لإعادة الاستخدام لتطبيق Donggurami","تخصيص أنماط المكونات مع Dart","تنظيم الكود مع هيكل مجلدات معياري"]},"limitations":{"en":["Requires Dart programming language","Specific to Donggurami app development","Follows a specific style separation pattern"],"zh":["需要Dart编程语言","特定于Donggurami应用程序开发","遵循特定的样式分离模式"],"ja":["Dartプログラミング言語が必要","Dongguramiアプリケーションの開発に特定","特定のスタイル分離パターンに従う"],"ko":["다트 프로그래밍 언어가 필요함","Donggurami 애플리케이션 개발에 특정함","특정한 스타일 분리 패턴을 따름"],"es":["Requiere el lenguaje de programación Dart","Específico para el desarrollo de la aplicación Donggurami","Sigue un patrón de separación de estilo específico"],"fr":["Nécessite le langage de programmation Dart","Spécifique au développement de l''application Donggurami","Suit un modèle de séparation de style spécifique"],"de":["Erfordert die Programmiersprache Dart","Spezifisch für die Entwicklung der Donggurami-App","Befolgt ein bestimmtes Stil-Trennmuster"],"pt":["Exige a linguagem de programação Dart","Específico para o desenvolvimento do aplicativo Donggurami","Siga um padrão específico de separação de estilos"],"ru":["Требует языка программирования Dart","Специфичен для разработки приложения Donggurami","Следует конкретному шаблону разделения стилей"],"ar":["يتطلب لغة برمجة Dart","محدد لتطوير تطبيق Donggurami","يتابع نمطا محددا لفصل الأنماط"]},"version":4},"contentHash":"df61e5848058238efbec4a6aa1b2d2853319f94aa0642751945180a5ba0a9e0d","qualityScore":30}');
