INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('USW-Circle-Link/USW-Circle-Link-APP/component-usage', 'component-usage', 'USW-Circle-Link', 'USW-Circle-Link-APP', 'community', 'component-usage USW-Circle-Link USW-Circle-Link-APP community The component-usage skill provides a reusable UI component library for Dart, enabling developers to efficiently build and style applications. It benefits developers working with the Donggurami app. 本文介绍了Dart组件库的使用方法，包括组件架构、样式模式和组件列表 コンポーネント使用の概要と、AIエージェントとの統合方法を説明します 동구라미 앱 컴포넌트 라이브러리의 개요와 컴포넌트 사용 방법을 설명합니다 La biblioteca de componentes de Dongurami proporciona componentes de interfaz de usuario reutilizables para aplicaciones. Los componentes están organizados en carpetas y siguen un patrón de estilo separado. La bibliothèque de composants de Dongurami fournit des composants d''interface utilisateur réutilisables pour les applications. Les composants sont organisés dans des dossiers et suivent un modèle de style séparé. Die Komponentenbibliothek von Dongurami bietet wiederverwendbare Benutzeroberflächenkomponenten für Anwendungen. Die Komponenten sind in Ordnern organisiert und folgen einem separaten Stil-Muster. O componente-usage é uma biblioteca de componentes UI reutilizáveis para o app. Veja como utilizar e personalizar. Компонент-usage - это библиотека повторно используемых UI-компонентов для приложения. См. как использовать и настраивать. مكون-إستخدام هو مكتبة من المكونات القابلة لإعادة الاستخدام لتقديم واجهة المستخدم. انظر كيفية الإستخدام والتخصيص. how to use component-usage component-usage Dart library component-usage vs Flutter component-usage setup guide install component-usage what is component-usage component-usage alternative component-usage navigation component component-usage style pattern Dart组件库 UI组件重用 自定义样式 组件架构 样式分离模式 AI工具 Dart开发 Provides a structured folder structure for components in `lib/widgets/{component_name}/` Supports style separation pattern through `{component_name}_styles.dart` files Allows for custom styling using `MyComponentStyle.defaultStyle.copyWith` method Includes a navigation and layout component library Enables efficient reuse of UI components across the application component-usage is a reusable UI component library for the Donggurami app, providing a structured approach to building and styling applications with Dart.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('panaversity/agentfactory/quiz-generator', 'community', 'panaversity', 'agentfactory', 'panaversity/agentfactory', 'quiz-generator', 0, 0, 30, '2026-03-08T01:57:15.356Z', '2026-03-08T02:04:02.392Z', 'c7b96f9a2a1a24fde8642b8433ef261a46c6061fa2a2e786f55c468c19ec740b', '{"id":"panaversity/agentfactory/quiz-generator","name":"quiz-generator","description":{"en":"The quiz-generator skill creates digital FTEs that work 24/7, generating college-level conceptual quizzes that test understanding, not memorization. This skill benefits educators and domain experts in sales, legal, finance, and healthcare.","zh":"Quiz Generator 是一个使用 Python 脚本和 CLI 自动创建概念性测验的工具，帮助开发者生成全天候工作的数字化员工","ja":"Quiz Generator は、Python スクリプトと CLI を使用して概念理解の自動テストを作成するツールで、開発者が 24 時間体制のデジタルスタッフを生成するのに役立ちます","ko":"Quiz Generator는 Python 스크립트와 CLI를 사용하여 개념 이해 자동 평가를 생성하는 도구로, 개발자가 24시간 体制의 디지털 직원을 생성하도록 도와줍니다","es":"El generador de quizzes crea preguntas conceptuales para evaluar la comprensión, no la memorización, utilizando Python","fr":"Le générateur de quizzes crée des questions conceptuelles pour évaluer la compréhension, et non la mémorisation, en utilisant Python","de":"Der Quiz-Generator erstellt konzeptionelle Fragen, um das Verständnis zu bewerten, nicht die Memorierung, mit Python","pt":"O Gerador de Quiz é uma ferramenta de IA que cria testes conceituais de nível universitário com foco em aplicação, não memorização","ru":"Генератор Викторин - это инструмент ИИ, создающий концептуальные тесты университетского уровня с фокусом на применении, а не на запоминании","ar":"مولد الاختبارات هو أداة ذكاء اصطناعي لإنشاء اختبارات مفاهيمية على مستوى الجامعة مع التركيز على التطبيق لا الحفظ"},"seo":{"title":{"en":"Quiz Generator: Automated Quiz Creation for AI Agents | A...","zh":"Quiz Generator 设置指南 - 使用 Python 和 CLI 自动创建概念性测验","ja":"Quiz Generator 導入ガイド - Python と CLI を使用した概念理解の自動テスト","ko":"Quiz Generator 설정 가이드 - Python 및 CLI를 사용한 개념 이해 자동 평가","es":"Generador de Quizzes: Guía de Configuración con Python","fr":"Générateur de Quizzes: Guide d''Installation avec Python","de":"Quiz-Generator: Einrichtungsanleitung mit Python","pt":"Guia de Configuração do Gerador de Quiz - Ferramentas de IA","ru":"Настройка Генератора Викторин - ИИ Агенты","ar":"دليل إعداد مولد الاختبارات - أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to generate 50 comprehensive questions with the quiz-generator skill. Learn how to redistribute answers and validate option lengths with Python ...","zh":"使用 Quiz Generator 创建数字化的全天候工作人员，利用 Python 脚本和 CLI 自动生成概念性测验","ja":"Quiz Generator を使用して、Python スクリプトと CLI を使用した概念理解の自動テストで 24 時間体制のデジタルスタッフを作成","ko":"Quiz Generator를 사용하여 Python 스크립트와 CLI를 사용한 개념 이해 자동 평가로 24시간 体制의 디지털 직원을 생성","es":"Crea quizzes digitales con el generador de quizzes y aprende a configurarlos con Python para evaluar conceptos","fr":"Créez des quizzes numériques avec le générateur de quizzes et découvrez comment les configurer avec Python pour évaluer les concepts","de":"Erstellen Sie digitale Quizzes mit dem Quiz-Generator und lernen Sie, wie Sie sie mit Python konfigurieren, um Konzepte zu bewerten","pt":"Aprenda a configurar o Gerador de Quiz para criar testes conceituais de nível universitário com Python e scripts personalizados","ru":"Узнайте, как настроить Генератор Викторин для создания концептуальных тестов университетского уровня с помощью Python и индивидуальных скриптов","ar":"تعلم كيفية إعداد مولد الاختبارات لإنشاء اختبارات مفاهيمية على مستوى الجامعة باستخدام Python وبرامج نصية مخصصة"},"definition":{"en":"quiz-generator is a skill that generates autonomous AI agents for creating digital quizzes, focusing on conceptual questions and redistributed answers.","zh":"Quiz Generator 是一个使用 AI 技术创建概念性测验的工具，帮助开发者生成数字化的全天候工作人员","ja":"Quiz Generator は、AI エージェントを使用して概念理解の自動テストを作成するツール","ko":"Quiz Generator는 AI 도구를 사용하여 개념 이해 자동 평가를 생성하는 도구","es":"Un generador de quizzes es una herramienta de inteligencia artificial que crea preguntas conceptuales para evaluar la comprensión","fr":"Un générateur de quizzes est un outil d''intelligence artificielle qui crée des questions conceptuelles pour évaluer la compréhension","de":"Ein Quiz-Generator ist ein KI-Tool, das konzeptionelle Fragen erstellt, um das Verständnis zu bewerten","pt":"O que é Gerador de Quiz? Uma ferramenta de IA que gera testes conceituais de nível universitário","ru":"Что такое Генератор Викторин? Инструмент ИИ, генерирующий концептуальные тесты университетского уровня","ar":"ما هو مولد الاختبارات؟ أداة ذكاء اصطناعي لإنشاء اختبارات مفاهيمية على مستوى الجامعة"},"features":{"en":["Generates 50 questions for a chapter using conceptual apply levels","Redistributes answers evenly using Python scripts (redistribute_answers_v2.py)","Validates option lengths to ensure ±3 words per question","Manually counts words for all 50 questions","Creates comprehensive quizzes covering all chapter concepts"],"zh":["使用 Python 脚本生成概念性测验","自动重新分配答案以确保均衡","验证选项长度以确保一致性","支持 CLI 命令以便于自动化","生成全天候工作的数字化员工"],"ja":["Python スクリプトを使用して概念理解の自動テストを作成","自動的に回答を再分配してバランスを確保","選択肢の長さを検証して一貫性を確保","CLI コマンドをサポートして自動化を容易にする","24 時間体制のデジタルスタッフを生成"],"ko":["Python 스크립트를 사용하여 개념 이해 자동 평가를 생성","자동으로 답변을 재분배하여 균형을 확보","선택지 길이를 검증하여 일관성을 확보","CLI 명령어를 지원하여 자동화를 쉽게 함","24시간 体制의 디지털 직원을 생성"],"es":["Generación de 50 preguntas conceptuales con Python","Redistribución de respuestas con el script redistribute_answers_v2.py","Validación de longitudes de opciones con una tolerancia de ±3 palabras","Enfoque en preguntas de aplicación en lugar de recuerdo","Compatibilidad con la línea de comandos (CLI) para una configuración flexible"],"fr":["Génération de 50 questions conceptuelles avec Python","Redistribution de réponses avec le script redistribute_answers_v2.py","Validation de longueurs d''options avec une tolérance de ±3 mots","Accent sur les questions d''application plutôt que de rappel","Compatibilité avec la ligne de commande (CLI) pour une configuration flexible"],"de":["Erstellung von 50 konzeptionellen Fragen mit Python","Neuverteilung von Antworten mit dem Skript redistribute_answers_v2.py","Validierung von Optionenlängen mit einer Toleranz von ±3 Wörtern","Fokus auf Anwendungsfragen anstelle von Erinnerungsfragen","Kompatibilität mit der Kommandozeile (CLI) für eine flexible Konfiguration"],"pt":["Geração de 50 perguntas para capítulos","Redistribuição de respostas com Python","Validação de comprimento de opções","Foco em aplicação, não memorização","Uso de scripts personalizados","Compatibilidade com CLI"],"ru":["Генерация 50 вопросов для глав","Перераспределение ответов с помощью Python","Валидация длины вариантов","Фокус на применении, а не на запоминании","Использование индивидуальных скриптов","Совместимость с CLI"],"ar":["إنشاء 50 سؤالاً للفصول","إعادة توزيع الإجابات باستخدام Python","التحقق من طول الخيارات","التركيز على التطبيق لا الحفظ","استخدام برامج نصية مخصصة","التوافق مع CLI"]},"keywords":{"en":["how to use quiz-generator","what is quiz-generator","quiz-generator alternative","quiz-generator vs automated quiz tools","quiz-generator install","quiz-generator setup guide","python scripts for quiz generation","automated quiz creation for AI agents"],"zh":["Quiz Generator","AI 技术","Python 脚本","CLI 命令","概念性测验","数字化员工","全天候工作","自动化测试","AI エージェント"],"ja":["Quiz Generator","AI エージェント","Python スクリプト","CLI コマンド","概念理解の自動テスト","デジタルスタッフ","24 時間体制","自動化テスト","AI ツール"],"ko":["Quiz Generator","AI 도구","Python 스크립트","CLI 명령어","개념 이해 자동 평가","디지털 직원","24시간 体制","자동화 평가","AI 기술"],"es":["generador de quizzes","preguntas conceptuales","evaluación de la comprensión","Python","CLI","redistribución de respuestas","validación de longitudes de opciones","herramientas de inteligencia artificial","evaluación de la comprensión con AI"],"fr":["générateur de quizzes","questions conceptuelles","évaluation de la compréhension","Python","CLI","redistribution de réponses","validation de longueurs d''options","outils d''intelligence artificielle","évaluation de la compréhension avec l''IA"],"de":["Quiz-Generator","konzeptionelle Fragen","Bewertung des Verständnisses","Python","CLI","Neuverteilung von Antworten","Validierung von Optionenlängen","KI-Tools","Bewertung des Verständnisses mit KI"],"pt":["Gerador de Quiz","Ferramentas de IA","Testes conceituais","Python","Scripts personalizados","CLI","Desenvolvimento de testes","Educação universitária","Tecnologia de IA"],"ru":["Генератор Викторин","ИИ Агенты","Концептуальные тесты","Python","Индивидуальные скрипты","CLI","Разработка тестов","Университетское образование","Технология ИИ"],"ar":["مولد الاختبارات","أدوات الذكاء الاصطناعي","اختبارات مفاهيمية","Python","برامج نصية مخصصة","CLI","تطوير الاختبارات","التعليم الجامعي","تكنولوجيا الذكاء الاصطناعي"]}},"owner":"panaversity","repo":"agentfactory","repoPath":"panaversity/agentfactory","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.356Z","topics":[],"category":"community","skillMd":{"name":"quiz-generator","description":"Generate 50-question interactive quizzes using the Quiz component with randomized batching. Use when creating end-of-chapter assessments. Displays 15-20 questions per session with immediate feedback. NOT for static markdown quizzes.","bodyPreview":"# Quiz Generator\n\n## Quick Start\n\n```bash\n# 1. Generate 50 questions for chapter\n# Focus on conceptual (75%+ Apply level), not recall\n\n# 2. Redistribute answers evenly\npython scripts/redistribute_answers_v2.py quiz.md A\n\n# 3. Validate option lengths (±3 words per question)\n# Manually count words for ALL 50 questions\n```\n\n## Persona\n\nYou generate college-level conceptual quizzes that test understanding, not memorization. Your goal is 50 comprehensive questions covering all chapter concepts with i","body":"# Quiz Generator\n\n## Quick Start\n\n```bash\n# 1. Generate 50 questions for chapter\n# Focus on conceptual (75%+ Apply level), not recall\n\n# 2. Redistribute answers evenly\npython scripts/redistribute_answers_v2.py quiz.md A\n\n# 3. Validate option lengths (±3 words per question)\n# Manually count words for ALL 50 questions\n```\n\n## Persona\n\nYou generate college-level conceptual quizzes that test understanding, not memorization. Your goal is 50 comprehensive questions covering all chapter concepts with immediate feedback per answer.\n\n## Fixed Constraints\n\n```yaml\nquestion_count: 50  # Comprehensive bank\nquestions_per_batch: 15-20  # Displayed per session\noptions_per_question: 4  # Always exactly 4\ncorrect_answer_distribution: ~12-13 per index (0-3)\nfeedback_timing: immediate  # After each answer\npassing_score: NONE  # No threshold\nfile_naming: ##_chapter_##_quiz.md\n```\n\n## Analysis Questions\n\n### 1. Is this conceptual (not recall)?\n\n| Type | Example | Valid? |\n|------|---------|--------|\n| Recall | \"What is a Python list?\" | ❌ |\n| Conceptual | \"Which operation reveals a mutability issue?\" | ✅ |\n\n**Target**: 75%+ at Apply level or higher\n\n### 2. Are options equal length (±3 words)?\n\n| Options | Words | Valid? |\n|---------|-------|--------|\n| A: \"Yes\" / B: \"It processes async\" | 2 vs 4 | ✅ |\n| A: \"Yes\" / B: \"The framework processes requests asynchronously\" | 2 vs 6 | ❌ |\n\n**Rule**: ALL options within ±3 words to prevent pattern-guessing\n\n### 3. Are answers evenly distributed?\n\n| Index | Count | Valid? |\n|-------|-------|--------|\n| 0 | 12-13 | ✅ |\n| 1 | 12-13 | ✅ |\n| 2 | 12-13 | ✅ |\n| 3 | 12-13 | ✅ |\n\n**Rule**: No 3+ consecutive same index, no obvious patterns\n\n## Principles\n\n### Principle 1: 50 Questions Required\n\n- Comprehensive coverage (all chapter concepts)\n- Spaced repetition (different questions each retake)\n- Component shuffles and displays 15-20 per session\n\n### Principle 2: Immediate Feedback\n\nShow after EACH answer (not at end):\n- ✅ Correct option highlighted (green)\n- ❌ Why wrong (if incorrect)\n- Explanation (100-150 words)\n\n### Principle 3: Address All Options\n\nEvery explanation must cover:\n1. Why correct is correct (2-3 sentences)\n2. Why each distractor is wrong (1-2 sentences × 3)\n3. Real-world connection (1-2 sentences)\n\n### Principle 4: Source Attribution\n\n```javascript\nsource: \"Lesson 1: Understanding Mutability\"\n```\n\nLinks each question to specific lesson for review.\n\n## Quiz Component Format\n\n```markdown\n---\nsidebar_position: 5\ntitle: \"Chapter X: [Topic] Quiz\"\n---\n\n# Chapter X Quiz\n\nBrief intro (1-2 sentences).\n\n<Quiz\n  title=\"Chapter X Assessment\"\n  questions={[\n    {\n      question: \"Conceptual question here?\",\n      options: [\n        \"Option A (4-6 words)\",\n        \"Option B (4-6 words)\",\n        \"Option C (4-6 words) ← CORRECT\",\n        \"Option D (4-6 words)\"\n      ],\n      correctOption: 2,  // Index 0-3, NOT 1-4!\n      explanation: \"Why C is correct (2-3 sentences). Why A is wrong (1-2 sentences). Why B is wrong. Why D is wrong. Real-world connection.\",\n      source: \"Lesson 1: Topic Title\"\n    },\n    // ... 49 more questions (total: 50)\n  ]}\n  questionsPerBatch={18}\n/>\n```\n\n## Answer Redistribution\n\nLLMs struggle with even distribution. Use the script after generation:\n\n```bash\npython scripts/redistribute_answers_v2.py quiz.md A\n```\n\n**Sequences A-H** provide different distributions (~12-13 per index).\n\n**What it does**:\n1. Parses quiz questions\n2. Swaps option positions to match sequence\n3. Updates explanations to reference new positions\n4. Validates all explanations match correct answers\n\n## Option Length Validation (CRITICAL)\n\n**Problem**: Unequal lengths let students guess by picking longest/shortest.\n\n**Solution**: Manually count words for EVERY option in EVERY question.\n\n```\n✅ PASS: 4, 5, 4, 5 words (all within ±3)\n❌ FAIL: 2, 4, 11, 3 words (2 to 11 = 9-word spread)\n```\n\n**Also verify**:\n- Longest option correct in ~25% (not biased)\n- Shortest option correct in ~25% (not biased)\n\n## Common Pitfalls\n\n| Pitfall | Wrong | Right |\n|---------|-------|-------|\n| Question count | <50 questions | Exactly 50 |\n| Index values | `correctOption: 4` | `correctOption: 3` (0-3) |\n| Missing source | No source field | `source: \"Lesson N: Title\"` |\n| Passing score | `passingScore={70}` | No prop (removed) |\n| Recall questions | \"What is X?\" | \"Which reveals X issue?\" |\n| Weak explanations | Only explains correct | Addresses all 4 options |\n| Answer patterns | 0,1,2,3,0,1,2,3... | Random, ~12-13 per index |\n| Option lengths | 2 vs 11 words | All within ±3 words |\n\n## File Naming\n\n**Pattern**: `##_chapter_##_quiz.md`\n\n| Chapter | Lessons | Filename |\n|---------|---------|----------|\n| 2 | 4 | `05_chapter_02_quiz.md` |\n| 5 | 6 | `07_chapter_05_quiz.md` |\n| 14 | 5 | `06_chapter_14_quiz.md` |\n\n## Handoff Checklist\n\n**Content**:\n- [ ] 50 questions (not fewer)\n- [ ] 75%+ Apply level or higher\n- [ ] All major topics covered\n- [ ] No recall questions\n\n**Distribution**:\n- [ ] correctOption uses 0-3 (not 1-4)\n- [ ] ~12-13 per index\n- [ ] No 3+ consecutive same index\n\n**Option Lengths**:\n- [ ] ALL options counted (all 50 questions)\n- [ ] ALL within ±3 words\n- [ ] Longest not biased toward correct\n- [ ] Shortest not biased toward correct\n\n**Explanations**:\n- [ ] 100-150 words each\n- [ ] Explains why correct\n- [ ] Addresses each distractor\n- [ ] Real-world connection\n\n**Format**:\n- [ ] Valid JSX syntax\n- [ ] Exactly 4 options per question\n- [ ] `source` field on all 50\n- [ ] NO `passingScore` prop\n- [ ] File named correctly\n\n## If Verification Fails\n\n1. Run redistribution script: `python scripts/redistribute_answers_v2.py quiz.md A`\n2. Re-count option lengths manually\n3. Check explanation references match correctOption\n4. **Stop and report** if issues persist after 2 attempts\n"},"lastSynced":"2026-03-08T02:04:02.392Z","agentAnalysis":{"suitability":{"en":"Ideal for Educational Agents and Domain Experts needing automated college-level conceptual quiz generation with Python scripting capabilities.","zh":"适合需要使用Python脚本自动生成大学水平概念性测验的教育代理和领域专家。","ja":"Pythonスクリプトを使用して大学レベルの概念クイズを自動生成する必要がある教育エージェントとドメインエキスパートに最適です。","ko":"Python 스크립트를 사용하여 대학 수준의 개념 퀴즈를 자동 생성해야 하는 교육 에이전트와 도메인 전문가에게 적합합니다.","es":"Ideal para Agentes Educativos y Expertos en Dominio que necesitan generación automática de pruebas conceptuales de nivel universitario con capacidades de scripting en Python.","fr":"Idéal pour les agents éducatifs et les experts en domaine ayant besoin de génération automatisée de quiz conceptuels de niveau universitaire avec des capacités de scripting Python.","de":"Ideal für Bildungsagenten und Domänenexperten, die eine automatisierte Generierung von konzeptionellen Tests im College-Bereich mit Python-Skriptfunktionen benötigen.","pt":"Ideal para Agentes Educacionais e Especialistas em Domínio que necessitam de geração automática de quizzes conceituais de nível universitário com capacidades de script em Python.","ru":"Идеально подходит для образовательных агентов и экспертов в области, которым необходима автоматизированная генерация концептуальных викторин университетского уровня с возможностями скриптов на Python.","ar":"مثالي للوكلاء التعليميين وخبراء المجال الذين يحتاجون إلى توليد تلقائي لاختبارات مفاهيمية على مستوى الكلية مع إمكانيات البرمجة النصية بااستخدام Python."},"recommendation":{"en":"Empowers agents to generate comprehensive conceptual quizzes with 75%+ Apply level questions, utilizing Python scripts like redistribute_answers_v2.py for even answer redistribution and validating option lengths with ±3 words per question, ensuring in-depth understanding rather than mere memorization.","zh":"赋予代理生成全面概念测验的能力，75%以上的Apply级别问题，利用Python脚本（如redistribute_answers_v2.py）实现答案的均匀重新分配，并使用±3个词验证选项长度，确保深入理解而不是简单记忆。","ja":"エージェントが、75%以上のApplyレベルの質問を含む包括的な概念クイズを生成する能力を提供します。Pythonスクリプト（redistribute_answers_v2.pyなど）を使用して、答えを均等に再分配し、±3ワードでオプションの長さを検証して、単純な記憶ではなく深い理解を確保します。","ko":"에이전트가 75% 이상의 적용 수준 질문을 포함하는 포괄적인 개념 퀴즈를 생성할 수 있는 기능을 제공합니다. Python 스크립트(redistribute_answers_v2.py 등)를 사용하여 답변을 균등하게 재배포하고, ±3 단어로 옵션 길이를 검증하여 단순한 암기 대신 깊은 이해를 보장합니다.","es":"Habilita a los agentes a generar pruebas conceptuales comprehensivas con preguntas de nivel de aplicación del 75%+, utilizando scripts de Python como redistribute_answers_v2.py para una redistribución equitativa de las respuestas y validando longitudes de opciones con ±3 palabras por pregunta, garantizando una comprensión en profundidad en lugar de una mera memorización.","fr":"Permet aux agents de générer des quiz conceptuels complets avec des questions de niveau d''application de 75%+, en utilisant des scripts Python tels que redistribute_answers_v2.py pour une redistribution équitable des réponses et en validant les longueurs d''options avec ±3 mots par question, garantissant une compréhension approfondie plutôt qu''une simple mémorisation.","de":"Ermächtigt Agenten, umfassende konzeptionelle Tests mit Anwendungsfragen von 75%+ zu generieren, indem Python-Skripte wie redistribute_answers_v2.py für eine gleichmäßige Verteilung der Antworten und Validierung von Optionenlängen mit ±3 Wörtern pro Frage verwendet werden, um ein tiefes Verständnis anstelle der bloßen Memorierung sicherzustellen.","pt":"Habilita os agentes a gerar quizzes conceituais abrangentes com 75%+ de perguntas de nível de aplicação, utilizando scripts Python como redistribute_answers_v2.py para redistribuição uniforme de respostas e validação de comprimentos de opções com ±3 palavras por pergunta, garantindo uma compreensão aprofundada em vez de mera memorização.","ru":"Наделяет агентов возможностью генерировать всесторонние концептуальные викторины с 75%+ вопросами уровня применения, используя скрипты Python, такие как redistribute_answers_v2.py, для равномерного распределения ответов и проверки длины вариантов с ±3 словами на вопрос, обеспечивая глубокое понимание, а не простое запоминание.","ar":"يمكّن الوكلاء من توليد اختبارات مفاهيمية شاملة مع 75%+ من أسئلة مستوى التطبيق، باستخدام نصوص برمجة Python مثل redistribute_answers_v2.py لتحقيق توزيع متساوٍ للإجابات وتصديق أطوال الخيارات مع ±3 كلمات لكل سؤال، مما يضمن فهمًا عميقًا بدلاً من مجرد الحفظ."},"useCases":{"en":["Generating 50 comprehensive questions for chapter concepts","Redistributing answers evenly across quizzes using redistribute_answers_v2.py","Validating option lengths for all questions to ensure consistency"],"zh":["为章节概念生成50个综合问题","使用redistribute_answers_v2.py将答案均匀地重新分配到测验中","验证所有问题的选项长度以确保一致性"],"ja":["章の概念のための50の包括的な質問を生成する","redistribute_answers_v2.pyを使用して答えをクイズに均等に再分配する","すべての質問のオプションの長さを検証して一貫性を確保する"],"ko":["장의 개념을 위한 50개의 포괄적인 질문을 생성하는 것","redistribute_answers_v2.py를 사용하여 답변을 퀴즈에 균등하게 재배포하는 것","모든 질문의 옵션 길이를 검증하여 일관성을 보장하는 것"],"es":["Generar 50 preguntas comprehensivas para conceptos de capítulos","Redistribuir respuestas de forma equitativa en pruebas utilizando redistribute_answers_v2.py","Validar longitudes de opciones para todas las preguntas para garantizar la coherencia"],"fr":["Générer 50 questions complètes pour les concepts de chapitres","Redistribuer les réponses de manière équitable dans les quiz en utilisant redistribute_answers_v2.py","Valider les longueurs d''options pour toutes les questions pour assurer la cohérence"],"de":["Generieren von 50 umfassenden Fragen für Kapitelkonzepte","Wiederverteilung von Antworten in Quizzes unter Verwendung von redistribute_answers_v2.py","Validierung von Optionenlängen für alle Fragen, um Konsistenz sicherzustellen"],"pt":["Geração de 50 perguntas abrangentes para conceitos de capítulo","Redistribuição uniforme de respostas em quizzes usando redistribute_answers_v2.py","Validação de comprimentos de opções para todas as perguntas para garantir consistência"],"ru":["Генерация 50 всесторонних вопросов для концепций главы","Равномерное распределение ответов в викторинах с помощью redistribute_answers_v2.py","Проверка длины вариантов для всех вопросов для обеспечения согласованности"],"ar":["توليد 50 سؤالًا شاملاً لمفاهيم الفصل","إعادة توزيع الإجابات بالتساوي في الاختبارات باستخدام redistribute_answers_v2.py","تصديق أطوال الخيارات لجميع الأسئلة لضمان الاتساق"]},"limitations":{"en":["Requires Python environment for script execution","Manual word count needed for validating option lengths","Focus on conceptual questions may not suit all educational needs"],"zh":["需要Python环境来执行脚本","需要手动计算词数来验证选项长度","专注于概念性问题可能不适合所有教育需求"],"ja":["スクリプトの実行にはPython環境が必要","オプションの長さを検証するために手動でワード数を数える必要がある","概念的質問に焦点を当てているため、すべての教育ニーズに適さない可能性がある"],"ko":["스크립트 실행을 위해 Python 환경이 필요하다","옵션 길이를 검증하기 위해 수동으로 단어 수를 계산해야 한다","개념적 질문에 초점을 맞추고 있으므로 모든 교육需求에 적합하지 않을 수 있다"],"es":["Requiere entorno de Python para la ejecución de scripts","Se necesita un recuento manual de palabras para validar longitudes de opciones","El enfoque en preguntas conceptuales puede no ser adecuado para todas las necesidades educativas"],"fr":["Nécessite un environnement Python pour l''exécution de scripts","Un comptage manuel de mots est nécessaire pour valider les longueurs d''options","L''accent mis sur les questions conceptuelles peut ne pas convenir à tous les besoins éducatifs"],"de":["Benötigt eine Python-Umgebung für die Skriptausführung","Manuelle Wortzählung erforderlich für die Validierung von Optionenlängen","Die Konzentration auf konzeptionelle Fragen kann nicht allen Bildungsbedürfnissen entsprechen"],"pt":["Requer ambiente Python para execução de scripts","Contagem manual de palavras necessária para validação de comprimentos de opções","Foco em perguntas conceituais pode não atender a todas as necessidades educacionais"],"ru":["Требуется среда Python для выполнения скриптов","Необходим ручной подсчет слов для проверки длины вариантов","Фокус на концептуальных вопросах может не подходить для всех образовательных потребностей"],"ar":["يتطلب بيئة Python لتنفيذ البرامج النصية","تحتاج إلى حساب يدوي للكلمات لتصديق أطوال الخيارات","التركيز على الأسئلة المفهومية قد لا يلبي جميع الاحتياجات التعليمية"]},"version":4},"contentHash":"c7b96f9a2a1a24fde8642b8433ef261a46c6061fa2a2e786f55c468c19ec740b","qualityScore":30}');
