INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('panaversity/agentfactory/quiz-generator', 'quiz-generator', 'panaversity', 'agentfactory', 'community', 'quiz-generator panaversity agentfactory community The quiz-generator skill creates digital FTEs that work 24/7, generating college-level conceptual quizzes that test understanding, not memorization. This skill benefits educators and domain experts in sales, legal, finance, and healthcare. Quiz Generator 是一个使用 Python 脚本和 CLI 自动创建概念性测验的工具，帮助开发者生成全天候工作的数字化员工 Quiz Generator は、Python スクリプトと CLI を使用して概念理解の自動テストを作成するツールで、開発者が 24 時間体制のデジタルスタッフを生成するのに役立ちます Quiz Generator는 Python 스크립트와 CLI를 사용하여 개념 이해 자동 평가를 생성하는 도구로, 개발자가 24시간 体制의 디지털 직원을 생성하도록 도와줍니다 El generador de quizzes crea preguntas conceptuales para evaluar la comprensión, no la memorización, utilizando Python Le générateur de quizzes crée des questions conceptuelles pour évaluer la compréhension, et non la mémorisation, en utilisant Python Der Quiz-Generator erstellt konzeptionelle Fragen, um das Verständnis zu bewerten, nicht die Memorierung, mit Python O Gerador de Quiz é uma ferramenta de IA que cria testes conceituais de nível universitário com foco em aplicação, não memorização Генератор Викторин - это инструмент ИИ, создающий концептуальные тесты университетского уровня с фокусом на применении, а не на запоминании مولد الاختبارات هو أداة ذكاء اصطناعي لإنشاء اختبارات مفاهيمية على مستوى الجامعة مع التركيز على التطبيق لا الحفظ how to use quiz-generator what is quiz-generator quiz-generator alternative quiz-generator vs automated quiz tools quiz-generator install quiz-generator setup guide python scripts for quiz generation automated quiz creation for AI agents Quiz Generator AI 技术 Python 脚本 CLI 命令 概念性测验 数字化员工 全天候工作 自动化测试 AI エージェント Generates 50 questions for a chapter using conceptual apply levels Redistributes answers evenly using Python scripts (redistribute_answers_v2.py) Validates option lengths to ensure ±3 words per question Manually counts words for all 50 questions Creates comprehensive quizzes covering all chapter concepts quiz-generator is a skill that generates autonomous AI agents for creating digital quizzes, focusing on conceptual questions and redistributed answers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('neptaco/mcproc/release-preview', 'community', 'neptaco', 'mcproc', 'neptaco/mcproc', 'release-preview', 0, 0, 30, '2026-03-08T01:57:15.357Z', '2026-03-08T02:04:04.528Z', '450f1a11fd5d14a408974f5f7f6fff877a33db40ca993e1973cc3f9687aa3849', '{"id":"neptaco/mcproc/release-preview","name":"release-preview","description":{"en":"The release-preview skill is a Model Context Protocol (MCP) server that enables comfortable background process management on AI agents. It benefits developers by providing a preview of upcoming release changes.","zh":"release-preview是一种MCP服务器，用于舒适地管理AI代理的背景进程。它提供了当前状态确认、前回发布后的提交列表和CHANGELOG的Unreleased部分确认等功能","ja":"release-previewは、AIエージェントのバックグラウンドプロセスを快適に管理するためのMCPサーバーです。現在の状態の確認、前回リリースからのコミット一覧、CHANGELOGのUnreleasedセクションの確認などを提供します","ko":"release-preview는 AI 에이전트의 배경 프로세스를 편안하게 관리하기 위한 MCP 서버입니다. 현재 상태 확인, 이전 릴리스 이후의 커밋 목록 및 CHANGELOG의 Unreleased 섹션 확인 등을 제공합니다","es":"release-preview es un protocolo de servidor MCP para la gestión de procesos en segundo plano en AI Agentes. Permite la visualización de cambios antes de la próxima versión.","fr":"release-preview est un serveur de protocole MCP pour la gestion de processus en arrière-plan des Outils IA. Il permet de prévisualiser les modifications avant la prochaine version.","de":"release-preview ist ein MCP-Server-Protokoll für die Verwaltung von Hintergrundprozessen in AI-Tools. Es ermöglicht die Vorschau von Änderungen vor der nächsten Version.","pt":"O Release-Preview é um protocolo de gerenciamento de processos em segundo plano para ferramentas de IA, permitindo a visualização de alterações antes da release.","ru":"Release-Preview - это протокол управления фоновыми процессами для ИИ Агентов, позволяющий предварительно просматривать изменения перед релизом.","ar":"Release-Preview هو بروتوكول لإدارة العمليات الخلفية لأدوات الذكاء الاصطناعي، يسمح بمعاينة التغييرات قبل الإصدار."},"seo":{"title":{"en":"release-preview: Model Context Protocol Setup Guide | AI ...","zh":"release-preview 设置指南 - AI代理背景进程管理","ja":"release-preview セットアップガイド - AIエージェントのバックグラウンドプロセス管理","ko":"release-preview 설정 가이드 - AI 에이전트 배경 프로세스 관리","es":"Guía de configuración de release-preview para AI Agentes","fr":"Guide d''installation de release-preview pour les Outils IA","de":"Einrichtungsleitfaden für release-preview in AI-Tools","pt":"Guia de Configuração do Release-Preview para Ferramentas ...","ru":"Настройка Release-Preview для ИИ Агентов: Лучшие Практики","ar":"دليل إعداد Release-Preview لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to preview upcoming release changes with release-preview. Learn to manage background processes on AI agents with ease. Get started now!","zh":"了解release-preview的技术细节，掌握AI代理背景进程管理的最佳实践","ja":"release-previewの技術的詳細を学び、AIエージェントのバックグラウンドプロセス管理のベストプラクティスをマスターする","ko":"release-preview의 기술적 세부 사항을 알아보고 AI 에이전트 배경 프로세스 관리의最佳实践을 익히세요","es":"Aprende a configurar release-preview para gestionar procesos en segundo plano en AI Agentes de manera eficiente","fr":"Découvrez comment installer release-preview pour gérer les processus en arrière-plan des Outils IA de manière confortable","de":"Erfahren Sie, wie Sie release-preview für die komfortable Verwaltung von Hintergrundprozessen in AI-Tools einrichten","pt":"Aprenda a configurar o Release-Preview para gerenciar processos em segundo plano em ferramentas de IA de forma eficaz","ru":"Узнайте, как настроить Release-Preview для комфортного управления фоновыми процессами на ИИ Агентах","ar":"تعلم كيفية إعداد Release-Preview لإدارة العمليات الخلفية لأدوات الذكاء الاصطناعي بفعالية"},"definition":{"en":"release-preview is a Model Context Protocol (MCP) server for managing background processes on AI agents, allowing developers to preview upcoming release changes.","zh":"release-preview是一种用于AI代理背景进程管理的MCP服务器","ja":"release-previewは、AIエージェントのバックグラウンドプロセス管理に使用されるMCPサーバーです","ko":"release-preview는 AI 에이전트의 배경 프로세스 관리를 위한 MCP 서버입니다","es":"release-preview es un protocolo que permite la gestión de procesos en segundo plano en AI Agentes","fr":"release-preview est un protocole qui permet la gestion de processus en arrière-plan des Outils IA","de":"release-preview ist ein Protokoll, das die Verwaltung von Hintergrundprozessen in AI-Tools ermöglicht","pt":"O que é Release-Preview? Um protocolo de gerenciamento de processos em segundo plano para ferramentas de IA.","ru":"Что такое Release-Preview? Протокол управления фоновыми процессами для ИИ Агентов.","ar":"ما هو Release-Preview؟ بروتوكول لإدارة العمليات الخلفية لأدوات الذكاء الاصطناعي."},"features":{"en":["Executes git commands to confirm current repository state","Retrieves commit history since the last release using git log","Verifies the presence of an Unreleased section in CHANGELOG.md","Runs git describe to identify the latest tag","Utilizes git status to check for any pending changes","Supports both tagged and untagged repository states"],"zh":["当前状态确认","前回发布后的提交列表","CHANGELOG的Unreleased部分确认","Git命令集成","CLI界面"],"ja":["現在の状態の確認","前回リリースからのコミット一覧","CHANGELOGのUnreleasedセクションの確認","Gitコマンドの統合","CLIインターフェース"],"ko":["현재 상태 확인","이전 릴리스 이후의 커밋 목록","CHANGELOG의 Unreleased 섹션 확인","Git 명령어 통합","CLI 인터페이스"],"es":["Gestión de procesos en segundo plano","Visualización de cambios antes de la próxima versión","Uso de git para la gestión de versiones","Compatibilidad con CLI","Verificación de estado de los cambios","Generación de registros de cambios"],"fr":["Gestion de processus en arrière-plan","Prévisualisation des modifications avant la prochaine version","Utilisation de git pour la gestion de versions","Compatibilité avec CLI","Vérification de l''état des modifications","Génération de journaux de modifications"],"de":["Verwaltung von Hintergrundprozessen","Vorschau von Änderungen vor der nächsten Version","Verwendung von git für die Versionsverwaltung","Kompatibilität mit CLI","Überprüfung des Status der Änderungen","Erstellung von Änderungsprotokollen"],"pt":["Gerenciamento de processos em segundo plano","Visualização de alterações antes da release","Uso de comandos Git para verificar o status do repositório","Verificação da seção Unreleased do CHANGELOG","Suporte à pré-visualização de commits"],"ru":["Управление фоновыми процессами","Просмотр изменений перед релизом","Использование команд Git для проверки статуса репозитория","Проверка раздела Unreleased в CHANGELOG","Поддержка предварительного просмотра коммитов"],"ar":["إدارة العمليات الخلفية","معاينة التغييرات قبل الإصدار","استخدام أوامر Git لتحقق من حالة المستودع","فحص قسم الإصدارات الغير منشورة في CHANGELOG","دعم معاينة الإلتزامات"]},"keywords":{"en":["how to use release-preview","release-preview setup guide","Model Context Protocol server","git log tutorial","CHANGELOG.md management","release-preview alternative","release-preview vs MCP","install release-preview","release-preview for AI agents"],"zh":["release-preview","AI代理","背景进程管理","MCP服务器","Git命令","CLI界面","AI工具","AI开发"],"ja":["release-preview","AIエージェント","バックグラウンドプロセス管理","MCPサーバー","Gitコマンド","CLIインターフェース","AIツール","AI開発"],"ko":["release-preview","AI 에이전트","배경 프로세스 관리","MCP 서버","Git 명령어","CLI 인터페이스","AI 도구","AI 개발"],"es":["release-preview","AI Agentes","gestión de procesos en segundo plano","git","CLI","visualización de cambios","próxima versión","protocolo MCP","servidor MCP"],"fr":["release-preview","Outils IA","gestion de processus en arrière-plan","git","CLI","prévisualisation des modifications","prochaine version","protocole MCP","serveur MCP"],"de":["release-preview","AI-Tools","Verwaltung von Hintergrundprozessen","git","CLI","Vorschau von Änderungen","nächste Version","MCP-Protokoll","MCP-Server"],"pt":["Release-Preview","Ferramentas de IA","Gerenciamento de processos em segundo plano","Visualização de alterações","Comandos Git","CHANGELOG","Pré-visualização de commits"],"ru":["Release-Preview","ИИ Агенты","Управление фоновыми процессами","Просмотр изменений","Команды Git","CHANGELOG","Предварительный просмотр коммитов"],"ar":["Release-Preview","أدوات الذكاء الاصطناعي","إدارة العمليات الخلفية","معاينة التغييرات","أوامر Git","CHANGELOG","معاينة الإلتزامات"]}},"owner":"neptaco","repo":"mcproc","repoPath":"neptaco/mcproc","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.357Z","topics":[],"category":"community","skillMd":{"name":"release-preview","description":"次回リリースに含まれる変更をプレビューする。「リリースプレビュー」「次のリリース」「リリース内容確認」と言われた場合に使用する。","bodyPreview":"# リリースプレビュー\n\n次回リリースに含まれる変更をプレビューします。\n\n## 実行手順\n\n以下のコマンドを順番に実行してください：\n\n### 1. 現在の状態確認\n\n```bash\ngit describe --tags --abbrev=0 2>/dev/null || echo \"タグなし\"\ngit branch --show-current\ngit status --short\n```\n\n### 2. 前回リリースからのコミット一覧\n\n最新タグがある場合：\n```bash\ngit log --oneline --no-merges $(git describe --tags --abbrev=0)..HEAD\n```\n\nタグがない場合：\n```bash\ngit log --oneline --no-merges -20\n```\n\n### 3. CHANGELOG の Unreleased セクション確認\n\nCHANGELOG.md の先頭部分を確認し、Unreleased セクションがあるか確認：\n\n```bash\nhead -50 CHANGELOG.md\n```\n\n###","body":"# リリースプレビュー\n\n次回リリースに含まれる変更をプレビューします。\n\n## 実行手順\n\n以下のコマンドを順番に実行してください：\n\n### 1. 現在の状態確認\n\n```bash\ngit describe --tags --abbrev=0 2>/dev/null || echo \"タグなし\"\ngit branch --show-current\ngit status --short\n```\n\n### 2. 前回リリースからのコミット一覧\n\n最新タグがある場合：\n```bash\ngit log --oneline --no-merges $(git describe --tags --abbrev=0)..HEAD\n```\n\nタグがない場合：\n```bash\ngit log --oneline --no-merges -20\n```\n\n### 3. CHANGELOG の Unreleased セクション確認\n\nCHANGELOG.md の先頭部分を確認し、Unreleased セクションがあるか確認：\n\n```bash\nhead -50 CHANGELOG.md\n```\n\n### 4. 変更の分類\n\nコミット一覧から以下を分類して報告：\n\n**リリースノートに含まれるもの：**\n- `feat:` 新機能\n- `fix:` バグ修正\n- `BREAKING CHANGE:` 破壊的変更\n\n**リリースノートに含まれないもの：**\n- `docs:`, `test:`, `chore:`, `ci:`, `build:`, `refactor:`, `style:`, `perf:`\n\n### 5. 推奨バージョンの提示\n\n| 変更タイプ | 次のバージョン |\n|-----------|---------------|\n| BREAKING CHANGE あり | メジャーアップ（例: v1.x.x → v2.0.0） |\n| feat: あり | マイナーアップ（例: v1.0.x → v1.1.0） |\n| fix: のみ | パッチアップ（例: v1.0.0 → v1.0.1） |\n\n### 6. 品質チェック\n\n```bash\ncargo fmt -- --check && cargo clippy --all-targets -- -D warnings && cargo test\n```\n\n## 次のステップ\n\nリリースを実行する場合：\n\n```bash\n/release v<VERSION>\n```\n"},"lastSynced":"2026-03-08T02:04:04.528Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined release management and preview capabilities.","zh":"非常适合需要简化发布管理和预览功能的开发代理。","ja":"開発エージェントがリリース管理とプレビュー機能をストリームライン化する必要がある場合に最適です。","ko":"개발 에이전트가 출시 관리와 미리 보기 기능을 간소화하는 데 필요한 경우에 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una gestión de lanzamientos optimizada y capacidades de vista previa.","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de version optimisée et de fonctionnalités d''aperçu.","de":"Perfekt für Entwicklungsmittel, die eine optimierte Veröffentlichungsverwaltung und Vorschau-Funktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de lançamento simplificado e capacidades de pré-visualização.","ru":"Идеально подходит для агентов разработки, которым необходим упрощенный менеджмент релизов и возможности предварительного просмотра.","ar":"مثالي للوكلاء التطوير الذين يحتاجون إلى إدارة الإصدارات المبسطة وقدرات العرض الأولي."},"recommendation":{"en":"Empowers agents to manage background processes and preview upcoming release changes using Git commands and Model Context Protocol (MCP) servers, providing insights into CHANGELOG.md and commit history.","zh":"赋予代理管理后台进程和预览即将发布的更改的能力，使用 Git 命令和 Model Context Protocol (MCP) 服务器，提供对 CHANGELOG.md 和提交历史的见解。","ja":"エージェントがバックグラウンドプロセスと次のリリース変更をプレビューする能力を与え、Git コマンドと Model Context Protocol (MCP) サーバーを使用し、CHANGELOG.md とコミット履歴に関する洞察を提供します。","ko":"에이전트가 백그라운드 프로세스와 다음 릴리즈의 변경 사항을 미리 보는 기능을 제공하며, Git 명령과 Model Context Protocol (MCP) 서버를 사용하여 CHANGELOG.md 및 커밋 기록에 대한 통찰력을 제공합니다.","es":"Habilita a los agentes a gestionar procesos en segundo plano y a previsualizar los cambios de la próxima versión utilizando comandos Git y servidores de Protocolo de Contexto de Modelo (MCP), proporcionando información sobre CHANGELOG.md y el historial de confirmaciones.","fr":"Permet aux agents de gérer les processus en arrière-plan et d''apercevoir les modifications de la prochaine version en utilisant des commandes Git et des serveurs de Protocole de Contexte de Modèle (MCP), fournissant des informations sur CHANGELOG.md et l''historique des validations.","de":"Ermöglicht es den Agenten, Hintergrundprozesse zu verwalten und Änderungen der nächsten Veröffentlichung mithilfe von Git-Befehlen und Modell-Kontext-Protokoll (MCP)-Servern vorab zu betrachten, wodurch Einblicke in CHANGELOG.md und die Commit-Historie gewährt werden.","pt":"Habilita os agentes a gerenciar processos em segundo plano e pré-visualizar as alterações de lançamento futuras usando comandos Git e servidores do Protocolo de Contexto do Modelo (MCP), fornecendo informações sobre CHANGELOG.md e histórico de commits.","ru":"Наделяет агентов возможностью управлять фоновыми процессами и предварительно просматривать предстоящие изменения релиза с помощью команд Git и серверов Протокола контекста модели (MCP), обеспечивая информацию о CHANGELOG.md и истории коммитов.","ar":"تمكين الوكلاء من إدارة العمليات الخلفية و معاينة التغييرات القادمة للإصدار باستخدام أوامر Git وخادم بروتوكول سياق النموذج (MCP) ، مما يوفر معلومات حول CHANGELOG.md وتاريخ الإلتزامات."},"useCases":{"en":["Automating release note generation","Debugging pre-release changes","Validating commit history since last release"],"zh":["自动化发布说明生成","调试预发布更改","验证自上次发布以来提交历史"],"ja":["リリースノートの自動生成","プレビュー変更のデバッグ","最後のリリース以降のコミット履歴の検証"],"ko":["릴리즈 노트 자동 생성","프리 릴리즈 변경 사항 디버깅","마지막 릴리즈 이후 커밋 기록 검증"],"es":["Automatización de la generación de notas de lanzamiento","Depuración de cambios previos al lanzamiento","Validación del historial de confirmaciones desde el último lanzamiento"],"fr":["Automatisation de la génération de notes de version","Débogage des modifications préalables à la version","Validation de l''historique des validations depuis la dernière version"],"de":["Automatisierung der Generierung von Veröffentlichungshinweisen","Fehlerbehebung von Änderungen vor der Veröffentlichung","Überprüfung der Commit-Historie seit der letzten Veröffentlichung"],"pt":["Automatizar a geração de notas de lançamento","Depurar alterações de pré-lançamento","Validar histórico de commits desde o último lançamento"],"ru":["Автоматизировать генерацию заметок о релизе","Отладить изменения до релиза","Проверить историю коммитов с момента последнего релиза"],"ar":["تأتمتة إنشاء ملاحظات الإصدار","تصحيح الأخطاء في التغييرات قبل الإصدار","التحقق من تاريخ الإلتزامات منذ آخر إصدار"]},"limitations":{"en":["Requires Git installation and configuration","Limited to repositories with CHANGELOG.md files"],"zh":["需要 Git 安装和配置","仅限于具有 CHANGELOG.md 文件的存储库"],"ja":["Git のインストールと設定が必要","CHANGELOG.md ファイルを持つリポジトリに限定"],"ko":["Git 설치 및 구성이 필요","CHANGELOG.md 파일을 가진 저장소에만 제한"],"es":["Requiere instalación y configuración de Git","Limitado a repositorios con archivos CHANGELOG.md"],"fr":["Nécessite l''installation et la configuration de Git","Limité aux référentiels avec des fichiers CHANGELOG.md"],"de":["Benötigt Git-Installation und -Konfiguration","Begrenzt auf Repositorys mit CHANGELOG.md-Dateien"],"pt":["Requer instalação e configuração do Git","Limitado a repositórios com arquivos CHANGELOG.md"],"ru":["Требует установки и конфигурации Git","Ограничен репозиториями с файлами CHANGELOG.md"],"ar":["يتطلب تثبيت وتكوين Git","محدود بالمخازن التي تحتوي على ملفات CHANGELOG.md"]},"version":4},"contentHash":"450f1a11fd5d14a408974f5f7f6fff877a33db40ca993e1973cc3f9687aa3849","qualityScore":30}');
