INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('neptaco/mcproc/release-preview', 'release-preview', 'neptaco', 'mcproc', 'community', 'release-preview neptaco mcproc community The release-preview skill is a Model Context Protocol (MCP) server that enables comfortable background process management on AI agents. It benefits developers by providing a preview of upcoming release changes. release-preview是一种MCP服务器，用于舒适地管理AI代理的背景进程。它提供了当前状态确认、前回发布后的提交列表和CHANGELOG的Unreleased部分确认等功能 release-previewは、AIエージェントのバックグラウンドプロセスを快適に管理するためのMCPサーバーです。現在の状態の確認、前回リリースからのコミット一覧、CHANGELOGのUnreleasedセクションの確認などを提供します release-preview는 AI 에이전트의 배경 프로세스를 편안하게 관리하기 위한 MCP 서버입니다. 현재 상태 확인, 이전 릴리스 이후의 커밋 목록 및 CHANGELOG의 Unreleased 섹션 확인 등을 제공합니다 release-preview es un protocolo de servidor MCP para la gestión de procesos en segundo plano en AI Agentes. Permite la visualización de cambios antes de la próxima versión. release-preview est un serveur de protocole MCP pour la gestion de processus en arrière-plan des Outils IA. Il permet de prévisualiser les modifications avant la prochaine version. release-preview ist ein MCP-Server-Protokoll für die Verwaltung von Hintergrundprozessen in AI-Tools. Es ermöglicht die Vorschau von Änderungen vor der nächsten Version. O Release-Preview é um protocolo de gerenciamento de processos em segundo plano para ferramentas de IA, permitindo a visualização de alterações antes da release. Release-Preview - это протокол управления фоновыми процессами для ИИ Агентов, позволяющий предварительно просматривать изменения перед релизом. Release-Preview هو بروتوكول لإدارة العمليات الخلفية لأدوات الذكاء الاصطناعي، يسمح بمعاينة التغييرات قبل الإصدار. how to use release-preview release-preview setup guide Model Context Protocol server git log tutorial CHANGELOG.md management release-preview alternative release-preview vs MCP install release-preview release-preview for AI agents release-preview AI代理 背景进程管理 MCP服务器 Git命令 CLI界面 AI工具 AI开发 Executes git commands to confirm current repository state Retrieves commit history since the last release using git log Verifies the presence of an Unreleased section in CHANGELOG.md Runs git describe to identify the latest tag Utilizes git status to check for any pending changes Supports both tagged and untagged repository states release-preview is a Model Context Protocol (MCP) server for managing background processes on AI agents, allowing developers to preview upcoming release changes.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dralgorhythm/claude-agentic-framework/writing-prds', 'community', 'dralgorhythm', 'claude-agentic-framework', 'dralgorhythm/claude-agentic-framework', 'writing-prds', 0, 0, 30, '2026-03-08T01:57:15.357Z', '2026-03-08T02:04:04.729Z', 'e3fdcd7c2059cf66fe81d4eb21474feadc32dcf039da420576dfab1975ce1831', '{"id":"dralgorhythm/claude-agentic-framework/writing-prds","name":"writing-prds","description":{"en":"writing-prds is a skill that helps AI agents create effective Product Requirements Documents (PRDs). It benefits developers and product managers by streamlining the product development process.","zh":"Writing PRDs是一种AI工具，帮助开发者创建产品需求文档，包括定义目标、识别利益相关者、编写用户故事和详细要求","ja":"Writing PRDsは、AIエージェントを使用して製品要件文書を作成するためのツールです。目標の定義、ステークホルダーの特定、ユーザーストーリーの作成、要件の詳細化などを含みます","ko":"Writing PRDs는 AI 에이전트를 사용하여 제품 요구 사항 문서를 생성하는 도구입니다. 목표 정의, 이해 관계자 식별, 사용자 스토리 작성 및 요구 사항 세부화 등","es":"Nuestro agente de IA para escribir PRDs te ayuda a definir metas y capturar necesidades de usuario de manera efectiva.","fr":"Notre outil d''IA pour rédiger des PRDs vous aide à définir des objectifs et à capturer les besoins des utilisateurs de manière efficace.","de":"Unser KI-Agent für das Schreiben von PRDs hilft Ihnen, Ziele zu definieren und Benutzeranforderungen effektiv zu erfassen.","pt":"O writing-prds é uma habilidade que melhora o agente Claude, permitindo que os desenvolvedores escrevam PRDs eficazes.","ru":"Writing-prds - это навык, который улучшает агента ИИ Агенты Claude, позволяя разработчикам писать эффективные PRD.","ar":"كتابة مواصفات المنتج هي مهارة تحسن وظيفة وكيل كلود، مما يسمح للمطورين بكتابة مواصفات المنتج بشكل فعال."},"seo":{"title":{"en":"writing-prds: PRD Setup Guide for AI Agents","zh":"AI工具Writing PRDs最佳实践指南","ja":"AIエージェントのWriting PRDsセットアップガイド","ko":"AI 에이전트 Writing PRDs 설정 가이드","es":"Guía de configuración para escribir PRDs con Agentes de IA","fr":"Guide de mise en place pour rédiger des PRDs avec des Out...","de":"Einrichtungsleitfaden für das Schreiben von PRDs mit KI-A...","pt":"Guia de Configuração para writing-prds: Melhorias no Agen...","ru":"Руководство по настройке writing-prds: Улучшение агента И...","ar":"دليل الإعداد لكتابة مواصفات المنتج: تحسين وظيفة كلود الإل..."},"description":{"en":"Unlock efficient product development with writing-prds. Learn how to define goals, identify stakeholders, and draft user stories with this AI agent skill. Ge...","zh":"了解Writing PRDs的技术细节，包括定义目标、识别利益相关者、编写用户故事和详细要求","ja":"Writing PRDsの技術的側面を学び、目標の定義、ステークホルダーの特定、ユーザーストーリーの作成、要件の詳細化について理解する","ko":"Writing PRDs의 기술적 세부 정보를 알아보세요. 목표 정의, 이해 관계자 식별, 사용자 스토리 작성 및 요구 사항 세부화 등","es":"Aprende a escribir PRDs efectivos con nuestro agente de IA. Descubre cómo definir metas, identificar partes interesadas y capturar necesidades de usuario.","fr":"Apprenez à rédiger des PRDs efficaces avec notre outil d''IA. Découvrez comment définir des objectifs, identifier les parties prenantes et capturer les besoin...","de":"Erfahren Sie, wie Sie mit unserem KI-Agenten effektive PRDs schreiben. Entdecken Sie, wie Sie Ziele definieren, Interessengruppen identifizieren und Benutzer...","pt":"Aprenda a escrever PRDs eficazes com o agente Claude. Descubra como definir metas, identificar partes interessadas e capturar histórias de usuário.","ru":"Узнайте, как писать эффективные PRD с помощью агента ИИ Агенты Claude. Откройте для себя, как определять цели, идентифицировать заинтересованные стороны и捕ыв...","ar":"تعرف على كيفية كتابة مواصفات المنتج بشكل فعال مع وكيل كلود. اكتشف كيف تحدد الأهداف وتحدد الأطراف المعنية والقصص المستخدمة."},"definition":{"en":"writing-prds is a technical skill that enables AI agents to generate PRDs by defining goals, identifying stakeholders, and detailing requirements.","zh":"Writing PRDs是一种AI工具，用于创建产品需求文档","ja":"Writing PRDsは、製品要件文書を作成するためのAIエージェントです","ko":"Writing PRDs는 제품 요구 사항 문서를 생성하기 위한 AI 에이전트입니다","es":"Un PRD es un documento que describe los requisitos y objetivos de un proyecto, utilizado por nuestro agente de IA para guiar el desarrollo.","fr":"Un PRD est un document qui décrit les exigences et les objectifs d''un projet, utilisé par notre outil d''IA pour guider le développement.","de":"Ein PRD ist ein Dokument, das die Anforderungen und Ziele eines Projekts beschreibt, verwendet von unserem KI-Agenten, um die Entwicklung zu leiten.","pt":"O writing-prds é uma habilidade que define metas, identifica partes interessadas e captura histórias de usuário para criar PRDs eficazes.","ru":"Writing-prds - это навык, который определяет цели, идентифицирует заинтересованные стороны и捕ывает истории пользователей для создания эффективных PRD.","ar":"كتابة مواصفات المنتج هي مهارة تحدد الأهداف وتحدد الأطراف المعنية والقصص المستخدمة لإنشاء مواصفات المنتج الفعالة."},"features":{"en":["Defines business goals and success metrics","Identifies and lists all relevant stakeholders","Drafts user stories to capture user needs","Details functional and non-functional requirements","Saves PRD artifacts to ./artifacts/prd_[feature].md","Conducts stakeholder review for feedback"],"zh":["定义目标和成功指标","识别利益相关者","编写用户故事","详细要求","保存文档到./artifacts/prd_[feature].md","进行利益相关者审查"],"ja":["目標と成功指標の定義","ステークホルダーの特定","ユーザーストーリーの作成","要件の詳細化","文書を./artifacts/prd_[feature].mdに保存","ステークホルダーのレビュー"],"ko":["목표와 성공 지표 정의","이해 관계자 식별","사용자 스토리 작성","요구 사항 세부화","문서를 ./artifacts/prd_[feature].md에 저장","이해 관계자 리뷰"],"es":["Definir metas y métricas de éxito","Identificar partes interesadas y capturar necesidades de usuario","Crear historias de usuario y requisitos funcionales y no funcionales","Guardar artefactos en formato Markdown","Revisar y refinar el PRD con stakeholders"],"fr":["Définir des objectifs et des métriques de succès","Identifier les parties prenantes et capturer les besoins des utilisateurs","Créer des histoires d''utilisateur et des exigences fonctionnelles et non fonctionnelles","Enregistrer des artefacts au format Markdown","Réviser et affiner le PRD avec les parties prenantes"],"de":["Ziele und Erfolgsmetriken definieren","Interessengruppen identifizieren und Benutzeranforderungen erfassen","Benutzerstories und funktionale sowie nicht-funktionale Anforderungen erstellen","Artefakte im Markdown-Format speichern","PRD mit Interessengruppen überprüfen und verfeinern"],"pt":["Definição de metas e métricas de sucesso","Identificação de partes interessadas","Criação de histórias de usuário","Detalhamento de requisitos funcionais e não funcionais","Salvar artefatos em ./artifacts/prd_[feature].md","Revisão com partes interessadas"],"ru":["Определение целей и метрик успеха","Идентификация заинтересованных сторон","Создание историй пользователей","Детализация функциональных и нефункциональных требований","Сохранение артефактов в ./artifacts/prd_[feature].md","Проверка с заинтересованными сторонами"],"ar":["تحديد الأهداف ومقاييس النجاح","تحديد الأطراف المعنية","إنشاء قصص المستخدمين","التفصيل المتطلبات الوظيفية وغير الوظيفية","حفظ الملفات في ./artifacts/prd_[feature].md","استعراض مع الأطراف المعنية"]},"keywords":{"en":["how to use writing-prds","writing-prds tutorial","what is writing-prds","writing-prds alternative","writing-prds vs product canvas","writing-prds setup guide","writing-prds install","PRD template for AI agents","AI agent skills for product development"],"zh":["AI工具","Writing PRDs","产品需求文档","定义目标","识别利益相关者","编写用户故事","详细要求","AIエージェント","製品要件文書"],"ja":["AIエージェント","Writing PRDs","製品要件文書","目標の定義","ステークホルダーの特定","ユーザーストーリーの作成","要件の詳細化","AIツール","製品開発"],"ko":["AI 에이전트","Writing PRDs","제품 요구 사항 문서","목표 정의","이해 관계자 식별","사용자 스토리 작성","요구 사항 세부화","AI 도구","제품 개발"],"es":["escribir PRDs","agentes de IA","desarrollo de software","metas y métricas de éxito","historias de usuario","requisitos funcionales y no funcionales","guía de configuración para PRDs"],"fr":["rédiger des PRDs","outils d''IA","développement de logiciels","objectifs et métriques de succès","histoires d''utilisateur","exigences fonctionnelles et non fonctionnelles","guide de mise en place pour PRDs"],"de":["PRDs schreiben","KI-Agents","Software-Entwicklung","Ziele und Erfolgsmetriken","Benutzerstories","funktionale und nicht-funktionale Anforderungen","Einrichtungsleitfaden für PRDs"],"pt":["writing-prds","PRD","agente Claude","desenvolvimento de software","metas e métricas de sucesso","histórias de usuário","requisitos funcionais e não funcionais","artefatos de desenvolvimento"],"ru":["writing-prds","PRD","агент ИИ Агенты Claude","разработка программного обеспечения","цели и метрики успеха","истории пользователей","функциональные и нефункциональные требования","артефакты разработки"],"ar":["كتابة مواصفات المنتج","PRD","وكيل كلود","تطوير البرمجيات","الأهداف ومقاييس النجاح","قصص المستخدمين","المتطلبات الوظيفية وغير الوظيفية","ملفات التطوير"]}},"owner":"dralgorhythm","repo":"claude-agentic-framework","repoPath":"dralgorhythm/claude-agentic-framework","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.357Z","topics":[],"category":"community","skillMd":{"name":"writing-prds","description":"Create Product Requirements Documents. Use when defining new features, projects, or initiatives. Covers user stories, acceptance criteria, and scope definition.","bodyPreview":"# Writing PRDs\n\n## Workflows\n\n- [ ] **Define Goals**: Articulate business goals and success metrics\n- [ ] **Identify Stakeholders**: List all relevant stakeholders\n- [ ] **Draft User Stories**: Capture user needs\n- [ ] **Detail Requirements**: List functional and non-functional requirements\n- [ ] **Save Artifact**: Save to `./artifacts/prd_[feature].md`\n- [ ] **Review**: Conduct stakeholder review\n\n## PRD Structure\n\n1. **Overview**: What and why\n2. **Goals & Success Metrics**: How we measure suc","body":"# Writing PRDs\n\n## Workflows\n\n- [ ] **Define Goals**: Articulate business goals and success metrics\n- [ ] **Identify Stakeholders**: List all relevant stakeholders\n- [ ] **Draft User Stories**: Capture user needs\n- [ ] **Detail Requirements**: List functional and non-functional requirements\n- [ ] **Save Artifact**: Save to `./artifacts/prd_[feature].md`\n- [ ] **Review**: Conduct stakeholder review\n\n## PRD Structure\n\n1. **Overview**: What and why\n2. **Goals & Success Metrics**: How we measure success\n3. **User Stories**: Who benefits and how\n4. **Requirements**: What must be built\n5. **Out of Scope**: What we''re NOT building\n6. **Timeline**: Key milestones\n\n## User Story Format\n\n```\nAs a [role],\nI want [feature],\nSo that [benefit].\n```\n\n### Example\n```\nAs a registered user,\nI want to reset my password via email,\nSo that I can regain access to my account if I forget it.\n```\n\n## Acceptance Criteria\n\nUse Given/When/Then format:\n\n```\nGiven I am on the login page\nWhen I click \"Forgot Password\"\nThen I see a form to enter my email\n\nGiven I enter a valid registered email\nWhen I submit the form\nThen I receive a password reset email within 5 minutes\n```\n\n## INVEST Criteria\n\nGood user stories are:\n- **I**ndependent: Can be developed separately\n- **N**egotiable: Details can be discussed\n- **V**aluable: Delivers user value\n- **E**stimable: Can be sized\n- **S**mall: Fits in a sprint\n- **T**estable: Has clear acceptance criteria\n\n## Resources\n\n- [PRD Template](./resources/prd.template.md)\n"},"lastSynced":"2026-03-08T02:04:04.729Z","agentAnalysis":{"suitability":{"en":"Perfect for Product Management Agents needing structured documentation capabilities.","zh":"非常适合需要结构化文档功能的产品管理代理。","ja":"構造化ドキュメント機能を必要とする製品管理エージェントに最適です。","ko":"구조화된 문서 기능이 필요한 제품 관리 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Gestión de Productos que necesitan capacidades de documentación estructurada.","fr":"Parfait pour les agents de gestion de produits ayant besoin de capacités de documentation structurée.","de":"Perfekt für Produktmanagement-Agenten, die strukturierte Dokumentationsfunktionen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Produtos que precisam de capacidades de documentação estruturada.","ru":"Идеально подходит для агентов по управлению продуктом, которым необходимы возможности структурированной документации.","ar":"مثالي لعميل إدارة المنتج الذين يحتاجون إلى إمكانيات توثيقية منظمة."},"recommendation":{"en":"Enables automated generation of comprehensive Product Requirements Documents with standardized structures including goals, stakeholder mapping, user stories, and success metrics. Outputs directly to markdown files in `./artifacts/` directory for immediate integration into development workflows.","zh":"能够自动生成具有标准化结构的综合产品需求文档，包括目标、利益相关者映射、用户故事和成功指标。输出直接到 `./artifacts/` 目录中的 markdown 文件，以便立即集成到开发工作流中。","ja":"目標、ステークホルダー・マッピング、ユーザー・ストーリー、成功メトリックを含む標準化された構造を持つ包括的な製品要件文書の自動生成を可能にします。`./artifacts/` ディレクトリ内の markdown ファイルに出力し、開発ワークフローに即座に統合できます。","ko":"표준화된 구조를 갖춘 포괄적인 제품 요구 사항 문서의 자동 생성을 가능하게 하며, 목표, 이해 관계자 매핑, 사용자 스토리 및 성공 지표를 포함합니다. `./artifacts/` 디렉토리内の markdown 파일로 직접 출력되어 개발 워크플로에 즉시 통합될 수 있습니다.","es":"Permite la generación automática de documentos de requisitos de producto completos con estructuras estandarizadas que incluyen objetivos, mapeo de partes interesadas, historias de usuario y métricas de éxito. Salida directa a archivos markdown en el directorio `./artifacts/` para integración inmediata en flujos de trabajo de desarrollo.","fr":"Permet la génération automatisée de documents de spécifications de produit complets avec des structures standardisées comprenant des objectifs, une cartographie des parties prenantes, des histoires utilisateur et des métriques de succès. Sortie directe dans des fichiers markdown dans le répertoire `./artifacts/` pour une intégration immédiate dans les flux de travail de développement.","de":"Ermöglicht die automatisierte Generierung umfassender Produktanforderungsdokumente mit standardisierten Strukturen, einschließlich Ziele, Stakeholder-Mapping, User Stories und Erfolgsmetrik. Ausgabe direkt in Markdown-Dateien im Verzeichnis `./artifacts/` für die sofortige Integration in Entwicklungswerkflüsse.","pt":"Permite a geração automatizada de Documentos de Requisitos de Produto abrangentes com estruturas padronizadas, incluindo metas, mapeamento de partes interessadas, histórias de usuário e métricas de sucesso. Saídas diretamente para arquivos markdown no diretório `./artifacts/` para integração imediata em fluxos de trabalho de desenvolvimento.","ru":"Позволяет автоматически генерировать всесторонние документы требований к продукту со стандартизированными структурами, включая цели, картографирование заинтересованных сторон, истории пользователей и метрики успеха. Выходные данные напрямую в файлы markdown в директории `./artifacts/` для немедленной интеграции в рабочие процессы разработки.","ar":"يمكنه توليد自动ي لوثائق متطلبات المنتج الشاملة الهيكلية مع هياكل معيارية بما في ذلك الأهداف وتصوير أصحاب المصلحة وقصص المستخدمين ومقاييس النجاح. الإخراج مباشرة إلى ملفات markdown في دليل `./artifacts/` من أجل الاندماج الفوري في سير عمل التطوير."},"useCases":{"en":["Automating PRD creation for new feature proposals","Generating stakeholder review-ready documentation","Structuring user requirements into actionable development tasks","Creating standardized artifact files for version control"],"zh":["自动创建新功能提案的 PRD","生成利益相关者审查准备就绪的文档","将用户需求结构化为可执行的开发任务","为版本控制创建标准化的文物文件"],"ja":["新機能提案の PRD を自動生成する","ステークホルダーによるレビュー用のドキュメントを生成する","ユーザー要求を実行可能な開発タスクに構造化する","バージョン管理用の標準化されたアーティファクト・ファイルを作成する"],"ko":["새로운 기능 제안을 위한 PRD 자동 생성","이해 관계자 리뷰 준비 문서 생성","사용자 요구 사항을 실행 가능한 개발 작업으로 구조화","버전 제어를 위한 표준화된 아티팩트 파일 생성"],"es":["Automatización de la creación de PRD para propuestas de nuevas características","Generación de documentación lista para revisión de partes interesadas","Estructuración de requisitos de usuario en tareas de desarrollo realizables","Creación de archivos de artefactos estandarizados para control de versiones"],"fr":["Automatisation de la création de PRD pour les propositions de nouvelles fonctionnalités","Génération de documentation prête pour la révision des parties prenantes","Structuration des exigences utilisateur en tâches de développement réalisables","Création de fichiers d''artefacts standardisés pour le contrôle de version"],"de":["Automatisierung der Erstellung von PRD für Vorschläge neuer Funktionen","Generierung von dokumentationsbereiter Überprüfung durch Stakeholder","Strukturierung von Benutzeranforderungen in umsetzbare Entwicklungsaufgaben","Erstellung standardisierter Artefaktdateien für Versionskontrolle"],"pt":["Automatizar a criação de PRD para novas propostas de recursos","Gerar documentação pronta para revisão por partes interessadas","Estruturar requisitos de usuário em tarefas de desenvolvimento ações","Criar arquivos de artefatos padronizados para controle de versão"],"ru":["Автоматизировать создание PRD для новых предложений функций","Генерировать документацию, готовую для рассмотрения заинтересованными сторонами","Структурировать требования пользователей в действия по разработке","Создавать стандартизированные файлы артефактов для контроля версий"],"ar":["أتمتة إنشاء PRD لطرح ميزات جديدة","توليد توثيق جاهز لاستعراض أصحاب المصلحة","هيكلة متطلبات المستخدم في مهام تطوير قابلة للتنفيذ","إنشاء ملفات هيكلية معيارية للتحكم في الإصدارات"]},"limitations":{"en":["Requires filesystem access for artifact saving","Needs stakeholder input for review completion","Limited to markdown output format"],"zh":["需要文件系统访问以保存文物","需要利益相关者输入以完成审查","仅限 markdown 输出格式"],"ja":["アーティファクトを保存するためにファイル・システム・アクセスが必要","レビューを完了するためにステークホルダーの入力が必要","出力形式は markdown に限定される"],"ko":["아티팩트를 저장하기 위해 파일 시스템 액세스가 필요함","검토를 완료하기 위해 이해 관계자의 입력이 필요함","출력 형식은 markdown으로 제한됨"],"es":["Requiere acceso al sistema de archivos para guardar artefactos","Necesita entrada de partes interesadas para completar la revisión","Limitado al formato de salida markdown"],"fr":["Nécessite un accès au système de fichiers pour enregistrer les artefacts","Nécessite une entrée des parties prenantes pour terminer la révision","Limité au format de sortie markdown"],"de":["Benötigt Dateisystemzugriff zum Speichern von Artefakten","Benötigt Eingabe von Stakeholdern zur Vervollständigung der Überprüfung","Begrenzt auf Markdown-Ausgabeformat"],"pt":["Requer acesso ao sistema de arquivos para salvar artefatos","Necessita de entrada de partes interessadas para completar a revisão","Limitado ao formato de saída markdown"],"ru":["Требует доступа к файловой системе для сохранения артефактов","Требует ввода заинтересованных сторон для завершения рассмотрения","Ограничен форматом вывода markdown"],"ar":["يتطلب الوصول إلى نظام الملفات لحفظ الهيكليات","يحتاج إلى إدخال أصحاب المصلحة لإكمال الاستعراض","محدود بتنسيق الإخراج markdown"]},"version":4},"contentHash":"e3fdcd7c2059cf66fe81d4eb21474feadc32dcf039da420576dfab1975ce1831","qualityScore":30}');
