INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dralgorhythm/claude-agentic-framework/writing-prds', 'writing-prds', 'dralgorhythm', 'claude-agentic-framework', 'community', 'writing-prds dralgorhythm claude-agentic-framework community writing-prds is a skill that helps AI agents create effective Product Requirements Documents (PRDs). It benefits developers and product managers by streamlining the product development process. Writing PRDs是一种AI工具，帮助开发者创建产品需求文档，包括定义目标、识别利益相关者、编写用户故事和详细要求 Writing PRDsは、AIエージェントを使用して製品要件文書を作成するためのツールです。目標の定義、ステークホルダーの特定、ユーザーストーリーの作成、要件の詳細化などを含みます Writing PRDs는 AI 에이전트를 사용하여 제품 요구 사항 문서를 생성하는 도구입니다. 목표 정의, 이해 관계자 식별, 사용자 스토리 작성 및 요구 사항 세부화 등 Nuestro agente de IA para escribir PRDs te ayuda a definir metas y capturar necesidades de usuario de manera efectiva. Notre outil d''IA pour rédiger des PRDs vous aide à définir des objectifs et à capturer les besoins des utilisateurs de manière efficace. Unser KI-Agent für das Schreiben von PRDs hilft Ihnen, Ziele zu definieren und Benutzeranforderungen effektiv zu erfassen. O writing-prds é uma habilidade que melhora o agente Claude, permitindo que os desenvolvedores escrevam PRDs eficazes. Writing-prds - это навык, который улучшает агента ИИ Агенты Claude, позволяя разработчикам писать эффективные PRD. كتابة مواصفات المنتج هي مهارة تحسن وظيفة وكيل كلود، مما يسمح للمطورين بكتابة مواصفات المنتج بشكل فعال. how to use writing-prds writing-prds tutorial what is writing-prds writing-prds alternative writing-prds vs product canvas writing-prds setup guide writing-prds install PRD template for AI agents AI agent skills for product development AI工具 Writing PRDs 产品需求文档 定义目标 识别利益相关者 编写用户故事 详细要求 AIエージェント 製品要件文書 Defines business goals and success metrics Identifies and lists all relevant stakeholders Drafts user stories to capture user needs Details functional and non-functional requirements Saves PRD artifacts to ./artifacts/prd_[feature].md Conducts stakeholder review for feedback writing-prds is a technical skill that enables AI agents to generate PRDs by defining goals, identifying stakeholders, and detailing requirements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AUD-DEV-TEAM/i-AUD-Developer-Kit/iaud-formula', 'community', 'AUD-DEV-TEAM', 'i-AUD-Developer-Kit', 'AUD-DEV-TEAM/i-AUD-Developer-Kit', 'iaud-formula', 0, 0, 30, '2026-03-08T01:57:15.359Z', '2026-03-08T02:04:09.404Z', '0797b4e15f30839d8d93766513da515c3673d33db5dc84565c5c9bb90adbb931', '{"id":"AUD-DEV-TEAM/i-AUD-Developer-Kit/iaud-formula","name":"iaud-formula","description":{"en":"The iaud-formula skill enables developers to automate calculations within their applications, leveraging controls like text boxes, labels, and data grids. It benefits developers seeking to simplify complex computations","zh":"i-AUD公式是一种自动计算系统，允许开发者在文本框、标签和数据网格中设置公式，实现自动计算和数据关联","ja":"i-AUD Formulaは自動計算システムであり、開発者がテキストボックス、ラベル、データグリッドに数式を設定して自動計算とデータの関連付けを実現できる","ko":"i-AUD 계산수식은 자동 연산 시스템으로 개발자가 텍스트박스, 라벨, 데이터그리드에 수식을 설정하여 자동 연산과 데이터 연동을 구현할 수 있다","es":"La fórmula iaud es un sistema de cálculo automático que permite referenciar controles y variables globales. Aprende a utilizarla en tus proyectos de desarrollo","fr":"La formule iaud est un système de calcul automatisé qui permet de référencer des contrôles et des variables globales. Apprenez à l''utiliser dans vos projets de développement","de":"Die iaud-Formel ist ein System für die automatische Berechnung, das das Referenzieren von Steuerelementen und globalen Variablen ermöglicht. Erfahren Sie, wie Sie sie in Ihren Entwicklungsprojekten verwenden","pt":"A fórmula i-AUD é um sistema de automação de cálculos para controles como caixas de texto e grades de dados. Aprenda a configurá-la.","ru":"Формула i-AUD - система автоматических расчетов для контролов, таких как текстовые поля и таблицы данных. Узнайте, как ее настроить.","ar":"صيغة i-AUD هي نظام للطورين لحسابات السيطرة مثل صناديق النص والقوائم. تعلم كيفية إعدادها."},"seo":{"title":{"en":"iaud-formula: Automated Calculation Setup Guide | AI Agen...","zh":"i-AUD公式设置指南 - 自动计算系统","ja":"i-AUD Formula セットアップガイド - 自動計算システム","ko":"i-AUD 계산수식 작성 가이드 - 자동 연산 시스템","es":"Guía de configuración de iaud-formula para desarrolladores","fr":"Guide de mise en place de la formule iaud pour les dévelo...","de":"Setup-Leitfaden für iaud-Formel für Entwickler","pt":"Guia de Configuração i-AUD Formula para Desenvolvedores","ru":"ИИ Агенты: Настройка i-AUD Formula для Автоматических Рас...","ar":"دليل إعداد صيغة i-AUD للطورين: أدوات ذكاء اصطناعي"},"description":{"en":"Discover how to harness iaud-formula for effortless calculations. Learn to set up and master this AI agent skill for streamlined development","zh":"了解i-AUD公式的基本语法和功能，实现自动计算和数据关联，提升开发效率","ja":"i-AUD Formulaの基本的な文法と機能を学び、自動計算とデータの関連付けを実現して開発効率を向上させる","ko":"i-AUD 계산수식의 기본 문법과 기능을 익히고 자동 연산과 데이터 연동을 구현하여 개발 효율을 높여라","es":"Aprende a utilizar la fórmula iaud para automatizar cálculos en tus aplicaciones. Descubre cómo referenciar controles y variables globales","fr":"Découvrez comment utiliser la formule iaud pour automatiser les calculs dans vos applications. Apprenez à référencer des contrôles et des variables globales","de":"Erfahren Sie, wie Sie die iaud-Formel verwenden, um Berechnungen in Ihren Anwendungen zu automatisieren. Entdecken Sie, wie Sie Steuerelemente und globale Va...","pt":"Aprenda a configurar a fórmula i-AUD para automação de cálculos em seus projetos de desenvolvimento. Guia prático para devs.","ru":"Узнайте, как настроить формулу i-AUD для автоматических расчетов в ваших проектах. Практическое руководство для разработчиков.","ar":"تعلم كيفية إعداد صيغة i-AUD للطورين لتأتمتة الحسابات في مشاريع التطوير. دليل عملي للطورين."},"definition":{"en":"iaud-formula is a developer kit that allows for the creation of automated calculations using formulas, enabling references to controls, global parameters, and data grid fields","zh":"i-AUD公式是一种自动计算系统，用于实现数据关联和自动计算","ja":"i-AUD Formulaは自動計算システムであり、データの関連付けと自動計算を実現する","ko":"i-AUD 계산수식은 자동 연산 시스템으로 데이터 연동과 자동 연산을 구현한다","es":"La fórmula iaud es un sistema de cálculo que permite automatizar operaciones aritméticas y lógicas en aplicaciones","fr":"La formule iaud est un système de calcul qui permet d''automatiser des opérations arithmétiques et logiques dans des applications","de":"Die iaud-Formel ist ein Berechnungssystem, das die Automatisierung arithmetischer und logischer Operationen in Anwendungen ermöglicht","pt":"A fórmula i-AUD é um sistema de automação de cálculos que permite referenciar controles e variáveis globais.","ru":"Формула i-AUD - это система автоматических расчетов, которая позволяет ссылаться на контролы и глобальные переменные.","ar":"صيغة i-AUD هي نظام للطورين للحسابات التي تمكن من الإشارة إلى السيطرة والمتغيرات العالمية."},"features":{"en":["Supports control references using `:컨트롤명` syntax","Enables global parameter and variable references via `:전역변수명`","Allows data grid field value references with `[필드명]` syntax","Automatically recalculates values when referenced controls change","Utilizes basic arithmetic operators like `+` for addition and string concatenation"],"zh":["支持在文本框、标签和数据网格中设置公式","自动计算和数据关联","支持使用`:控制名`、`:全局变量名`和`[字段名]`进行数据引用","支持基本的算术运算符，如`+`、`-`、`*`、`/`","支持在数据网格中使用公式"],"ja":["テキストボックス、ラベル、データグリッドに数式を設定することができる","自動計算とデータの関連付け","`:コントロール名`、`:グローバル変数名`、`[フィールド名]`を使用したデータ参照をサポート","基本的な算術演算子、例えば`+`、`-`、`*`、`/`をサポート","データグリッド内で数式を使用することができる"],"ko":["텍스트박스, 라벨, 데이터그리드에 수식을 설정할 수 있다","自动 연산과 데이터 연동","`:컨트롤명`、`:전역변수명`、`[필드명]`을 사용한 데이터 참조를 지원","기본적인 산술 연산자, 예를 들어 `+`、`-`、`*`、`/`를 지원","데이터그리드 내에서 수식을 사용할 수 있다"],"es":["Referencia a controles y variables globales","Cálculo automático de valores","Uso de operadores aritméticos y lógicos","Compatibilidad con datos en cuadrícula","Referencia a campos de cuadrícula","Uso de la sintaxis `:control` y `:variable`"],"fr":["Référence à des contrôles et des variables globales","Calcul automatisé de valeurs","Utilisation d''opérateurs arithmétiques et logiques","Compatibilité avec des données en grille","Référence à des champs de grille","Utilisation de la syntaxe `:contrôle` et `:variable`"],"de":["Referenzierung von Steuerelementen und globalen Variablen","Automatische Berechnung von Werten","Verwendung arithmetischer und logischer Operatoren","Kompatibilität mit Daten in Tabellen","Referenzierung von Tabellenfeldern","Verwendung der Syntax `:Steuerelement` und `:Variable`"],"pt":["Referência a controles como caixas de texto e grades de dados","Suporte a variáveis globais e parâmetros","Operadores aritméticos e lógicos para cálculos complexos","Automação de cálculos em tempo real","Integração com controles de formulário"],"ru":["Ссылка на контролы, такие как текстовые поля и таблицы данных","Поддержка глобальных переменных и параметров","Арифметические и логические операторы для сложных расчетов","Автоматические расчеты в реальном времени","Интеграция с контролами формы"],"ar":["الإشارة إلى السيطرة مثل صناديق النص والقوائم","دعم المتغيرات العالمية والمعاملات","عوامل حسابية وموجة للطورين المعقدة","التأتمتة للحسابات في الوقت الفعلي","التكامل مع سيطرة الاستمارة"]},"keywords":{"en":["how to use iaud-formula","iaud-formula setup guide","iaud-formula alternative","automated calculation in iaud-formula","iaud-formula vs competitor","iaud-formula install","what is iaud-formula","iaud-formula documentation","iaud-formula tutorial"],"zh":["i-AUD公式","自动计算系统","数据关联","公式设置","开发效率","AI工具","AIエージェント","自动计算"],"ja":["i-AUD Formula","自動計算システム","データの関連付け","数式の設定","開発効率","AIエージェント","AIツール","自動計算"],"ko":["i-AUD 계산수식","자동 연산 시스템","데이터 연동","수식 설정","개발 효율","AI 에이전트","AI 도구","자동 연산"],"es":["iaud formula","cálculo automático","referencia a controles","variables globales","desarrollo de aplicaciones","automatización de tareas","operadores aritméticos","operadores lógicos","datos en cuadrícula"],"fr":["formule iaud","calcul automatisé","référence à des contrôles","variables globales","développement d''applications","automatisation de tâches","opérateurs arithmétiques","opérateurs logiques","données en grille"],"de":["iaud-formel","automatische berechnung","referenzierung von steuerelementen","globale variablen","anwendungsentwicklung","automatisierung von aufgaben","arithmetische operatoren","logische operatoren","daten in tabellen"],"pt":["i-AUD formula","automação de cálculos","controles de formulário","variáveis globais","parâmetros","operadores aritméticos","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ИИ Агенты","формула i-AUD","автоматические расчеты","контроли формы","глобальные переменные","параметры","арифметические операторы","разработка программного обеспечения","инструменты разработки"],"ar":["أدوات ذكاء اصطناعي","صيغة i-AUD","التأتمتة للحسابات","سيطرة الاستمارة","المتغيرات العالمية","المعاملات","عوامل حسابية","تطوير البرمجيات","أدوات التطوير"]}},"owner":"AUD-DEV-TEAM","repo":"i-AUD-Developer-Kit","repoPath":"AUD-DEV-TEAM/i-AUD-Developer-Kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.359Z","topics":[],"category":"community","skillMd":{"name":"iaud-formula","description":"i-AUD 계산수식(Formula) 작성 가이드. 텍스트박스, 라벨, 데이터그리드 등 컨트롤에 수식을 설정하여 값을 자동 연산하는 방법을 안내합니다. 계산수식, 수식 설정, SUMIF, 컨트롤 참조, 그리드 수식, JavaScript 수식 등을 물어볼 때 사용하세요.","bodyPreview":"# i-AUD Formula (계산수식) 작성 가이드\n\ni-AUD 계산수식(FormulaManager)은 텍스트박스, 라벨, 데이터그리드 등의 컨트롤에 수식을 설정하여 값을 자동 연산하는 시스템이다.\n수식 내 다른 컨트롤을 참조하면 해당 컨트롤의 값 변경 시 자동으로 재연산된다.\n\n---\n\n## 수식 기본 문법\n\n### 컨트롤 참조\n- **`:컨트롤명`** - 다른 컨트롤의 값을 참조\n- **`:전역변수명`** - 전역 파라미터(GlobalParam) 또는 Variable 참조\n- **`[필드명]`** - 데이터그리드 내 필드(컬럼) 값 참조 (그리드 수식에서만 사용)\n\n```\n// 텍스트박스 txtPrice의 값 참조\n:txtPrice\n\n// 전역변수 gYear 참조\n:gYear\n\n// 그리드 필드 참조 (그리드 수식 내)\n[PRICE] * [QTY]\n```\n\n### 연산자\n| 연산자 | 설명 | 예시 |\n|--------|------|------|\n| `+` | 덧셈 / 문자열","body":"# i-AUD Formula (계산수식) 작성 가이드\n\ni-AUD 계산수식(FormulaManager)은 텍스트박스, 라벨, 데이터그리드 등의 컨트롤에 수식을 설정하여 값을 자동 연산하는 시스템이다.\n수식 내 다른 컨트롤을 참조하면 해당 컨트롤의 값 변경 시 자동으로 재연산된다.\n\n---\n\n## 수식 기본 문법\n\n### 컨트롤 참조\n- **`:컨트롤명`** - 다른 컨트롤의 값을 참조\n- **`:전역변수명`** - 전역 파라미터(GlobalParam) 또는 Variable 참조\n- **`[필드명]`** - 데이터그리드 내 필드(컬럼) 값 참조 (그리드 수식에서만 사용)\n\n```\n// 텍스트박스 txtPrice의 값 참조\n:txtPrice\n\n// 전역변수 gYear 참조\n:gYear\n\n// 그리드 필드 참조 (그리드 수식 내)\n[PRICE] * [QTY]\n```\n\n### 연산자\n| 연산자 | 설명 | 예시 |\n|--------|------|------|\n| `+` | 덧셈 / 문자열 연결 | `:txtA + :txtB` |\n| `-` | 뺄셈 | `[PRICE] - [DISCOUNT]` |\n| `*` | 곱셈 | `[PRICE] * [QTY]` |\n| `/` | 나눗셈 | `[TOTAL] / [COUNT]` |\n| `%` | 나머지 | `[VALUE] % 2` |\n| `^` | 거듭제곱 | `[BASE] ^ 2` |\n| `=` | 비교(==) | `[STATUS] = \"Y\"` |\n| `!=` | 불일치 | `[STATUS] != \"N\"` |\n| `>` `<` `>=` `<=` | 비교 | `[AMT] > 1000` |\n| `!` | 논리 NOT | `![FLAG]` |\n| `&&` / `AND` | 논리 AND (연산자) | `[A] > 0 && [B] > 0` |\n| `‖` / `OR` | 논리 OR (연산자) | `[A] = 1 ‖ [B] = 1` |\n\n> **참고:** 수식 모드에서 단일 `=`는 비교(`==`)로 처리된다. JavaScript 모드(`return`, `var`, `{}`가 포함된 경우)에서는 대입(`=`)으로 처리된다.\n\n### 주석\n```\n// 한 줄 주석\n/* 여러 줄\n   주석 */\n```\n\n### JavaScript 모드\n수식에 `return`, `var`, `{`, `}` 키워드가 포함되면 JavaScript 모드로 동작한다.\n```\nvar result = [PRICE] * [QTY];\nif (result > 10000) {\n    return result * 0.9;\n} else {\n    return result;\n}\n```\n\n---\n\n## 그리드 전용 키워드\n\n| 키워드 | 설명 |\n|--------|------|\n| `CELL_VALUE` | 현재 셀의 기존 값 (데이터 셀의 집계 값) |\n| `FIELD_LABEL` | 현재 컬럼의 Caption (데이터 필드의 표시명) |\n| `FIELD_KEY` | 현재 컬럼의 Name (데이터 필드의 키값) |\n| `IS_GRAND_TOTAL` | 현재 행이 총합계 행인지 여부 (boolean) |\n| `IS_SUB_TOTAL` | 현재 행이 소계 행인지 여부 (boolean) |\n\n```\n// 총합계 행에서만 다른 계산 적용\nIIF(IS_GRAND_TOTAL, [TOTAL_AMT], [PRICE] * [QTY])\n```\n\n---\n\n## 함수 레퍼런스\n\n### 조건/논리 함수\n\n#### IIF(condition, trueValue, falseValue)\n> `bool IF(bool condition, object trueValue, object falseValue)`\n\n조건 검사를 수행하여 참이면 trueValue를 반환하고, 거짓이면 falseValue를 반환한다.\n- `IF()`로도 사용 가능 (내부에서 `IIF`로 변환됨)\n```\nIIF([STATUS] = \"Y\", \"활성\", \"비활성\")\nIIF(:txtAge > 20, \"성인\", \"미성년\")\n```\n\n#### CASE(condition1, value1, condition2, value2, ..., defaultValue)\n> `object Switch(bool condition1, object value1, bool condition2, object value2, ..., object elseValue)`\n\n조건 n개에 대해 순차적으로 검사하여 가장 처음으로 참인 조건의 값을 반환한다.\n모든 조건이 거짓일 경우 마지막 default 값이 반환된다.\n인자가 홀수 개이면 마지막 값이 기본값이다.\n- `SWITCH()`와 동일하게 동작한다.\n```\nCASE(\n    [GRADE] = \"A\", 100,\n    [GRADE] = \"B\", 80,\n    [GRADE] = \"C\", 60,\n    0\n)\n```\n\n#### AND(condition1, condition2, ...)\n> `bool AND(bool condition1, bool condition2, ...)`\n\n넘겨진 파라미터 n개의 논리곱을 반환한다. 모든 조건이 참이면 `true`를 반환한다.\n```\nAND([AMT] > 0, [QTY] > 0)\n```\n\n#### OR(condition1, condition2, ...)\n> `bool OR(bool condition1, bool condition2, ...)`\n\n넘겨진 파라미터 n개의 논리합을 반환한다. 하나라도 참이면 `true`를 반환한다.\n```\nOR([STATUS] = \"A\", [STATUS] = \"B\")\n```\n\n---\n\n### 타입 변환 함수\n\n#### TOSTRING(value, format?)\n> `string ToString(object value, [string format])`\n\n넘겨진 값을 문자열로 변환한다. format은 수치형 포맷 및 일자형 포맷을 사용할 수 있으며, 생략 가능하다.\n```\nTOSTRING(123456789, \"#,##0\")          // \"123,456,789\"\nTOSTRING(12345, \"{0:N2}\")             // \"12,345.00\"\nTOSTRING(0.15, \"{0:P1}\")              // \"15.0%\"\nTOSTRING(NOW(), \"{0:yyyy-MM-dd}\")     // \"2025-01-15\"\n```\n\n**format 종류:**\n| 포맷 | 설명 | 예시 |\n|-------|------|------|\n| `{0:N숫자}` | 숫자(천 단위 콤마, 소수점) | `{0:N2}` -> `1,234.56` |\n| `{0:P숫자}` | 백분율 | `{0:P1}` -> `15.0%` |\n| `{0:E숫자}` | 지수표현 | `{0:E2}` -> `1.23E45` |\n| `{0:C숫자}` | 화폐 | `{0:C0}` -> `1,235` |\n| `{0:#,###}` | 사용자 정의 숫자 | `{0:#,###.00}` |\n| `#,##0` | 사용자 정의 숫자 (중괄호 없이) | `#,##0` -> `123,456,789` |\n| `{0:yyyy-MM-dd}` | 날짜 | `{0:yyyy-MM-dd}` -> `2025-01-15` |\n\n#### TONUMBER(value, defaultValue)\n> `double ToNumber(object value, double defaultValue)`\n\nvalue를 숫자형으로 변환한 값을 반환한다. 수치 형변환 실패 시 defaultValue를 반환한다.\n```\nTONUMBER(\"123\", 0)        // 123\nTONUMBER(\"abc\", -1)       // -1\nTONUMBER([QTY], 0)        // 필드값을 숫자로 변환\n```\n\n#### TODATE(value, format?)\n> `DateTime ToDate(object value, [string format])`\n\n넘겨진 값을 일자형으로 변환한다. format은 일자형 포맷으로 생략 가능하다. format 미지정 시 `yyyy-MM-dd` 형식이다.\n```\nTODATE(\"20250115\", \"{0:yyyy-MM-dd}\")   // \"2025-01-15\"\nTODATE(\"20250115\", \"{0:yyyy/MM/dd}\")   // \"2025/01/15\"\nTODATE(TODAY(), \"yyyy-MM-dd\")          // \"2025-01-15\"\n```\n\n---\n\n### 타입 체크 함수\n\n| 함수 | 설명 | 반환 |\n|------|------|------|\n| `ISNULL(value)` | 검사 대상 값이 null 값인지 여부를 반환 | boolean |\n| `ISBOOL(value)` | 검사 대상 값이 Boolean인지 여부를 반환 | boolean |\n| `ISNUMBER(value)` | 검사 대상 값이 숫자로 치환 가능한지 여부를 반환 | boolean |\n| `ISSTRING(value)` | 검사 대상 값의 타입이 문자열인지 여부를 반환 | boolean |\n| `ISDATETIME(value)` | 검사 대상 값의 타입이 일자형(DateTime)인지 여부를 반환 | boolean |\n\n```\nIIF(ISNULL([PRICE]), 0, [PRICE] * [QTY])\n```\n\n---\n\n### 집계 함수 (Aggregate)\n\n집계 함수는 데이터그리드의 데이터를 기반으로 연산한다. `:그리드컨트롤명`으로 그리드를 참조한다.\n\n#### SUMIF(grid, fieldName, condition?)\n> `double SUMIF(:Gridname, \"Fieldname\", \"criteria\")`\n\n지정한 Grid에서 조건에 맞는 Field 데이터의 합을 구한다.\n```\nSUMIF(:DataGrid1, \"AMT\")                                    // AMT 필드 전체 합계\nSUMIF(:DataGrid1, \"AMT\", \"[DEPT] = ''영업부''\")                // 영업부만 합계\nSUMIF(:DataGrid1, \"AMT\", \"AND([AREA] == ''Seoul'' , [Product] == ''NotBook'')\")\n```\n\n#### AVERAGEIF(grid, fieldName, condition?)\n> `double AVERAGEIF(:Gridname, \"Fieldname\", \"criteria\")`\n\n지정한 Grid에서 조건을 만족하는 Field 데이터의 평균을 구한다.\n```\nAVERAGEIF(:DataGrid1, \"SCORE\")\nAVERAGEIF(:DataGrid1, \"SCORE\", \"[CLASS] = ''A''\")\nAVERAGEIF(:Grid, \"AMT\", \"OR([AREA] == ''Seoul'', [AREA] == ''Busan'')\")\n```\n\n#### COUNTIF(grid, fieldName, condition?)\n> `int COUNTIF(:Gridname, \"Fieldname\", \"criteria\")`\n\n지정한 Grid에서 조건에 맞는 Field 데이터의 개수를 구한다.\n```\nCOUNTIF(:DataGrid1, \"ID\")                          // 전체 행 수\nCOUNTIF(:DataGrid1, \"ID\", \"[STATUS] = ''Y''\")        // STATUS가 Y인 행 수\nCOUNTIF(:Grid, \"CODE\", \"AND([AGE] > 20, [AGE] < 30)\")\n```\n\n#### MAXIF(grid, fieldName, condition?)\n> `double MAXIF(:Gridname, \"Fieldname\", \"criteria\")`\n\n지정한 Grid에서 조건에 맞는 Field 데이터 중 최대 값을 구한다.\n```\nMAXIF(:DataGrid1, \"AMT\")\nMAXIF(:DataGrid1, \"AMT\", \"[YEAR] = ''2025''\")\nMAXIF(:Grid, \"Score\", \"AND([Level] == 3 , [SEX] == ''F'')\")\n```\n\n#### MINIF(grid, fieldName, condition?)\n> `double MINIF(:Gridname, \"Fieldname\", \"criteria\")`\n\n지정한 Grid에서 조건에 맞는 Field 데이터 중 최소 값을 구한다.\n```\nMINIF(:DataGrid1, \"AMT\")\nMINIF(:Grid, \"Score\", \"AND([Level] == 3 , [SEX] == ''F'')\")\n```\n\n#### DISTINCTCOUNT(grid, fieldName)\n> `int DistinctCount(:Gridname, \"Fieldname\")`\n\n지정한 Grid에서 Field 데이터의 고유(distinct) 값의 개수를 구한다.\n```\nDISTINCTCOUNT(:DataGrid1, \"DEPT\")\nDISTINCTCOUNT(:Grid, \"AREA\")\n```\n\n#### GETPIVOTDATA(grid, fieldName, criteria)\n> `string GETPIVOTDATA(:Gridname, \"Fieldname\", \"criteria\")`\n\nOlapGrid에 저장된 데이터를 반환한다. criteria에 `[차원][값]` 형식으로 조건을 지정한다.\n```\nGETPIVOTDATA(:Grid, \"AMT\", \"[YEAR][2017],[AREA][Seoul],[COMPANY][BIMATRIX]\")\n```\n\n#### SELECTEDFIELDVALUE(grid, fieldName, defaultValue?)\n> `string SelectedFieldValue(:Gridname, \"Fieldname\", defaultValue)`\n\n지정한 Grid에서 선택된 셀을 구성하고 있는 레코드 중 특정 필드의 값을 반환한다.\nOLAP 그리드의 경우 여러 개의 레코드를 포함하는 경우 모든 레코드의 필드값이 동일하지 않으면 NULL을 반환한다.\n```\nSELECTEDFIELDVALUE(:DataGrid1, \"EMP_NAME\", \"\")\nSELECTEDFIELDVALUE(:DataGrid1, \"DEPT_CD\", \"ALL\")\n```\n\n#### SUMCELLS(grid, fieldName?)\n> `double SUMCELLS(:Gridname, \"Fieldname\")`\n\n지정한 Grid에서 선택된 영역의 합계를 구한다. fieldName을 지정하면 해당 필드만 대상으로 한다.\n```\nSUMCELLS(:DataGrid1)\nSUMCELLS(:DataGrid1, \"AMT\")\n\"합계 : \" + TOSTRING(SUMCELLS(:Grid, \"FieldName\"), \"#,##0.0\")\n// -> \"합계 : 12,777,856.0\"\n```\n\n#### COUNTCELLS(grid, fieldName?)\n> `int COUNTCELLS(:Gridname, \"Fieldname\")`\n\n지정한 Grid에서 선택된 영역의 개수를 구한다.\n```\nCOUNTCELLS(:DataGrid1)\n\"개수 : \" + TOSTRING(COUNTCELLS(:Grid, \"FieldName\"), \"#,##0\")\n// -> \"개수 : 3\"\n```\n\n#### AVGCELLS(grid, fieldName?)\n> `double AVGCELLS(:Gridname, \"Fieldname\")`\n\n지정한 Grid에서 선택된 영역의 평균값을 구한다.\n```\nAVGCELLS(:DataGrid1, \"SCORE\")\n\"평균 : \" + TOSTRING(AVGCELLS(:Grid, \"FieldName\"), \"#,##0.##\")\n// -> \"평균 : 4,259,285.33\"\n```\n\n> **참고:** SUMCELLS, COUNTCELLS, AVGCELLS는 숫자(Numeric) 타입이고 Visible한 컬럼의 셀만 대상으로 한다.\n\n---\n\n### 문자열 함수\n\n#### LEFT(text, size)\n> `string Left(string target, int nCount)`\n\n원본 문자열에서 좌측으로부터 nCount개만큼의 길이를 가지는 새로운 문자열을 반환한다.\n```\nLEFT(\"123456789\", 3)    // \"123\"\nLEFT([CODE], 2)          // CODE 필드의 앞 2자리\n```\n\n#### RIGHT(text, size)\n> `string Right(string target, int nCount)`\n\n원본 문자열에서 우측으로부터 nCount개만큼의 길이를 가지는 새로운 문자열을 반환한다.\n```\nRIGHT(\"123456789\", 3)   // \"789\"\n```\n\n#### MID(text, startIndex, count)\n> `string SubString(string, int nFirst, int nCount)`\n\n원본 문자열의 특정 위치(nFirst, 0-based)로부터 nCount만큼의 문자열을 반환한다.\n`Mid`와 `Substring`은 동일한 함수이다.\n```\nMID(\"abcde\", 1, 3)      // \"bcd\"\n```\n\n#### LEN(text)\n> `int Len(string target)`\n\n전달받은 문자열의 길이를 반환한다.\n필드가 파라미터로 전달될 경우 해당 필드의 모든 레코드에 대한 문자열 길이의 배열을 반환한다.\n```\nLEN(\"123456789\")         // 9\nLEN([NAME])              // NAME 필드의 문자열 길이\n```\n\n#### LOWER(text) / UPPER(text)\n> `string Lower(string target)` / `string Upper(string text)`\n\n전달받은 문자열을 소문자/대문자로 변환한 문자열을 반환한다.\n필드가 파라미터로 전달될 경우 해당 필드의 모든 레코드에 대해 처리한다.\n```\nLOWER(\"ABC\")             // \"abc\"\nUPPER(\"abcde\")           // \"ABCDE\"\n```\n\n#### FIND(textToFind, textToSearch, startIndex?)\n> `int Find(string textToFind, string textToSearch, int startIndex)`\n\n원본 문자열(textToSearch)의 특정 위치(startIndex, 0-based)로부터 대상 문자열(textToFind)을 검색하여 해당 인덱스를 반환한다. 검색 대상이 없을 경우 `-1`을 반환한다.\n\n**주의:** 첫 번째 인자가 찾을 문자열(textToFind), 두 번째 인자가 검색 대상 문자열(textToSearch)이다.\n```\nFIND(\"bc\", \"abcde\")              // 1\nFIND(\"World\", \"Hello World\")     // 6\nFIND(\"xyz\", \"Hello World\")       // -1\n```\n\n#### REPLACE(text, oldText, newText)\n> `string Replace(string text, string oldText, string newText)`\n\n원본 문자열의 oldText를 newText로 치환한 문자열을 반환한다 (정규식 지원).\n- `SUBSTITUTE()`로도 사용 가능하다 (동일한 함수).\n```\nREPLACE(\"abcde\", \"bc\", \"BC\")            // \"aBCde\"\nREPLACE(\"Hello World\", \"World\", \"AUD\")   // \"Hello AUD\"\nREPLACE([CODE], \"-\", \"\")                  // CODE에서 하이픈 제거\n```\n\n#### TRIM(text)\n> `string Trim(string text)`\n\n원본 문자열의 시작과 종료 부분에 공백을 모두 제거한 문자열을 반환한다.\n```\nTRIM(\"   abcde   \")     // \"abcde\"\n```\n\n---\n\n### 수학 함수\n\n| 함수 | 시그니처 | 설명 | 예시 |\n|------|---------|------|------|\n| `ABS(value)` | `double ABS(double value)` | 절댓값 | `ABS(-100)` -> `100` |\n| `CEIL(value)` | `double CEIL(value)` | 지정한 수 이상의 가장 작은 정수(올림) | `CEIL(0.95)` -> `1` |\n| `FLOOR(value, significance?)` | `double FLOOR(double value, double significance)` | 수를 significance의 배수가 되도록 내림. significance 생략 시 주어진 수와 같거나 작은 가장 큰 정수를 반환 | `FLOOR(45.95)` -> `45`, `FLOOR(3910, 50)` -> `3900` |\n| `ROUND(value, decimals?)` | `double ROUND(double value, int decimals)` | 지정한 소수점 자릿수로 반올림 | `ROUND(1.256, 2)` -> `1.26` |\n| `LOG(value, base?)` | `double LOG(double value, double base)` | 지정한 밑의 로그 | `LOG(2, 8)` -> `3` |\n| `LOG10(value)` | `double LOG10(double value)` | 상용로그 (밑 10) | `LOG10(100)` -> `2` |\n| `EXP(value)` | `double EXP(double value)` | 자연 상수 e의 거듭제곱 | `EXP(1)` -> `2.71828...` |\n| `RAND(max?)` | `double RAND([double max])` | 0~max 사이 난수. max 미지정 시 0~1 사이 난수 반환 | `RAND(100)` -> `97.1234` |\n| `SIN(value)` | `double SIN(double value)` | 사인 (라디안) | `SIN(Math.PI / 2)` -> `1` |\n| `COS(value)` | `double COS(double value)` | 코사인 (라디안) | `COS(1)` -> `0.5403...` |\n| `TAN(value)` | `double TAN(double value)` | 탄젠트 | `TAN(1)` -> `1.557...` |\n| `ASIN(value)` | `double ASIN(double value)` | 아크사인 | `ASIN(-1)` -> `-1.5707...` |\n| `ACOS(value)` | `double ACOS(double value)` | 아크코사인 | `ACOS(-1)` -> `3.1415...` |\n| `ATAN(value)` | `double ATAN(double value)` | 아크탄젠트 | `ATAN(1)` -> `0.7853...` |\n\n---\n\n### 날짜/시간 함수\n\n#### NOW()\n> `DateTime NOW()`\n\n현재 시스템의 날짜와 시간을 `yyyyMMddHHmmssSSS` 형식 문자열로 반환한다.\n```\nNOW()       // \"20250115170409448\"\n```\n\n#### TODAY()\n> `DateTime TODAY()`\n\n현재 시스템의 날짜를 `yyyyMMdd` 형식 문자열로 반환한다. 시간은 00:00:00으로 설정된다.\n```\nTODAY()     // \"20250115\"\n```\n\n#### YEAR(date), MONTH(date), DAY(date)\n> `int YEAR(DateTime date)` / `int MONTH(DateTime date)` / `int DAY(DateTime date)`\n\n대상 날짜에서 연/월/일을 추출한다. date는 Date 객체 또는 `yyyyMMdd` 이상의 문자열이다.\n- **YEAR**: 년도를 반환\n- **MONTH**: 월의 값을 반환 (1~12)\n- **DAY**: 일의 값을 반환 (1~31)\n```\nYEAR(\"20250115\")    // 2025\nMONTH(\"20250115\")   // 1\nDAY(\"20250115\")     // 15\nYEAR(TODAY())       // 현재 연도\n```\n\n#### WEEKDAY(date)\n> `int WEEKDAY(DateTime date)`\n\n대상 날짜의 요일값을 반환한다 (0=일요일, 1=월요일, ..., 6=토요일).\n```\nWEEKDAY(\"20250115\")   // 3 (수요일)\n```\n\n#### HOUR(date), MINUTE(date), SECOND(date)\n> `int HOUR(DateTime date)` / `int MINUTE(DateTime date)` / `int SECOND(DateTime date)`\n\n대상 시간의 시/분/초를 추출한다.\n- **HOUR**: 시간 값 반환 (0~23)\n- **MINUTE**: 분 값 반환 (0~59)\n- **SECOND**: 초 값 반환 (0~59)\n```\nHOUR(\"20250115143025\")      // 14\nMINUTE(\"20250115143025\")    // 30\nSECOND(\"20250115143025\")    // 25\n```\n\n#### DATEADD(interval, number, date)\n> `DateTime DATEADD(interval, double number, DateTime date)`\n\n대상 일자에 일자의 각 단위(년, 분기, 월, 일 등)를 가감한 일자를 반환한다.\n\n**interval 상수:**\n| 상수 | 의미 |\n|------|------|\n| `1` | YEAR (년) |\n| `2` | MONTH (월) |\n| `5` | DAY (일) |\n| `11` | HOUR (시) |\n| `12` | MINUTE (분) |\n| `13` | SECOND (초) |\n\n```\nDATEADD(5, 1, \"20201231\")           // 1일 후 -> \"202101010000000\"\nDATEADD(5, 7, \"20250115\")           // 7일 후 -> \"20250122...\"\nDATEADD(2, -1, \"20250115\")          // 1개월 전 -> \"20241215...\"\nDATEADD(1, 1, TODAY())              // 1년 후\n```\n\n#### DATEDIFF(interval, date1, date2)\n> `int DATEDIFF(interval, DateTime date1, DateTime date2)`\n\n두 일자 간 차이의 값을 반환한다 (date2 - date1). interval 상수는 DATEADD와 동일하다.\n```\nDATEDIFF(5, \"20201215\", \"20201231\")    // 16 (일)\nDATEDIFF(5, \"20250101\", \"20250115\")    // 14 (일)\nDATEDIFF(2, \"20240115\", \"20250115\")    // 12 (개월)\nDATEDIFF(1, \"20200101\", \"20250101\")    // 5 (년)\n```\n\n#### DATEPART(interval, date)\n> `double DATEPART(interval, DateTime date)`\n\n일자의 각 파트에 해당하는 값을 반환한다. interval 상수는 DATEADD와 동일하다.\nYEAR(), MONTH() 등과 유사하나 interval로 지정한다.\n```\nDATEPART(1, \"20250115\")     // 2025 (년)\nDATEPART(2, \"20250115\")     // 1 (월)\nDATEPART(5, \"20250115\")     // 15 (일)\n```\n\n#### DATE(year, month, day, hour?, minute?, second?)\n> `DateTime DATE(int year, int month, int day [, int hour, int minute, int second])`\n\n넘겨진 파라미터 값을 가지고 새로운 일자(Date 객체)를 반환한다. 시/분/초는 옵션이다.\n```\nDATE(2025, 1, 15)\nDATE(2025, 1, 15, 14, 30, 0)\nDATE(\"2020\", \"12\", \"31\")           // Thu Dec 31 2020 ...\n```\n\n#### DATE2(year_diff, month_diff, day_diff)\n> `DateTime DATE2(int year_diff, int month_diff, int day_diff)`\n\n현재 날짜를 기준으로 상대적인 차이(년, 월, 일)를 적용한 새로운 일자를 반환한다.\n```\nDATE2(0, 0, 1)      // 오늘 + 1일\nDATE2(0, -1, 0)     // 오늘 - 1개월\nDATE2(1, 0, 0)      // 오늘 + 1년\n```\n\n---\n\n## MTSD 문서에서의 수식 적용 위치\n\nMTSD(.mtsd) 파일에서 수식은 각 Element의 `Formula` 속성에 설정한다.\n\n### Formula 속성을 지원하는 Element 타입\n\n| Element 타입 | Formula 속성 | 필수/선택 | MTSD JSON 경로 |\n|-------------|-------------|----------|---------------|\n| **Label** | `Formula` | 필수 | `Forms[].Elements[].Formula` |\n| **NumberBox** | `Formula` | 필수 | `Forms[].Elements[].Formula` |\n| **TextBox** | `Formula` | 선택 | `Forms[].Elements[].Formula` |\n\n> **참고:** CheckBox, ComboBox, Button, DataGrid(GridColumn) 등에는 `Formula` 속성이 없다.\n\n### MTSD 적용 예시\n\n#### 라벨에 수식 설정\n`:VS_COMPANY` 값이 변경될 때 `lblText`에 `:VS_COMPANY + 1` 값을 표시하려면,\n해당 Label Element의 `Formula` 속성에 수식을 작성한다.\n```json\n{\n  \"Type\": \"Label\",\n  \"Name\": \"lblText\",\n  \"Formula\": \":VS_COMPANY + 1\",\n  \"Text\": \"\",\n  \"Cursor\": \"default\",\n  \"UseTextOverflow\": false,\n  \"UseAutoLineBreak\": false,\n  \"LineSpacing\": 0,\n  \"HasLineSpacing\": false,\n  \"LanguageCode\": \"\",\n  \"MxBinding\": \"\",\n  \"MxBindingUseStyle\": false\n}\n```\n수식에서 `:VS_COMPANY`를 참조하면, 해당 컨트롤의 값이 변경될 때 수식이 자동 재연산된다.\n\n#### NumberBox에 수식 설정\n두 텍스트박스의 곱셈 결과를 NumberBox에 자동 계산하려면:\n```json\n{\n  \"Type\": \"NumberBox\",\n  \"Name\": \"nbxTotal\",\n  \"Formula\": \":txtPrice * :txtQty\",\n  \"Format\": \"{0:N0}\",\n  \"Value\": 0,\n  \"Text\": \"\",\n  \"IsReadOnly\": true,\n  \"Maximum\": 999999999,\n  \"Minimum\": 0,\n  \"MxBinding\": \"\",\n  \"MxBindingUseStyle\": false\n}\n```\n\n### DataGrid 컬럼 수식에 대한 참고\n\nDataGrid의 GridColumn에는 MTSD 스키마상 `Formula` 속성이 존재하지 않는다.\n그리드 컬럼 수식(`[PRICE] * [QTY]` 등)은 i-AUD Designer에서 컬럼의 **계산수식** 설정을 통해 구성한다.\n따라서 MTSD 파일을 직접 편집하여 그리드 컬럼에 수식을 추가할 수 없으며,\ni-AUD Designer에서 해당 컬럼을 선택한 뒤 속성 창의 ''계산수식'' 항목에서 설정해야 한다.\n\n> **대안:** 클라이언트 스크립트에서 `DataGrid`의 `OnCellFormatting` 이벤트 등을 활용하여\n> 런타임에 셀 값을 동적으로 계산하는 방법도 있다.\n\n---\n\n## 수식 사용 예시\n\n### 라벨/텍스트박스 수식\n```\n// 다른 컨트롤 참조하여 계산\n:txtPrice * :txtQty\n\n// 그리드 합계를 라벨에 표시\nSUMIF(:DataGrid1, \"AMT\")\n\n// 조건부 텍스트 표시\nIIF(:txtScore >= 60, \"합격\", \"불합격\")\n\n// 포맷 적용\nTOSTRING(SUMIF(:DataGrid1, \"AMT\"), \"{0:N0}\")\n\n// 문자열 연결 + 날짜 함수 조합\nLEFT(TODAY(), 4) + \"년 \" + MID(TODAY(), 4, 2) + \"월\"\n```\n\n### 데이터그리드 컬럼 수식\n```\n// 단가 x 수량\n[PRICE] * [QTY]\n\n// 할인율 적용 금액\n[PRICE] * [QTY] * (1 - [DISCOUNT_RATE] / 100)\n\n// 조건에 따른 등급\nIIF([SCORE] >= 90, \"A\", IIF([SCORE] >= 80, \"B\", IIF([SCORE] >= 70, \"C\", \"D\")))\n\n// CASE 사용\nCASE(\n    [DEPT] = \"10\", \"영업부\",\n    [DEPT] = \"20\", \"개발부\",\n    [DEPT] = \"30\", \"관리부\",\n    \"기타\"\n)\n\n// 날짜 차이 계산\nDATEDIFF(5, [START_DATE], [END_DATE])\n\n// 총합계 행에서 다른 계산 적용 (GroupGrid)\nIIF(IS_GRAND_TOTAL, CELL_VALUE, [PRICE] * [QTY])\n```\n\n### 복합 수식 (JavaScript 모드)\n```\nvar price = TONUMBER([PRICE], 0);\nvar qty = TONUMBER([QTY], 0);\nvar total = price * qty;\n\nif (total > 100000) {\n    return TOSTRING(total * 0.9, \"{0:N0}\");\n} else {\n    return TOSTRING(total, \"{0:N0}\");\n}\n```\n\n---\n\n## 주의사항\n\n1. **순환 참조 금지**: 수식에서 자기 자신을 참조하거나 순환 참조하면 오류가 발생한다.\n2. **필드명/캡션**: 그리드 집계 함수의 fieldName 인자에는 필드명(Name) 또는 캡션(Caption) 모두 사용 가능하다.\n3. **대소문자**: 함수명은 대소문자를 구분하지 않는다 (`SUMIF`, `SumIf`, `sumif` 모두 동일).\n4. **문자열 리터럴**: 문자열은 큰따옴표(`\"`) 또는 작은따옴표(`''`)로 감싼다.\n5. **반환값**: 수식 모드에서는 `return`을 생략하면 자동으로 추가된다. JavaScript 모드에서는 명시적으로 `return`을 사용해야 한다.\n6. **숫자 필드**: Numeric 타입 필드의 값이 null/undefined이면 `0`으로 처리된다.\n7. **집계 함수의 condition**: condition 내에서 `[필드명]`으로 그리드의 각 행의 필드를 참조할 수 있다.\n8. **FIND 파라미터 순서**: `FIND(찾을문자열, 검색대상문자열, 시작인덱스)` 순서이다. 첫 번째가 찾을 문자열임에 주의한다.\n9. **FLOOR의 significance**: `FLOOR(3910, 50)` -> `3900`과 같이 significance 인자를 지정하면 해당 배수로 내림한다."},"lastSynced":"2026-03-08T02:04:09.404Z","agentAnalysis":{"suitability":{"en":"Perfect for Calculation Agents needing automated formula processing and data grid computations.","zh":"适合于需要自动公式处理和数据网格计算的计算代理。","ja":"計算エージェントが自動式処理とデータグリッド計算を必要とする場合に適しています。","ko":"자동 수식 처리 및 데이터 그리드 계산이 필요한 계산 에이전트에 적합합니다.","es":"Perfecto para Agentes de Cálculo que necesitan procesamiento de fórmulas automatizado y cálculos de cuadrículas de datos.","fr":"Parfait pour les Agents de Calcul nécessitant un traitement de formules automatisé et des calculs de grille de données.","de":"Perfekt für Berechnungsagenten, die ein automatisiertes Formelverarbeitung und Datenrasterberechnungen benötigen.","pt":"Perfeito para Agentes de Cálculo que precisam de processamento de fórmulas automatizado e cálculos em grade de dados.","ru":"Идеально для Calculation Agents, которым требуется автоматизированная обработка формул и вычисления в сетке данных.","ar":"متوافق完全 مع وكلاء الحساب الذين يحتاجون إلى معالجة صيغ مت автомاتيكية وحسابات شبكة البيانات."},"recommendation":{"en":"Empowers agents to automate calculations within applications using controls like text boxes, labels, and data grids, leveraging formula references like :컨트롤명, :전역변수명, and [필드명], and supporting various operators such as + for addition and string concatenation.","zh":"赋予代理在应用程序中使用文本框、标签和数据网格等控件自动执行计算的能力，利用公式引用如：控件名, ：全局变量名, 和 [字段名]，并支持各种运算符，如 + 用于加法和字符串连接。","ja":"エージェントがアプリケーション内でテキストボックス、ラベル、データグリッドなどのコントロールを使用して計算を自動化する能力を提供し、：コントロール名、：グローバル変数名、[フィールド名]などの式参照を利用し、+ などの加算や文字列結合などの演算子をサポートします。","ko":"에이전트가 애플리케이션 내에서 텍스트 상자, 레이블, 데이터 그리드 등의 컨트롤을 사용하여 계산을 자동화할 수 있는 능력을 제공하며, :컨트롤명, :전역변수명, [필드명] 등의 수식 참조를 利用하며, + 등의 연산자와 문자열 연결을 지원합니다.","es":"Habilita a los agentes a automatizar cálculos dentro de aplicaciones utilizando controles como cuadros de texto, etiquetas y cuadrículas de datos, aprovechando referencias de fórmulas como :컨트롤명, :전역변수명, y [필드명], y admitiendo varios operadores como + para suma y concatenación de cadenas.","fr":"Permet aux agents d''automatiser les calculs au sein des applications en utilisant des contrôles tels que des zones de texte, des étiquettes et des grilles de données, en exploitant des références de formules comme :컨트롤명, :전역변수명, et [필드명], et en prenant en charge divers opérateurs tels que + pour l''addition et la concaténation de chaînes.","de":"Ermöglicht es Agenten, Berechnungen innerhalb von Anwendungen zu automatisieren, die Steuerelemente wie Textfelder, Beschriftungen und Datenraster verwenden, indem Formelverweise wie :컨트롤명, :전역변수명, und [필드명] genutzt werden, und unterstützt verschiedene Operatoren wie + für Addition und Zeichenfolgenverkettung.","pt":"Permite que os agentes automatem cálculos dentro de aplicações usando controles como caixas de texto, rótulos e grades de dados, aproveitando referências de fórmulas como :컨트롤명, :전역변수명 e [필드명], e suportando vários operadores, como + para adição e concatenação de strings.","ru":"Позволяет агентам автоматизировать вычисления внутри приложений, используя элементы управления, такие как текстовые поля, метки и сетки данных, используя ссылки на формулы, такие как :컨트롤명, :전역변수명 и [필드명], и поддерживая различные операторы, такие как + для сложения и конкатенации строк.","ar":"تمكن الوكلاء من توفير حسابات داخل التطبيقات باستخدام عناصر تحكم مثل مربعات النص والتعليمات والشبكات البيانية، واستخدام المراجع الصيغ مثل :컨트롤명، :전역변수명 و [필드명]، ودعم مشغلات متعددة مثل + للجمع وتركيب السلاسل."},"useCases":{"en":["Automating complex computations in data grids","Generating dynamic values based on user input in text boxes","Referencing and updating global variables like gYear in calculations"],"zh":["在数据网格中自动执行复杂计算","根据用户在文本框中的输入生成动态值","在计算中引用和更新全局变量，如 gYear"],"ja":["データグリッド内の複雑な計算の自動化","テキストボックス内のユーザー入力に基づいて動的な値を生成","計算でグローバル変数を参照して更新する、例えば gYear"],"ko":["데이터 그리드 내의 복잡한 계산 자동화","텍스트 상자 내의 사용자 입력에 따라 동적 값을 생성","계산에서 전역 변수를 참조하고 업데이트하는 것, 예를 들어 gYear"],"es":["Automatizar cálculos complejos en cuadrículas de datos","Generar valores dinámicos en función de la entrada del usuario en cuadros de texto","Hacer referencia y actualizar variables globales como gYear en cálculos"],"fr":["Automatiser des calculs complexes dans des grilles de données","Générer des valeurs dynamiques en fonction de la saisie de l''utilisateur dans des zones de texte","Référencer et mettre à jour des variables globales comme gYear dans les calculs"],"de":["Automatisierung komplexer Berechnungen in Datenrastern","Erzeugen dynamischer Werte basierend auf Benutzereingaben in Textfeldern","Verweis auf und Aktualisierung globaler Variablen wie gYear in Berechnungen"],"pt":["Automatizar cálculos complexos em grades de dados","Gerar valores dinâmicos com base na entrada do usuário em caixas de texto","Referenciar e atualizar variáveis globais, como gYear, em cálculos"],"ru":["Автоматизация сложных вычислений в сетке данных","Генерация динамических значений на основе ввода пользователя в текстовых полях","Ссылка и обновление глобальных переменных, таких как gYear, в вычислениях"],"ar":["توفير حسابات معقدة في شبكات البيانات","توليد قيم ديناميكية بالاعتماد على إدخال المستخدم في مربعات النص","المرجع وتحديث المتغيرات العالمية، مثل gYear، في الحسابات"]},"limitations":{"en":["Requires FormulaManager setup","Limited to specific control types like text boxes, labels, and data grids"],"zh":["需要 FormulaManager 设置","仅限特定控件类型，如文本框、标签和数据网格"],"ja":["FormulaManager の設定が必要","特定のコントロールタイプのみをサポートしている、例えばテキストボックス、ラベル、データグリッド"],"ko":["FormulaManager 설정이 필요","특정 컨트롤 유형만 지원, 예를 들어 텍스트 상자, 레이블, 데이터 그리드"],"es":["Requiere configuración de FormulaManager","Limitado a tipos de controles específicos como cuadros de texto, etiquetas y cuadrículas de datos"],"fr":["Nécessite une configuration de FormulaManager","Limité à des types de contrôles spécifiques tels que des zones de texte, des étiquettes et des grilles de données"],"de":["Benötigt FormulaManager-Einrichtung","Begrenzt auf bestimmte Steuerelementtypen wie Textfelder, Beschriftungen und Datenraster"],"pt":["Requer configuração do FormulaManager","Limitado a tipos de controles específicos, como caixas de texto, rótulos e grades de dados"],"ru":["Требуется настройка FormulaManager","Ограничен конкретными типами элементов управления, такими как текстовые поля, метки и сетки данных"],"ar":["يتطلب إعداد FormulaManager","محدود بنوع معين من عناصر التحكم، مثل مربعات النص والتعليمات والشبكات البيانية"]},"version":4},"contentHash":"0797b4e15f30839d8d93766513da515c3673d33db5dc84565c5c9bb90adbb931","qualityScore":30}');
