INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AUD-DEV-TEAM/i-AUD-Developer-Kit/iaud-formula', 'iaud-formula', 'AUD-DEV-TEAM', 'i-AUD-Developer-Kit', 'community', 'iaud-formula AUD-DEV-TEAM i-AUD-Developer-Kit community The iaud-formula skill enables developers to automate calculations within their applications, leveraging controls like text boxes, labels, and data grids. It benefits developers seeking to simplify complex computations i-AUD公式是一种自动计算系统，允许开发者在文本框、标签和数据网格中设置公式，实现自动计算和数据关联 i-AUD Formulaは自動計算システムであり、開発者がテキストボックス、ラベル、データグリッドに数式を設定して自動計算とデータの関連付けを実現できる i-AUD 계산수식은 자동 연산 시스템으로 개발자가 텍스트박스, 라벨, 데이터그리드에 수식을 설정하여 자동 연산과 데이터 연동을 구현할 수 있다 La fórmula iaud es un sistema de cálculo automático que permite referenciar controles y variables globales. Aprende a utilizarla en tus proyectos de desarrollo La formule iaud est un système de calcul automatisé qui permet de référencer des contrôles et des variables globales. Apprenez à l''utiliser dans vos projets de développement Die iaud-Formel ist ein System für die automatische Berechnung, das das Referenzieren von Steuerelementen und globalen Variablen ermöglicht. Erfahren Sie, wie Sie sie in Ihren Entwicklungsprojekten verwenden A fórmula i-AUD é um sistema de automação de cálculos para controles como caixas de texto e grades de dados. Aprenda a configurá-la. Формула i-AUD - система автоматических расчетов для контролов, таких как текстовые поля и таблицы данных. Узнайте, как ее настроить. صيغة i-AUD هي نظام للطورين لحسابات السيطرة مثل صناديق النص والقوائم. تعلم كيفية إعدادها. how to use iaud-formula iaud-formula setup guide iaud-formula alternative automated calculation in iaud-formula iaud-formula vs competitor iaud-formula install what is iaud-formula iaud-formula documentation iaud-formula tutorial i-AUD公式 自动计算系统 数据关联 公式设置 开发效率 AI工具 AIエージェント 自动计算 Supports control references using `:컨트롤명` syntax Enables global parameter and variable references via `:전역변수명` Allows data grid field value references with `[필드명]` syntax Automatically recalculates values when referenced controls change Utilizes basic arithmetic operators like `+` for addition and string concatenation iaud-formula is a developer kit that allows for the creation of automated calculations using formulas, enabling references to controls, global parameters, and data grid fields');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Umisyo/Lorepedia/codex', 'community', 'Umisyo', 'Lorepedia', 'Umisyo/Lorepedia', 'codex', 0, 0, 30, '2026-03-08T01:57:15.360Z', '2026-03-08T02:04:10.608Z', '44136fb3de359d79fc8f01c13459d1c6e1ad1e6b11df849ae8683d7cf519b786', '{"id":"Umisyo/Lorepedia/codex","name":"codex","description":{"en":"Codex is a shared world creation support tool that utilizes the OpenAI Codex CLI for automated code review and analysis, benefiting developers with efficient project examination.","zh":"Codex是使用OpenAI Codex CLI进行代码审查和分析的工具，支持完全自动模式和安全的读取专用沙盒","ja":"CodexはOpenAI Codex CLIを使用してコードレビュー・分析を実行するスキルで、完全自動モードと読み取り専用サンドボックスをサポートする","ko":"Codex는 OpenAI Codex CLI를 사용하여 코드 리뷰 및 분석을 수행하는 툴로, 완전 자동 모드와 안전한 읽기 전용 샌드박스를 지원합니다","es":"Codex es una herramienta de análisis de código que utiliza OpenAI Codex CLI para revisar y analizar código de manera automática","fr":"Codex est un outil d''analyse de code qui utilise OpenAI Codex CLI pour réviser et analyser du code de manière automatisée","de":"Codex ist ein Code-Analyse-Tool, das OpenAI Codex CLI verwendet, um Code automatisch zu überprüfen und zu analysieren","pt":"O Codex é uma ferramenta de criação de mundo compartilhado que utiliza a CLI do OpenAI Codex para análise de código. Ele permite a execução de comandos como `codex exec` para análise de código em projetos","ru":"Codex - это инструмент создания общего мира, использующий CLI OpenAI Codex для анализа кода. Он позволяет выполнять команды, такие как `codex exec`, для анализа кода в проектах","ar":"Codex هي أداة إنشاء عالم مشترك تستخدم واجهة سطر الأوامر OpenAI Codex لتحليل الكود. أنها تسمح بتنفيذ أوامر مثل `codex exec` لتحليل الكود في المشاريع"},"seo":{"title":{"en":"Codex: Automated Code Review Setup Guide | AI Agent Skill","zh":"Codex Setup Guide: 使用OpenAI Codex CLI进行代码审查","ja":"Codex セットアップガイド: OpenAI Codex CLIを使用したコードレビュー・分析","ko":"Codex 설정 가이드: OpenAI Codex CLI를 사용한 코드 리뷰 및 분석","es":"Guía de configuración de Codex: Análisis de código automa...","fr":"Guide de mise en place de Codex: Analyse de code automatisée","de":"Codex-Setup-Anleitung: Automatisierte Code-Analyse","pt":"Guia de Configuração do Codex: Ferramenta de Criação de M...","ru":"Настройка Codex: Инструмент Создания Общего Мира для ИИ А...","ar":"دليل إعداد Codex: أداة إنشاء عالم مشترك للأدوات الذكية"},"description":{"en":"Unlock efficient code analysis with Codex. Learn how to set up and utilize the OpenAI Codex CLI for seamless code reviews and discover its capabilities today!","zh":"使用Codex和OpenAI Codex CLI进行代码审查和分析，提高代码质量和安全性","ja":"CodexとOpenAI Codex CLIを使用してコードレビュー・分析を実行し、コードの品質と安全性を向上させる","ko":"Codex와 OpenAI Codex CLI를 사용하여 코드 리뷰 및 분석을 수행하고 코드 품질 및 보안을 개선합니다","es":"Aprende a utilizar Codex para analizar y revisar código de manera automática con OpenAI Codex CLI","fr":"Découvrez comment utiliser Codex pour analyser et réviser du code de manière automatisée avec OpenAI Codex CLI","de":"Erfahren Sie, wie Sie Codex verwenden, um Code automatisch mit OpenAI Codex CLI zu analysieren und zu überprüfen","pt":"Aprenda a configurar o Codex, uma ferramenta de criação de mundo compartilhado que utiliza a CLI do OpenAI Codex para análise de código","ru":"Узнайте, как настроить Codex, инструмент создания общего мира, использующий CLI OpenAI Codex для анализа кода и ИИ Агентов","ar":"تعرف على كيفية إعداد Codex، أداة إنشاء عالم مشترك تستخدم واجهة سطر الأوامر OpenAI Codex لتحليل الكود والأدوات الذكية"},"definition":{"en":"Codex is an AI agent skill that leverages the OpenAI Codex CLI for automated code review and analysis, supporting developers in identifying issues within their projects.","zh":"Codex是一种使用OpenAI Codex CLI的代码审查和分析工具","ja":"CodexはOpenAI Codex CLIを使用するコードレビュー・分析ツールである","ko":"Codex는 OpenAI Codex CLI를 사용하는 코드 리뷰 및 분석 툴입니다","es":"Codex es una herramienta de análisis de código que utiliza inteligencia artificial para revisar y analizar código","fr":"Codex est un outil d''analyse de code qui utilise l''intelligence artificielle pour réviser et analyser du code","de":"Codex ist ein Code-Analyse-Tool, das künstliche Intelligenz verwendet, um Code zu überprüfen und zu analysieren","pt":"O Codex é uma ferramenta de criação de mundo compartilhado que utiliza a CLI do OpenAI Codex para análise de código e desenvolvimento de projetos","ru":"Codex - это инструмент создания общего мира, представляющий собой набор инструментов для анализа кода и разработки проектов с помощью ИИ Агентов","ar":"Codex هي أداة إنشاء عالم مشترك تعتمد على واجهة سطر الأوامر OpenAI Codex لتحليل الكود وتطوير المشاريع للأدوات الذكية"},"features":{"en":["Executes code review using the OpenAI Codex CLI with the `codex exec` command","Supports fully automatic mode with the `--full-auto` parameter","Utilizes a read-only sandbox for safe analysis with `--sandbox read-only`","Allows specification of the project directory with `--cd <project_directory>`","Accepts Japanese requests for code review with `<request>`"],"zh":["支持完全自动模式","安全的读取专用沙盒","使用OpenAI Codex CLI进行代码审查和分析","支持多种编程语言","可用于代码安全性和质量检查"],"ja":["完全自動モードをサポート","読み取り専用サンドボックスを提供","OpenAI Codex CLIを使用したコードレビュー・分析","複数のプログラミング言語をサポート","コードの安全性と品質のチェックに使用可能"],"ko":["완전 자동 모드를 지원","안전한 읽기 전용 샌드박스를 제공","OpenAI Codex CLI를 사용한 코드 리뷰 및 분석","여러 프로그래밍 언어를 지원","코드 보안 및 품질 체크에 사용 가능"],"es":["Análisis de código automático con OpenAI Codex CLI","Revisión de código en modo sandbox para garantizar la seguridad","Compatibilidad con proyectos en diferentes directorios","Soporte para solicitudes de revisión de código en japonés","Ejecución de comandos personalizados con la opción --full-auto"],"fr":["Analyse de code automatisée avec OpenAI Codex CLI","Révision de code en mode sandbox pour assurer la sécurité","Compatibilité avec des projets dans différents répertoires","Prise en charge des demandes de révision de code en japonais","Exécution de commandes personnalisées avec l''option --full-auto"],"de":["Automatisierte Code-Analyse mit OpenAI Codex CLI","Code-Überprüfung im Sandbox-Modus für Sicherheitsgarantie","Kompatibilität mit Projekten in verschiedenen Verzeichnissen","Unterstützung für Code-Überprüfungsanfragen auf Japanisch","Ausführung von benutzerdefinierten Befehlen mit der Option --full-auto"],"pt":["Suporte à análise de código com a CLI do OpenAI Codex","Execução de comandos como `codex exec` para análise de código","Modo de sandbox read-only para análise segura de código","Suporte a projetos em diretórios personalizados com `--cd <dir>`","Aceitação de requisições em japonês com `\"<request>\"`"],"ru":["Поддержка анализа кода с помощью CLI OpenAI Codex","Выполнение команд, таких как `codex exec`, для анализа кода","Режим песочницы read-only для безопасного анализа кода","Поддержка проектов в пользовательских директориях с `--cd <dir>`","Принятие запросов на японском языке с `\"<request>\"`"],"ar":["دعم تحليل الكود باستخدام واجهة سطر الأوامر OpenAI Codex","تنفيذ أوامر مثل `codex exec` لتحليل الكود","وضع حماية Sandbox read-only لتحليل الكود الآمن","دعم المشاريع في الدلائل المخصصة مع `--cd <dir>`","قبول الطلبات باللغة اليابانية مع `\"<request>\"`"]},"keywords":{"en":["how to use codex","codex setup guide","OpenAI Codex CLI tutorial","codex alternative","codex vs code review tools","codex install","automated code review with codex","codex for developers","codex AI agent skill"],"zh":["OpenAI Codex CLI","代码审查","代码分析","AI代码审查工具","代码安全性检查","代码质量检查","自动代码审查","AI代码分析工具"],"ja":["OpenAI Codex CLI","コードレビュー","コード分析","AIコードレビューツール","コードの安全性チェック","コードの品質チェック","自動コードレビュー","AIコード分析ツール"],"ko":["OpenAI Codex CLI","코드 리뷰","코드 분석","AI 코드 리뷰 툴","코드 보안성 체크","코드 품질 체크","자동 코드 리뷰","AI 코드 분석 툴"],"es":["herramientas de análisis de código","OpenAI Codex CLI","análisis de código automático","revisión de código","sandbox de código","proyectos de código","AI para desarrolladores","herramientas de desarrollo de software","codex AI"],"fr":["outils d''analyse de code","OpenAI Codex CLI","analyse de code automatisée","révision de code","sandbox de code","projets de code","IA pour les développeurs","outils de développement de logiciels","codex IA"],"de":["Code-Analyse-Tools","OpenAI Codex CLI","automatisierte Code-Analyse","Code-Überprüfung","Code-Sandbox","Code-Projekte","KI für Entwickler","Software-Entwicklungstools","codex KI"],"pt":["codex","ferramenta de criação de mundo compartilhado","análise de código","OpenAI Codex","CLI","desenvolvimento de projetos","sandbox read-only","comandos de execução"],"ru":["codex","инструмент создания общего мира","анализ кода","OpenAI Codex","CLI","разработка проектов","песочница read-only","команды выполнения","ИИ Агенты"],"ar":["codex","أداة إنشاء عالم مشترك","تحليل الكود","OpenAI Codex","واجهة سطر الأوامر","تطوير المشاريع","وضع حماية Sandbox read-only","أوامر التنفيذ","الأدوات الذكية"]}},"owner":"Umisyo","repo":"Lorepedia","repoPath":"Umisyo/Lorepedia","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.360Z","topics":[],"category":"community","skillMd":{"name":"codex","description":"OpenAI Codex CLIを使用したコードレビュー、分析、コードベースへの質問を実行する。使用場面: (1) PRセルフレビュー、(2) コードベース全体の分析、(3) 実装に関する質問、(4) バグの調査、(5) リファクタリング提案。トリガー: codex, コードレビュー, レビューして, 分析して, /codex","bodyPreview":"# Codex\n\nOpenAI Codex CLIを使用してコードレビュー・分析を実行するスキル。\n\n## 実行コマンド\n\n```bash\ncodex exec --full-auto --sandbox read-only --cd <project_directory> \"<request>\"\n```\n\n## パラメータ\n\n| パラメータ | 説明 |\n|-----------|------|\n| `--full-auto` | 完全自動モードで実行 |\n| `--sandbox read-only` | 読み取り専用サンドボックス（安全な分析用） |\n| `--cd <dir>` | 対象プロジェクトのディレクトリ |\n| `\"<request>\"` | 依頼内容（日本語可） |\n\n## 使用例\n\n### PRセルフレビュー（主要ユースケース）\n\n```bash\ncodex exec --full-auto --sandbox read-only --cd /path/to/project \"このPRの変更をレビューして、以下の観点で問題を指摘してください：\n- 型安全性（any","body":"# Codex\n\nOpenAI Codex CLIを使用してコードレビュー・分析を実行するスキル。\n\n## 実行コマンド\n\n```bash\ncodex exec --full-auto --sandbox read-only --cd <project_directory> \"<request>\"\n```\n\n## パラメータ\n\n| パラメータ | 説明 |\n|-----------|------|\n| `--full-auto` | 完全自動モードで実行 |\n| `--sandbox read-only` | 読み取り専用サンドボックス（安全な分析用） |\n| `--cd <dir>` | 対象プロジェクトのディレクトリ |\n| `\"<request>\"` | 依頼内容（日本語可） |\n\n## 使用例\n\n### PRセルフレビュー（主要ユースケース）\n\n```bash\ncodex exec --full-auto --sandbox read-only --cd /path/to/project \"このPRの変更をレビューして、以下の観点で問題を指摘してください：\n- 型安全性（any型、型アサーション）\n- セキュリティ（OWASP Top 10）\n- テストの有無\n- コード規約違反\n指摘は🔴必須/🟡推奨/💡提案に分類してください\"\n```\n\n### コード分析\n\n```bash\ncodex exec --full-auto --sandbox read-only --cd /path/to/project \"このプロジェクトのコードをレビューして、改善点を指摘してください\"\n```\n\n### バグ調査\n\n```bash\ncodex exec --full-auto --sandbox read-only --cd /path/to/project \"認証処理でエラーが発生する原因を調査してください\"\n```\n\n### リファクタリング提案\n\n```bash\ncodex exec --full-auto --sandbox read-only --cd /path/to/project \"このコンポーネントのリファクタリング案を提案してください\"\n```\n\n## PRセルフレビューとしての使用\n\nPR作成後のセルフレビューでは、以下の手順で実行する：\n\n### 1. PR差分の確認\n\n```bash\ngh pr diff\n```\n\n### 2. Codexでレビュー実行\n\n```bash\ncodex exec --full-auto --sandbox read-only --cd $(pwd) \"このPRの変更をレビューして、CLAUDE.mdの品質基準に照らして問題を指摘してください。\n指摘は以下に分類してください：\n- 🔴必須: セキュリティ問題、any型使用、テスト欠如、ESLintエラー\n- 🟡推奨: 型アサーションの改善、命名規則違反、パフォーマンス改善\n- 💡提案: リファクタリング提案、より良いパターン\"\n```\n\n### 3. 指摘への対応\n\n| 分類 | 対応 |\n|------|------|\n| 🔴必須 | 必ず修正 |\n| 🟡推奨 | 可能な限り修正 |\n| 💡提案 | 任意で検討 |\n\n🔴必須・🟡推奨の指摘がなくなるまで修正を繰り返す（最大3回）\n\n## 実行手順\n\n1. ユーザーから依頼内容を受け取る\n2. 対象プロジェクトのディレクトリを特定する（デフォルト: 現在のworktree）\n3. 上記コマンド形式でCodexを実行\n4. 結果をユーザーに報告\n\n## 注意事項\n\n- `--sandbox read-only` により、コードの変更は行われない（安全）\n- 結果は読み取り専用で分析結果のみ出力\n- 日本語でのリクエストに対応\n- 大規模なコードベースでも効率的に分析可能\n"},"lastSynced":"2026-03-08T02:04:10.608Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing automated code review and examination capabilities via OpenAI Codex CLI.","zh":"非常适合需要通过OpenAI Codex CLI自动化代码审查和检查功能的代码分析代理。","ja":"OpenAI Codex CLIを介した自動コードレビューおよび検査機能を必要とするコード分析エージェントに最適です。","ko":"OpenAI Codex CLI를 통해 자동 코드 리뷰 및 검사 기능을 필요로 하는 코드 분석 에이전트에 적합합니다.","es":"Perfecto para agentes de análisis de código que necesitan capacidades de revisión y examen de código automatizadas a través de OpenAI Codex CLI.","fr":"Parfait pour les agents d''analyse de code nécessitant des capacités de révision et d''examen de code automatisées via OpenAI Codex CLI.","de":"Perfekt für Code-Analyse-Agents, die automatisierte Code-Überprüfungs- und Untersuchungsfunktionen über OpenAI Codex CLI benötigen.","pt":"Perfeito para Agentes de Análise de Código que precisam de revisão e exame de código automatizados via OpenAI Codex CLI.","ru":"Идеально подходит для агентов анализа кода, которым необходимы автоматизированные возможности проверки и изучения кода через OpenAI Codex CLI.","ar":"مثالي للوكلاء قائمين على تحليل الشفرة الذين يحتاجون إلى تقييم و فحص آلي للشفرة من خلال واجهة سطر الأوامر OpenAI Codex."},"recommendation":{"en":"Empowers agents to execute comprehensive code analysis using the OpenAI Codex CLI, providing efficient project examination with features like fully automatic mode, sandboxed environments for secure analysis, and support for Japanese requests.","zh":"赋予代理执行全面代码分析的能力，使用OpenAI Codex CLI提供高效的项目检查，具有完全自动模式、安全分析的沙盒环境以及对日语请求的支持等功能。","ja":"OpenAI Codex CLIを使用して、完全自動モード、安全な分析のためのサンドボックス環境、日本語のリクエストに対するサポートなどの機能を備えた効率的なプロジェクトの検査を提供することで、エージェントに包括的なコード分析を実行する機能を付与します。","ko":"OpenAI Codex CLI를 사용하여 완전 자동 모드, 보안 분석을 위한 샌드박스 환경, 일본어 요청 지원 등의 기능을 제공하여 효율적인 프로젝트 검사를 제공함으로써 에이전트가 포괄적인 코드 분석을 실행할 수 있는 기능을 부여합니다.","es":"Habilita a los agentes a ejecutar un análisis de código integral utilizando OpenAI Codex CLI, proporcionando un examen de proyecto eficiente con características como modo completamente automático, entornos aislados para un análisis seguro y soporte para solicitudes en japonés.","fr":"Permet aux agents d''exécuter une analyse de code complète en utilisant OpenAI Codex CLI, offrant un examen de projet efficace avec des fonctionnalités comme le mode entièrement automatique, des environnements sandbox pour une analyse sécurisée et un support pour les requêtes en japonais.","de":"Ermöglicht es Agents, eine umfassende Code-Analyse mithilfe von OpenAI Codex CLI durchzuführen, wodurch eine effiziente Projektprüfung mit Funktionen wie vollautomatischem Modus, sandboxten Umgebungen für sichere Analyse und Unterstützung für japanische Anfragen bereitgestellt wird.","pt":"Habilita os agentes a executar uma análise de código abrangente usando o OpenAI Codex CLI, fornecendo exame de projeto eficiente com recursos como modo totalmente automático, ambientes isolados para análise segura e suporte a solicitações em japonês.","ru":"Наделяет агентов возможностью выполнять комплексный анализ кода с помощью OpenAI Codex CLI, обеспечивая эффективный анализ проекта с функциями, такими как полностью автоматический режим, изолированные среды для безопасного анализа и поддержка запросов на японском языке.","ar":"يمنح الوكلاء القدرة على تنفيذ تحليل شفرة شامل باستخدام واجهة سطر أوامر OpenAI Codex، مما يوفر فحص پروژه فعال مع ميزات مثل الوضع التلقائي الكامل وبيئات معزولة لتقييم آمن ودعم الطلبات اليابانية."},"useCases":{"en":["Automating code reviews for pull requests with detailed feedback on type safety and best practices","Analyzing project directories for potential issues and vulnerabilities","Generating reports on code quality and adherence to coding standards"],"zh":["自动执行拉取请求的代码审查，并提供有关类型安全性和最佳实践的详细反馈","分析项目目录以查找潜在问题和漏洞","生成有关代码质量和遵循编码标准的报告"],"ja":["プルリクエストのコードレビューを自動化し、型安全性とベストプラクティスに関する詳細なフィードバックを提供する","プロジェクトディレクトリを分析して潜在的な問題と脆弱性を特定する","コード品質とコーディング規約への準拠に関するレポートを生成する"],"ko":["풀 리クエ스트에 대한 코드 리뷰를 자동화하고, 유형 안전성 및 모범 사례에 대한 자세한 피드백을 제공합니다","프로젝트 디렉토리를 분석하여 잠재적인 문제 및 취약점을 식별합니다","코드 품질 및 코딩 표준 준수에 대한 보고서를 생성합니다"],"es":["Automatizar las revisiones de código para solicitudes de extracción con comentarios detallados sobre la seguridad de los tipos y las mejores prácticas","Analizar directorios de proyectos en busca de posibles problemas y vulnerabilidades","Generar informes sobre la calidad del código y el cumplimiento de los estándares de codificación"],"fr":["Automatiser les examens de code pour les demandes d''extraction avec des commentaires détaillés sur la sécurité des types et les meilleures pratiques","Analyser les répertoires de projets pour détecter les problèmes et vulnérabilités potentiels","Générer des rapports sur la qualité du code et le respect des normes de codage"],"de":["Automatisieren von Code-Reviews für Pull-Requests mit detaillierten Kommentaren zu Typsicherheit und Best Practices","Analysieren von Projektverzeichnissen auf potenzielle Probleme und Schwachstellen","Erstellen von Berichten über die Code-Qualität und die Einhaltung von Codierungsstandards"],"pt":["Automatizar análises de código para solicitações de pull com feedback detalhado sobre segurança de tipo e boas práticas","Analizar diretórios de projeto para problemas e vulnerabilidades potenciais","Gerar relatórios sobre qualidade de código e aderência a padrões de codificação"],"ru":["Автоматизировать проверку кода для запросов на слияние с подробными отзывами о безопасности типов и лучших практиках","Анализировать директории проекта для потенциальных проблем и уязвимостей","Генерировать отчеты о качестве кода и соблюдении стандартов кодирования"],"ar":["تأتمتة تقييم الشفرة لطلبات الدمج مع تغذية راجعة مفصلة حول سلامة النوع وأفضل الممارسات","تحليل دليل المشروع لمشاكل وثغرات محتملة","توليد تقارير حول جودة الشفرة والامتثال لمعايير البرمجة"]},"limitations":{"en":["Requires access to the OpenAI Codex CLI","Dependent on the capabilities and limitations of the OpenAI Codex CLI","Needs specification of the project directory for analysis"],"zh":["需要访问OpenAI Codex CLI","依赖于OpenAI Codex CLI的功能和限制","需要指定项目目录以进行分析"],"ja":["OpenAI Codex CLIへのアクセスが必要","OpenAI Codex CLIの機能と制限に依存する","分析のためにプロジェクトディレクトリの指定が必要"],"ko":["OpenAI Codex CLI에 대한 액세스가 필요합니다","OpenAI Codex CLI의 기능 및 제한에 의존합니다","분석을 위해 프로젝트 디렉토리의 지정이 필요합니다"],"es":["Requiere acceso a OpenAI Codex CLI","Depende de las capacidades y limitaciones de OpenAI Codex CLI","Necesita la especificación del directorio del proyecto para el análisis"],"fr":["Nécessite un accès à OpenAI Codex CLI","Dépend des capacités et des limites de OpenAI Codex CLI","Nécessite la spécification du répertoire de projet pour l''analyse"],"de":["Erfordert Zugriff auf OpenAI Codex CLI","Hängt von den Fähigkeiten und Einschränkungen von OpenAI Codex CLI ab","Benötigt die Angabe des Projektverzeichnisses für die Analyse"],"pt":["Requer acesso ao OpenAI Codex CLI","Depende das capacidades e limitações do OpenAI Codex CLI","Necessita de especificação do diretório do projeto para análise"],"ru":["Требует доступа к OpenAI Codex CLI","Зависит от возможностей и ограничений OpenAI Codex CLI","Требует указания директории проекта для анализа"],"ar":["يتطلب الوصول إلى واجهة سطر الأوامر OpenAI Codex","يعتمد على قدرات وقيود واجهة سطر الأوامر OpenAI Codex","يحتاج إلى تحديد دليل المشروع لتقييم"]},"version":4},"contentHash":"44136fb3de359d79fc8f01c13459d1c6e1ad1e6b11df849ae8683d7cf519b786","qualityScore":30}');
