INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Umisyo/Lorepedia/codex', 'codex', 'Umisyo', 'Lorepedia', 'community', 'codex Umisyo Lorepedia community Codex is a shared world creation support tool that utilizes the OpenAI Codex CLI for automated code review and analysis, benefiting developers with efficient project examination. Codex是使用OpenAI Codex CLI进行代码审查和分析的工具，支持完全自动模式和安全的读取专用沙盒 CodexはOpenAI Codex CLIを使用してコードレビュー・分析を実行するスキルで、完全自動モードと読み取り専用サンドボックスをサポートする Codex는 OpenAI Codex CLI를 사용하여 코드 리뷰 및 분석을 수행하는 툴로, 완전 자동 모드와 안전한 읽기 전용 샌드박스를 지원합니다 Codex es una herramienta de análisis de código que utiliza OpenAI Codex CLI para revisar y analizar código de manera automática Codex est un outil d''analyse de code qui utilise OpenAI Codex CLI pour réviser et analyser du code de manière automatisée Codex ist ein Code-Analyse-Tool, das OpenAI Codex CLI verwendet, um Code automatisch zu überprüfen und zu analysieren O Codex é uma ferramenta de criação de mundo compartilhado que utiliza a CLI do OpenAI Codex para análise de código. Ele permite a execução de comandos como `codex exec` para análise de código em projetos Codex - это инструмент создания общего мира, использующий CLI OpenAI Codex для анализа кода. Он позволяет выполнять команды, такие как `codex exec`, для анализа кода в проектах Codex هي أداة إنشاء عالم مشترك تستخدم واجهة سطر الأوامر OpenAI Codex لتحليل الكود. أنها تسمح بتنفيذ أوامر مثل `codex exec` لتحليل الكود في المشاريع how to use codex codex setup guide OpenAI Codex CLI tutorial codex alternative codex vs code review tools codex install automated code review with codex codex for developers codex AI agent skill OpenAI Codex CLI 代码审查 代码分析 AI代码审查工具 代码安全性检查 代码质量检查 自动代码审查 AI代码分析工具 Executes code review using the OpenAI Codex CLI with the `codex exec` command Supports fully automatic mode with the `--full-auto` parameter Utilizes a read-only sandbox for safe analysis with `--sandbox read-only` Allows specification of the project directory with `--cd <project_directory>` Accepts Japanese requests for code review with `<request>` Codex is an AI agent skill that leverages the OpenAI Codex CLI for automated code review and analysis, supporting developers in identifying issues within their projects.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rockorager/ziglint/release', 'community', 'rockorager', 'ziglint', 'rockorager/ziglint', 'release', 0, 0, 30, '2026-03-08T01:57:15.326Z', '2026-03-08T02:04:12.873Z', 'c3b0614fc758957c2f4175bbe30ccc5b90d8f5a97a113d87fc7580ec21d71264', '{"id":"rockorager/ziglint/release","name":"release","description":{"en":"The release skill provides opinionated linting to keep your AI agent in check, benefiting developers with automated version control and release notes management.","zh":"使用opinionated linting发布AI工具，包括ziglint和版本更新","ja":"AIエージェントのリリース方法を学び、ziglintとバージョン更新の詳細を確認する","ko":"AI 에이전트 릴리즈 방법을 알아보고, ziglint 및 버전 업데이트에 대한 세부 정보를 확인하십시오","es":"La función de release permite una configuración y actualización sencilla de tus agentes de AI","fr":"La fonctionnalité release permet une configuration et une mise à jour simples de vos outils d''IA","de":"Die Release-Funktion ermöglicht eine einfache Konfiguration und Aktualisierung Ihrer KI-Agenten","pt":"O lançamento de ferramentas de inteligência artificial é um processo que envolve atualização de versão e criação de notas de lançamento. Aprenda a fazer isso corretamente.","ru":"Выпуск ИИ Агентов - это процесс, включающий обновление версии и создание заметок о выпуске. Узнайте, как это сделать правильно.","ar":"إصدار أدوات الذكاء الاصطناعي هو عملية تتضمن تحديث الإصدار وإنشاء ملاحظات الإصدار. تعلم كيفية القيام بذلك بشكل صحيح."},"seo":{"title":{"en":"Release: Opinionated Linting Setup Guide | AI Agent Skill","zh":"AI工具发布设置指南","ja":"AIエージェントのリリースベストプラクティス","ko":"AI 에이전트 릴리즈 설정 가이드","es":"Guía de configuración de release para agentes de AI","fr":"Guide de mise en place de la fonctionnalité release pour ...","de":"Release-Setup-Anleitung für KI-Agenten","pt":"Guia de Configuração de Lançamento de Ferramentas de Inte...","ru":"Настройка ИИ Агентов: Руководство по выпуску","ar":"