INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rockorager/ziglint/release', 'release', 'rockorager', 'ziglint', 'community', 'release rockorager ziglint community The release skill provides opinionated linting to keep your AI agent in check, benefiting developers with automated version control and release notes management. 使用opinionated linting发布AI工具，包括ziglint和版本更新 AIエージェントのリリース方法を学び、ziglintとバージョン更新の詳細を確認する AI 에이전트 릴리즈 방법을 알아보고, ziglint 및 버전 업데이트에 대한 세부 정보를 확인하십시오 La función de release permite una configuración y actualización sencilla de tus agentes de AI La fonctionnalité release permet une configuration et une mise à jour simples de vos outils d''IA Die Release-Funktion ermöglicht eine einfache Konfiguration und Aktualisierung Ihrer KI-Agenten O lançamento de ferramentas de inteligência artificial é um processo que envolve atualização de versão e criação de notas de lançamento. Aprenda a fazer isso corretamente. Выпуск ИИ Агентов - это процесс, включающий обновление версии и создание заметок о выпуске. Узнайте, как это сделать правильно. إصدار أدوات الذكاء الاصطناعي هو عملية تتضمن تحديث الإصدار وإنشاء ملاحظات الإصدار. تعلم كيفية القيام بذلك بشكل صحيح. how to use release skill release skill setup guide git tag and push tutorial automated linting for AI agents release notes management best practices release skill vs other linting tools install release skill for AI development what is release skill in AI development AI工具发布 opinionated linting ziglint 版本更新 代码检查 git标签 发布说明 AI开发 代码质量 Updates version in build.zig.zon files Generates release notes in markdown format at docs/releases/vX.Y.Z.md Commits changes and tags releases using git tag and push Supports automated linting for Zig code Creates markdown files for release notes with breaking changes and what''s new sections Release is an AI agent skill that enforces consistent coding standards through automated linting and release management using git and markdown files');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('amyodov/pytest-claude-agent-sdk/complete-checkpoint', 'community', 'amyodov', 'pytest-claude-agent-sdk', 'amyodov/pytest-claude-agent-sdk', 'complete-checkpoint', 0, 0, 30, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:13.456Z', '373826b80b4b1b7654114a0fd84c6941a791596389a3d939046694c2c285bd08', '{"id":"amyodov/pytest-claude-agent-sdk/complete-checkpoint","name":"complete-checkpoint","description":{"en":"The complete-checkpoint skill automates testing for developers, integrating Claude Code with pytests for efficient linting, formatting, and testing. It benefits developers working with Python and pytest.","zh":"Complete Checkpoint 是一个用于运行 lint、格式化和测试的工具，确保 Claude Code 代码的质量","ja":"Complete Checkpoint は、 Claude Code コードの品質を確保するために lint、フォーマット、テストを実行するツールです","ko":"완료 체크포인트는 Claude Code 코드의 품질을 보장하기 위해 lint, 형식 및 테스트를 실행하는 도구입니다","es":"El punto de control completo es una herramienta que permite a los desarrolladores ejecutar comprobaciones de lint y formato, así como pruebas de pytests, para asegurarse de que su código sea correcto y esté listo para su implementación","fr":"Le point de contrôle complet est un outil qui permet aux développeurs d''exécuter des vérifications de lint et de format, ainsi que des tests pytests, pour s''assurer que leur code est correct et prêt à être mis en œuvre","de":"Der vollständige Checkpoint ist ein Tool, das es Entwicklern ermöglicht, Lint- und Format-Checks sowie pytests-Tests auszuführen, um sicherzustellen, dass ihr Code korrekt ist und bereit für die Implementierung ist","pt":"O Complete Checkpoint é uma ferramenta que executa checks de lint e format e testes com pytest para garantir a qualidade do código","ru":"Complete Checkpoint - это инструмент, который выполняет проверки lint и формат, а также тесты с pytest для обеспечения качества кода","ar":"Complete Checkpoint هو أداة تقوم بتشغيل فحص lint وformat واختبارات مع pytest لضمان جودة الكود"},"seo":{"title":{"en":"complete-checkpoint: Automated Testing Setup Guide | AI A...","zh":"完整检查点设置指南 - Claude Code AI工具","ja":"Complete Checkpoint セットアップガイド - Claude Code AIエージェント","ko":"완료 체크포인트 설정 가이드 - Claude Code AI 에이전트","es":"Configuración de Punto de Control Completo: Guía de Imple...","fr":"Configuration de Point de Contrôle Complet : Guide d''Inst...","de":"Vollständiger Checkpoint-Setup: Leitfaden für Entwickler","pt":"Guia de Configuração do Complete Checkpoint para Pytests","ru":"Настройка Complete Checkpoint для Pytest: ИИ Агенты","ar":"إعداد Complete Checkpoint لpytest: أدوات الذكاء الاصطناعي"},"description":{"en":"Streamline your testing workflow with complete-checkpoint. Learn how to integrate Claude Code with pytests and automate checks for optimal results. Get start...","zh":"了解如何使用 Claude Code AI工具进行完整检查点，包括 lint、格式化和测试","ja":" Claude Code AIエージェントを使用して完全チェックポイントを実行する方法について学びます","ko":"Claude Code AI 에이전트를 사용하여 완료 체크포인트를 실행하는 방법에 대해 알아보세요","es":"Aprende a utilizar Claude Code en tus pruebas de pytests y a probar tus propios agentes de código con este punto de control completo","fr":"Découvrez comment utiliser Claude Code dans vos tests pytests et tester vos propres agents de code avec ce point de contrôle complet","de":"Erfahren Sie, wie Sie Claude Code in Ihren pytests verwenden und Ihre eigenen Code-Agents mit diesem vollständigen Checkpoint testen","pt":"Aprenda a configurar o Complete Checkpoint para executar testes e lint em seus projetos Python com pytest e Claude Code","ru":"Узнайте, как настроить Complete Checkpoint для запуска тестов и lint в ваших проектах Python с pytest и Claude Code","ar":"تعلم كيفية إعداد Complete Checkpoint لتشغيل الاختبارات وlint في مشاريع Python الخاصة بك مع pytest وClaude Code"},"definition":{"en":"complete-checkpoint is a skill that automates the testing process using Claude Code and pytests, ensuring code quality through linting, formatting, and testing.","zh":"Complete Checkpoint 是一个 Claude Code AI工具，用于运行一系列检查以确保代码质量","ja":"Complete Checkpoint は、 Claude Code コードの品質を確保するために一連のチェックを実行する AIエージェントです","ko":"완료 체크포인트는 Claude Code 에이전트의 코드 품질을 보장하기 위해 일련의 확인을 실행하는 AI 에이전트입니다","es":"Un punto de control completo es una herramienta de desarrollo que automatiza la ejecución de comprobaciones de código y pruebas para asegurarse de su calidad","fr":"Un point de contrôle complet est un outil de développement qui automatise l''exécution de vérifications de code et de tests pour assurer sa qualité","de":"Ein vollständiger Checkpoint ist ein Entwicklungstool, das die Ausführung von Code-Checks und -Tests automatisiert, um dessen Qualität sicherzustellen","pt":"O que é Complete Checkpoint? É uma ferramenta de verificação de código que executa lint e testes automatizados","ru":"Что такое Complete Checkpoint? Это инструмент проверки кода, который выполняет lint и автоматические тесты","ar":"ما هو Complete Checkpoint؟ إنه أداة لفحص الكود التي تقوم بتشغيل lint واختبارات آلية"},"features":{"en":["Runs lint and format checks using uv run ruff check and ruff format","Executes tests with pytest using uv run pytest -v","Provides a one-liner command for combined checks","Automatically fixes issues and re-runs checks upon failure","Briefly reports success and continues with a summary upon passing checks"],"zh":["运行 lint 和格式化检查","执行 pytest 测试","支持一键运行所有检查","自动修复代码问题","生成测试报告","集成 Claude Code AI工具"],"ja":["lint とフォーマットのチェックを実行","pytest テストを実行","一連のチェックを一括実行","コードの問題を自動修復","テストレポートを生成","Claude Code AIエージェントと統合"],"ko":["lint 및 형식 확인을 실행","pytest 테스트를 실행","모든 확인을 한 번에 실행","코드 문제를 자동으로 수정","테스트 보고서를 생성","Claude Code AI 에이전트와 통합"],"es":["Ejecución de comprobaciones de lint y formato con ruff","Ejecución de pruebas de pytests con pytest","Compatibilidad con Claude Code para pruebas personalizadas","Informes de éxito y resumen de resultados","Capacidad para corregir errores y volver a ejecutar comprobaciones"],"fr":["Exécution de vérifications de lint et de format avec ruff","Exécution de tests pytests avec pytest","Compatibilité avec Claude Code pour des tests personnalisés","Rapports de succès et résumé des résultats","Capacité à corriger les erreurs et à réexécuter les vérifications"],"de":["Ausführung von Lint- und Format-Checks mit ruff","Ausführung von pytests-Tests mit pytest","Kompatibilität mit Claude Code für benutzerdefinierte Tests","Berichte über Erfolge und Zusammenfassung der Ergebnisse","Fähigkeit, Fehler zu korrigieren und Checks erneut auszuführen"],"pt":["Executa lint e format com ruff","Executa testes com pytest","Fornece um one-liner para execução de checks","Executa checks sem permissão","Relata sucesso ou falha nos checks","Reexecuta checks após correção de erros"],"ru":["Выполняет lint и формат с помощью ruff","Выполняет тесты с pytest","Предоставляет one-liner для выполнения проверок","Выполняет проверки без разрешения","Отчитывается о успехе или неудаче проверок","Повторно выполняет проверки после исправления ошибок"],"ar":["يقوم بتشغيل lint وformat مع ruff","يقوم بتشغيل الاختبارات مع pytest","يوفر one-liner لتشغيل الفحوصات","يقوم بتشغيل الفحوصات بدون إذن","يبلغ عن نجاح أو فشل الفحوصات","يعيد تشغيل الفحوصات بعد تصحيح الأخطاء"]},"keywords":{"en":["how to use complete-checkpoint","complete-checkpoint setup guide","automated testing with pytest","Claude Code integration","complete-checkpoint vs pytest","complete-checkpoint install","what is complete-checkpoint","complete-checkpoint alternative","pytest automation"],"zh":["Claude Code AI工具","完整检查点","lint 和格式化","pytest 测试","代码质量","AI开发工具","自动化测试","代码检查"," Claude Code 集成"],"ja":["Claude Code AIエージェント","完全チェックポイント","lint とフォーマット","pytest テスト","コード品質","AI開発ツール","自動テスト","コードチェック","Claude Code 統合"],"ko":["Claude Code AI 에이전트","완료 체크포인트","lint 및 형식","pytest 테스트","코드 품질","AI 개발 도구","자동 테스트","코드 확인","Claude Code 통합"],"es":["punto de control completo","Claude Code","pruebas de pytests","ruff","pytest","desarrollo de software","herramientas de desarrollo","agentes de código","IA herramientas"],"fr":["point de contrôle complet","Claude Code","tests pytests","ruff","pytest","développement de logiciels","outils de développement","agents de code","outils d''IA"],"de":["vollständiger Checkpoint","Claude Code","pytests-Tests","ruff","pytest","Software-Entwicklung","Entwicklungstools","Code-Agents","KI-Tools"],"pt":["complete checkpoint","pytest","ruff","lint","format","testes automatizados","ferramentas de desenvolvimento","qualidade de código","desenvolvimento de software"],"ru":["complete checkpoint","pytest","ruff","lint","формат","автоматические тесты","инструменты разработки","качество кода","разработка программного обеспечения","ИИ Агенты"],"ar":["complete checkpoint","pytest","ruff","lint","format","اختبارات آلية","أدوات التطوير","جودة الكود","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"amyodov","repo":"pytest-claude-agent-sdk","repoPath":"amyodov/pytest-claude-agent-sdk","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.361Z","topics":[],"category":"community","skillMd":{"name":"complete-checkpoint","description":"Run after completing significant work — implementing a feature, fixing a bug, refactoring, or any substantial code changes. Proactively ensure code quality before reporting work as done.","bodyPreview":"# Complete Checkpoint\n\nAfter finishing a significant piece of work, run these checks:\n\n## 1. Lint and Format\n\n```bash\nuv run ruff check --fix && uv run ruff format\n```\n\n## 2. Run Tests\n\n```bash\nuv run pytest -v\n```\n\n## One-Liner\n\n```bash\nuv run ruff check --fix && uv run ruff format && uv run pytest -v\n```\n\n## Behavior\n\n1. Run the checks without asking permission\n2. If everything passes: briefly report success, continue with summary\n3. If anything fails: fix the issues, then re-run checks\n4. Don","body":"# Complete Checkpoint\n\nAfter finishing a significant piece of work, run these checks:\n\n## 1. Lint and Format\n\n```bash\nuv run ruff check --fix && uv run ruff format\n```\n\n## 2. Run Tests\n\n```bash\nuv run pytest -v\n```\n\n## One-Liner\n\n```bash\nuv run ruff check --fix && uv run ruff format && uv run pytest -v\n```\n\n## Behavior\n\n1. Run the checks without asking permission\n2. If everything passes: briefly report success, continue with summary\n3. If anything fails: fix the issues, then re-run checks\n4. Don''t report work as \"done\" until checks pass\n"},"lastSynced":"2026-03-08T02:04:13.456Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing automated testing and linting capabilities with pytest and ruff.","zh":"适合需要使用pytest和ruff进行自动化测试和linting的Python开发代理。","ja":"pytestとruffを使用した自動テストとlinting機能が必要なPython開発エージェントに最適です。","ko":"pytest와 ruff를 사용하여 자동 테스트 및 linting 기능이 필요한 Python 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo de Python que necesitan pruebas automatizadas y capacidades de linting con pytest y ruff.","fr":"Parfait pour les Agents de Développement Python nécessitant des tests automatisés et des capacités de linting avec pytest et ruff.","de":"Perfekt für Python-Entwicklungsagenten, die automatisierte Tests und Linting-Funktionen mit pytest und ruff benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Python que necessitam de testes automatizados e capacidades de linting com pytest e ruff.","ru":"Идеально для агентов разработки Python, которым требуются автоматизированное тестирование и возможности linting с помощью pytest и ruff.","ar":"مثالي للوكلاء الذين يحتاجون إلى اختبارات自动ية وقدرات linting مع pytest و ruff"},"recommendation":{"en":"Empowers agents to automate testing, linting, and formatting using ruff and pytest, ensuring efficient and high-quality code validation with --fix and -v flags.","zh":"赋予代理自动化测试、linting和格式化的能力，使用ruff和pytest，确保高效和高质量的代码验证，使用--fix和-v标志。","ja":"ruffとpytestを使用して、エージェントに自動テスト、linting、フォーマットの機能を与え、--fixと-vフラグを使用して効率的かつ高品質のコード検証を実現します。","ko":"ruff와 pytest를 사용하여 에이전트에 자동 테스트, linting, 포맷팅 기능을 부여하여 --fix와 -v 플래그를 사용하는 효율적이고 고품질의 코드 검증을 보장합니다.","es":"Habilita a los agentes a automatizar las pruebas, el linting y el formato utilizando ruff y pytest, garantizando una validación de código eficiente y de alta calidad con los indicadores --fix y -v.","fr":"Permet aux agents d''automatiser les tests, le linting et le formatage en utilisant ruff et pytest, garantissant une validation de code efficace et de haute qualité avec les indicateurs --fix et -v.","de":"Ermächtigt die Agenten, Tests, Linting und Formatierung mit ruff und pytest zu automatisieren, um eine effiziente und hochwertige Code-Validierung mit den Flags --fix und -v zu gewährleisten.","pt":"Habilita os agentes a automatizar testes, linting e formatação usando ruff e pytest, garantindo uma validação de código eficiente e de alta qualidade com flags --fix e -v.","ru":"Наделяет агентов возможностью автоматизировать тестирование, linting и форматирование с помощью ruff и pytest, обеспечивая эффективную и высококачественную проверку кода с флагами --fix и -v.","ar":"تمكين الوكلاء من توفير اختبارات وlinting وتنسيق تلقائي باستخدام ruff و pytest، مما يضمن التحقق الفعال والعالية الجودة للكود باستخدام --fix و -v الأعلام"},"useCases":{"en":["Automating code linting and formatting with ruff","Running comprehensive tests with pytest","Validating code quality before deployment"],"zh":["使用ruff进行代码linting和格式化","使用pytest运行全面的测试","部署前验证代码质量"],"ja":["ruffを使用したコードのlintingとフォーマット","pytestを使用した包括的なテストの実行","デプロイ前のコード品質の検証"],"ko":["ruff를 사용한 코드 linting과 포맷팅","pytest를 사용한 종합적인 테스트 실행","배포 전 코드 품질 검증"],"es":["Automatizar el linting y el formato de código con ruff","Ejecutar pruebas comprehensivas con pytest","Validar la calidad del código antes de la implementación"],"fr":["Automatiser le linting et le formatage de code avec ruff","Exécuter des tests complets avec pytest","Valider la qualité du code avant le déploiement"],"de":["Automatisieren des Code-Linting und -Formatierens mit ruff","Ausführen umfassender Tests mit pytest","Überprüfen der Code-Qualität vor der Bereitstellung"],"pt":["Automatizar a verificação de código e formatação com ruff","Executar testes abrangentes com pytest","Validar a qualidade do código antes da implantação"],"ru":["Автоматизировать проверку кода и форматирование с помощью ruff","Запускать комплексные тесты с помощью pytest","Проверять качество кода перед развертыванием"],"ar":["توفير اختبارات وتنسيق تلقائي للكود مع ruff","تشغيل اختبارات شاملة مع pytest","التحقق من جودة الكود قبل النشر"]},"limitations":{"en":["Requires pytest and ruff installation","Python environment only","Limited to command-line interface"],"zh":["需要安装pytest和ruff","仅限Python环境","仅限命令行接口"],"ja":["pytestとruffのインストールが必要","Python環境のみ","コマンドラインインターフェイスのみ"],"ko":["pytest와 ruff 설치가 필요함","Python 환경만 지원","명령行 인터페이스만 지원"],"es":["Requiere la instalación de pytest y ruff","Entorno de Python solo","Limitado a la interfaz de línea de comandos"],"fr":["Nécessite l''installation de pytest et ruff","Environnement Python uniquement","Limité à l''interface en ligne de commande"],"de":["Erfordert die Installation von pytest und ruff","Nur Python-Umgebung","Begrenzt auf die Kommandozeilenoberfläche"],"pt":["Requer a instalação do pytest e ruff","Ambiente Python apenas","Limitado à interface de linha de comando"],"ru":["Требует установки pytest и ruff","Только среда Python","Ограничен интерфейсом командной строки"],"ar":["يتطلب تثبيت pytest و ruff","بيئة بايثون فقط","محدود بالواجهة السطرية"]},"version":4},"contentHash":"373826b80b4b1b7654114a0fd84c6941a791596389a3d939046694c2c285bd08","qualityScore":30}');
