INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('amyodov/pytest-claude-agent-sdk/complete-checkpoint', 'complete-checkpoint', 'amyodov', 'pytest-claude-agent-sdk', 'community', 'complete-checkpoint amyodov pytest-claude-agent-sdk community The complete-checkpoint skill automates testing for developers, integrating Claude Code with pytests for efficient linting, formatting, and testing. It benefits developers working with Python and pytest. Complete Checkpoint 是一个用于运行 lint、格式化和测试的工具，确保 Claude Code 代码的质量 Complete Checkpoint は、 Claude Code コードの品質を確保するために lint、フォーマット、テストを実行するツールです 완료 체크포인트는 Claude Code 코드의 품질을 보장하기 위해 lint, 형식 및 테스트를 실행하는 도구입니다 El punto de control completo es una herramienta que permite a los desarrolladores ejecutar comprobaciones de lint y formato, así como pruebas de pytests, para asegurarse de que su código sea correcto y esté listo para su implementación Le point de contrôle complet est un outil qui permet aux développeurs d''exécuter des vérifications de lint et de format, ainsi que des tests pytests, pour s''assurer que leur code est correct et prêt à être mis en œuvre Der vollständige Checkpoint ist ein Tool, das es Entwicklern ermöglicht, Lint- und Format-Checks sowie pytests-Tests auszuführen, um sicherzustellen, dass ihr Code korrekt ist und bereit für die Implementierung ist O Complete Checkpoint é uma ferramenta que executa checks de lint e format e testes com pytest para garantir a qualidade do código Complete Checkpoint - это инструмент, который выполняет проверки lint и формат, а также тесты с pytest для обеспечения качества кода Complete Checkpoint هو أداة تقوم بتشغيل فحص lint وformat واختبارات مع pytest لضمان جودة الكود how to use complete-checkpoint complete-checkpoint setup guide automated testing with pytest Claude Code integration complete-checkpoint vs pytest complete-checkpoint install what is complete-checkpoint complete-checkpoint alternative pytest automation Claude Code AI工具 完整检查点 lint 和格式化 pytest 测试 代码质量 AI开发工具 自动化测试 代码检查 Claude Code 集成 Runs lint and format checks using uv run ruff check and ruff format Executes tests with pytest using uv run pytest -v Provides a one-liner command for combined checks Automatically fixes issues and re-runs checks upon failure Briefly reports success and continues with a summary upon passing checks complete-checkpoint is a skill that automates the testing process using Claude Code and pytests, ensuring code quality through linting, formatting, and testing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('moonbit-community/fastcc/moonbit-lang', 'community', 'moonbit-community', 'fastcc', 'moonbit-community/fastcc', 'moonbit-lang', 0, 0, 30, '2026-03-08T01:57:15.371Z', '2026-03-08T02:04:27.408Z', '7513df6b34bcf22dfd694441fa6c59d539e200e475f97f8c6d393925fa81c536', '{"id":"moonbit-community/fastcc/moonbit-lang","name":"moonbit-lang","description":{"en":"The moonbit-lang skill provides a C compiler optimized for speed, written in MoonBit. It benefits developers seeking efficient compilation and official package support.","zh":"MoonBit 语言是一种优化了 C 编译器的语言，具有高速的特点，开发者可以通过官方包和文档快速上手","ja":"MoonBit言語は、Cコンパイラを最適化した言語で、高速な特徴を持っています。開発者は公式パッケージとドキュメントを使用して迅速に始めることができます","ko":"MoonBit 언어는 C 컴파일러를 최적화한 언어로,高速의 특징을 가지고 있습니다. 개발자는 공식 패키지와 문서를 통해 빠르게 시작할 수 있습니다","es":"Moonbit-lang es un compilador C optimizado para velocidad, escrito en MoonBit. Ofrece paquetes oficiales y capacidades de programación avanzadas.","fr":"Moonbit-lang est un compilateur C optimisé pour la vitesse, écrit en MoonBit. Il propose des packages officiels et des capacités de programmation avancées.","de":"Moonbit-lang ist ein für Geschwindigkeit optimierter C-Compiler, der in MoonBit geschrieben ist. Er bietet offizielle Pakete und erweiterte Programmierfunktionen.","pt":"O Moonbit-Lang é um compilador C otimizado para velocidade, desenvolvido em MoonBit. Ele oferece recursos avançados para desenvolvedores.","ru":"Moonbit-Lang - это оптимизированный компилятор C, разработанный на MoonBit. Он предлагает продвинутые функции для разработчиков.","ar":"Moonbit-Lang هو مترجم سي محسّن للسرعة، مطوّر بلغة MoonBit. يقدّم ميزات متقدمة للمطورين."},"seo":{"title":{"en":"moonbit-lang: Optimized C Compiler Setup Guide | AI Agent...","zh":"MoonBit 语言优化 C 编译器快速入门","ja":"MoonBit言語による高速Cコンパイラの設定ガイド","ko":"MoonBit 언어로 구현된高速 C 컴파일러 설정 가이드","es":"Guía de configuración de mo