INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('moonbit-community/fastcc/moonbit-lang', 'moonbit-lang', 'moonbit-community', 'fastcc', 'community', 'moonbit-lang moonbit-community fastcc community The moonbit-lang skill provides a C compiler optimized for speed, written in MoonBit. It benefits developers seeking efficient compilation and official package support. MoonBit 语言是一种优化了 C 编译器的语言，具有高速的特点，开发者可以通过官方包和文档快速上手 MoonBit言語は、Cコンパイラを最適化した言語で、高速な特徴を持っています。開発者は公式パッケージとドキュメントを使用して迅速に始めることができます MoonBit 언어는 C 컴파일러를 최적화한 언어로,高速의 특징을 가지고 있습니다. 개발자는 공식 패키지와 문서를 통해 빠르게 시작할 수 있습니다 Moonbit-lang es un compilador C optimizado para velocidad, escrito en MoonBit. Ofrece paquetes oficiales y capacidades de programación avanzadas. Moonbit-lang est un compilateur C optimisé pour la vitesse, écrit en MoonBit. Il propose des packages officiels et des capacités de programmation avancées. Moonbit-lang ist ein für Geschwindigkeit optimierter C-Compiler, der in MoonBit geschrieben ist. Er bietet offizielle Pakete und erweiterte Programmierfunktionen. O Moonbit-Lang é um compilador C otimizado para velocidade, desenvolvido em MoonBit. Ele oferece recursos avançados para desenvolvedores. Moonbit-Lang - это оптимизированный компилятор C, разработанный на MoonBit. Он предлагает продвинутые функции для разработчиков. Moonbit-Lang هو مترجم سي محسّن للسرعة، مطوّر بلغة MoonBit. يقدّم ميزات متقدمة للمطورين. how to use moonbit-lang moonbit-lang alternative moonbit-lang install what is moonbit-lang moonbit-lang vs GCC moonbit-lang setup guide moonbit-lang language reference moonbit-lang official packages MoonBit 语言 C 编译器优化 AI 编程语言 AIエージェント 编程语言比较 C 编译器设置 MoonBit 文档 Supports official packages maintained by the MoonBit team, including moonbitlang/x Provides extensive language references, including introduction, fundamentals, and methods Includes error-handling and derive capabilities for robust development Offers benchmarks and tests for performance evaluation Utilizes TOML parser for efficient configuration moonbit-lang is a C compiler optimized for speed, written in the MoonBit language, offering official packages and extensive language references.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('moonbitlang/website/blog-adding', 'community', 'moonbitlang', 'website', 'moonbitlang/website', 'blog-adding', 0, 0, 30, '2026-03-08T01:57:15.372Z', '2026-03-08T02:04:29.530Z', 'b680b9d858b12a0f1ece678ad0c10a780e16de58251951bed4ec7f19ad126766', '{"id":"moonbitlang/website/blog-adding","name":"blog-adding","description":{"en":"The blog-adding skill automates the creation of new blog posts, generating front matter and inserting cover images. This skill benefits developers and bloggers looking to streamline their content creation workflow.","zh":"本文介绍如何使用AI智能工具添加博客文章，包括创建博客文件夹、设置front matter和添加cover图像","ja":"この記事では、AIエージェントを使用してブログ投稿を追加する方法について説明します。ブログフォルダの作成、フロントマターの設定、カバーアイコンの追加など","ko":"이 문서는 AI 에이전트를 사용하여 블로그 게시물을 추가하는 방법에 대해 설명합니다. 블로그 폴더 생성, 프론트 매터 설정, 커버 이미지 추가 등","es":"La habilidad de agregar publicaciones de blog permite a los desarrolladores crear fácilmente nuevas entradas de blog con metadatos y contenido.","fr":"La compétence d''ajout de publications de blog permet aux développeurs de créer facilement de nouvelles entrées de blog avec des métadonnées et du contenu.","de":"Die Fähigkeit, Blogbeiträge hinzuzufügen, ermöglicht es Entwicklern, neue Blog-Einträge mit Metadaten und Inhalt leicht zu erstellen.","pt":"O blog-adding é uma habilidade que permite criar postagens de blog personalizadas com front matter, slug e imagens de capa","ru":"ИИ Агенты blog-adding позволяет создавать блог-посты с настраиваемым контентом и изображениями","ar":"أدوات الذكاء الاصطناعي بلوج-إضافة تمكنك من إضافة منشورات بلوج مخصصة مع بيانات التعريف الأمامية وسلاج وصور الغلاف"},"seo":{"title":{"en":"blog-adding: Automated Blog Post Setup Guide | AI Agent S...","zh":"AI智能工具博客添加设置指南","ja":"AIエージェントによるブログ投稿のベストプラクティス","ko":"AI 에이전트 블로그 추가 설정 가이드","es":"Guía de configuración para agregar publicaciones de blog ...","fr":"Guide d''installation pour ajouter des publications de blo...","de":"Einrichtungsleitfaden für das Hinzufügen von Blogbeiträge...","pt":"Guia de Configuração do blog-adding: Adicionando Postagen...","ru":"Настройка ИИ Агентов: blog-adding для создания блог-постов","ar":"دليل إضافة مدونة بلوج: إضافة منشورات بلوج بفعالية باستخدا..."},"description":{"en":"Discover how to streamline your blogging workflow with blog-adding, an AI agent skill that automates blog post creation - learn how to get started today!","zh":"了解如何使用AI智能工具添加博客文章，包括创建博客文件夹、front matter和cover图像","ja":"AIエージェントを使用してブログ投稿を追加する方法を学びます。ブログフォルダの作成、フロントマター、カバーアイコンなど","ko":"AI 에이전트를 사용하여 블로그 게시물을 추가하는 방법을 알아보세요. 블로그 폴더 생성, 프론트 매터, 커버 이미지 등","es":"Aprende a agregar publicaciones de blog de manera efectiva con nuestra herramienta de AI. Descubre cómo crear carpetas de blog, agregar metadatos y más.","fr":"Découvrez comment ajouter des publications de blog de manière efficace avec notre outil d''IA. Apprenez à créer des dossiers de blog, à ajouter des métadonnée...","de":"Erfahren Sie, wie Sie Blogbeiträge effektiv mit unserem KI-Tool hinzufügen. Entdecken Sie, wie Sie Blog-Ordner erstellen, Metadaten hinzufügen und mehr.","pt":"Aprenda a usar o blog-adding para criar postagens de blog personalizadas com front matter, slug e imagens de capa","ru":"Узнайте, как использовать ИИ Агенты для создания блог-постов с настраиваемым контентом и изображениями","ar":"تعرف على كيفية استخدام أدوات الذكاء الاصطناعي لإضافة منشورات بلوج مخصصة مع بيانات التعريف الأمامية وسلاج وصور الغلاف"},"definition":{"en":"blog-adding is a skill that automates the process of adding new blog posts, creating folders and files with front matter and cover images","zh":"博客添加是指使用AI智能工具创建新的博客文章，包括设置front matter和添加cover图像","ja":"ブログ追加とは、AIエージェントを使用して新しいブログ投稿を追加することであり、フロントマターの設定とカバーアイコンの追加が含まれます","ko":"블로그 추가는 AI 에이전트를 사용하여 새로운 블로그 게시물을 추가하는 것을 의미하며, 프론트 매터 설정과 커버 이미지 추가가 포함됩니다","es":"La habilidad de agregar publicaciones de blog es una función que permite a los desarrolladores crear y configurar nuevas entradas de blog con herramientas de AI.","fr":"La compétence d''ajout de publications de blog est une fonction qui permet aux développeurs de créer et de configurer de nouvelles entrées de blog avec des outils d''IA.","de":"Die Fähigkeit, Blogbeiträge hinzuzufügen, ist eine Funktion, die es Entwicklern ermöglicht, neue Blog-Einträge mit KI-Tools zu erstellen und zu konfigurieren.","pt":"O blog-adding é uma habilidade que permite criar postagens de blog com front matter, slug e imagens de capa","ru":"ИИ Агенты blog-adding - это функция, которая позволяет создавать блог-посты с настраиваемым контентом","ar":"بلوج-إضافة هو أداة ذكاء اصطناعي تمكنك من إضافة منشورات بلوج مخصصة مع بيانات التعريف الأمامية وسلاج وصور الغلاف"},"features":{"en":["Creates blog folders with names in the format YYYY-MM-DD-short-slug","Generates front matter with description, slug, image, and tags","Inserts cover images near the top of the blog post","Supports custom folder names and slugs","Automates the creation of index.md files with H1 titles"],"zh":["创建YYYY-MM-DD-short-slug格式的博客文件夹","设置front matter，包括描述、slug和标签","添加cover图像","使用Markdown语法创建博客内容","支持自定义博客文件夹名称和front matter"],"ja":["YYYY-MM-DD-short-slug形式のブログフォルダを作成","フロントマターを設定、説明、slug、タグを含む","カバーアイコンを追加","Markdown構文を使用してブログコンテンツを作成","カスタムブログフォルダ名とフロントマターをサポート"],"ko":["YYYY-MM-DD-short-slug 형식의 블로그 폴더 생성","프론트 매터 설정, 설명, slug, 태그 포함","커버 이미지 추가","Markdown 구문을 사용하여 블로그 콘텐츠 생성","사용자 정의 블로그 폴더 이름과 프론트 매터 지원"],"es":["Creación de carpetas de blog con nombre de carpeta personalizado","Agregar metadatos como descripción, slug y etiquetas","Inserción de imágenes de portada en el contenido del blog","Compatibilidad con formatos de archivo de imagen variados","Creación de títulos H1 y contenido de blog personalizado"],"fr":["Création de dossiers de blog avec nom de dossier personnalisé","Ajout de métadonnées telles que description, slug et étiquettes","Insertion d''images de couverture dans le contenu du blog","Compatibilité avec différents formats de fichiers d''image","Création de titres H1 et de contenu de blog personnalisé"],"de":["Erstellung von Blog-Ordnern mit benutzerdefiniertem Ordnernamen","Hinzufügen von Metadaten wie Beschreibung, Slug und Tags","Einfügen von Titelbildern in den Blog-Inhalt","Unterstützung für verschiedene Bilddateiformate","Erstellung von H1-Titeln und benutzerdefiniertem Blog-Inhalt"],"pt":["Criação de pastas de blog personalizadas com data e slug","Adição de front matter com descrição, slug e imagem de capa","Inserção de título H1 e imagem de capa near the top","Suporte a arrays de tags para categorização de postagens","Criação de arquivos index.md com conteúdo personalizado"],"ru":["Создание настраиваемых блог-папок с датой и слагом","Добавление фронт-мэтера с описанием, слагом и изображением обложки","Вставка заголовка H1 и изображения обложки near the top","Поддержка массивов тегов для категоризации постов","Создание файлов index.md с настраиваемым контентом"],"ar":["إنشاء مجلدات بلوج مخصصة بالتاريخ وسلاج","إضافة بيانات التعريف الأمامية مع الوصف وسلاج وصور الغلاف","إدراج عنوان H1 وصور الغلاف بالقرب من الأعلى","دعم مصفوفات الوسوم لتصنيف المنشورات","إنشاء ملفات index.md مع المحتوى المخصص"]},"keywords":{"en":["how to use blog-adding","what is blog-adding","blog-adding alternative","blog-adding vs ghost","blog-adding install","blog-adding setup guide","automated blog post creation","blog post workflow optimization"],"zh":["AI智能工具","博客添加","front matter","cover图像","Markdown语法","博客文件夹","自定义博客","AI工具博客","智能博客添加"],"ja":["AIエージェント","ブログ追加","フロントマター","カバーアイコン","Markdown構文","ブログフォルダ","カスタムブログ","AIツールブログ","スマートブログ追加"],"ko":["AI 에이전트","블로그 추가","프론트 매터","커버 이미지","Markdown 구문","블로그 폴더","사용자 정의 블로그","AI 도구 블로그","스마트 블로그 추가"],"es":["agregar publicaciones de blog","herramientas de AI para bloggers","creación de contenido de blog","metadatos para blogs","imagenes de portada para blogs","formatos de archivo de imagen para blogs","titulos H1 para blogs","contenido de blog personalizado"],"fr":["ajouter des publications de blog","outils d''IA pour les blogueurs","création de contenu de blog","métadonnées pour les blogs","images de couverture pour les blogs","formats de fichier d''image pour les blogs","titres H1 pour les blogs","contenu de blog personnalisé"],"de":["Blogbeiträge hinzufügen","KI-Tools für Blogger","Erstellung von Blog-Inhalt","Metadaten für Blogs","Titelbilder für Blogs","Bilddateiformate für Blogs","H1-Titel für Blogs","benutzerdefinierter Blog-Inhalt"],"pt":["blog-adding","criação de postagens de blog","front matter","slug","imagem de capa","pastas de blog personalizadas","índice de blog","otimização de blog para SEO"],"ru":["ИИ Агенты","создание блог-постов","фронт-мэтер","слаг","изображение обложки","настраиваемые блог-папки","индекс блога","оптимизация блога для SEO"],"ar":["أدوات الذكاء الاصطناعي","إضافة منشورات بلوج","بيانات التعريف الأمامية","سلاج","صور الغلاف","مجلدات بلوج مخصصة","فهرس بلوج","تحسين بلوج لتحسين محركات البحث"]}},"owner":"moonbitlang","repo":"website","repoPath":"moonbitlang/website","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"blog-adding","description":"Add a new blog post to this Docusaurus site from a staging folder.","bodyPreview":"# Add a Blog Post\n\nUse this skill when the user asks to add a new blog post\n\n## Steps\n\n1. Choose a blog folder name `YYYY-MM-DD-short-slug` (use the current date unless the user specifies one).\n2. Create `blog/<folder>/index.md` with front matter:\n   - `description`: short summary string\n   - `slug`: URL slug without date\n   - `image`: `/img/blogs/<folder>/cover.<ext>`\n   - `tags`: array (e.g. `[MoonBit]`)\n3. Add the H1 title and insert a cover image near the top: `![](./cover.<ext>)`.\n4. Copy t","body":"# Add a Blog Post\n\nUse this skill when the user asks to add a new blog post\n\n## Steps\n\n1. Choose a blog folder name `YYYY-MM-DD-short-slug` (use the current date unless the user specifies one).\n2. Create `blog/<folder>/index.md` with front matter:\n   - `description`: short summary string\n   - `slug`: URL slug without date\n   - `image`: `/img/blogs/<folder>/cover.<ext>`\n   - `tags`: array (e.g. `[MoonBit]`)\n3. Add the H1 title and insert a cover image near the top: `![](./cover.<ext>)`.\n4. Copy the staging Markdown content into the blog `index.md` after the front matter and cover.\n5. If the post includes videos, follow the existing pattern (see `blog/2024-04-18-ai-coding`):\n   - Place `.mp4` (or `.webm`) files in `blog/<folder>/`.\n   - Add `import` statements at the top of `index.md`.\n   - Use `<video controls src={videoImport} style={{width: ''100%''}}></video>` in the body.\n6. Copy referenced images/assets into `blog/<folder>/` and ensure all `./image` links resolve.\n7. Pick a cover image.\n8. Copy the cover into `static/img/blogs/<folder>/cover.<ext>` for the meta image path.\n9. If the staging post is English-only, Add a zh placeholder for English-only posts:\n\n   - Create `i18n/zh/docusaurus-plugin-content-blog/<folder>/index.md` with:\n\n     ```\n     ---\n     unlisted: true\n     ---\n     ```\n\n   If the staging post includes Chinese content, Repeat steps 2-6 for the Chinese version in `i18n/zh/docusaurus-plugin-content-blog/<folder>/index.md`.\n\n10. Remove the staging folder\n\n## Notes\n\n- No Docusaurus config changes are required; the blog plugin picks up new folders automatically.\n- Keep file paths and front matter ASCII-safe; avoid introducing new non-ASCII unless required.\n"},"lastSynced":"2026-03-08T02:04:29.530Z","agentAnalysis":{"suitability":{"en":"Perfect for Content Creation Agents needing automated blog post generation with Markdown and front matter support.","zh":"非常适合需要自动化博客帖子生成的内容创作代理，支持Markdown和前置事项","ja":"コンテンツ作成エージェントが自動化されたブログ投稿の生成を必要とする場合に最適です。Markdownおよびフロントマターのサポートを提供します。","ko":"자동화된 블로그 게시물 생성이 필요한 콘텐츠 생성 에이전트에게 적합하며 Markdown 및 프론트 매터를 지원합니다.","es":"Perfecto para agentes de creación de contenido que necesitan generación automática de publicaciones de blog con Markdown y soporte de front matter.","fr":"Parfait pour les agents de création de contenu ayant besoin de génération automatique de billets de blog avec Markdown et prise en charge de front matter.","de":"Perfekt für Content Creation Agents, die automatisierte Blog-Beitragsgenerierung mit Markdown und Front-Matter-Unterstützung benötigen.","pt":"Perfeito para Agentes de Criação de Conteúdo que precisam de geração automática de posts de blog com suporte a Markdown e front matter.","ru":"Идеально для агентов по созданию контента, которым требуется автоматизированная генерация постов в блоге с поддержкой Markdown и front matter.","ar":"مثالي للوكلاء الذين يحتاجون إلى إنشاء منشورات مدونة أوتوماتيكية مع دعم Markdown وfront matter."},"recommendation":{"en":"Empowers agents to generate new blog posts with formatted front matter, including description, slug, and image fields, while seamlessly inserting cover images using Markdown syntax and supporting protocols like HTTP for image sourcing.","zh":"赋予代理生成新博客帖子的能力，包括格式化的前置事项，例如描述、Slug和图像字段，同时使用Markdown语法无缝地插入封面图像，并支持HTTP等协议用于图像来源","ja":"エージェントが新しいブログ投稿を生成する機能を提供します。投稿には、説明、スラッグ、画像フィールドなどのフォーマットされたフロントマターが含まれます。また、Markdown構文を使用してカバー画像を投稿にシームレスに挿入できます。さらに、HTTPなどのプロトコルによる画像ソーシングもサポートします。","ko":"에이전트가 새 블로그 게시물을 생성할 수 있는 기능을 제공합니다. 게시글에는 설명, 슬러그, 이미지 필드 등과 같은 형식화된 프론트 매터가 포함되며 Markdown 구문을 사용하여 커버 이미지를 게시글에無縫に 삽입할 수 있습니다. 또한 HTTP와 같은 프로토콜을 통한 이미지 소싱도 지원합니다.","es":"Habilita a los agentes a generar nuevos posts de blog con front matter formateado, incluyendo descripción, slug y campos de imagen, mientras inserta imágenes de portada de forma transparente utilizando la sintaxis Markdown y soportando protocolos como HTTP para la obtención de imágenes.","fr":"Permet aux agents de générer de nouveaux billets de blog avec un front matter formaté, y compris la description, le slug et les champs d''image, tout en insérant des images de couverture de manière transparente en utilisant la syntaxe Markdown et en prenant en charge des protocoles tels que HTTP pour la récupération d''images.","de":"Ermächtigt Agenten, neue Blog-Beiträge mit formatiertem Front-Matter zu generieren, einschließlich Beschreibung, Slug und Bildfeldern, während es problemlos Cover-Bilder mithilfe der Markdown-Syntax einfügt und Protokolle wie HTTP für die Bildquelle unterstützt.","pt":"Habilita os agentes a gerar novos posts de blog com front matter formatado, incluindo descrição, slug e campos de imagem, enquanto insere imagens de capa usando a sintaxe Markdown e suporta protocolos como HTTP para obtenção de imagens.","ru":"Наделяет агентов возможностью генерировать новые посты в блоге с отформатированным front matter, включая описание, slug и поля изображений, а также без проблем вставляет изображения обложек с помощью синтаксиса Markdown и поддерживает протоколы, такие как HTTP, для получения изображений.","ar":"يمنح الوكلاء القدرة على إنشاء منشورات مدونة جديدة مع دعم front matter المحسّن، بما في ذلك الوصف والرابط والحقول المرئية، مع إمكانية إدراج صور الغلاف باستخدام بناء الجملة Markdown ودعم بروتوكولات مثل HTTP لاستخدام الصور."},"useCases":{"en":["Automating blog post creation with custom folder names and slug URLs","Generating front matter with tags and descriptions for improved SEO","Inserting cover images into blog posts using Markdown image syntax"],"zh":["使用自定义文件夹名称和Slug URL自动化博客帖子创建","生成带有标签和描述的前置事项以改善SEO","使用Markdown图像语法将封面图像插入博客帖子"],"ja":["カスタムフォルダ名とスラッグURLを使用してブログ投稿の作成を自動化する","タグや説明を含むフロントマターを生成してSEOを改善する","Markdown画像構文を使用してカバー画像をブログ投稿に挿入する"],"ko":["사용자 지정 폴더 이름과 슬러그 URL을 사용하여 블로그 게시글 생성 자동화","태그 및 설명을 포함하는 프론트 매터를 생성하여 SEO 개선","Markdown 이미지 구문을 사용하여 커버 이미지를 블로그 게시글에 삽입"],"es":["Automatizar la creación de publicaciones de blog con nombres de carpetas personalizados y URLs de slug","Generar front matter con etiquetas y descripciones para una mejor optimización para motores de búsqueda","Insertar imágenes de portada en las publicaciones de blog utilizando la sintaxis de imagen Markdown"],"fr":["Automatiser la création de billets de blog avec des noms de dossiers personnalisés et des URL de slug","Générer un front matter avec des balises et des descriptions pour une meilleure optimisation pour les moteurs de recherche","Insérer des images de couverture dans les billets de blog en utilisant la syntaxe d''image Markdown"],"de":["Automatisieren der Erstellung von Blog-Beiträgen mit benutzerdefinierten Ordnernamen und Slug-URLs","Generieren von Front-Matter mit Tags und Beschreibungen für eine verbesserte Suchmaschinenoptimierung","Einfügen von Cover-Bildern in Blog-Beiträge mithilfe der Markdown-Bildsyntax"],"pt":["Automatizar a criação de posts de blog com nomes de pastas personalizados e URLs de slug","Gerar front matter com tags e descrições para melhor SEO","Inserir imagens de capa em posts de blog usando a sintaxe de imagem Markdown"],"ru":["Автоматизировать создание постов в блоге с настраиваемыми именами папок и URL-адресами slug","Генерировать front matter с тегами и описаниями для улучшения SEO","Вставлять изображения обложек в посты в блоге с помощью синтаксиса изображений Markdown"],"ar":["توفير آلي لإنشاء منشورات مدونة مع أسماء المجلدات والمسارات المخصصة","إنشاء دعم front matter مع علامات ووصف لمحركات البحث لتحسينها","إدراج صور الغلاف في منشورات المدونة باستخدام بناء الجملة المرئي لمرجع Markdown"]},"limitations":{"en":["Requires filesystem access for creating blog folders and files","Limited to Markdown file format for blog posts","Dependent on user input for blog post details like title and content"],"zh":["需要文件系统访问权限来创建博客文件夹和文件","仅限Markdown文件格式用于博客帖子","依赖于用户输入以获取博客帖子的详细信息，例如标题和内容"],"ja":["ブログフォルダやファイルを作成するためにファイルシステムへのアクセスが必要","ブログ投稿にはMarkdownファイル形式のみがサポートされる","ブログ投稿の詳細、たとえばタイトルやコンテンツについてはユーザーの入力に依存する"],"ko":["블로그 폴더 및 파일을 생성하기 위해 파일 시스템 액세스가 필요","블로그 게시글에는 Markdown 파일 형식만 지원","블로그 게시글의詳細, 예를 들어 제목 및 콘텐츠는 사용자 입력에 의존"],"es":["Requiere acceso al sistema de archivos para crear carpetas y archivos de blog","Limitado al formato de archivo Markdown para las publicaciones de blog","Dependiente de la entrada del usuario para detalles del post de blog como título y contenido"],"fr":["Nécessite un accès au système de fichiers pour créer des dossiers et des fichiers de blog","Limité au format de fichier Markdown pour les billets de blog","Dépend de la saisie de l''utilisateur pour les détails du billet de blog tels que le titre et le contenu"],"de":["Benötigt Dateisystemzugriff für die Erstellung von Blog-Ordnern und -Dateien","Begrenzt auf das Markdown-Dateiformat für Blog-Beiträge","Abhängig von der Benutzereingabe für Blog-Beitragdetails wie Titel und Inhalt"],"pt":["Requer acesso ao sistema de arquivos para criar pastas e arquivos de blog","Limitado ao formato de arquivo Markdown para posts de blog","Dependente da entrada do usuário para detalhes do post de blog, como título e conteúdo"],"ru":["Требует доступа к файловой системе для создания папок и файлов блога","Ограничен форматом файла Markdown для постов в блоге","Зависит от ввода пользователя для деталей поста в блоге, таких как заголовок и содержание"],"ar":["يتطلب الوصول إلى نظام الملفات لإنشاء مجلدات وملفات المدونة","محدود بتنسيق ملف Markdown لمنشورات المدونة","يعتمد على إدخال المستخدم لتفاصيل منشور المدونة مثل العنوان والمحتوى"]},"version":4},"contentHash":"b680b9d858b12a0f1ece678ad0c10a780e16de58251951bed4ec7f19ad126766","qualityScore":30}');
