INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('moonbitlang/website/blog-adding', 'blog-adding', 'moonbitlang', 'website', 'community', 'blog-adding moonbitlang website community The blog-adding skill automates the creation of new blog posts, generating front matter and inserting cover images. This skill benefits developers and bloggers looking to streamline their content creation workflow. 本文介绍如何使用AI智能工具添加博客文章，包括创建博客文件夹、设置front matter和添加cover图像 この記事では、AIエージェントを使用してブログ投稿を追加する方法について説明します。ブログフォルダの作成、フロントマターの設定、カバーアイコンの追加など 이 문서는 AI 에이전트를 사용하여 블로그 게시물을 추가하는 방법에 대해 설명합니다. 블로그 폴더 생성, 프론트 매터 설정, 커버 이미지 추가 등 La habilidad de agregar publicaciones de blog permite a los desarrolladores crear fácilmente nuevas entradas de blog con metadatos y contenido. La compétence d''ajout de publications de blog permet aux développeurs de créer facilement de nouvelles entrées de blog avec des métadonnées et du contenu. Die Fähigkeit, Blogbeiträge hinzuzufügen, ermöglicht es Entwicklern, neue Blog-Einträge mit Metadaten und Inhalt leicht zu erstellen. O blog-adding é uma habilidade que permite criar postagens de blog personalizadas com front matter, slug e imagens de capa ИИ Агенты blog-adding позволяет создавать блог-посты с настраиваемым контентом и изображениями أدوات الذكاء الاصطناعي بلوج-إضافة تمكنك من إضافة منشورات بلوج مخصصة مع بيانات التعريف الأمامية وسلاج وصور الغلاف how to use blog-adding what is blog-adding blog-adding alternative blog-adding vs ghost blog-adding install blog-adding setup guide automated blog post creation blog post workflow optimization AI智能工具 博客添加 front matter cover图像 Markdown语法 博客文件夹 自定义博客 AI工具博客 智能博客添加 Creates blog folders with names in the format YYYY-MM-DD-short-slug Generates front matter with description, slug, image, and tags Inserts cover images near the top of the blog post Supports custom folder names and slugs Automates the creation of index.md files with H1 titles blog-adding is a skill that automates the process of adding new blog posts, creating folders and files with front matter and cover images');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('YusukeShimizu/lightning-compute-protocol/lcp-protocol-spec', 'community', 'YusukeShimizu', 'lightning-compute-protocol', 'YusukeShimizu/lightning-compute-protocol', 'lcp-protocol-spec', 0, 0, 30, '2026-03-08T01:57:15.377Z', '2026-03-08T02:05:21.997Z', '853e3c4d63f19c556530cdff50bf16cd514cd1dfbc7593e74b53bb4b9f717e91', '{"id":"YusukeShimizu/lightning-compute-protocol/lcp-protocol-spec","name":"lcp-protocol-spec","description":{"en":"The lcp-protocol-spec skill enables developers to work with the Lightning Compute Protocol, an application-layer protocol for paying for small compute jobs over Lightning. It benefits developers working with Lightning and compute jobs.","zh":"LCP 协议规范是一种应用层协议，用于在 Lightning 网络上支付小型计算任务。它利用 Lightning 原语进行认证、加密、路由和支付","ja":"LCP プロトコル仕様は、Lightning ネットワーク上での小規模な計算タスクの支払いを行うためのアプリケーション層プロトコルです。Lightning プリミティブを使用して認証、暗号化、ルーティング、支払いを行います","ko":"LCP 프로토콜 명세는 Lightning 네트워크에서 작은 컴퓨팅 작업을 지불하기 위한 응용 계층 프로토콜입니다. Lightning 원시를 사용하여 인증, 암호화, 라우팅 및 지불을 수행합니다","es":"LCP-Protocol-Spec es un protocolo de aplicación para pagar por trabajos de computación pequeños sobre Lightning. Se utiliza para la autenticación, el cifrado, el enrutamiento y el pago.","fr":"LCP-Protocol-Spec est un protocole d''application pour payer des petits travaux de calcul sur Lightning. Il utilise les primitives Lightning pour l''authentification, le chiffrement, le routage et le paiement.","de":"LCP-Protocol-Spec ist ein Anwendungsprotokoll zum Bezahlen kleiner Rechenaufgaben über Lightning. Es verwendet Lightning-Primitives für Authentifizierung, Verschlüsselung, Routing und Zahlung.","pt":"O LCP-Protocol-Spec é um protocolo de camada de aplicação para pagamento de pequenos trabalhos de computação sobre Lightning. Aprenda a configurá-lo e a usar suas funcionalidades.","ru":"LCP-Protocol-Spec - это протокол прикладного уровня для оплаты небольших вычислительных задач через Lightning. Узнайте, как его настроить и использовать его возможности.","ar":"بروتوكول LCP هو بروتوكول طبقة التطبيق لدفع أجور الأعمال الحاسوبية الصغيرة عبر Lightning. تعلم كيفية إعدادته واستخدام ميزاته"},"seo":{"title":{"en":"lcp-protocol-spec: Lightning Compute Protocol Setup Guide...","zh":"LCP 协议规范设置指南 - AIエージェント","ja":"LCP プロトコル仕様設定ガイド - AIエージェント","ko":"LCP 프로토콜 명세 설정 가이드 - AI 에이전트","es":"Guía de configuración de LCP-Protocol-Spec para desarroll...","fr":"Guide de mise en œuvre de LCP-Protocol-Spec pour les déve...","de":"Einrichtungsleitfaden für LCP-Protocol-Spec für Entwickler","pt":"Guia de Configuração do LCP-Protocol-Spec para Desenvolve...","ru":"Настройка LCP-Protocol-Spec: Руководство для Разработчиков","ar":"إعداد بروتوكول LCP: دليل للمطورين"},"description":{"en":"Unlock the power of LCP with our expert guide. Learn how to implement the Lightning Compute Protocol for secure compute jobs over Lightning. Get started now!","zh":"了解 LCP 协议规范的技术细节，包括应用层协议、Lightning 原语和 BOLT 行为","ja":"LCP プロトコル仕様の技術的詳細を学ぶ、应用層プロトコル、Lightning プリミティブ、BOLT 行為を含む","ko":"LCP 프로토콜 명세의 기술적 세부 정보를 알아보세요. 응용 계층 프로토콜, Lightning 원시 및 BOLT 동작 포함","es":"Aprende a implementar LCP-Protocol-Spec, un protocolo de aplicación para pagar por trabajos de computación pequeños sobre Lightning","fr":"Découvrez comment mettre en œuvre LCP-Protocol-Spec, un protocole d''application pour payer des petits travaux de calcul sur Lightning","de":"Erfahren Sie, wie Sie LCP-Protocol-Spec implementieren, ein Anwendungsprotokoll zum Bezahlen kleiner Rechenaufgaben über Lightning","pt":"Aprenda a configurar o LCP-Protocol-Spec para pagamento de pequenos trabalhos de computação sobre Lightning. Descubra como utilizar o protocolo de camada de ...","ru":"Узнайте, как настроить LCP-Protocol-Spec для оплаты небольших вычислительных задач через Lightning. Откройте для себя возможности протокола прикладного уровня.","ar":"تعلم كيفية إعداد بروتوكول LCP لدفع أجور الأعمال الحاسوبية الصغيرة عبر Lightning. اكتشف كيفية استخدام بروتوكول التطبيق"},"definition":{"en":"lcp-protocol-spec is an application-layer protocol specification for the Lightning Compute Protocol, enabling secure and efficient compute jobs over Lightning.","zh":"LCP 协议规范是一种应用层协议，用于在 Lightning 网络上支付小型计算任务","ja":"LCP プロトコル仕様は、Lightning ネットワーク上での小規模な計算タスクの支払いを行うためのアプリケーション層プロトコル","ko":"LCP 프로토콜 명세는 Lightning 네트워크에서 작은 컴퓨팅 작업을 지불하기 위한 응용 계층 프로토콜","es":"LCP-Protocol-Spec es un protocolo de aplicación que permite pagar por trabajos de computación pequeños sobre la red Lightning","fr":"LCP-Protocol-Spec est un protocole d''application qui permet de payer des petits travaux de calcul sur le réseau Lightning","de":"LCP-Protocol-Spec ist ein Anwendungsprotokoll, das das Bezahlen kleiner Rechenaufgaben über das Lightning-Netzwerk ermöglicht","pt":"O LCP-Protocol-Spec é um protocolo de camada de aplicação para pagamento de pequenos trabalhos de computação sobre Lightning.","ru":"LCP-Protocol-Spec - это протокол прикладного уровня для оплаты небольших вычислительных задач через Lightning.","ar":"بروتوكول LCP هو بروتوكول طبقة التطبيق لدفع أجور الأعمال الحاسوبية الصغيرة عبر Lightning"},"features":{"en":["Edits the primary spec: docs/protocol/protocol.md","Supports related implementation: go-lcpd/","Leverages Lightning primitives for authentication, encryption, routing, and payment","Does not modify BOLTs, ensuring compatibility with upstream Lightning behavior","Reuses existing Lightning infrastructure for efficient compute jobs"],"zh":["应用层协议","利用 Lightning 原语进行认证、加密、路由和支付","不修改 BOLT 行为","重用 Lightning 原语","支持小型计算任务的支付"],"ja":["アプリケーション層プロトコル","Lightning プリミティブを使用して認証、暗号化、ルーティング、支払いを行う","BOLT 行為の変更なし","Lightning プリミティブの再利用","小規模な計算タスクの支払いをサポート"],"ko":["응용 계층 프로토콜","Lightning 원시를 사용하여 인증, 암호화, 라우팅 및 지불을 수행","BOLT 동작 변경 없음","Lightning 원시의 재사용","작은 컴퓨팅 작업의 지불을 지원"],"es":["Utiliza primitives Lightning para autenticación y cifrado","Permite el pago por trabajos de computación pequeños sobre Lightning","No requiere modificaciones a BOLTs","Se integra con la implementación de go-lcpd","Soporta la autenticación y el pago sobre la red Lightning"],"fr":["Utilise des primitives Lightning pour l''authentification et le chiffrement","Permet de payer des petits travaux de calcul sur Lightning","Nécessite aucune modification de BOLTs","S''intègre avec la mise en œuvre de go-lcpd","Prend en charge l''authentification et le paiement sur le réseau Lightning"],"de":["Verwendet Lightning-Primitives für Authentifizierung und Verschlüsselung","Ermöglicht das Bezahlen kleiner Rechenaufgaben über Lightning","Erfordert keine Änderungen an BOLTs","Integriert sich mit der Implementierung von go-lcpd","Unterstützt Authentifizierung und Zahlung über das Lightning-Netzwerk"],"pt":["Utiliza primitivos de autenticação do Lightning","Utiliza primitivos de criptografia do Lightning","Utiliza primitivos de roteamento do Lightning","Não modifica o comportamento do BOLT","Reutiliza funcionalidades do Lightning","Suporta implementação em go-lcpd"],"ru":["Использует примитивы аутентификации Lightning","Использует примитивы шифрования Lightning","Использует примитивы маршрутизации Lightning","Не модифицирует поведение BOLT","Переиспользует функциональность Lightning","Поддерживает реализацию в go-lcpd"],"ar":["يستخدم البدائيات التأكيد من هوية Lightning","يستخدم البدائيات التشفير Lightning","يستخدم البدائيات التوجيه Lightning","لا يعدل سلوك BOLT","يعيد استخدام وظائف Lightning","يدعم التنفيذ في go-lcpd"]},"keywords":{"en":["how to use lcp-protocol-spec","lcp-protocol-spec setup guide","what is lcp-protocol-spec","lcp-protocol-spec alternative","lcp-protocol-spec vs BOLTs","lcp-protocol-spec install","Lightning Compute Protocol implementation"],"zh":["LCP 协议规范","Lightning 网络","应用层协议","小型计算任务","支付协议","Lightning 原语","BOLT 行为","AIエージェント","计算任务支付"],"ja":["LCP プロトコル仕様","Lightning ネットワーク","アプリケーション層プロトコル","小規模な計算タスク","支払いプロトコル","Lightning プリミティブ","BOLT 行為","AIエージェント","計算タスクの支払い"],"ko":["LCP 프로토콜 명세","Lightning 네트워크","응용 계층 프로토콜","작은 컴퓨팅 작업","지불 프로토콜","Lightning 원시","BOLT 동작","AI 에이전트","컴퓨팅 작업 지불"],"es":["LCP-Protocol-Spec","protocolo de aplicación","Lightning","trabajos de computación pequeños","autenticación","cifrado","ruta de pago","go-lcpd","desarrollo de software","Herramientas de AI como LCP-Protocol-Spec"],"fr":["LCP-Protocol-Spec","protocole d''application","Lightning","petits travaux de calcul","authentification","chiffrement","route de paiement","go-lcpd","développement de logiciels","Outils d''IA comme LCP-Protocol-Spec"],"de":["LCP-Protocol-Spec","Anwendungsprotokoll","Lightning","kleine Rechenaufgaben","Authentifizierung","Verschlüsselung","Zahlungsroute","go-lcpd","Software-Entwicklung","KI-Tools wie LCP-Protocol-Spec"],"pt":["LCP-Protocol-Spec","Lightning Compute Protocol","pagamento de trabalhos de computação","protocolo de camada de aplicação","autenticação do Lightning","criptografia do Lightning","roteamento do Lightning","BOLT","go-lcpd"],"ru":["LCP-Protocol-Spec","Lightning Compute Protocol","оплата вычислительных задач","протокол прикладного уровня","аутентификация Lightning","шифрование Lightning","маршрутизация Lightning","BOLT","go-lcpd"],"ar":["LCP-Protocol-Spec","بروتوكول Lightning الحاسوبي","دفع أجور الأعمال الحاسوبية","بروتوكول طبقة التطبيق","التأكيد من هوية Lightning","تشفير Lightning","توجيه Lightning","BOLT","go-lcpd"]}},"owner":"YusukeShimizu","repo":"lightning-compute-protocol","repoPath":"YusukeShimizu/lightning-compute-protocol","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.377Z","topics":[],"category":"community","skillMd":{"name":"lcp-protocol-spec","description":"Edit LCP protocol docs under docs/protocol/ in BOLT-style (TLVs, message formats, state flow).","bodyPreview":"You are editing the Lightning Compute Protocol (LCP) specification and related protocol docs.\n\n## Scope\n\n- Primary spec: `docs/protocol/protocol.md` (and `docs/protocol/protocol-ja.md` when applicable)\n- Related implementation: `go-lcpd/`\n\n## Non-negotiables\n\n- No modification to BOLTs: do not propose or require changes to upstream Lightning BOLT behavior. LCP is an application-layer protocol.\n- Leverage, do not reinvent: reuse Lightning primitives for authentication, encryption, routing, and pa","body":"You are editing the Lightning Compute Protocol (LCP) specification and related protocol docs.\n\n## Scope\n\n- Primary spec: `docs/protocol/protocol.md` (and `docs/protocol/protocol-ja.md` when applicable)\n- Related implementation: `go-lcpd/`\n\n## Non-negotiables\n\n- No modification to BOLTs: do not propose or require changes to upstream Lightning BOLT behavior. LCP is an application-layer protocol.\n- Leverage, do not reinvent: reuse Lightning primitives for authentication, encryption, routing, and payment binding when possible.\n- BOLT-quality documentation: aim for BOLT-level rigor, formatting, and readability.\n- TLV streams only: define new message fields as TLVs for extensibility; avoid fixed-position fields unless the existing spec already does so.\n\n## Leveraging BOLT features\n\n### Transport\n\n- Onion messages: for non-payment data transport, prefer onion messages over a custom TCP transport.\n- Custom messages: for direct peer-to-peer communication, use high-range custom message types (>= 32768) and follow BOLT #1 parity rules.\n\n### Data structure\n\n- Extension areas: if attaching to existing messages (`init`, HTLC-related messages, etc.), use spec-defined extension TLVs.\n\n### Privacy\n\n- Blinded paths: if the protocol carries identifiers or route information, use route blinding / blinded paths to protect endpoint privacy.\n\n## Specification strictness\n\nKeep message and TLV definitions parseable and consistent. Use a BOLT-style definition shape like:\n\n```text\n1. type: <TypeNumber> (`<message_name>`)\n2. data:\n   * [`<type>`:`<field_name>`]\n   * [`<length>`*`<type>`:`<array_name>`]\n```\n\n## Workflow\n\n1. Identify the exact section you are changing (message definition, TLV table, state machine, examples).\n3. Update the English spec first (`docs/protocol/protocol.md`). If the Japanese page is meant to mirror it, update `docs/protocol/protocol-ja.md` accordingly (it may be a summary).\n4. Keep terminology consistent with identifiers used in `go-lcpd/` (when they exist).\n5. If you introduce new fields:\n   - Define them as TLVs with explicit type numbers and clear semantics.\n   - Specify validation rules (required/optional, size limits, encoding, error handling).\n6. Add/adjust examples to match the new behavior.\n\n## Validation\n\n- For prose/spec changes: re-read for consistency and BOLT-style formatting.\n- If the change implies implementation changes, ensure `go-lcpd/` is updated in the same PR and validated with:\n  - `cd go-lcpd && make test`\n  - `cd go-lcpd && make lint`\n"},"lastSynced":"2026-03-08T02:05:21.997Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents specializing in blockchain and cryptocurrency development, particularly those working with Lightning and compute jobs.","zh":"适合专门从事区块链和加密货币开发的AI代理，特别是那些与Lightning和计算作业合作的代理。","ja":"Lightningおよびコンピュートジョブと協力するブロックチェーンおよび仮想通貨開発を専門とするAIエージェントに最適です。","ko":"블록체인 및 가상화폐 개발을 전문으로 하는 AI 에이전트에게 적합하며, 특히 Lightning 및 컴퓨팅 작업과 협력하는 에이전트에게 적합합니다.","es":"Ideal para agentes de IA que se especializan en desarrollo de blockchain y criptomonedas, particularmente aquellos que trabajan con Lightning y trabajos de cómputo.","fr":"Idéal pour les agents IA spécialisés dans le développement de blockchain et de cryptomonnaies, en particulier ceux qui travaillent avec Lightning et des tâches de calcul.","de":"Ideal für KI-Agents, die sich auf Blockchain- und Kryptowährungsentwicklung spezialisieren, insbesondere solche, die mit Lightning und Rechenjobs arbeiten.","pt":"Ideal para Agentes de IA especializados em desenvolvimento de blockchain e criptomoedas, particularmente aqueles que trabalham com Lightning e jobs de computação.","ru":"Идеально для агентов ИИ, специализирующихся на разработке блокчейна и криптовалют, особенно тех, кто работает с Lightning и вычислительными задачами.","ar":"مثالي للوكلاء الذكية المتخصصة في تطوير البلوكشين والعملات الرقمية، ولا سيما أولئك الذين يعملون مع Lightning ووظائف الحوسبة."},"recommendation":{"en":"Empowers agents to work seamlessly with the Lightning Compute Protocol, leveraging Lightning primitives for authentication, encryption, routing, and payment, while ensuring compliance with the LCP specification and related protocol documentation, including the primary spec in `docs/protocol/protocol.md` and implementation in `go-lcpd/`.","zh":"赋予代理无缝地与Lightning Compute Protocol合作的能力，利用Lightning原语进行身份验证、加密、路由和支付，同时确保遵守LCP规范和相关协议文档，包括`docs/protocol/protocol.md`中的主要规范和`go-lcpd/`中的实现。","ja":"Lightning Compute Protocolとシームレスに連携するエージェントを可能にし、Lightningのプリミティブを使用して認証、暗号化、ルーティング、支払いを行い、LCPの仕様および関連するプロトコルドキュメント（`docs/protocol/protocol.md`内の主な仕様と`go-lcpd/`内の実装を含む）に準拠することを保証します。","ko":"에이전트가 Lightning Compute Protocol과 원활하게 협력할 수 있도록 하며, Lightning의 원시 함수를 사용하여 인증, 암호화, 라우팅, 결제 등을 수행하며, LCP 사양 및 관련 프로토콜 문서(`docs/protocol/protocol.md`의 주요 사양 및 `go-lcpd/`의 구현 포함)를 준수하는 것을 보장합니다.","es":"Habilita a los agentes a trabajar de forma transparente con el Protocolo de Cómputo de Lightning, aprovechando los primitivos de Lightning para autenticación, cifrado, enrutamiento y pago, al mismo tiempo que garantiza el cumplimiento de la especificación LCP y la documentación del protocolo relacionada, incluyendo la especificación principal en `docs/protocol/protocol.md` y la implementación en `go-lcpd/`.","fr":"Permet aux agents de travailler en toute transparence avec le Protocole de Calcul Lightning, en exploitant les primitives Lightning pour l''authentification, le chiffrement, le routage et le paiement, tout en garantissant la conformité avec la spécification LCP et la documentation du protocole liée, y compris la spécification principale dans `docs/protocol/protocol.md` et la mise en œuvre dans `go-lcpd/`.","de":"Ermöglicht es den Agents, nahtlos mit dem Lightning-Compute-Protokoll zu arbeiten, indem es die Lightning-Primitiven für Authentifizierung, Verschlüsselung, Routing und Zahlung nutzt, während es gleichzeitig die Einhaltung der LCP-Spezifikation und der zugehörigen Protokoll-Dokumentation sicherstellt, einschließlich der primären Spezifikation in `docs/protocol/protocol.md` und der Implementierung in `go-lcpd/`.","pt":"Permite que os agentes trabalhem de forma transparente com o Protocolo de Computação Lightning, utilizando primitivos Lightning para autenticação, criptografia, roteamento e pagamento, garantindo a conformidade com a especificação LCP e a documentação do protocolo relacionada, incluindo a especificação principal em `docs/protocol/protocol.md` e a implementação em `go-lcpd/`.","ru":"Позволяет агентам работать бесшовно с Протоколом вычислений Lightning, используя примитивы Lightning для аутентификации, шифрования, маршрутизации и оплаты, обеспечивая соблюдение спецификации LCP и связанной документации протокола, включая основную спецификацию в `docs/protocol/protocol.md` и реализацию в `go-lcpd/`.","ar":"تمكن الوكلاء من العمل بسلاسة مع بروتوكول الحوسبة Lightning، واستخدام البدائيات Lightning للتحقق وتشفير التوجيه والدفع، مع ضمان الامتثال لمواصفات LCP وتوثيق البروتوكول المرتبط، بما في ذلك المواصفات الأساسية في `docs/protocol/protocol.md` والتنفيذ في `go-lcpd/`."},"useCases":{"en":["Editing the Lightning Compute Protocol specification and related protocol docs","Implementing application-layer protocols for paying for small compute jobs over Lightning","Ensuring compliance with non-negotiables such as not modifying BOLTs and reusing Lightning primitives"],"zh":["编辑Lightning Compute Protocol规范和相关协议文档","实现应用层协议以在Lightning上为小型计算作业付费","确保遵守不可商议的内容，例如不修改BOLTs和重用Lightning原语"],"ja":["Lightning Compute Protocolの仕様および関連するプロトコルドキュメントの編集","Lightning上での小規模なコンピュートジョブの支払い用にアプリケーション層プロトコルを実装する","BOLTsの変更を許可しないことやLightningのプリミティブの再利用など、非交渉事項に準拠することを保証する"],"ko":["Lightning Compute Protocol 사양 및 관련 프로토콜 문서 편집","Lightning에서 작은 컴퓨팅 작업에 대한 결제를 위한 애플리케이션 계층 프로토콜 구현","BOLTs 수정 불가 및 Lightning의 원시 함수 재사용 등 비협상 항목 준수 보장"],"es":["Edición de la especificación del Protocolo de Cómputo de Lightning y la documentación del protocolo relacionada","Implementación de protocolos de capa de aplicación para pagar pequeños trabajos de cómputo sobre Lightning","Garantizar el cumplimiento de aspectos no negociables como no modificar BOLTs y reutilizar primitivos de Lightning"],"fr":["Édition de la spécification du Protocole de Calcul Lightning et de la documentation du protocole liée","Mise en œuvre de protocoles de couche d''application pour payer de petits travaux de calcul sur Lightning","Garantir la conformité avec des aspects non négociables tels que ne pas modifier les BOLTs et réutiliser les primitives Lightning"],"de":["Bearbeitung der Spezifikation des Lightning-Compute-Protokolls und der zugehörigen Protokoll-Dokumentation","Implementierung von Anwendungs-Schicht-Protokollen zur Bezahlung von kleinen Rechenjobs über Lightning","Sicherstellung der Einhaltung von nicht verhandelbaren Aspekten wie der Nicht-Änderung von BOLTs und der Wiederverwendung von Lightning-Primitiven"],"pt":["Edição da especificação do Protocolo de Computação Lightning e documentos de protocolo relacionados","Implementação de protocolos de camada de aplicação para pagamento de pequenos trabalhos de computação sobre Lightning","Garantia de conformidade com aspectos não negociáveis, como não modificar BOLTs e reutilizar primitivos Lightning"],"ru":["Редактирование спецификации Протокола вычислений Lightning и связанных документов протокола","Реализация протоколов прикладного уровня для оплаты небольших вычислительных задач через Lightning","Обеспечение соблюдения незыблемых требований, таких как не изменение BOLT и повторное использование примитивов Lightning"],"ar":["تحرير مواصفات بروتوكول الحوسبة Lightning ووثائق البروتوكول المرتبطة","تنفيذ بروتوكولات طبقة التطبيق لدفع وظائف الحوسبة الصغيرة عبر Lightning","ضمان الامتثال للشروط غير القابلة للتفاوض، مثل عدم تعديل BOLTs وإعادة استخدام البدائيات Lightning"]},"limitations":{"en":["No modification to BOLTs allowed","Requires adherence to the LCP specification and protocol documentation","Limited to application-layer protocol development"],"zh":["不允许修改BOLTs","需要遵守LCP规范和协议文档","仅限应用层协议开发"],"ja":["BOLTsの変更を許可しない","LCPの仕様およびプロトコルドキュメントに準拠する必要がある","アプリケーション層プロトコルの開発のみに限定される"],"ko":["BOLTs 수정 불가","LCP 사양 및 프로토콜 문서 준수 필요","애플리케이션 계층 프로토콜 개발만 제한"],"es":["No se permite la modificación de BOLTs","Requiere la adhesión a la especificación LCP y la documentación del protocolo","Limitado al desarrollo de protocolos de capa de aplicación"],"fr":["Aucune modification des BOLTs n''est autorisée","Exige l''adhésion à la spécification LCP et à la documentation du protocole","Limité au développement de protocoles de couche d''application"],"de":["Keine Änderung von BOLTs ist erlaubt","Erfordert die Einhaltung der LCP-Spezifikation und der Protokoll-Dokumentation","Begrenzt auf die Entwicklung von Anwendungs-Schicht-Protokollen"],"pt":["Não é permitida modificação dos BOLTs","Exige adesão à especificação LCP e documentação do protocolo","Limitada ao desenvolvimento de protocolos de camada de aplicação"],"ru":["Не допускается изменение BOLT","Требуется соблюдение спецификации LCP и документации протокола","Ограничена разработкой протоколов прикладного уровня"],"ar":["لا يسمح بتعديل BOLTs","يتطلب الامتثال لمواصفات LCP وتوثيق البروتوكول","محدود بتطوير بروتوكولات طبقة التطبيق"]},"version":4},"contentHash":"853e3c4d63f19c556530cdff50bf16cd514cd1dfbc7593e74b53bb4b9f717e91","qualityScore":30}');
