INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('CarlosVerasteguii/Daticket/interactive-portfolio', 'interactive-portfolio', 'CarlosVerasteguii', 'Daticket', 'community', 'interactive-portfolio CarlosVerasteguii Daticket community The interactive-portfolio skill helps developers and designers create impressive portfolios with interactive case studies and personal branding, making a lasting impression on hiring managers. 交互式作品集是一种需要平衡创造力和可用性的在线形象，帮助开发者和设计师在竞争中脱颖而出 インタラクティブポートフォリオは、開発者とデザイナーのブランディングを強化するために不可欠なオンライン形象です 인터랙티브 포트폴리오는 개발자와 디자이너의 개인 브랜딩을 강화하는 데 중요한 온라인形象입니다 Diseña experiencias de portfolio interactivas con arquitectura de portfolio, diseño de casos de estudio y marca personal para desarrolladores y diseñadores Concevez des expériences de portfolio interactives avec une architecture de portfolio, un design de cas d''étude et une marque personnelle pour les développeurs et les designers Entwerfen Sie interaktive Portfolio-Erfahrungen mit Portfolio-Architektur, Fallstudien-Design und persönlicher Marke für Entwickler und Designer O portfólio interativo é uma primeira impressão que precisa converter, com balanço entre criatividade e usabilidade Интерактивное портфолио - это первое впечатление, которое должно конвертировать, с балансом между креативностью и удобством использования المحفظة التفاعلية هي انطباع أولي يحتاج إلى التحويل، مع توازن بين الإبداع وسهولة الاستخدام how to use interactive-portfolio what is interactive-portfolio interactive-portfolio alternative interactive-portfolio vs traditional portfolios interactive-portfolio setup guide interactive-portfolio install for developers 交互式作品集 在线形象设计 开发者个人品牌 设计师个人品牌 作品集架构 项目展示 交互式案例研究 联系转换优化 Portfolio architecture design Project showcase design with interactive elements Interactive case studies for enhanced user experience Personal branding for developers and designers Contact conversion optimization interactive-portfolio is a skill that enables the design of engaging portfolios with features like portfolio architecture, project showcase design, and contact conversion.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Joseph-VJ/XAI-Threat-Attribution-IDS/feature-validator', 'community', 'Joseph-VJ', 'XAI-Threat-Attribution-IDS', 'Joseph-VJ/XAI-Threat-Attribution-IDS', 'feature-validator', 0, 0, 30, '2026-03-08T01:57:15.387Z', '2026-03-08T02:05:54.671Z', '3e8c50c0435ad40520b082ad188ea4f374431d1fef04a0ea23291d1af8c70c53', '{"id":"Joseph-VJ/XAI-Threat-Attribution-IDS/feature-validator","name":"feature-validator","description":{"en":"The feature-validator skill ensures all features align with documented business requirements, benefiting developers and product managers. It references core business documents like BRD, FRD, and PRD.","zh":"Feature Validator 是一个确保功能与业务需求一致的工具，通过检查核心业务文档","ja":"Feature Validator は機能とビジネス要件を一致させるツールです。核心ビジネス文書をチェックします","ko":"Feature Validator는 기능과 비즈니스 요구사항을 일치시키는 도구로, 핵심 비즈니스 문서를 확인합니다","es":"feature-validator garantiza que las características se alineen con los requisitos comerciales documentados, como BRD, FRD y PRD","fr":"feature-validator assure que les fonctionnalités sont alignées sur les exigences commerciales documentées, telles que BRD, FRD et PRD","de":"feature-validator stellt sicher, dass Funktionen mit den dokumentierten Geschäftsanforderungen, wie BRD, FRD und PRD, übereinstimmen","pt":"O feature-validator é uma ferramenta que garante a conformidade com os documentos de requisitos de negócios. Ele verifica a alinhamento dos recursos com os requisitos documentados.","ru":"Feature-validator - это инструмент, обеспечивающий соответствие требованиям бизнеса. Он проверяет соответствие функций документированным требованиям.","ar":"feature-validator هو أداة تضمن مطابقة متطلبات الأعمال. يتحقق من مطابقة الميزات للمتطلبات المُوثقة."},"seo":{"title":{"en":"feature-validator: Feature Alignment Setup Guide | AI Age...","zh":"Feature Validator 设置指南 - 确保业务需求一致性","ja":"Feature Validator のベストプラクティス - ビジネス要件の整合性を確保する","ko":"Feature Validator 설정 가이드 - 비즈니스 요구사항 일치性 보장","es":"Guía de configuración de feature-validator para alinear c...","fr":"Guide de configuration de feature-validator pour l''aligne...","de":"Einrichtungsleitfaden für feature-validator zur Ausrichtu...","pt":"Guia de Configuração do feature-validator: Validação de R...","ru":"Настройка feature-validator: ИИ Агенты для проверки требо...","ar":"دليل إعداد feature-validator: التحقق من متطلبات الأعمال"},"description":{"en":"Ensure business requirements alignment with feature-validator. Check docs and setup guide to streamline your development process","zh":"了解 Feature Validator 如何通过检查 6 个核心业务文档（BRD、FRD、MRD、PRD、SRS 和 BUSINESS）确保功能与业务需求一致","ja":"Feature Validator が 6 つの核心ビジネス文書（BRD、FRD、MRD、PRD、SRS、BUSINESS）をチェックして機能とビジネス要件を一致させる方法を学びます","ko":"Feature Validator 가 6 개의 핵심 비즈니스 문서(BRD, FRD, MRD, PRD, SRS, BUSINESS)를 확인하여 기능과 비즈니스 요구사항을 일치시키는 방법에 대해 알아보세요","es":"Aprende a configurar feature-validator para garantizar el cumplimiento de los requisitos comerciales documentados y mejora la alineación de características","fr":"Découvrez comment configurer feature-validator pour assurer la conformité aux exigences commerciales documentées et améliorer l''alignement des fonctionnalités","de":"Erfahren Sie, wie Sie feature-validator konfigurieren, um die Einhaltung der dokumentierten Geschäftsanforderungen sicherzustellen und die Funktionen auszuri...","pt":"Aprenda a configurar o feature-validator para garantir a conformidade com os documentos de requisitos de negócios, incluindo BRD, FRD, MRD, PRD, SRS","ru":"Узнайте, как настроить feature-validator для обеспечения соответствия требованиям бизнеса, включая BRD, FRD, MRD, PRD, SRS, с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد feature-validator للتحقق من متطلبات الأعمال، بما في ذلك BRD و FRD و MRD و PRD و SRS"},"definition":{"en":"feature-validator is a technical skill that validates feature alignment with business requirements documents such as BRD, FRD, and PRD","zh":"Feature Validator 是一種 AI 工具，用于验证功能是否与业务需求一致","ja":"Feature Validator は機能とビジネス要件を一致させるための AI エージェントです","ko":"Feature Validator는 기능과 비즈니스 요구사항을 일치시키는 AI 도구입니다","es":"feature-validator es una herramienta de AI que verifica la alineación de características con requisitos comerciales documentados","fr":"feature-validator est un outil d''IA qui vérifie l''alignement des fonctionnalités sur les exigences commerciales documentées","de":"feature-validator ist ein AI-Tool, das die Ausrichtung von Funktionen mit dokumentierten Geschäftsanforderungen überprüft","pt":"O feature-validator é uma ferramenta de validação que garante a conformidade dos recursos com os documentos de requisitos de negócios.","ru":"Feature-validator - это инструмент проверки, обеспечивающий соответствие функций требованиям бизнеса.","ar":"feature-validator هو أداة التحقق التي تضمن مطابقة الميزات لمتطلبات الأعمال."},"features":{"en":["References core business documents including BRD, FRD, MRD, PRD, SRS, and BUSINESS","Validates feature alignment with documented business requirements","Supports multiple document formats including Markdown (.md) files","Ensures compliance with market, product, and software specifications","Streamlines development process by checking core business docs","Facilitates collaboration between developers, product managers, and business stakeholders"],"zh":["检查 BRD 文档以确保功能符合业务需求","验证 FRD 文档以确保功能实现","检查 MRD 文档以确保功能满足市场需求","验证 PRD 文档以确保功能满足产品需求","检查 SRS 文档以确保功能满足软件规格","检查 BUSINESS 文档以确保功能与业务战略一致"],"ja":["BRD 文書をチェックして機能がビジネス要件を満たすことを確認","FRD 文書を検証して機能の実装を確認","MRD 文書をチェックして機能が市場要件を満たすことを確認","PRD 文書を検証して機能が製品要件を満たすことを確認","SRS 文書をチェックして機能がソフトウェア仕様を満たすことを確認","BUSINESS 文書をチェックして機能がビジネス戦略と一致することを確認"],"ko":["BRD 문서를 확인하여 기능이 비즈니스 요구사항을 충족하는지 확인","FRD 문서를 검증하여 기능 구현을 확인","MRD 문서를 확인하여 기능이 시장 요구사항을 충족하는지 확인","PRD 문서를 검증하여 기능이 제품 요구사항을 충족하는지 확인","SRS 문서를 확인하여 기능이 소프트웨어 규격을 충족하는지 확인","BUSINESS 문서를 확인하여 기능이 비즈니스 전략과 일치하는지 확인"],"es":["Verificación de la alineación de características con BRD (Business Requirements Document)","Validación de la conformidad con FRD (Functional Requirements Document)","Comprobación de la coherencia con PRD (Product Requirements Document)","Soporte para la verificación de requisitos comerciales documentados","Integración con documentos de especificaciones de software (SRS)","Compatibilidad con requisitos de mercado (MRD) y documentos de negocio (BUSINESS)"],"fr":["Vérification de l''alignement des fonctionnalités sur le BRD (Business Requirements Document)","Validation de la conformité au FRD (Functional Requirements Document)","Vérification de la cohérence avec le PRD (Product Requirements Document)","Prise en charge de la vérification des exigences commerciales documentées","Intégration avec les documents de spécifications de logiciel (SRS)","Compatibilité avec les exigences de marché (MRD) et les documents de commerce (BUSINESS)"],"de":["Überprüfung der Ausrichtung von Funktionen mit BRD (Business Requirements Document)","Validierung der Einhaltung von FRD (Functional Requirements Document)","Überprüfung der Konsistenz mit PRD (Product Requirements Document)","Unterstützung für die Überprüfung von dokumentierten Geschäftsanforderungen","Integration mit Software-Spezifikationsdokumenten (SRS)","Kompatibilität mit Marktanforderungen (MRD) und Geschäftsdokumenten (BUSINESS)"],"pt":["Verificação de conformidade com os documentos de requisitos de negócios (BRD, FRD, MRD, PRD, SRS)","Alinhamento dos recursos com os requisitos documentados","Suporte a documentos de especificação de software (SRS)","Integração com documentos de requisitos de produto (PRD)"],"ru":["Проверка соответствия требованиям бизнеса (BRD, FRD, MRD, PRD, SRS)","Соответствие функций документированным требованиям","Поддержка документов спецификации программного обеспечения (SRS)","Интеграция с документами требований продукта (PRD) с помощью ИИ Агентов"],"ar":["التحقق من مطابقة متطلبات الأعمال (BRD و FRD و MRD و PRD و SRS)","مطابقة الميزات للمتطلبات المُوثقة","دعم وثائق مواصفات البرمجيات (SRS)","التكامل مع وثائق متطلبات المنتج (PRD)"]},"keywords":{"en":["how to use feature-validator","what is feature-validator","feature-validator setup guide","feature-validator alternative","feature-validator vs requirements management tools","feature-validator install","business requirements document validation","feature alignment best practices","technical skill for product managers","streamlining development process with feature-validator"],"zh":["Feature Validator","AI 工具","业务需求","功能验证","核心业务文档","BRD","FRD","MRD","PRD","SRS"],"ja":["Feature Validator","AI エージェント","ビジネス要件","機能検証","核心ビジネス文書","BRD","FRD","MRD","PRD","SRS"],"ko":["Feature Validator","AI 도구","비즈니스 요구사항","기능 검증","핵심 비즈니스 문서","BRD","FRD","MRD","PRD","SRS"],"es":["feature-validator","herramientas de AI","alineación de características","requisitos comerciales documentados","BRD","FRD","PRD","SRS","MRD","documento de requisitos de negocio"],"fr":["feature-validator","outils d''IA","alignement des fonctionnalités","exigences commerciales documentées","BRD","FRD","PRD","SRS","MRD","document d''exigences de commerce"],"de":["feature-validator","AI-Tools","Ausrichtung von Funktionen","dokumentierte Geschäftsanforderungen","BRD","FRD","PRD","SRS","MRD","Geschäftsanforderungsdokument"],"pt":["feature-validator","validação de recursos","requisitos de negócios","BRD","FRD","MRD","PRD","SRS","desenvolvimento de software"],"ru":["feature-validator","ИИ Агенты","проверка требований бизнеса","BRD","FRD","MRD","PRD","SRS","разработка программного обеспечения"],"ar":["feature-validator","أداة التحقق","متطلبات الأعمال","BRD","FRD","MRD","PRD","SRS","تطوير البرمجيات"]}},"owner":"Joseph-VJ","repo":"XAI-Threat-Attribution-IDS","repoPath":"Joseph-VJ/XAI-Threat-Attribution-IDS","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.387Z","topics":[],"category":"community","skillMd":{"name":"feature-validator","description":"Validate all features against 6 core business requirement documents (BRD, FRD, MRD, PRD, SRS, BUSINESS_MODEL). Use when implementing any new feature, user story, or capability. Enforces requirements traceability and alerts on undocumented features.","bodyPreview":"# Feature Alignment Validator\n\n## Purpose\nEnsure all features align with documented business requirements\n\n## Reference Documents (MUST CHECK ALL)\n\n### Core Business Docs (6 Required):\n1. **BRD** - `docs/business/brd.md` - Business Requirements\n2. **FRD** - `docs/business/FRD.md` - Functional Requirements\n3. **MRD** - `docs/business/mrd.md` - Market Requirements\n4. **PRD** - `docs/business/PRD.md` - Product Requirements\n5. **SRS** - `docs/business/srs.md` - Software Specifications\n6. **BUSINESS_","body":"# Feature Alignment Validator\n\n## Purpose\nEnsure all features align with documented business requirements\n\n## Reference Documents (MUST CHECK ALL)\n\n### Core Business Docs (6 Required):\n1. **BRD** - `docs/business/brd.md` - Business Requirements\n2. **FRD** - `docs/business/FRD.md` - Functional Requirements\n3. **MRD** - `docs/business/mrd.md` - Market Requirements\n4. **PRD** - `docs/business/PRD.md` - Product Requirements\n5. **SRS** - `docs/business/srs.md` - Software Specifications\n6. **BUSINESS_MODEL** - `docs/business/BUSINESS_MODEL.md` - Revenue model\n\n### Supporting Documentation:\n- `docs/business/FREE_FOR_BUYERS.md` - Free buyer philosophy\n- `docs/technical/SELLER_LISTING_FLOW_ANALYSIS.md` - Feature flows\n- `docs/DOCUMENTATION_INDEX.md` - Full doc inventory\n- `docs/PROJECT_OVERVIEW.md` - High-level summary\n\n## AI Workflow for New Features\n**🔴 STEP 0: VALIDATE USER REQUEST (MANDATORY)**\n- [ ] **Read user''s exact words** - What feature do they want?\n- [ ] **Understand their intent** - Why do they want this feature?\n- [ ] **Check for business conflicts** - Does this match FREE_FOR_BUYERS.md and BUSINESS_MODEL.md?\n- [ ] **Identify pricing implications** - Will this be free or paid?\n- [ ] **Ask clarifying questions** - If uncertain, ask BEFORE searching docs\n\n1. **📝 Feature Request Received**\n2. **🔍 Search ALL 6 docs** for matching requirement\n3. **Decision Tree:**\n   \n   ```\n   Feature in docs?\n   ├─ ✅ YES → Proceed with implementation\n   └─ ❌ NO → Follow \"Undocumented Feature Protocol\"\n   ```\n\n## Undocumented Feature Protocol\nWhen feature is NOT in any of the 6 docs:\n\n1. **🛑 PAUSE implementation**\n2. **📋 INFORM user:**\n   - \"This feature is not documented in BRD/FRD/MRD/PRD/SRS/BUSINESS_MODEL\"\n   - \"Searched: [list what you searched for]\"\n   - \"Results: Not found\"\n3. **💡 SUGGEST next steps:**\n   - Option A: Add feature to appropriate doc first (recommend which doc)\n   - Option B: Skip this feature (explain why it might not fit)\n   - Option C: Proceed anyway (explain risks)\n4. **⏸️ WAIT for user decision**\n5. **✅ Proceed** only after user confirms\n\n## Validation Checklist\n- [ ] Feature exists in at least ONE of the 6 docs?\n- [ ] Implementation matches documented requirements?\n- [ ] No conflicting requirements across docs?\n- [ ] User stories/use cases covered?\n- [ ] Business logic aligns with BUSINESS_MODEL?\n- [ ] Technical specs match SRS?\n- [ ] Functional behavior matches FRD?\n\n## Core Business Logic (Always Validate Against)\nFrom BUSINESS_MODEL.md:\n- ✅ **FREE for Buyers** - All customer features must be free\n- ✅ **Paid for Sellers** - Revenue comes from promoters/sellers only\n- ✅ **Offline-First** - Must work without internet\n- ✅ **Dual-Mode** - Support both SQLite (offline) and Supabase (online)\n- ✅ **Lead Generation** - Maximize seller leads, not buyer friction\n\n## Red Flags (Alert User Immediately)\n- 🚫 Feature charges buyers money\n- 🚫 Feature breaks offline mode\n- 🚫 Feature conflicts with \"free for buyers\" model\n- 🚫 Feature requires always-online connection\n- 🚫 Feature not in any of the 6 reference docs\n"},"lastSynced":"2026-03-08T02:05:54.671Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring rigorous feature validation against business requirements documents like BRD, FRD, and PRD.","zh":"适用于需要严格验证开发特性与业务需求文档（如BRD、FRD和PRD）一致性的开发代理","ja":"BRD、FRD、PRDなどのビジネス要件文書に対して徹底的な機能検証が必要な開発エージェントに最適","ko":"BRD, FRD, PRD 등의 비즈니스 요구사항 문서에 대한 엄격한 기능 검증이 필요한 개발 에이전트에게 적합","es":"Ideal para agentes de desarrollo que requieren una validación rigurosa de características contra documentos de requisitos comerciales como BRD, FRD y PRD.","fr":"Idéal pour les agents de développement nécessitant une validation rigoureuse des fonctionnalités contre des documents de spécifications commerciales tels que BRD, FRD et PRD.","de":"Ideal für Entwicklungsspezialisten, die eine strenge Überprüfung von Funktionen gegen Geschäftsanforderungsdokumente wie BRD, FRD und PRD erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem uma validação rigorosa de recursos contra documentos de requisitos de negócios, como BRD, FRD e PRD.","ru":"Идеально подходит для агентов разработки, требующих строгой проверки функций против документов бизнес-требований, таких как BRD, FRD и PRD.","ar":"مثالية لعميل التطوير الذين يتطلبون التحقق المُشدد من الميزات مقابل وثائق متطلبات الأعمال مثل BRD و FRD و PRD."},"recommendation":{"en":"Empowers agents to ensure feature alignment with core business documents, providing validation against BRD, FRD, MRD, PRD, SRS, and other business specifications, utilizing markdown files for documentation.","zh":"赋予代理人确保功能与核心业务文档（如BRD、FRD、MRD、PRD、SRS等）一致的能力，利用markdown文件进行文档验证","ja":"BRD、FRD、MRD、PRD、SRSなどのコアビジネス文書との機能の一致を保証するエージェントを可能にし、ドキュメントの検証にはmarkdownファイルを利用する","ko":"BRD, FRD, MRD, PRD, SRS 등의 핵심 비즈니스 문서와의 기능 일치를 보장하는 에이전트를 가능하게 하며, 문서의 검증에는 markdown 파일을 활용한다","es":"Habilita a los agentes a garantizar la alineación de las características con los documentos comerciales principales, proporcionando validación contra BRD, FRD, MRD, PRD, SRS y otras especificaciones comerciales, utilizando archivos markdown para la documentación.","fr":"Permet aux agents de s''assurer de l''alignement des fonctionnalités avec les documents commerciaux principaux, en fournissant une validation contre BRD, FRD, MRD, PRD, SRS et d''autres spécifications commerciales, en utilisant des fichiers markdown pour la documentation.","de":"Ermächtigt die Agenten, die Ausrichtung der Funktionen mit den Hauptgeschäftsdokumenten sicherzustellen und eine Überprüfung gegen BRD, FRD, MRD, PRD, SRS und andere Geschäftsspezifikationen bereitzustellen, indem Markdown-Dateien für die Dokumentation verwendet werden.","pt":"Permite que os agentes garantam a alinhamento das funcionalidades com os documentos de negócios principais, fornecendo validação contra BRD, FRD, MRD, PRD, SRS e outras especificações de negócios, utilizando arquivos markdown para documentação.","ru":"Наделяет агентов возможностью обеспечить выравнивание функций с основными бизнес-документами, предоставляя проверку против BRD, FRD, MRD, PRD, SRS и других бизнес-спецификаций, используя файлы markdown для документации.","ar":"تمكّن الوكيل من ضمان محاذاة الميزات مع الوثائق التجارية الأساسية، وتوفير التحقق ضد BRD و FRD و MRD و PRD و SRS والمواصفات التجارية الأخرى، باستخدام ملفات markdown للتوثيق."},"useCases":{"en":["Validating features against Business Requirements Documents (BRD)","Aligning product development with Functional Requirements Documents (FRD)","Ensuring market requirements compliance using Market Requirements Documents (MRD)"],"zh":["验证功能是否符合业务需求文档（BRD）","将产品开发与功能需求文档（FRD）对齐","使用市场需求文档（MRD）确保市场需求的合规性"],"ja":["ビジネス要件文書（BRD）との機能の一致を検証する","製品開発を機能要件文書（FRD）と一致させる","市場要件文書（MRD）を使用して市場要件のコンプライアンスを確保する"],"ko":["기능을 비즈니스 요구사항 문서(BRD)와 일치시키는 것을 검증","제품 개발을 기능 요구사항 문서(FRD)와 일치시키는 것","시장 요구사항 문서(MRD)를 사용하여 시장 요구사항의 준수를 보장"],"es":["Validar características contra documentos de requisitos comerciales (BRD)","Alinear el desarrollo de productos con documentos de requisitos funcionales (FRD)","Garantizar el cumplimiento de los requisitos del mercado mediante documentos de requisitos del mercado (MRD)"],"fr":["Valider les fonctionnalités contre des documents de spécifications commerciales (BRD)","Aligner le développement de produits avec des documents de spécifications fonctionnelles (FRD)","Assurer la conformité aux exigences du marché à l''aide de documents de spécifications du marché (MRD)"],"de":["Überprüfen von Funktionen gegen Geschäftsanforderungsdokumente (BRD)","Ausrichten der Produktentwicklung mit funktionalen Anforderungsdokumenten (FRD)","Sicherstellen der Einhaltung der Marktanforderungen mithilfe von Marktanforderungsdokumenten (MRD)"],"pt":["Validar funcionalidades contra Documentos de Requisitos de Negócios (BRD)","Alinhar o desenvolvimento de produtos com Documentos de Requisitos Funcionais (FRD)","Garantir o cumprimento dos requisitos de mercado usando Documentos de Requisitos de Mercado (MRD)"],"ru":["Проверять функции против Документов бизнес-требований (BRD)","Соответствовать разработку продукта с Документами функциональных требований (FRD)","Обеспечить соблюдение требований рынка с помощью Документов требований рынка (MRD)"],"ar":["التحقق من الميزات مقابل وثائق متطلبات الأعمال (BRD)","محاذاة تطوير المنتج مع وثائق متطلبات وظيفية (FRD)","ضمان الامتثال لمتطلبات السوق باستخدام وثائق متطلبات السوق (MRD)"]},"limitations":{"en":["Requires access to core business documents (BRD, FRD, MRD, PRD, SRS)","Must have markdown file format support for documentation","Limited to features outlined in referenced business documents"],"zh":["需要访问核心业务文档（BRD、FRD、MRD、PRD、SRS）","必须支持markdown文件格式用于文档","仅限于引用的业务文档中概述的功能"],"ja":["コアビジネス文書（BRD、FRD、MRD、PRD、SRS）へのアクセスが必要","ドキュメントではmarkdownファイル形式をサポートする必要がある","参照されたビジネス文書に記載されている機能のみに限定される"],"ko":["핵심 비즈니스 문서(BRD, FRD, MRD, PRD, SRS)에 대한 액세스가 필요","문서는 markdown 파일 형식을 지원해야 함","참조된 비즈니스 문서에 설명된 기능만 적용 가능"],"es":["Requiere acceso a documentos comerciales principales (BRD, FRD, MRD, PRD, SRS)","Debe tener soporte para formato de archivo markdown para la documentación","Limitado a las características descritas en los documentos comerciales de referencia"],"fr":["Nécessite un accès aux documents commerciaux principaux (BRD, FRD, MRD, PRD, SRS)","Doit avoir une prise en charge du format de fichier markdown pour la documentation","Limité aux fonctionnalités décrites dans les documents commerciaux de référence"],"de":["Benötigt Zugriff auf die Hauptgeschäftsdokumente (BRD, FRD, MRD, PRD, SRS)","Muss Unterstützung für Markdown-Dateiformat für die Dokumentation haben","Begrenzt auf die in den referenzierten Geschäftsdokumenten beschriebenen Funktionen"],"pt":["Exige acesso a documentos de negócios principais (BRD, FRD, MRD, PRD, SRS)","Deve ter suporte ao formato de arquivo markdown para documentação","Limitado às funcionalidades descritas nos documentos de negócios referenciados"],"ru":["Требует доступа к основным бизнес-документам (BRD, FRD, MRD, PRD, SRS)","Должно иметь поддержку формата файла markdown для документации","Ограничен функциями, описанными в ссылочных бизнес-документах"],"ar":["يتطلب الوصول إلى الوثائق التجارية الرئيسية (BRD و FRD و MRD و PRD و SRS)","يجب أن يكون لديه دعم لتنسيق ملف markdown للتوثيق","محدود بالميزات المحددة في الوثائق التجارية المُشِرة"]},"version":4},"contentHash":"3e8c50c0435ad40520b082ad188ea4f374431d1fef04a0ea23291d1af8c70c53","qualityScore":30}');
